def _bulk_manifest_candidate_barcodes(raw_barcode):
    """Build a prioritized set of barcode candidates for raw_bol_items lookup."""
    normalized = _normalize_upc_preserve_suffix_for_match(_normalize_scanned_upc(raw_barcode))
    if not normalized:
        return []

    candidates = []
    seen = set()

    def _add(value):
        v = _normalize_upc_preserve_suffix_for_match(_normalize_upc(value))
        v = str(v or '').strip()
        if not v:
            return
        key = v.lower()
        if key in seen:
            return
        seen.add(key)
        candidates.append(v)

    _add(normalized)
    base = normalized.split('-', 1)[0].strip()
    stripped_base = _strip_leading_zeros_numeric(base)
    _add(base)
    _add(stripped_base)

    if base.isdigit():
        for width in (12, 13):
            if len(base) <= width:
                _add(base.zfill(width))
            if stripped_base and stripped_base.isdigit() and len(stripped_base) <= width:
                _add(stripped_base.zfill(width))

    return candidates

def _bulk_manifest_pick_price_column(raw_cols):
    raw_cols = raw_cols or {}
    preferred_price_keys = (
        'original retail',
        'original_retail',
        'original retail price',
        'original_retail_price',
        'originalretail',
        'retail price',
        'retail_price'
    )
    for key in preferred_price_keys:
        if key in raw_cols:
            return raw_cols[key]

    for key, raw_name in raw_cols.items():
        compact = key.replace(' ', '').replace('_', '').replace('-', '')
        if 'original' in compact and 'retail' in compact:
            return raw_name

    return raw_cols.get('unit_price')

def _bulk_manifest_rawbol_price_column(cur):
    cur.execute('PRAGMA table_info(raw_bol_items)')
    raw_cols = {str(r[1]).lower(): str(r[1]) for r in cur.fetchall()}
    return _bulk_manifest_pick_price_column(raw_cols)

def _bulk_manifest_price_numeric_expr(price_col):
    safe_col = '"' + str(price_col or '').replace('"', '""') + '"'
    return (
        "CAST(REPLACE(REPLACE(REPLACE(TRIM(CAST(COALESCE("
        + safe_col +
        ", '') AS TEXT)), '$', ''), ',', ''), ' ', '') AS REAL)"
    )

def _bulk_manifest_lot_average_price(cur, lot_number, price_col=None, cache=None):
    lot_n = _normalize_lot_number(lot_number)
    if not lot_n or cur is None:
        return 0.0

    cache_key = lot_n.lower()
    if isinstance(cache, dict) and cache_key in cache:
        return cache[cache_key]

    avg_price = 0.0
    try:
        price_col = price_col or _bulk_manifest_rawbol_price_column(cur)
        if price_col:
            numeric_expr = _bulk_manifest_price_numeric_expr(price_col)
            cur.execute(f'''
                SELECT AVG({numeric_expr}) AS lot_avg
                FROM raw_bol_items
                WHERE lot_number = ? COLLATE NOCASE
                  AND {numeric_expr} > 0
            ''', (lot_n,))
            row = cur.fetchone()
            if row is not None:
                if isinstance(row, sqlite3.Row):
                    avg_price = _bulk_manifest_money(row.get('lot_avg'), default=0.0)
                else:
                    avg_price = _bulk_manifest_money(row[0], default=0.0)
    except Exception:
        avg_price = 0.0

    avg_price = _bulk_manifest_money(avg_price, default=0.0)
    if avg_price <= 0:
        avg_price = 0.0

    if isinstance(cache, dict):
        cache[cache_key] = avg_price
    return avg_price

def _bulk_manifest_random_unit_price(min_cents=999, max_cents=2999):
    lower = max(1, _coerce_int(min_cents, 999))
    upper = max(lower, _coerce_int(max_cents, 2999))
    return round(random.randint(lower, upper) / 100.0, 2)

def _bulk_manifest_resolve_unit_price(raw_value, *, lot_avg_price=0.0, default=None):
    unit_price = _bulk_manifest_money(raw_value, default=0.0)
    if unit_price > 0:
        return unit_price

    lot_avg = _bulk_manifest_money(lot_avg_price, default=0.0)
    if lot_avg > 0:
        return lot_avg

    fallback = _bulk_manifest_money(default, default=0.0)
    if fallback <= 0:
        fallback = _bulk_manifest_random_unit_price()
    return fallback

def _bulk_manifest_lookup_rawbol(raw_barcode):
    """Return best raw_bol_items match for barcode, or None."""
    candidates = _bulk_manifest_candidate_barcodes(raw_barcode)
    if not candidates:
        return None

    conn = None
    try:
        conn = sqlite3.connect('rawbol.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        price_col = _bulk_manifest_rawbol_price_column(cur)
        if price_col:
            safe_price_col = '"' + price_col.replace('"', '""') + '"'
            price_expr = f'{safe_price_col} AS unit_price'
        else:
            price_expr = '0 AS unit_price'
        select_cols = f'upc, item_description, image_url, lot_number, quantity, import_date, {price_expr}'
        lot_avg_cache = {}

        def _with_lot_avg(raw_row):
            if not raw_row:
                return None
            out = dict(raw_row)
            lot_n = _normalize_lot_number(out.get('lot_number'))
            out['lot_number'] = lot_n
            out['lot_avg_price'] = _bulk_manifest_lot_average_price(
                cur,
                lot_n,
                price_col=price_col,
                cache=lot_avg_cache
            )
            return out

        for candidate in candidates:
            cur.execute('''
                SELECT ''' + select_cols + '''
                FROM raw_bol_items
                WHERE upc = ? COLLATE NOCASE
                ORDER BY COALESCE(import_date, '') DESC, rowid DESC
                LIMIT 1
            ''', (candidate,))
            row = cur.fetchone()
            if row:
                return _with_lot_avg(row)

        stripped = _strip_leading_zeros_numeric(candidates[0])
        if stripped and len(stripped) >= 8:
            cur.execute('''
                SELECT ''' + select_cols + '''
                FROM raw_bol_items
                WHERE REPLACE(COALESCE(upc, ''), '.0', '') LIKE ? COLLATE NOCASE
                ORDER BY COALESCE(import_date, '') DESC, rowid DESC
                LIMIT 1
            ''', (f'%{stripped}',))
            row = cur.fetchone()
            if row:
                return _with_lot_avg(row)

        if stripped and stripped.isdigit():
            cur.execute('''
                SELECT ''' + select_cols + '''
                FROM raw_bol_items
                WHERE CAST(CAST(REPLACE(COALESCE(upc, ''), '.0', '') AS INTEGER) AS TEXT) = ?
                ORDER BY COALESCE(import_date, '') DESC, rowid DESC
                LIMIT 1
            ''', (stripped,))
            row = cur.fetchone()
            if row:
                return _with_lot_avg(row)
    finally:
        if conn is not None:
            conn.close()

    return None

@app.route('/api/bulk-manifest/lookup', methods=['GET'])
def api_bulk_manifest_lookup():
    """Lookup title metadata in rawbol.db for bulk manifest scanned barcodes."""
    try:
        barcode_raw = (request.args.get('barcode') or '').strip()
        if not barcode_raw:
            return jsonify({'success': False, 'error': 'Missing barcode'}), 400

        normalized_barcode = _normalize_upc_preserve_suffix_for_match(_normalize_scanned_upc(barcode_raw))
        row = _bulk_manifest_lookup_rawbol(barcode_raw)
        if not row:
            fallback_price = _bulk_manifest_random_unit_price()
            return jsonify({
                'success': True,
                'found': False,
                'barcode': normalized_barcode,
                'upc': normalized_barcode,
                'title': 'item',
                'image_url': '',
                'lot_number': '',
                'quantity': 0,
                'unit_price': fallback_price,
                'price_source': 'random'
            })

        upc = _normalize_upc_preserve_suffix_for_match(row.get('upc') or normalized_barcode)
        title = str(row.get('item_description') or '').strip() or 'item'
        image_url = str(row.get('image_url') or '').strip()
        lot_number = _normalize_lot_number(row.get('lot_number'))
        quantity = max(0, _coerce_int(row.get('quantity'), 0))
        lot_avg_price = _bulk_manifest_money(row.get('lot_avg_price'), default=0.0)
        unit_price = _bulk_manifest_resolve_unit_price(
            row.get('unit_price'),
            lot_avg_price=lot_avg_price,
            default=None
        )

        return jsonify({
            'success': True,
            'found': True,
            'barcode': upc,
            'upc': upc,
            'title': title,
            'image_url': image_url,
            'lot_number': lot_number,
            'quantity': quantity,
            'unit_price': unit_price,
            'price_source': ('exact' if _bulk_manifest_money(row.get('unit_price'), default=0.0) > 0 else ('lot_average' if lot_avg_price > 0 else 'random'))
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500

@app.route('/api/bulk-manifest/search', methods=['GET'])
def api_bulk_manifest_search():
    """Search raw_bol_items by keyword/UPC for manual bulk-manifest row selection."""
    try:
        query = str(request.args.get('q') or request.args.get('query') or '').strip()
        limit = max(1, min(60, _coerce_int(request.args.get('limit'), 20)))
        page = max(1, _coerce_int(request.args.get('page'), 1))
        if len(query) < 2:
            return jsonify({
                'success': True,
                'query': query,
                'page': 1,
                'limit': limit,
                'total': 0,
                'total_pages': 0,
                'results': []
            })

        conn = None
        lot_avg_by_lot = {}
        try:
            conn = sqlite3.connect('rawbol.db')
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()

            price_col = _bulk_manifest_rawbol_price_column(cur)
            if price_col:
                safe_price_col = '"' + price_col.replace('"', '""') + '"'
                price_expr = f'{safe_price_col} AS unit_price'
            else:
                price_expr = '0 AS unit_price'

            like_query = f'%{query}%'
            starts_query = f'{query}%'
            cur.execute('''
                SELECT COUNT(*) AS total_rows
                FROM raw_bol_items
                WHERE item_description LIKE ? COLLATE NOCASE
                   OR upc LIKE ? COLLATE NOCASE
            ''', (like_query, like_query))
            count_row = cur.fetchone()
            total_rows = max(0, _coerce_int(count_row['total_rows'] if count_row else 0, 0))
            total_pages = ((total_rows + limit - 1) // limit) if total_rows else 0
            if total_pages and page > total_pages:
                page = total_pages
            offset = ((page - 1) * limit) if total_pages else 0

            cur.execute('''
                SELECT upc, item_description, image_url, lot_number, quantity, import_date, ''' + price_expr + '''
                FROM raw_bol_items
                WHERE item_description LIKE ? COLLATE NOCASE
                   OR upc LIKE ? COLLATE NOCASE
                ORDER BY
                    CASE
                        WHEN item_description LIKE ? COLLATE NOCASE THEN 0
                        WHEN upc LIKE ? COLLATE NOCASE THEN 1
                        ELSE 2
                    END,
                    COALESCE(import_date, '') DESC,
                    rowid DESC
                LIMIT ?
                OFFSET ?
            ''', (like_query, like_query, starts_query, starts_query, limit, offset))
            raw_rows = [dict(r) for r in cur.fetchall()]

            if price_col and raw_rows:
                numeric_expr = _bulk_manifest_price_numeric_expr(price_col)
                lot_values = []
                seen_lots = set()
                for raw_row in raw_rows:
                    lot_n = _normalize_lot_number(raw_row.get('lot_number'))
                    if not lot_n:
                        continue
                    key = lot_n.lower()
                    if key in seen_lots:
                        continue
                    seen_lots.add(key)
                    lot_values.append(lot_n)

                if lot_values:
                    placeholders = ','.join('?' for _ in lot_values)
                    cur.execute(f'''
                        SELECT lot_number, AVG({numeric_expr}) AS lot_avg
                        FROM raw_bol_items
                        WHERE lot_number IN ({placeholders})
                          AND {numeric_expr} > 0
                        GROUP BY lot_number
                    ''', tuple(lot_values))
                    for lot_row in cur.fetchall():
                        lot_n = _normalize_lot_number(
                            lot_row['lot_number'] if isinstance(lot_row, sqlite3.Row) else lot_row[0]
                        )
                        if not lot_n:
                            continue
                        lot_avg = _bulk_manifest_money(
                            lot_row['lot_avg'] if isinstance(lot_row, sqlite3.Row) else lot_row[1],
                            default=0.0
                        )
                        if lot_avg > 0:
                            lot_avg_by_lot[lot_n.lower()] = lot_avg
        finally:
            if conn is not None:
                conn.close()

        results = []
        for row in raw_rows:
            barcode = _normalize_upc_preserve_suffix_for_match(_normalize_scanned_upc(row.get('upc')))
            barcode = str(barcode or '').strip()
            title = str(row.get('item_description') or '').strip() or 'item'
            image_url = str(row.get('image_url') or '').strip()
            lot_number = _normalize_lot_number(row.get('lot_number'))
            quantity = max(0, _coerce_int(row.get('quantity'), 0))
            lot_avg_price = lot_avg_by_lot.get(lot_number.lower(), 0.0) if lot_number else 0.0
            unit_price = _bulk_manifest_resolve_unit_price(
                row.get('unit_price'),
                lot_avg_price=lot_avg_price,
                default=None
            )

            results.append({
                'barcode': barcode,
                'upc': barcode,
                'title': title,
                'image_url': image_url,
                'thumbnail_url': image_url,
                'lot_number': lot_number,
                'quantity': quantity,
                'unit_price': unit_price,
                'price_source': ('exact' if _bulk_manifest_money(row.get('unit_price'), default=0.0) > 0 else ('lot_average' if lot_avg_price > 0 else 'random'))
            })

        return jsonify({
            'success': True,
            'query': query,
            'page': page,
            'limit': limit,
            'total': total_rows,
            'total_pages': total_pages,
            'results': results
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'bulk_manifest_search')}), 500

def _marketplace_sale_store_key(value):
    raw = str(value or '').strip().lower().replace('_', '-')
    if raw in (
        'marketplace-sale-bulk',
        'marketplace sale - bulk',
        'marketplace sale bulk',
        'marketplace-bulk',
        'marketplace bulk',
        'bulk-marketplace'
    ):
        return 'marketplace-sale-bulk'
    return 'marketplace'

def _bulk_manifest_status_key(value):
    raw = str(value or '').strip().lower().replace(' ', '_').replace('-', '_')
    if raw in ('sold', 'processed_sale'):
        return 'sold'
    if raw in ('cleanup_complete', 'cleaned'):
        return 'cleanup_complete'
    if raw in ('cleanup_partial', 'partial_cleanup'):
        return 'cleanup_partial'
    return 'created'

def _bulk_manifest_parse_ids(raw_value):
    seen = set()
    out = []
    for token in str(raw_value or '').split(','):
        part = token.strip()
        if not part:
            continue
        try:
            val = int(part)
        except Exception:
            continue
        if val <= 0 or val in seen:
            continue
        seen.add(val)
        out.append(val)
    return out

def _bulk_manifest_money(value, default=0.0):
    try:
        num = float(value)
    except Exception:
        num = float(default or 0.0)
    return round(max(0.0, num), 2)

def _bulk_manifest_next_title(cur):
    """Return next auto-generated manifest title (Bulk Manifest N)."""
    cur.execute('''
        SELECT manifest_title
        FROM bulk_manifests
        WHERE manifest_title IS NOT NULL
          AND TRIM(manifest_title) != ''
    ''')
    rows = cur.fetchall()
    max_num = 0
    prefix = 'bulk manifest'
    for row in rows:
        raw_title = row[0] if not isinstance(row, sqlite3.Row) else row['manifest_title']
        title = str(raw_title or '').strip()
        lower = title.lower()
        if not lower.startswith(prefix):
            continue
        suffix = title[len(prefix):].strip()
        if not suffix:
            continue
        try:
            num = int(suffix)
        except Exception:
            continue
        if num > max_num:
            max_num = num
    return f'Bulk Manifest {max_num + 1}'

def _ensure_bulk_manifest_tables(cur):
    cur.execute('''
        CREATE TABLE IF NOT EXISTS bulk_manifests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            manifest_title TEXT NOT NULL,
            buyer TEXT,
            manifest_date TEXT,
            total_items INTEGER DEFAULT 0,
            total_units INTEGER DEFAULT 0,
            total_original_retail REAL DEFAULT 0,
            status TEXT DEFAULT 'created',
            sold_at TEXT,
            sold_session_id TEXT,
            sold_total REAL,
            sold_rows INTEGER DEFAULT 0,
            cleanup_at TEXT,
            cleanup_note TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cur.execute('''
        CREATE TABLE IF NOT EXISTS bulk_manifest_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            manifest_id INTEGER NOT NULL,
            line_number INTEGER NOT NULL,
            barcode TEXT NOT NULL,
            title TEXT,
            quantity INTEGER DEFAULT 1,
            unit_price REAL DEFAULT 0,
            line_total REAL DEFAULT 0,
            image_url TEXT,
            lot_number TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (manifest_id) REFERENCES bulk_manifests(id) ON DELETE CASCADE
        )
    ''')
    cur.execute('''
        CREATE TABLE IF NOT EXISTS bulk_manifest_images (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            manifest_id INTEGER NOT NULL,
            image_path TEXT NOT NULL,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (manifest_id) REFERENCES bulk_manifests(id) ON DELETE CASCADE
        )
    ''')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_bulk_manifests_status_created ON bulk_manifests(status, created_at DESC)')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_bulk_manifest_items_manifest_id ON bulk_manifest_items(manifest_id)')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_bulk_manifest_items_barcode ON bulk_manifest_items(barcode)')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_bulk_manifest_images_manifest_id ON bulk_manifest_images(manifest_id, created_at DESC)')

    try:
        cur.execute('PRAGMA table_info(bulk_manifests)')
        existing = {str(r[1]).lower() for r in cur.fetchall()}
        migrations = {
            'status': "ALTER TABLE bulk_manifests ADD COLUMN status TEXT DEFAULT 'created'",
            'sold_at': 'ALTER TABLE bulk_manifests ADD COLUMN sold_at TEXT',
            'sold_session_id': 'ALTER TABLE bulk_manifests ADD COLUMN sold_session_id TEXT',
            'sold_total': 'ALTER TABLE bulk_manifests ADD COLUMN sold_total REAL',
            'sold_rows': 'ALTER TABLE bulk_manifests ADD COLUMN sold_rows INTEGER DEFAULT 0',
            'cleanup_at': 'ALTER TABLE bulk_manifests ADD COLUMN cleanup_at TEXT',
            'cleanup_note': 'ALTER TABLE bulk_manifests ADD COLUMN cleanup_note TEXT',
            'updated_at': 'ALTER TABLE bulk_manifests ADD COLUMN updated_at TEXT',
            'google_sheet_id': 'ALTER TABLE bulk_manifests ADD COLUMN google_sheet_id TEXT',
            'google_sheet_url': 'ALTER TABLE bulk_manifests ADD COLUMN google_sheet_url TEXT',
            'google_sheet_exported_at': 'ALTER TABLE bulk_manifests ADD COLUMN google_sheet_exported_at TEXT',
            'google_sheet_shared_with': 'ALTER TABLE bulk_manifests ADD COLUMN google_sheet_shared_with TEXT'
        }
        for col_name, ddl in migrations.items():
            if col_name not in existing:
                cur.execute(ddl)
    except Exception:
        pass

def _bulk_manifest_prepare_items(raw_items, *, force_lookup_refresh=False):
    items = []
    total_units = 0
    total_original_retail = 0.0
    rawbol_conn = None
    rawbol_cur = None
    rawbol_price_col = None
    rawbol_lot_avg_cache = {}
    try:
        rawbol_conn = sqlite3.connect('rawbol.db')
        rawbol_conn.row_factory = sqlite3.Row
        rawbol_cur = rawbol_conn.cursor()
        rawbol_price_col = _bulk_manifest_rawbol_price_column(rawbol_cur)
    except Exception:
        rawbol_cur = None
        rawbol_price_col = None

    try:
        for idx, raw_item in enumerate(raw_items or [], start=1):
            row = raw_item if isinstance(raw_item, dict) else {}
            barcode = _normalize_upc_preserve_suffix_for_match(
                _normalize_scanned_upc(row.get('barcode') or row.get('upc'))
            )
            barcode = str(barcode or '').strip()
            title = str(row.get('name') or row.get('title') or '').strip()
            quantity = max(1, _coerce_int(row.get('qty') if row.get('qty') is not None else row.get('quantity'), 1))
            unit_price = _bulk_manifest_money(
                row.get('unit_price') if row.get('unit_price') is not None else row.get('price'),
                default=0.0
            )
            image_url = str(row.get('image_url') or row.get('image') or '').strip()
            lot_number = _normalize_lot_number(row.get('lot_number'))
            lookup_row = None
            existing_unit_price = unit_price

            if not title:
                title = 'item'
            if barcode and (force_lookup_refresh or unit_price <= 0 or not lot_number or not image_url or title == 'item'):
                try:
                    lookup_row = _bulk_manifest_lookup_rawbol(barcode)
                except Exception:
                    lookup_row = None
                if lookup_row:
                    looked_up_title = str(lookup_row.get('item_description') or '').strip()
                    looked_up_image = str(lookup_row.get('image_url') or '').strip()
                    looked_up_lot = _normalize_lot_number(lookup_row.get('lot_number'))
                    if force_lookup_refresh:
                        if looked_up_title and title.lower() in ('', 'item', barcode.lower()):
                            title = looked_up_title
                        if looked_up_image:
                            image_url = looked_up_image
                        if looked_up_lot:
                            lot_number = looked_up_lot
                    else:
                        if title == 'item':
                            title = looked_up_title or title
                        if not image_url:
                            image_url = looked_up_image
                        if not lot_number:
                            lot_number = looked_up_lot
            if barcode and force_lookup_refresh:
                lot_avg_price = 0.0
                lookup_unit_price = 0.0
                if lookup_row:
                    lookup_unit_price = _bulk_manifest_money(lookup_row.get('unit_price'), default=0.0)
                    lot_avg_price = _bulk_manifest_money(lookup_row.get('lot_avg_price'), default=0.0)
                if lot_avg_price <= 0 and lot_number:
                    lot_avg_price = _bulk_manifest_lot_average_price(
                        rawbol_cur,
                        lot_number,
                        price_col=rawbol_price_col,
                        cache=rawbol_lot_avg_cache
                    )
                unit_price = _bulk_manifest_resolve_unit_price(
                    lookup_unit_price,
                    lot_avg_price=lot_avg_price,
                    default=(existing_unit_price if existing_unit_price > 0 else None)
                )
            elif unit_price <= 0:
                lot_avg_price = 0.0
                lookup_unit_price = 0.0
                if lookup_row:
                    lookup_unit_price = _bulk_manifest_money(lookup_row.get('unit_price'), default=0.0)
                    lot_avg_price = _bulk_manifest_money(lookup_row.get('lot_avg_price'), default=0.0)
                if barcode and lot_avg_price <= 0:
                    lot_avg_price = _bulk_manifest_lot_average_price(
                        rawbol_cur,
                        lot_number,
                        price_col=rawbol_price_col,
                        cache=rawbol_lot_avg_cache
                    )
                unit_price = _bulk_manifest_resolve_unit_price(
                    lookup_unit_price,
                    lot_avg_price=lot_avg_price,
                    default=None
                )

            line_total = round(quantity * unit_price, 2)
            items.append({
                'line_number': idx,
                'barcode': barcode,
                'title': title,
                'quantity': quantity,
                'unit_price': unit_price,
                'line_total': line_total,
                'image_url': image_url,
                'lot_number': lot_number
            })
            total_units += quantity
            total_original_retail += line_total
    finally:
        if rawbol_conn is not None:
            rawbol_conn.close()

    return items, total_units, round(total_original_retail, 2)

def _bulk_manifest_replace_items(cur, manifest_id, items, total_units, total_original_retail, now_iso):
    manifest_key = max(0, _coerce_int(manifest_id, 0))
    _ensure_bulk_manifest_tables(cur)
    cur.execute('DELETE FROM bulk_manifest_items WHERE manifest_id = ?', (manifest_key,))
    for item in items:
        cur.execute('''
            INSERT INTO bulk_manifest_items (
                manifest_id, line_number, barcode, title, quantity,
                unit_price, line_total, image_url, lot_number, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ''', (
            manifest_key,
            item['line_number'],
            item['barcode'],
            item['title'],
            item['quantity'],
            item['unit_price'],
            item['line_total'],
            item['image_url'],
            item['lot_number'],
            now_iso
        ))

    cur.execute('''
        UPDATE bulk_manifests
        SET total_items = ?,
            total_units = ?,
            total_original_retail = ?,
            updated_at = ?
        WHERE id = ?
    ''', (
        len(items),
        total_units,
        round(total_original_retail, 2),
        now_iso,
        manifest_key
    ))

def _bulk_manifest_photo_label_text(manifest_id, manifest_title=''):
    title = str(manifest_title or '').strip() or f'Bulk Manifest {max(0, _coerce_int(manifest_id, 0))}'
    return title[:120]

def _bulk_manifest_photo_url(image_path):
    rel = str(image_path or '').replace('\\', '/').strip().lstrip('/')
    return f"/static/{rel}" if rel else ''

def _bulk_manifest_photo_payload(row):
    data = dict(row or {})
    image_path = str(data.get('image_path') or '').strip()
    return {
        'id': max(0, _coerce_int(data.get('id'), 0)),
        'image_path': image_path,
        'image_url': _bulk_manifest_photo_url(image_path),
        'created_at': str(data.get('created_at') or '').strip()
    }

def _bulk_manifest_load_photos(cur, manifest_id):
    _ensure_bulk_manifest_tables(cur)
    cur.execute('''
        SELECT id, image_path, created_at
        FROM bulk_manifest_images
        WHERE manifest_id = ?
        ORDER BY created_at DESC, id DESC
    ''', (max(0, _coerce_int(manifest_id, 0)),))
    return [_bulk_manifest_photo_payload(r) for r in cur.fetchall()]

def _bulk_manifest_photo_counts(cur, manifest_ids):
    _ensure_bulk_manifest_tables(cur)
    cleaned_ids = []
    seen = set()
    for value in (manifest_ids or []):
        manifest_id = max(0, _coerce_int(value, 0))
        if manifest_id <= 0 or manifest_id in seen:
            continue
        seen.add(manifest_id)
        cleaned_ids.append(manifest_id)
    if not cleaned_ids:
        return {}

    placeholders = ','.join('?' for _ in cleaned_ids)
    cur.execute(f'''
        SELECT manifest_id, COUNT(*) AS photo_count
        FROM bulk_manifest_images
        WHERE manifest_id IN ({placeholders})
        GROUP BY manifest_id
    ''', tuple(cleaned_ids))
    counts = {manifest_id: 0 for manifest_id in cleaned_ids}
    for row in cur.fetchall():
        row_data = dict(row or {})
        manifest_id = max(0, _coerce_int(row_data.get('manifest_id'), 0))
        if manifest_id <= 0:
            continue
        counts[manifest_id] = max(0, _coerce_int(row_data.get('photo_count'), 0))
    return counts

def _bulk_manifest_photo_abs_path(image_path):
    rel = str(image_path or '').replace('\\', '/').strip().lstrip('/\\')
    if not rel:
        return ''
    static_root = os.path.abspath(os.path.join(app.root_path, 'static'))
    abs_path = os.path.abspath(os.path.join(static_root, rel))
    try:
        if os.path.commonpath([static_root, abs_path]) != static_root:
            return ''
    except Exception:
        return ''
    return abs_path

def _bulk_manifest_delete_photo_files(image_paths):
    seen = set()
    deleted_count = 0
    for raw_path in (image_paths or []):
        image_path = str(raw_path or '').strip()
        if not image_path:
            continue
        key = image_path.lower()
        if key in seen:
            continue
        seen.add(key)
        abs_path = _bulk_manifest_photo_abs_path(image_path)
        if not abs_path:
            continue
        try:
            if os.path.exists(abs_path):
                os.remove(abs_path)
                deleted_count += 1
        except FileNotFoundError:
            continue
        except Exception as exc:
            logger.warning('bulk_manifest_delete_photo_files failed for %s: %s', abs_path, exc, exc_info=True)
    return deleted_count

def _bulk_manifest_delete_manifest(manifest_id):
    manifest_key = max(0, _coerce_int(manifest_id, 0))
    if manifest_key <= 0:
        raise LookupError('Manifest not found')

    with db_connection('marketplace.db') as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        _ensure_bulk_manifest_tables(cur)
        cur.execute('''
            SELECT id, manifest_title, google_sheet_id, google_sheet_url
            FROM bulk_manifests
            WHERE id = ?
        ''', (manifest_key,))
        manifest_row = cur.fetchone()
        if not manifest_row:
            raise LookupError('Manifest not found')

        cur.execute('SELECT image_path FROM bulk_manifest_images WHERE manifest_id = ?', (manifest_key,))
        photo_paths = [str((row or {}).get('image_path') or '').strip() for row in cur.fetchall()]
        manifest_title = str(manifest_row['manifest_title'] or '').strip()

    google_sheet_deleted = False
    google_sheet_warning = ''
    try:
        google_result = _bulk_manifest_google_delete_manifest(manifest_key)
        google_sheet_deleted = bool(google_result.get('deleted'))
    except Exception as exc:
        google_sheet_warning = str(exc or '').strip()
        logger.warning('bulk_manifest_delete_manifest google cleanup failed for manifest %s: %s', manifest_key, exc, exc_info=True)

    with db_connection('marketplace.db') as conn:
        cur = conn.cursor()
        _ensure_bulk_manifest_tables(cur)
        cur.execute('DELETE FROM bulk_manifest_images WHERE manifest_id = ?', (manifest_key,))
        cur.execute('DELETE FROM bulk_manifest_items WHERE manifest_id = ?', (manifest_key,))
        cur.execute('DELETE FROM bulk_manifests WHERE id = ?', (manifest_key,))
        if cur.rowcount <= 0:
            raise LookupError('Manifest not found')

    _bulk_manifest_google_job_clear(manifest_key)
    deleted_photos = _bulk_manifest_delete_photo_files(photo_paths)
    return {
        'success': True,
        'manifest_id': manifest_key,
        'manifest_title': manifest_title,
        'deleted': True,
        'deleted_photo_files': deleted_photos,
        'google_sheet_deleted': google_sheet_deleted,
        'google_sheet_warning': google_sheet_warning
    }

def _bulk_manifest_save_labeled_photo(file_storage, label_text, abs_path):
    if file_storage is None:
        raise ValueError('Missing file upload')

    stream = getattr(file_storage, 'stream', file_storage)
    try:
        if hasattr(stream, 'seek'):
            stream.seek(0)
        with Image.open(stream) as raw_img:
            img = ImageOps.exif_transpose(raw_img)
            if img.mode not in ('RGB', 'RGBA'):
                img = img.convert('RGBA')
            else:
                img = img.copy()

            if img.size[0] > 2400 or img.size[1] > 2400:
                img.thumbnail((2400, 2400), Image.Resampling.LANCZOS)

            base = img.convert('RGBA')
            overlay = Image.new('RGBA', base.size, (0, 0, 0, 0))
            draw = ImageDraw.Draw(overlay)

            font_size = max(24, min(72, base.size[0] // 14))
            try:
                font = ImageFont.truetype('DejaVuSans-Bold.ttf', font_size)
            except Exception:
                font = ImageFont.load_default()

            text = str(label_text or '').strip() or 'Bulk Manifest'
            bbox = draw.textbbox((0, 0), text, font=font)
            text_w = max(1, bbox[2] - bbox[0])
            text_h = max(1, bbox[3] - bbox[1])
            pad_x = max(16, font_size // 2)
            pad_y = max(10, font_size // 3)
            banner_h = text_h + (pad_y * 2)
            bottom_gap = max(18, base.size[1] // 36)
            rect_x0 = max(12, (base.size[0] - (text_w + (pad_x * 2))) // 2)
            rect_y0 = max(12, base.size[1] - banner_h - bottom_gap)
            rect_x1 = min(base.size[0] - 12, rect_x0 + text_w + (pad_x * 2))
            rect_y1 = min(base.size[1] - 12, rect_y0 + banner_h)

            draw.rounded_rectangle(
                (rect_x0, rect_y0, rect_x1, rect_y1),
                radius=max(10, font_size // 3),
                fill=(10, 10, 10, 168)
            )
            text_x = rect_x0 + pad_x
            text_y = rect_y0 + pad_y - bbox[1]
            draw.text((text_x, text_y), text, font=font, fill=(255, 255, 255, 236))

            final_img = Image.alpha_composite(base, overlay).convert('RGB')
            final_img.save(abs_path, format='JPEG', quality=88, optimize=True)
    finally:
        try:
            if hasattr(stream, 'seek'):
                stream.seek(0)
        except Exception:
            pass

def _bulk_manifest_google_share_email():
    candidate = str(
        os.getenv('GOOGLE_SHEETS_SHARE_EMAIL')
        or os.getenv('SMTP_USER')
        or ''
    ).strip()
    return candidate if '@' in candidate else ''

def _bulk_manifest_google_shared_spreadsheet_id():
    raw_value = str(
        os.getenv('GOOGLE_SHEETS_SHARED_SPREADSHEET_ID')
        or os.getenv('GOOGLE_SHEETS_SPREADSHEET_ID')
        or ''
    ).strip()
    if not raw_value:
        return ''
    if '/d/' in raw_value:
        tail = raw_value.split('/d/', 1)[1]
        return tail.split('/', 1)[0].split('?', 1)[0].split('#', 1)[0].strip()
    return raw_value

def _bulk_manifest_google_tab_title(manifest_id, shared_mode=False):
    manifest_key = max(0, _coerce_int(manifest_id, 0))
    base = f'Manifest {manifest_key}' if shared_mode else 'Manifest'
    cleaned = ''.join(ch for ch in base if ch not in ('[', ']', ':', '*', '?', '/', '\\'))
    return cleaned[:100].strip() or f'Manifest {manifest_key}'

def _bulk_manifest_google_timeout(default_seconds=8):
    raw_value = str(os.getenv('GOOGLE_API_TIMEOUT_SECONDS') or '').strip()
    try:
        timeout_seconds = int(raw_value or default_seconds)
    except Exception:
        timeout_seconds = default_seconds
    return max(3, min(20, timeout_seconds))

def _bulk_manifest_google_request_error(prefix, exc):
    detail = str(exc or '').strip() or exc.__class__.__name__
    lower = detail.lower()
    if isinstance(exc, requests.exceptions.Timeout):
        return f'{prefix}: timed out contacting Google'
    if isinstance(exc, requests.exceptions.ConnectionError):
        dns_signals = (
            'name or service not known',
            'name resolution',
            'temporary failure in name resolution',
            'nodename nor servname',
            'getaddrinfo failed'
        )
        if any(signal in lower for signal in dns_signals):
            return f'{prefix}: DNS lookup for Google failed'
        return f'{prefix}: could not connect to Google'
    return f'{prefix}: {detail}'

def _bulk_manifest_google_access_token(scopes=None):
    creds_path = BASE_DIR / 'credentials.json'
    if not creds_path.exists():
        raise RuntimeError('Google credentials.json not found')

    with open(creds_path, 'r', encoding='utf-8') as fh:
        creds = json.load(fh)

    if str(creds.get('type') or '').strip() != 'service_account':
        raise RuntimeError('credentials.json is not a Google service account key')

    import json as _json
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.asymmetric import padding

    token_uri = str(creds.get('token_uri') or 'https://oauth2.googleapis.com/token').strip()
    client_email = str(creds.get('client_email') or '').strip()
    private_key_pem = str(creds.get('private_key') or '').strip()
    if not client_email or not private_key_pem:
        raise RuntimeError('Google service account key is missing required fields')

    scope_list = list(scopes or (
        'https://www.googleapis.com/auth/spreadsheets',
        'https://www.googleapis.com/auth/drive.file'
    ))

    private_key = serialization.load_pem_private_key(
        private_key_pem.encode('utf-8'),
        password=None
    )

    now = int(time.time())
    header = {'alg': 'RS256', 'typ': 'JWT'}
    claim = {
        'iss': client_email,
        'scope': ' '.join(scope_list),
        'aud': token_uri,
        'iat': now,
        'exp': now + 3600
    }

    def _b64url(data):
        return base64.urlsafe_b64encode(data).rstrip(b'=')

    unsigned = b'.'.join((
        _b64url(_json.dumps(header, separators=(',', ':')).encode('utf-8')),
        _b64url(_json.dumps(claim, separators=(',', ':')).encode('utf-8'))
    ))
    signature = private_key.sign(unsigned, padding.PKCS1v15(), hashes.SHA256())
    assertion = unsigned + b'.' + _b64url(signature)

    try:
        resp = requests.post(
            token_uri,
            data={
                'grant_type': 'urn:ietf:params:oauth:grant-type:jwt-bearer',
                'assertion': assertion.decode('utf-8')
            },
            timeout=_bulk_manifest_google_timeout(8)
        )
    except requests.RequestException as exc:
        raise RuntimeError(_bulk_manifest_google_request_error('Google token request failed', exc)) from exc
    try:
        payload = resp.json()
    except Exception:
        payload = {}
    if not resp.ok:
        raise RuntimeError(
            'Google token request failed: ' +
            str(payload.get('error_description') or payload.get('error') or resp.text[:240] or 'unknown error')
        )
    token = str(payload.get('access_token') or '').strip()
    if not token:
        raise RuntimeError('Google token response did not include access_token')
    return token

def _bulk_manifest_google_request(method, url, *, token, params=None, json_body=None, timeout=45):
    headers = {'Authorization': f'Bearer {token}'}
    if json_body is not None:
        headers['Content-Type'] = 'application/json'
    effective_timeout = timeout if timeout is not None else _bulk_manifest_google_timeout(8)
    try:
        resp = requests.request(
            method,
            url,
            headers=headers,
            params=params,
            json=json_body,
            timeout=effective_timeout
        )
    except requests.RequestException as exc:
        raise RuntimeError(_bulk_manifest_google_request_error('Google API request failed', exc)) from exc
    try:
        data = resp.json()
    except Exception:
        data = None
    if not resp.ok:
        message = ''
        if isinstance(data, dict):
            error_obj = data.get('error')
            if isinstance(error_obj, dict):
                message = str(error_obj.get('message') or '').strip()
            elif error_obj:
                message = str(error_obj).strip()
        if not message:
            message = str(resp.text[:300] or f'HTTP {resp.status_code}').strip()
        raise RuntimeError(message)
    return data if data is not None else {}

def _bulk_manifest_google_health(include_token_probe=False):
    creds_path = BASE_DIR / 'credentials.json'
    health = {
        'credentials_present': creds_path.exists(),
        'service_account': False,
        'client_email_present': False,
        'cryptography_ok': False,
        'share_email_configured': bool(_bulk_manifest_google_share_email()),
        'shared_spreadsheet_configured': bool(_bulk_manifest_google_shared_spreadsheet_id()),
        'token_ok': None
    }

    creds = {}
    if creds_path.exists():
        try:
            with open(creds_path, 'r', encoding='utf-8') as fh:
                creds = json.load(fh)
            health['service_account'] = str(creds.get('type') or '').strip() == 'service_account'
            health['client_email_present'] = bool(str(creds.get('client_email') or '').strip())
        except Exception as exc:
            health['credentials_error'] = str(exc).strip() or 'Failed to read credentials.json'
    else:
        health['credentials_error'] = 'Google credentials.json not found'

    try:
        from cryptography.hazmat.primitives import hashes, serialization  # noqa: F401
        from cryptography.hazmat.primitives.asymmetric import padding  # noqa: F401
        health['cryptography_ok'] = True
    except Exception as exc:
        health['cryptography_error'] = str(exc).strip() or 'cryptography import failed'

    if include_token_probe:
        try:
            _bulk_manifest_google_access_token()
            health['token_ok'] = True
        except Exception as exc:
            health['token_ok'] = False
            health['token_error'] = str(exc).strip() or 'Google token probe failed'

    return health

def _bulk_manifest_google_sheet_range(sheet_title, cell_range='A1'):
    title = str(sheet_title or 'Manifest').replace("'", "''")
    return f"'{title}'!{cell_range}"

def _bulk_manifest_google_get_spreadsheet(spreadsheet_id, token):
    data = _bulk_manifest_google_request(
        'GET',
        f'https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}',
        token=token,
        params={'fields': 'spreadsheetId,spreadsheetUrl,sheets(properties(sheetId,title))'}
    )
    return data if isinstance(data, dict) else {}

def _bulk_manifest_google_ensure_manifest_sheet(spreadsheet_id, token, desired_title='Manifest', allow_rename_singleton=True):
    desired_title = str(desired_title or 'Manifest').strip() or 'Manifest'
    meta = _bulk_manifest_google_get_spreadsheet(spreadsheet_id, token)
    spreadsheet_url = str(meta.get('spreadsheetUrl') or '').strip() or f'https://docs.google.com/spreadsheets/d/{spreadsheet_id}/edit'

    sheets = meta.get('sheets')
    if not isinstance(sheets, list):
        sheets = []

    for sheet in sheets:
        props = sheet.get('properties') if isinstance(sheet, dict) else {}
        title = str((props or {}).get('title') or '').strip()
        sheet_id = _coerce_int((props or {}).get('sheetId'), -1)
        if title == desired_title and sheet_id >= 0:
            return {
                'spreadsheet_id': str(spreadsheet_id).strip(),
                'spreadsheet_url': spreadsheet_url,
                'sheet_id': sheet_id,
                'sheet_title': desired_title
            }

    if allow_rename_singleton and len(sheets) == 1:
        props = sheets[0].get('properties') if isinstance(sheets[0], dict) else {}
        existing_id = _coerce_int((props or {}).get('sheetId'), -1)
        existing_title = str((props or {}).get('title') or '').strip()
        if existing_id >= 0 and existing_title and existing_title != desired_title:
            _bulk_manifest_google_request(
                'POST',
                f'https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}:batchUpdate',
                token=token,
                json_body={
                    'requests': [{
                        'updateSheetProperties': {
                            'properties': {'sheetId': existing_id, 'title': desired_title},
                            'fields': 'title'
                        }
                    }]
                }
            )
            return {
                'spreadsheet_id': str(spreadsheet_id).strip(),
                'spreadsheet_url': spreadsheet_url,
                'sheet_id': existing_id,
                'sheet_title': desired_title
            }

    created = _bulk_manifest_google_request(
        'POST',
        f'https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}:batchUpdate',
        token=token,
        json_body={
            'requests': [{
                'addSheet': {
                    'properties': {'title': desired_title}
                }
            }]
        }
    )
    replies = created.get('replies') if isinstance(created, dict) else []
    new_sheet_id = -1
    if isinstance(replies, list):
        for reply in replies:
            add_sheet = reply.get('addSheet') if isinstance(reply, dict) else {}
            props = add_sheet.get('properties') if isinstance(add_sheet, dict) else {}
            if str(props.get('title') or '').strip() == desired_title:
                new_sheet_id = _coerce_int(props.get('sheetId'), -1)
                break

    if new_sheet_id < 0:
        refreshed = _bulk_manifest_google_get_spreadsheet(spreadsheet_id, token)
        refreshed_sheets = refreshed.get('sheets')
        if isinstance(refreshed_sheets, list):
            for sheet in refreshed_sheets:
                props = sheet.get('properties') if isinstance(sheet, dict) else {}
                if str((props or {}).get('title') or '').strip() == desired_title:
                    new_sheet_id = _coerce_int((props or {}).get('sheetId'), -1)
                    break
        spreadsheet_url = str(refreshed.get('spreadsheetUrl') or spreadsheet_url).strip() or spreadsheet_url

    if new_sheet_id < 0:
        raise RuntimeError('Google Sheets export could not find or create the Manifest tab')

    return {
        'spreadsheet_id': str(spreadsheet_id).strip(),
        'spreadsheet_url': spreadsheet_url,
        'sheet_id': new_sheet_id,
        'sheet_title': desired_title
    }

def _bulk_manifest_google_style_sheet(
    spreadsheet_id,
    worksheet_id,
    worksheet_title,
    sheet_title,
    token,
    update_spreadsheet_title=True,
    row_count=0,
    image_row_indexes=None,
    emphasis_row_indexes=None,
    header_row_index=0,
    frozen_row_count=1
):
    row_count = max(0, _coerce_int(row_count, 0))
    totals_start_row = max(0, row_count - 1)
    header_row_index = max(0, min(totals_start_row, _coerce_int(header_row_index, 0)))
    frozen_row_count = max(1, min(row_count or 1, _coerce_int(frozen_row_count, 1)))
    normal_row_height = 21
    summary_row_height = 30
    image_row_height = 124
    thumb_column_index = 6
    thumb_column_width = 100
    image_rows = sorted({
        idx for idx in [
            _coerce_int(value, -1) for value in (image_row_indexes or [])
        ]
        if 0 < idx < totals_start_row
    })
    emphasis_rows = sorted({
        idx for idx in [
            _coerce_int(value, -1) for value in (emphasis_row_indexes or [])
        ]
        if header_row_index < idx < totals_start_row
    })
    requests_payload = []
    if update_spreadsheet_title:
        requests_payload.append({'updateSpreadsheetProperties': {
            'properties': {'title': sheet_title},
            'fields': 'title'
        }})
    requests_payload.extend([
        {'repeatCell': {
            'range': {'sheetId': worksheet_id, 'startRowIndex': header_row_index, 'endRowIndex': header_row_index + 1},
            'cell': {'userEnteredFormat': {'textFormat': {'bold': True}}},
            'fields': 'userEnteredFormat.textFormat.bold'
        }},
        {'updateSheetProperties': {
            'properties': {
                'sheetId': worksheet_id,
                'title': worksheet_title,
                'gridProperties': {'frozenRowCount': frozen_row_count}
            },
            'fields': 'title,gridProperties.frozenRowCount'
        }}
    ])
    if row_count > 0:
        requests_payload.append({'updateDimensionProperties': {
            'range': {
                'sheetId': worksheet_id,
                'dimension': 'ROWS',
                'startIndex': 0,
                'endIndex': row_count
            },
            'properties': {'pixelSize': normal_row_height},
            'fields': 'pixelSize'
        }})
        requests_payload.append({'updateDimensionProperties': {
            'range': {
                'sheetId': worksheet_id,
                'dimension': 'ROWS',
                'startIndex': 0,
                'endIndex': 1
            },
            'properties': {'pixelSize': summary_row_height},
            'fields': 'pixelSize'
        }})
    requests_payload.append({'updateDimensionProperties': {
        'range': {
            'sheetId': worksheet_id,
            'dimension': 'COLUMNS',
            'startIndex': thumb_column_index,
            'endIndex': thumb_column_index + 1
        },
        'properties': {'pixelSize': thumb_column_width},
        'fields': 'pixelSize'
    }})
    if image_rows:
        start_idx = image_rows[0]
        end_idx = start_idx + 1
        contiguous_ranges = []
        for idx in image_rows[1:]:
            if idx == end_idx:
                end_idx += 1
                continue
            contiguous_ranges.append((start_idx, end_idx))
            start_idx = idx
            end_idx = idx + 1
        contiguous_ranges.append((start_idx, end_idx))
        for start_idx, end_idx in contiguous_ranges:
            requests_payload.append({'updateDimensionProperties': {
                'range': {
                    'sheetId': worksheet_id,
                    'dimension': 'ROWS',
                    'startIndex': start_idx,
                    'endIndex': end_idx
                },
                'properties': {'pixelSize': image_row_height},
                'fields': 'pixelSize'
            }})
    for idx in emphasis_rows:
        requests_payload.append({'repeatCell': {
            'range': {
                'sheetId': worksheet_id,
                'startRowIndex': idx,
                'endRowIndex': idx + 1,
                'startColumnIndex': 4,
                'endColumnIndex': 6
            },
            'cell': {'userEnteredFormat': {'textFormat': {'bold': True}}},
            'fields': 'userEnteredFormat.textFormat.bold'
        }})
    if row_count > 1:
        totals_range = {
            'sheetId': worksheet_id,
            'startRowIndex': totals_start_row,
            'endRowIndex': row_count,
            'startColumnIndex': 2,
            'endColumnIndex': 6
        }
        top_summary_range = {
            'sheetId': worksheet_id,
            'startRowIndex': 0,
            'endRowIndex': 1,
            'startColumnIndex': 0,
            'endColumnIndex': 6
        }
        requests_payload.extend([
            {'repeatCell': {
                'range': top_summary_range,
                'cell': {'userEnteredFormat': {
                    'backgroundColor': {'red': 1.0, 'green': 0.949, 'blue': 0.8},
                    'textFormat': {'bold': True, 'fontSize': 14}
                }},
                'fields': 'userEnteredFormat.backgroundColor,userEnteredFormat.textFormat.bold,userEnteredFormat.textFormat.fontSize'
            }},
            {'updateBorders': {
                'range': top_summary_range,
                'top': {'style': 'SOLID', 'color': {'red': 0.6, 'green': 0.52, 'blue': 0.18}},
                'bottom': {'style': 'SOLID', 'color': {'red': 0.6, 'green': 0.52, 'blue': 0.18}},
                'left': {'style': 'SOLID', 'color': {'red': 0.6, 'green': 0.52, 'blue': 0.18}},
                'right': {'style': 'SOLID', 'color': {'red': 0.6, 'green': 0.52, 'blue': 0.18}},
                'innerVertical': {'style': 'SOLID', 'color': {'red': 0.82, 'green': 0.72, 'blue': 0.25}}
            }},
            {'repeatCell': {
                'range': totals_range,
                'cell': {'userEnteredFormat': {
                    'backgroundColor': {'red': 1.0, 'green': 0.949, 'blue': 0.8},
                    'textFormat': {'bold': True}
                }},
                'fields': 'userEnteredFormat.backgroundColor,userEnteredFormat.textFormat.bold'
            }},
            {'updateBorders': {
                'range': totals_range,
                'top': {'style': 'SOLID', 'color': {'red': 0.6, 'green': 0.52, 'blue': 0.18}},
                'bottom': {'style': 'SOLID', 'color': {'red': 0.6, 'green': 0.52, 'blue': 0.18}},
                'left': {'style': 'SOLID', 'color': {'red': 0.6, 'green': 0.52, 'blue': 0.18}},
                'right': {'style': 'SOLID', 'color': {'red': 0.6, 'green': 0.52, 'blue': 0.18}},
                'innerVertical': {'style': 'SOLID', 'color': {'red': 0.82, 'green': 0.72, 'blue': 0.25}}
            }}
        ])
    _bulk_manifest_google_request(
        'POST',
        f'https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}:batchUpdate',
        token=token,
        json_body={'requests': requests_payload}
    )

def _bulk_manifest_google_write_sheet_rows(spreadsheet_id, worksheet_title, rows, token):
    a1_full_range = _bulk_manifest_google_sheet_range(worksheet_title, 'A:O')
    a1_start = _bulk_manifest_google_sheet_range(worksheet_title, 'A1')

    _bulk_manifest_google_request(
        'POST',
        f'https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}/values:batchClear',
        token=token,
        json_body={'ranges': [a1_full_range]}
    )
    _bulk_manifest_google_request(
        'POST',
        f'https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}/values:batchUpdate',
        token=token,
        json_body={
            'valueInputOption': 'USER_ENTERED',
            'data': [{
                'range': a1_start,
                'majorDimension': 'ROWS',
                'values': rows
            }]
        }
    )

def _bulk_manifest_google_should_recreate_sheet(message):
    reason = str(message or '').strip().lower()
    if not reason:
        return False
    recreate_signals = (
        'requested entity was not found',
        'not found',
        'permission denied',
        'the caller does not have permission',
        'insufficient permissions',
        'forbidden'
    )
    return any(signal in reason for signal in recreate_signals)

def _bulk_manifest_google_share_sheet(spreadsheet_id, token):
    try:
        _bulk_manifest_google_request(
            'POST',
            f'https://www.googleapis.com/drive/v3/files/{spreadsheet_id}/permissions',
            token=token,
            params={'sendNotificationEmail': 'false'},
            json_body={'type': 'anyone', 'role': 'reader'}
        )
    except Exception:
        pass

    share_email = _bulk_manifest_google_share_email()
    if share_email:
        try:
            _bulk_manifest_google_request(
                'POST',
                f'https://www.googleapis.com/drive/v3/files/{spreadsheet_id}/permissions',
                token=token,
                params={'sendNotificationEmail': 'false'},
                json_body={'type': 'user', 'role': 'writer', 'emailAddress': share_email}
            )
        except Exception:
            pass
    return share_email

def _bulk_manifest_google_export_sheet(
    existing_sheet_id,
    sheet_title,
    rows,
    token,
    *,
    worksheet_title='Manifest',
    update_spreadsheet_title=True,
    allow_rename_singleton=True,
    image_row_indexes=None,
    emphasis_row_indexes=None,
    header_row_index=0,
    frozen_row_count=1
):
    desired_tab_title = str(worksheet_title or 'Manifest').strip() or 'Manifest'
    existing_sheet_id = str(existing_sheet_id or '').strip()
    sheet_title = str(sheet_title or 'Bulk Manifest').strip() or 'Bulk Manifest'

    sheet_meta = None
    if existing_sheet_id:
        try:
            sheet_meta = _bulk_manifest_google_ensure_manifest_sheet(
                existing_sheet_id,
                token,
                desired_title=desired_tab_title,
                allow_rename_singleton=allow_rename_singleton
            )
        except Exception as exc:
            if _bulk_manifest_google_should_recreate_sheet(exc):
                logger.warning('bulk_manifest_google_sheet: recreating spreadsheet %s after reuse failure: %s', existing_sheet_id, exc)
                sheet_meta = None
            else:
                raise

    if sheet_meta is None:
        created = _bulk_manifest_google_request(
            'POST',
            'https://sheets.googleapis.com/v4/spreadsheets',
            token=token,
            json_body={
                'properties': {'title': sheet_title},
                'sheets': [{'properties': {'title': desired_tab_title}}]
            }
        )
        spreadsheet_id = str(created.get('spreadsheetId') or '').strip()
        if not spreadsheet_id:
            raise RuntimeError('Google Sheets create response did not include spreadsheet ID')
        sheet_meta = _bulk_manifest_google_ensure_manifest_sheet(
            spreadsheet_id,
            token,
            desired_title=desired_tab_title,
            allow_rename_singleton=allow_rename_singleton
        )

    _bulk_manifest_google_write_sheet_rows(
        sheet_meta['spreadsheet_id'],
        sheet_meta['sheet_title'],
        rows,
        token
    )
    _bulk_manifest_google_style_sheet(
        sheet_meta['spreadsheet_id'],
        sheet_meta['sheet_id'],
        sheet_meta['sheet_title'],
        sheet_title,
        token,
        update_spreadsheet_title=update_spreadsheet_title,
        row_count=len(rows or []),
        image_row_indexes=image_row_indexes,
        emphasis_row_indexes=emphasis_row_indexes,
        header_row_index=header_row_index,
        frozen_row_count=frozen_row_count
    )
    return sheet_meta

def _bulk_manifest_google_job_get(manifest_id):
    manifest_key = max(0, _coerce_int(manifest_id, 0))
    with _bulk_manifest_google_jobs_lock:
        job = _bulk_manifest_google_jobs.get(manifest_key)
        return dict(job) if isinstance(job, dict) else None

def _bulk_manifest_google_job_set(manifest_id, **updates):
    manifest_key = max(0, _coerce_int(manifest_id, 0))
    with _bulk_manifest_google_jobs_lock:
        current = dict(_bulk_manifest_google_jobs.get(manifest_key) or {})
        current.update(updates)
        current['manifest_id'] = manifest_key
        _bulk_manifest_google_jobs[manifest_key] = current
        return dict(current)

def _bulk_manifest_google_job_clear(manifest_id):
    manifest_key = max(0, _coerce_int(manifest_id, 0))
    with _bulk_manifest_google_jobs_lock:
        _bulk_manifest_google_jobs.pop(manifest_key, None)

def _bulk_manifest_google_delete_sheet_resource(manifest_id, spreadsheet_id, token):
    spreadsheet_id = str(spreadsheet_id or '').strip()
    if not spreadsheet_id:
        return
    shared_workbook_id = _bulk_manifest_google_shared_spreadsheet_id()
    using_shared_workbook = bool(shared_workbook_id and spreadsheet_id == shared_workbook_id)
    if using_shared_workbook:
        worksheet_title = _bulk_manifest_google_tab_title(manifest_id, shared_mode=True)
        meta = _bulk_manifest_google_get_spreadsheet(spreadsheet_id, token)
        sheets = meta.get('sheets') if isinstance(meta, dict) else []
        target_sheet_id = -1
        sheet_count = 0
        if isinstance(sheets, list):
            sheet_count = len(sheets)
            for sheet in sheets:
                props = sheet.get('properties') if isinstance(sheet, dict) else {}
                if str((props or {}).get('title') or '').strip() == worksheet_title:
                    target_sheet_id = _coerce_int((props or {}).get('sheetId'), -1)
                    break
        if target_sheet_id < 0:
            return
        if sheet_count <= 1:
            _bulk_manifest_google_request(
                'POST',
                f'https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}/values:batchClear',
                token=token,
                json_body={
                    'ranges': [_bulk_manifest_google_sheet_range(worksheet_title, 'A:Z')]
                }
            )
            return
        _bulk_manifest_google_request(
            'POST',
            f'https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}:batchUpdate',
            token=token,
            json_body={
                'requests': [{
                    'deleteSheet': {'sheetId': target_sheet_id}
                }]
            }
        )
        return
    _bulk_manifest_google_request(
        'DELETE',
        f'https://www.googleapis.com/drive/v3/files/{spreadsheet_id}',
        token=token
    )

def _bulk_manifest_google_delete_manifest(manifest_id):
    manifest_key = max(0, _coerce_int(manifest_id, 0))
    with db_connection('marketplace.db') as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        _ensure_bulk_manifest_tables(cur)
        cur.execute('''
            SELECT id, manifest_title, google_sheet_id, google_sheet_url
            FROM bulk_manifests
            WHERE id = ?
        ''', (manifest_key,))
        manifest_row = cur.fetchone()
        if not manifest_row:
            raise LookupError('Manifest not found')
        manifest = dict(manifest_row)

    spreadsheet_id = str(manifest.get('google_sheet_id') or '').strip()
    sheet_url = str(manifest.get('google_sheet_url') or '').strip()
    if not spreadsheet_id and not sheet_url:
        _bulk_manifest_google_job_clear(manifest_key)
        return {
            'success': True,
            'manifest_id': manifest_key,
            'deleted': False,
            'status': 'idle'
        }

    token = _bulk_manifest_google_access_token()
    try:
        _bulk_manifest_google_delete_sheet_resource(manifest_key, spreadsheet_id, token)
    except Exception as exc:
        detail = str(exc).strip().lower()
        ignorable = (
            'requested entity was not found',
            'not found',
            'does not exist',
            'insufficient permissions'
        )
        if not any(signal in detail for signal in ignorable):
            raise

    now_iso = datetime.datetime.now().isoformat()
    with db_connection('marketplace.db') as conn:
        cur = conn.cursor()
        _ensure_bulk_manifest_tables(cur)
        cur.execute('''
            UPDATE bulk_manifests
            SET google_sheet_id = '',
                google_sheet_url = '',
                google_sheet_exported_at = '',
                google_sheet_shared_with = '',
                updated_at = ?
            WHERE id = ?
        ''', (now_iso, manifest_key))

    _bulk_manifest_google_job_clear(manifest_key)
    return {
        'success': True,
        'manifest_id': manifest_key,
        'deleted': True,
        'status': 'idle'
    }

def _bulk_manifest_google_state(manifest_id, row=None):
    manifest_key = max(0, _coerce_int(manifest_id, 0))
    source = row if isinstance(row, dict) else {}
    job = _bulk_manifest_google_job_get(manifest_key) or {}

    db_sheet_id = str(source.get('google_sheet_id') or '').strip()
    db_sheet_url = str(source.get('google_sheet_url') or '').strip()
    db_exported_at = str(source.get('google_sheet_exported_at') or '').strip()
    db_shared_with = str(source.get('google_sheet_shared_with') or '').strip()

    job_status = str(job.get('status') or '').strip().lower()
    sheet_id = str(job.get('sheet_id') or db_sheet_id).strip()
    sheet_url = str(job.get('sheet_url') or db_sheet_url).strip()
    exported_at = str(job.get('exported_at') or db_exported_at).strip()
    shared_with = str(job.get('shared_with') or db_shared_with).strip()
    available = bool(sheet_url)

    if job_status in ('queued', 'processing'):
        status = job_status
    elif job_status == 'error':
        status = 'error'
    elif available:
        status = 'ready'
    else:
        status = 'idle'

    if status in ('queued', 'processing'):
        button_label = 'Updating Sheet...' if available else 'Creating Sheet...'
    elif available:
        button_label = 'Google Sheet'
    else:
        button_label = 'Create Sheet'

    return {
        'google_sheet_status': status,
        'google_sheet_available': available,
        'google_sheet_button_label': button_label,
        'google_sheet_button_tone': ('primary' if available else 'default'),
        'google_sheet_id': sheet_id,
        'google_sheet_url': sheet_url,
        'google_sheet_exported_at': exported_at,
        'google_sheet_shared_with': shared_with,
        'google_sheet_error': str(job.get('error') or '').strip() if status == 'error' else ''
    }

def _bulk_manifest_queue_google_export(manifest_id, origin_base='', manifest_title='', force_refresh=False):
    manifest_key = max(0, _coerce_int(manifest_id, 0))
    origin_base = str(origin_base or '').strip().rstrip('/')
    manifest_title = str(manifest_title or '').strip()

    active_job = _bulk_manifest_google_job_get(manifest_key) or {}
    active_status = str(active_job.get('status') or '').strip().lower()
    if active_status in ('queued', 'processing'):
        if force_refresh:
            _bulk_manifest_google_job_set(
                manifest_key,
                refresh_pending=True,
                origin_base=origin_base or str(active_job.get('origin_base') or '').strip(),
                manifest_title=manifest_title or str(active_job.get('manifest_title') or '').strip()
            )
        return _bulk_manifest_google_status_payload(manifest_key)

    _bulk_manifest_google_job_set(
        manifest_key,
        status='queued',
        started_at=datetime.datetime.now().isoformat(),
        finished_at='',
        error='',
        sheet_id=str(active_job.get('sheet_id') or '').strip(),
        sheet_url=str(active_job.get('sheet_url') or '').strip(),
        shared_with=str(active_job.get('shared_with') or '').strip(),
        exported_at=str(active_job.get('exported_at') or '').strip(),
        origin_base=origin_base,
        manifest_title=manifest_title,
        refresh_pending=False
    )
    worker = threading.Thread(
        target=_bulk_manifest_google_export_worker,
        args=(manifest_key, origin_base),
        daemon=True
    )
    worker.start()
    return _bulk_manifest_google_status_payload(manifest_key)

def _bulk_manifest_google_manifest_meta(manifest_id):
    with db_connection('marketplace.db') as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        _ensure_bulk_manifest_tables(cur)
        cur.execute('''
            SELECT
                id,
                manifest_title,
                google_sheet_id,
                google_sheet_url,
                google_sheet_exported_at,
                google_sheet_shared_with
            FROM bulk_manifests
            WHERE id = ?
        ''', (manifest_id,))
        row = cur.fetchone()
        if not row:
            raise LookupError('Manifest not found')
        row = dict(row)
        return {
            'manifest_id': max(0, _coerce_int(row.get('id'), 0)),
            'manifest_title': str(row.get('manifest_title') or '').strip(),
            'sheet_id': str(row.get('google_sheet_id') or '').strip(),
            'sheet_url': str(row.get('google_sheet_url') or '').strip(),
            'shared_with': str(row.get('google_sheet_shared_with') or '').strip(),
            'exported_at': str(row.get('google_sheet_exported_at') or '').strip()
        }

def _bulk_manifest_google_export_manifest(manifest_id, origin_base=''):
    with db_connection('marketplace.db') as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        try:
            manifest, items = _bulk_manifest_load_detail(cur, manifest_id)
        except LookupError:
            raise LookupError('Manifest not found')

    if not items:
        raise RuntimeError('Manifest has no line items to export')

    token = _bulk_manifest_google_access_token()
    sheet_data = _bulk_manifest_build_google_sheet_rows(manifest, items, origin_base=origin_base)
    rows = list((sheet_data or {}).get('rows') or [])
    image_row_indexes = list((sheet_data or {}).get('image_row_indexes') or [])
    emphasis_row_indexes = list((sheet_data or {}).get('emphasis_row_indexes') or [])
    header_row_index = _coerce_int((sheet_data or {}).get('header_row_index'), 0)
    frozen_row_count = _coerce_int((sheet_data or {}).get('frozen_row_count'), 1)
    sheet_title = str((manifest or {}).get('manifest_title') or f'Bulk Manifest {manifest_id}').strip() or f'Bulk Manifest {manifest_id}'
    sheet_title = f'{sheet_title} Digital Export'
    shared_workbook_id = _bulk_manifest_google_shared_spreadsheet_id()
    configured_sheet_id = str((manifest or {}).get('google_sheet_id') or '').strip()
    target_spreadsheet_id = configured_sheet_id or shared_workbook_id
    using_shared_workbook = bool(shared_workbook_id and target_spreadsheet_id == shared_workbook_id)
    worksheet_title = _bulk_manifest_google_tab_title(manifest_id, shared_mode=using_shared_workbook)

    exported = _bulk_manifest_google_export_sheet(
        target_spreadsheet_id,
        sheet_title,
        rows,
        token,
        worksheet_title=worksheet_title,
        update_spreadsheet_title=(not using_shared_workbook),
        allow_rename_singleton=(not using_shared_workbook),
        image_row_indexes=image_row_indexes,
        emphasis_row_indexes=emphasis_row_indexes,
        header_row_index=header_row_index,
        frozen_row_count=frozen_row_count
    )
    spreadsheet_id = str(exported.get('spreadsheet_id') or '').strip()
    worksheet_id = max(0, _coerce_int(exported.get('sheet_id'), 0))
    sheet_url = str(exported.get('spreadsheet_url') or '').strip() or f'https://docs.google.com/spreadsheets/d/{spreadsheet_id}/edit'
    if using_shared_workbook and spreadsheet_id and worksheet_id > 0:
        sheet_url = f'https://docs.google.com/spreadsheets/d/{spreadsheet_id}/edit#gid={worksheet_id}'
    if not spreadsheet_id or not sheet_url:
        raise RuntimeError('Google Sheets export did not return a spreadsheet link')
    shared_with = ''
    if not using_shared_workbook:
        shared_with = _bulk_manifest_google_share_sheet(spreadsheet_id, token)

    now_iso = datetime.datetime.now().isoformat()
    with db_connection('marketplace.db') as conn:
        cur = conn.cursor()
        _ensure_bulk_manifest_tables(cur)
        cur.execute('''
            UPDATE bulk_manifests
            SET google_sheet_id = ?,
                google_sheet_url = ?,
                google_sheet_exported_at = ?,
                google_sheet_shared_with = ?,
                updated_at = ?
            WHERE id = ?
        ''', (
            spreadsheet_id,
            sheet_url,
            now_iso,
            shared_with,
            now_iso,
            manifest_id
        ))

    return {
        'success': True,
        'status': 'ready',
        'manifest_id': manifest_id,
        'sheet_id': spreadsheet_id,
        'sheet_url': sheet_url,
        'shared_with': shared_with,
        'exported_at': now_iso
    }

def _bulk_manifest_google_export_worker(manifest_id, origin_base=''):
    started_at = datetime.datetime.now().isoformat()
    logger.info('bulk_manifest_google_export_worker started for manifest %s', manifest_id)
    _bulk_manifest_google_job_set(
        manifest_id,
        status='processing',
        started_at=started_at,
        finished_at='',
        error=''
    )
    with app.app_context():
        try:
            result = _bulk_manifest_google_export_manifest(manifest_id, origin_base=origin_base)
            result = dict(result or {})
            result.pop('manifest_id', None)
            job_state = _bulk_manifest_google_job_set(
                manifest_id,
                finished_at=datetime.datetime.now().isoformat(),
                error='',
                **result
            )
            if job_state.get('refresh_pending'):
                next_origin_base = str(job_state.get('origin_base') or origin_base).strip().rstrip('/')
                next_title = str(job_state.get('manifest_title') or '').strip()
                _bulk_manifest_google_job_set(
                    manifest_id,
                    status='queued',
                    finished_at='',
                    error='',
                    refresh_pending=False,
                    origin_base=next_origin_base,
                    manifest_title=next_title
                )
                threading.Thread(
                    target=_bulk_manifest_google_export_worker,
                    args=(manifest_id, next_origin_base),
                    daemon=True
                ).start()
                logger.info('bulk_manifest_google_export_worker requeued refresh for manifest %s', manifest_id)
                return
            logger.info('bulk_manifest_google_export_worker ready for manifest %s', manifest_id)
        except LookupError:
            _bulk_manifest_google_job_set(
                manifest_id,
                status='error',
                error='Manifest not found',
                finished_at=datetime.datetime.now().isoformat()
            )
            logger.warning('bulk_manifest_google_export_worker manifest not found: %s', manifest_id)
        except Exception as exc:
            logger.warning('bulk_manifest_google_export_worker failed for manifest %s: %s', manifest_id, exc, exc_info=True)
            _bulk_manifest_google_job_set(
                manifest_id,
                status='error',
                error=str(exc).strip() or 'Google Sheet export failed',
                finished_at=datetime.datetime.now().isoformat()
            )

def _bulk_manifest_google_status_payload(manifest_id):
    job = _bulk_manifest_google_job_get(manifest_id) or {}
    status = str(job.get('status') or '').strip().lower()
    if status:
        state = _bulk_manifest_google_state(manifest_id)
        payload = {
            'success': state['google_sheet_status'] != 'error',
            'status': state['google_sheet_status'],
            'manifest_id': manifest_id,
            'sheet_id': state['google_sheet_id'],
            'sheet_url': state['google_sheet_url'],
            'shared_with': state['google_sheet_shared_with'],
            'exported_at': state['google_sheet_exported_at'],
            'manifest_title': str(job.get('manifest_title') or '').strip()
        }
        payload['button_label'] = state['google_sheet_button_label']
        payload['button_tone'] = state['google_sheet_button_tone']
        payload['sheet_available'] = state['google_sheet_available']
        if state['google_sheet_status'] == 'error':
            payload['error'] = state['google_sheet_error'] or 'Google Sheet export failed'
        return payload

    meta = _bulk_manifest_google_manifest_meta(manifest_id)
    state = _bulk_manifest_google_state(manifest_id, row={
        'google_sheet_id': meta.get('sheet_id'),
        'google_sheet_url': meta.get('sheet_url'),
        'google_sheet_exported_at': meta.get('exported_at'),
        'google_sheet_shared_with': meta.get('shared_with')
    })
    payload = {
        'success': state['google_sheet_status'] != 'error',
        'status': state['google_sheet_status'],
        'manifest_id': manifest_id,
        'sheet_id': state['google_sheet_id'],
        'sheet_url': state['google_sheet_url'],
        'shared_with': state['google_sheet_shared_with'],
        'exported_at': state['google_sheet_exported_at'],
        'manifest_title': str(meta.get('manifest_title') or '').strip()
    }
    payload['button_label'] = state['google_sheet_button_label']
    payload['button_tone'] = state['google_sheet_button_tone']
    payload['sheet_available'] = state['google_sheet_available']
    if state['google_sheet_status'] == 'error':
        payload['error'] = state['google_sheet_error'] or 'Google Sheet export failed'
    return payload

def _bulk_manifest_normalize_image_url(raw_value, origin_base=''):
    url = str(raw_value or '').strip()
    if not url:
        return ''
    low = url.lower()
    if low in ('nan', 'none', 'null', 'undefined'):
        return ''
    base = str(origin_base or '').strip().rstrip('/')
    if url.startswith('/') and base:
        url = base + url
    if url.startswith('//'):
        url = 'https:' + url
    if url.startswith('http://'):
        url = 'https://' + url[len('http://'):]
    return url

def _bulk_manifest_is_macy_image_host(hostname):
    host = str(hostname or '').strip().lower()
    return ('macys.com' in host) or ('bloomingdales.com' in host)

def _bulk_manifest_macy_thumb_url(image_url, origin_base=''):
    normalized = _bulk_manifest_normalize_image_url(image_url, origin_base=origin_base)
    if not normalized:
        return ''
    try:
        from urllib.parse import urlparse, parse_qsl, urlencode, urlunparse
        parsed = urlparse(normalized)
        if _bulk_manifest_is_macy_image_host(parsed.hostname):
            query = dict(parse_qsl(parsed.query, keep_blank_values=True))
            query['wid'] = '180'
            query['hei'] = '220'
            query['fmt'] = 'jpeg'
            query['qlt'] = '85'
            query['op_sharpen'] = '1'
            return urlunparse(parsed._replace(query=urlencode(query)))
    except Exception:
        pass
    return normalized

def _bulk_manifest_macy_full_image_url(image_url, origin_base=''):
    normalized = _bulk_manifest_normalize_image_url(image_url, origin_base=origin_base)
    if not normalized:
        return ''
    try:
        from urllib.parse import urlparse, urlunparse
        parsed = urlparse(normalized)
        if _bulk_manifest_is_macy_image_host(parsed.hostname):
            return urlunparse(parsed._replace(query=''))
    except Exception:
        pass
    return normalized

def _bulk_manifest_google_image_formula(url, origin_base='', width=None, height=None):
    normalized = _bulk_manifest_normalize_image_url(url, origin_base=origin_base)
    if not normalized:
        return ''
    escaped = normalized.replace('"', '""')
    width = _coerce_int(width, 0)
    height = _coerce_int(height, 0)
    if width > 0 and height > 0:
        return f'=IMAGE("{escaped}",4,{height},{width})'
    return f'=IMAGE("{escaped}")'

def _bulk_manifest_google_link_formula(url, label='Open', origin_base=''):
    normalized = _bulk_manifest_normalize_image_url(url, origin_base=origin_base)
    if not normalized:
        return ''
    escaped_url = normalized.replace('"', '""')
    escaped_label = str(label or 'Open').replace('"', '""')
    return f'=HYPERLINK("{escaped_url}","{escaped_label}")'

def _bulk_manifest_load_detail(cur, manifest_id):
    _ensure_bulk_manifest_tables(cur)

    cur.execute('SELECT * FROM bulk_manifests WHERE id = ?', (manifest_id,))
    manifest_row = cur.fetchone()
    if not manifest_row:
        raise LookupError('Manifest not found')

    cur.execute('''
        SELECT
            id,
            line_number,
            barcode,
            title,
            quantity,
            unit_price,
            line_total,
            image_url,
            lot_number,
            created_at
        FROM bulk_manifest_items
        WHERE manifest_id = ?
        ORDER BY line_number ASC, id ASC
    ''', (manifest_id,))
    item_rows = [dict(r) for r in cur.fetchall()]

    manifest = dict(manifest_row)
    out_manifest = {
        'id': manifest.get('id'),
        'manifest_title': str(manifest.get('manifest_title') or '').strip(),
        'buyer': str(manifest.get('buyer') or '').strip(),
        'manifest_date': str(manifest.get('manifest_date') or '').strip(),
        'status': _bulk_manifest_status_key(manifest.get('status')),
        'total_items': max(0, _coerce_int(manifest.get('total_items'), 0)),
        'total_units': max(0, _coerce_int(manifest.get('total_units'), 0)),
        'total_original_retail': _bulk_manifest_money(manifest.get('total_original_retail'), default=0.0),
        'sold_total': _bulk_manifest_money(manifest.get('sold_total'), default=0.0),
        'sold_rows': max(0, _coerce_int(manifest.get('sold_rows'), 0)),
        'sold_at': str(manifest.get('sold_at') or '').strip(),
        'sold_session_id': str(manifest.get('sold_session_id') or '').strip(),
        'cleanup_at': str(manifest.get('cleanup_at') or '').strip(),
        'cleanup_note': str(manifest.get('cleanup_note') or '').strip(),
        'created_at': str(manifest.get('created_at') or '').strip(),
        'updated_at': str(manifest.get('updated_at') or '').strip(),
        'google_sheet_id': str(manifest.get('google_sheet_id') or '').strip(),
        'google_sheet_url': str(manifest.get('google_sheet_url') or '').strip(),
        'google_sheet_exported_at': str(manifest.get('google_sheet_exported_at') or '').strip(),
        'google_sheet_shared_with': str(manifest.get('google_sheet_shared_with') or '').strip()
    }
    sheet_state = _bulk_manifest_google_state(out_manifest.get('id'), row=out_manifest)
    out_manifest.update({
        'google_sheet_id': sheet_state['google_sheet_id'],
        'google_sheet_url': sheet_state['google_sheet_url'],
        'google_sheet_exported_at': sheet_state['google_sheet_exported_at'],
        'google_sheet_shared_with': sheet_state['google_sheet_shared_with'],
        'google_sheet_status': sheet_state['google_sheet_status'],
        'google_sheet_available': sheet_state['google_sheet_available'],
        'google_sheet_button_label': sheet_state['google_sheet_button_label'],
        'google_sheet_button_tone': sheet_state['google_sheet_button_tone'],
        'google_sheet_error': sheet_state['google_sheet_error']
    })

    items = []
    for row in item_rows:
        barcode = str(row.get('barcode') or '').strip()
        qty = max(1, _coerce_int(row.get('quantity'), 1))
        unit_price = _bulk_manifest_money(row.get('unit_price'), default=0.0)
        items.append({
            'id': row.get('id'),
            'line_number': max(1, _coerce_int(row.get('line_number'), len(items) + 1)),
            'barcode': barcode,
            'barcode_display': _format_upc_display(barcode),
            'title': str(row.get('title') or '').strip() or barcode,
            'quantity': qty,
            'unit_price': unit_price,
            'line_total': _bulk_manifest_money(row.get('line_total'), default=(qty * unit_price)),
            'image_url': str(row.get('image_url') or '').strip(),
            'lot_number': _normalize_lot_number(row.get('lot_number')),
            'created_at': str(row.get('created_at') or '').strip()
        })

    return out_manifest, items

def _bulk_manifest_build_google_sheet_rows(manifest, items, origin_base=''):
    manifest_id = max(0, _coerce_int((manifest or {}).get('id'), 0))
    title = str((manifest or {}).get('manifest_title') or f'Bulk Manifest {manifest_id}').strip() or f'Bulk Manifest {manifest_id}'

    rows = []
    image_row_indexes = []
    emphasis_row_indexes = []

    total_units = 0
    total_retail = Decimal('0.00')
    item_rows = list(items or [])
    prepared_rows = []
    for idx, row in enumerate(item_rows):
        qty = max(0, _coerce_int(row.get('quantity'), 0))
        unit_price = Decimal(str(_bulk_manifest_money(row.get('unit_price'), default=0.0)))
        line_total = (Decimal(qty) * unit_price).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        total_units += qty
        total_retail += line_total

        raw_image = str(row.get('image_url') or '').strip()
        if not raw_image:
            try:
                lookup = _bulk_manifest_lookup_rawbol(row.get('barcode'))
            except Exception:
                lookup = None
            raw_image = str((lookup or {}).get('image_url') or '').strip()
        raw_image = _bulk_manifest_normalize_image_url(raw_image, origin_base=origin_base)
        thumb_image = _bulk_manifest_macy_thumb_url(raw_image, origin_base=origin_base)
        full_image = _bulk_manifest_macy_full_image_url(raw_image, origin_base=origin_base)
        thumb_formula = _bulk_manifest_google_image_formula(
            thumb_image,
            origin_base=origin_base,
            width=100,
            height=122
        )
        full_link_formula = _bulk_manifest_google_link_formula(full_image, 'Open Full Size', origin_base=origin_base)
        prepared_rows.append({
            'row_number': idx + 1,
            'barcode': str(row.get('barcode') or '').strip(),
            'title': str(row.get('title') or '').strip() or 'item',
            'qty': qty,
            'display_price': f'{(line_total if qty > 1 else unit_price):.2f}',
            'emphasis': qty > 1,
            'thumb_formula': thumb_formula,
            'full_link_formula': full_link_formula
        })

    rows.append([
        'Total Items',
        total_units,
        '',
        '',
        'Total Retail Price',
        f'{total_retail.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP):.2f}',
        '',
        ''
    ])
    rows.append(['', '', '', '', '', '', '', ''])
    header_row_index = len(rows)
    rows.append([
        'Manifest Title',
        'Line #',
        'Barcode',
        'Item Name',
        'Qty',
        'Original Retail',
        'Macy Thumb (Sheets)',
        'Full Size Link (Sheets)'
    ])

    for prepared in prepared_rows:
        row_index = len(rows)
        if prepared['thumb_formula']:
            image_row_indexes.append(row_index)
        if prepared['emphasis']:
            emphasis_row_indexes.append(row_index)
        rows.append([
            title,
            prepared['row_number'],
            prepared['barcode'],
            prepared['title'],
            prepared['qty'],
            prepared['display_price'],
            prepared['thumb_formula'],
            prepared['full_link_formula']
        ])

    rows.append([
        '',
        '',
        'Total Items',
        total_units,
        'Total Retail Price',
        f'{total_retail.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP):.2f}',
        '',
        ''
    ])
    return {
        'rows': rows,
        'image_row_indexes': image_row_indexes,
        'emphasis_row_indexes': emphasis_row_indexes,
        'header_row_index': header_row_index,
        'frozen_row_count': header_row_index + 1
    }

@app.route('/api/bulk-manifest/create', methods=['POST'])
def api_bulk_manifest_create():
    """Persist a bulk manifest and its line items into marketplace.db."""
    try:
        data = request.get_json() or {}
        buyer = ''
        manifest_date = datetime.date.today().isoformat()
        raw_items = data.get('items') or []

        if not isinstance(raw_items, list) or not raw_items:
            return jsonify({'success': False, 'error': 'Manifest items are required'}), 400

        items, total_units, total_original_retail = _bulk_manifest_prepare_items(raw_items)

        if not items:
            return jsonify({'success': False, 'error': 'No valid manifest items to save'}), 400

        now_iso = datetime.datetime.now().isoformat()
        with db_connection('marketplace.db') as conn:
            cur = conn.cursor()
            _ensure_bulk_manifest_tables(cur)
            manifest_title = _bulk_manifest_next_title(cur)
            cur.execute('''
                INSERT INTO bulk_manifests (
                    manifest_title, buyer, manifest_date,
                    total_items, total_units, total_original_retail,
                    status, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, 'created', ?, ?)
            ''', (
                manifest_title,
                buyer,
                manifest_date,
                len(items),
                total_units,
                round(total_original_retail, 2),
                now_iso,
                now_iso
            ))
            manifest_id = cur.lastrowid

            for item in items:
                cur.execute('''
                    INSERT INTO bulk_manifest_items (
                        manifest_id, line_number, barcode, title, quantity,
                        unit_price, line_total, image_url, lot_number, created_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ''', (
                    manifest_id,
                    item['line_number'],
                    item['barcode'],
                    item['title'],
                    item['quantity'],
                    item['unit_price'],
                    item['line_total'],
                    item['image_url'],
                    item['lot_number'],
                    now_iso
                ))

        try:
            _bulk_manifest_queue_google_export(
                manifest_id,
                origin_base=str(request.host_url or '').strip().rstrip('/'),
                manifest_title=manifest_title,
                force_refresh=True
            )
        except Exception as queue_exc:
            logger.warning('bulk_manifest_create: failed to queue Google Sheet export for manifest %s: %s', manifest_id, queue_exc, exc_info=True)
        sheet_view = _bulk_manifest_google_state(manifest_id)

        return jsonify({
            'success': True,
            'manifest': {
                'id': manifest_id,
                'manifest_title': manifest_title,
                'buyer': buyer,
                'manifest_date': manifest_date,
                'status': 'created',
                'total_items': len(items),
                'total_units': total_units,
                'total_original_retail': round(total_original_retail, 2),
                'created_at': now_iso,
                'updated_at': now_iso,
                'google_sheet_id': sheet_view['google_sheet_id'],
                'google_sheet_status': sheet_view['google_sheet_status'],
                'google_sheet_url': sheet_view['google_sheet_url'],
                'google_sheet_exported_at': sheet_view['google_sheet_exported_at'],
                'google_sheet_shared_with': sheet_view['google_sheet_shared_with'],
                'google_sheet_button_label': sheet_view['google_sheet_button_label'],
                'google_sheet_button_tone': sheet_view['google_sheet_button_tone'],
                'google_sheet_available': sheet_view['google_sheet_available'],
                'google_sheet_error': sheet_view['google_sheet_error']
            }
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'bulk_manifest_create')}), 500

