def _listingagent_init_settings_table(cur):
    cur.execute('''
        CREATE TABLE IF NOT EXISTS listing_agent_settings (
            key TEXT PRIMARY KEY,
            value TEXT,
            updated_at TEXT
        )
    ''')

def _listingagent_get_settings():
    try:
        with db_connection('sync_settings.db') as conn:
            cur = conn.cursor()
            _listingagent_init_settings_table(cur)
            cur.execute('SELECT key, value FROM listing_agent_settings')
            rows = cur.fetchall()
            return {r['key']: r['value'] for r in rows}
    except Exception:
        return {}

def _listingagent_upsert_settings(settings: dict):
    now = datetime.datetime.now().isoformat()
    with db_connection('sync_settings.db') as conn:
        cur = conn.cursor()
        _listingagent_init_settings_table(cur)
        for k, v in (settings or {}).items():
            if not k:
                continue
            cur.execute('''
                INSERT INTO listing_agent_settings (key, value, updated_at)
                VALUES (?, ?, ?)
                ON CONFLICT(key) DO UPDATE SET
                    value = excluded.value,
                    updated_at = excluded.updated_at
            ''', (str(k), None if v is None else str(v), now))

def _listingagent_parse_float(val, default=None):
    try:
        if val is None:
            return default
        if isinstance(val, (int, float)):
            return float(val)
        s = str(val).strip()
        if s == '':
            return default
        return float(s)
    except Exception:
        return default

def _listingagent_parse_int(val, default=None):
    try:
        if val is None:
            return default
        if isinstance(val, bool):
            return default
        if isinstance(val, int):
            return int(val)
        s = str(val).strip()
        if s == '':
            return default
        return int(float(s))
    except Exception:
        return default

def _listagent_normalize_added_mode(val, default='my'):
    raw = (val or '').strip().lower().replace(' ', '_')
    if raw in ('auto', 'auto_added', 'autofill', 'automatic'):
        return 'auto'
    if raw in ('my', 'mine', 'my_added', 'manual', 'user'):
        return 'my'
    fallback = '' if default is None else str(default).strip().lower()
    if fallback not in ('my', 'auto', ''):
        fallback = 'my'
    return fallback

# -----------------------------
# Listing Agent - Listing Queue (listagent.db)
# -----------------------------

def _listagent_init_tables(cur):
    # listagent.db might be created after startup; ensure WAL gets enabled.
    try:
        cur.execute('PRAGMA journal_mode=WAL')
    except Exception:
        pass

    cur.execute('''
        CREATE TABLE IF NOT EXISTS listing_queue (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            upc TEXT NOT NULL,
            title TEXT,
            source TEXT,
            added_mode TEXT NOT NULL DEFAULT 'my',
            item_status TEXT,
            status TEXT NOT NULL DEFAULT 'queued',
            added_at TEXT NOT NULL,
            listed_at TEXT,
            listed_platform TEXT,
            listed_listing_id TEXT,
            listed_offer_id TEXT,
            listed_sku TEXT,
            listed_asin TEXT,
            listed_url TEXT,
            listed_ebay_at TEXT,
            listed_amazon_at TEXT,
            removed_at TEXT
        )
    ''')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_listing_queue_status_added_at ON listing_queue(status, added_at)')
    try:
        # Enforce only one active (queued) entry per UPC.
        cur.execute("CREATE UNIQUE INDEX IF NOT EXISTS uq_listing_queue_active_upc ON listing_queue(upc) WHERE status='queued'")
    except Exception:
        # Partial indexes require newer SQLite; degrade gracefully.
        pass
    try:
        # Keep done entries unique too (so queue stays clean).
        cur.execute("CREATE UNIQUE INDEX IF NOT EXISTS uq_listing_queue_done_upc ON listing_queue(upc) WHERE status='done'")
    except Exception:
        pass

    # Schema migration: add item_status for queue provenance (e.g., good/bad from list manager)
    try:
        cur.execute('PRAGMA table_info(listing_queue)')
        cols = []
        for r in cur.fetchall() or []:
            try:
                cols.append((r['name'] or '').lower())
            except Exception:
                try:
                    cols.append((r[1] or '').lower())
                except Exception:
                    pass
        if 'item_status' not in cols:
            cur.execute('ALTER TABLE listing_queue ADD COLUMN item_status TEXT')
        if 'listed_ebay_at' not in cols:
            cur.execute('ALTER TABLE listing_queue ADD COLUMN listed_ebay_at TEXT')
        if 'listed_amazon_at' not in cols:
            cur.execute('ALTER TABLE listing_queue ADD COLUMN listed_amazon_at TEXT')
        if 'removed_at' not in cols:
            cur.execute('ALTER TABLE listing_queue ADD COLUMN removed_at TEXT')
        if 'added_mode' not in cols:
            cur.execute("ALTER TABLE listing_queue ADD COLUMN added_mode TEXT NOT NULL DEFAULT 'my'")
    except Exception:
        pass

    # Legacy fix: manual queue adds from Item Manager were incorrectly tagged as auto.
    try:
        cur.execute("""
            UPDATE listing_queue
            SET added_mode = 'my'
            WHERE status IN ('queued', 'done')
              AND COALESCE(NULLIF(TRIM(source), ''), '') = 'list_manager'
              AND COALESCE(NULLIF(TRIM(added_mode), ''), 'my') = 'auto'
        """)
    except Exception:
        pass

    # Uploaded listing photos (mobile -> desktop)
    cur.execute('''
        CREATE TABLE IF NOT EXISTS listing_photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            upc TEXT NOT NULL,
            image_path TEXT NOT NULL,
            original_filename TEXT,
            size_bytes INTEGER,
            created_at TEXT NOT NULL
        )
    ''')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_listing_photos_upc_created_at ON listing_photos(upc, created_at, id)')

def _listagent_row_to_dict(row):
    if not row:
        return None
    try:
        return {k: row[k] for k in row.keys()}
    except Exception:
        try:
            return dict(row)
        except Exception:
            return None

def _listagent_now_iso():
    return datetime.datetime.now().isoformat()

# -----------------------------
# Listing Log (listinglog.db)
# -----------------------------

def _listinglog_init_tables(cur):
    # listinglog.db might be created after startup; ensure WAL gets enabled.
    try:
        cur.execute('PRAGMA journal_mode=WAL')
    except Exception:
        pass

    cur.execute('''
        CREATE TABLE IF NOT EXISTS listing_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            created_at TEXT NOT NULL,
            upc TEXT NOT NULL,
            platform TEXT NOT NULL,
            action TEXT NOT NULL,
            source TEXT,
            marketplace_id TEXT,
            listing_id TEXT,
            offer_id TEXT,
            sku TEXT,
            asin TEXT,
            url TEXT,
            title TEXT,
            price REAL,
            quantity INTEGER,
            success INTEGER NOT NULL DEFAULT 1,
            error TEXT,
            meta_json TEXT
        )
    ''')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_listing_log_upc_created_at ON listing_log(upc, created_at, id)')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_listing_log_platform_created_at ON listing_log(platform, created_at, id)')

def _listinglog_add_entry(*,
                          upc,
                          platform,
                          action='listed',
                          source='listingagent',
                          created_at=None,
                          marketplace_id=None,
                          listing_id=None,
                          offer_id=None,
                          sku=None,
                          asin=None,
                          url=None,
                          title=None,
                          price=None,
                          quantity=None,
                          success=True,
                          error=None,
                          meta=None):
    upc = (upc or '').strip()
    if not upc:
        raise ValueError('upc is required')

    platform = (platform or 'unknown').strip().lower() or 'unknown'
    action = (action or 'listed').strip().lower() or 'listed'
    source = (source or '').strip() or None
    created_at = (created_at or _listagent_now_iso()).strip()

    meta_json = None
    try:
        if meta is not None:
            meta_json = json.dumps(meta, ensure_ascii=False)
    except Exception:
        meta_json = None

    with db_connection('listinglog.db') as conn:
        cur = conn.cursor()
        _listinglog_init_tables(cur)
        cur.execute('''
            INSERT INTO listing_log (
                created_at, upc, platform, action, source, marketplace_id,
                listing_id, offer_id, sku, asin, url, title, price, quantity,
                success, error, meta_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ''', (
            created_at, upc, platform, action, source, (marketplace_id or None),
            (listing_id or None), (offer_id or None), (sku or None), (asin or None),
            (url or None), (title or None), price, quantity,
            1 if success else 0, (error or None), meta_json
        ))
        rid = cur.lastrowid
        cur.execute('SELECT * FROM listing_log WHERE id = ? LIMIT 1', (rid,))
        return _listagent_row_to_dict(cur.fetchone())

# -----------------------------
# Prep Log (preplog.db)
# -----------------------------

def _preplog_init_tables(cur):
    # preplog.db might be created after startup; ensure WAL gets enabled.
    try:
        cur.execute('PRAGMA journal_mode=WAL')
    except Exception:
        pass

    cur.execute('''
        CREATE TABLE IF NOT EXISTS prep_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            created_at TEXT NOT NULL,
            upc TEXT NOT NULL,
            base_upc TEXT,
            status TEXT NOT NULL,
            quantity INTEGER,
            note TEXT,
            reason TEXT,
            source TEXT,
            meta_json TEXT,
            undone INTEGER NOT NULL DEFAULT 0,
            undone_at TEXT,
            undo_error TEXT
        )
    ''')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_prep_log_created_at ON prep_log(created_at, id)')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_prep_log_upc_created_at ON prep_log(upc, created_at, id)')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_prep_log_undone_created_at ON prep_log(undone, created_at, id)')

def _preplog_add_entry(*,
                       upc,
                       status,
                       quantity=1,
                       created_at=None,
                       base_upc=None,
                       note=None,
                       reason=None,
                       source='item-prep',
                       meta=None,
                       dedupe=False):
    upc = (upc or '').strip()
    if not upc:
        raise ValueError('upc is required')

    status = (status or '').strip().lower()
    if status not in ('good', 'bad', 'unchecked', 'return'):
        raise ValueError('status must be good/bad/unchecked/return')

    created_at = (created_at or _listagent_now_iso()).strip()
    base_upc = (base_upc or '').strip() or None
    note = (note or '').strip() or None
    reason = (reason or '').strip() or None
    source = (source or '').strip() or None

    meta_json = None
    try:
        if meta is not None:
            meta_json = json.dumps(meta, ensure_ascii=False)
    except Exception:
        meta_json = None

    try:
        quantity = int(quantity) if quantity is not None else None
    except Exception:
        quantity = None

    with db_connection('preplog.db') as conn:
        cur = conn.cursor()
        _preplog_init_tables(cur)

        if dedupe:
            cur.execute('''
                SELECT id, meta_json
                FROM prep_log
                WHERE upc = ? COLLATE NOCASE
                  AND status = ?
                  AND undone = 0
                ORDER BY id DESC
                LIMIT 1
            ''', (upc, status))
            existing = cur.fetchone()
            if existing and (existing[0] is not None):
                rid = int(existing[0])
                existing_meta_json = existing[1] if len(existing) > 1 else None
                merged_meta_json = meta_json
                if existing_meta_json and meta_json:
                    try:
                        existing_meta = json.loads(existing_meta_json)
                        incoming_meta = json.loads(meta_json)
                        if isinstance(existing_meta, dict) and isinstance(incoming_meta, dict):
                            merged_meta = dict(existing_meta)
                            merged_meta.update(incoming_meta)
                            merged_meta_json = json.dumps(merged_meta, ensure_ascii=False)
                    except Exception:
                        merged_meta_json = meta_json
                cur.execute('''
                    UPDATE prep_log
                    SET created_at=?,
                        base_upc=COALESCE(?, base_upc),
                        quantity=COALESCE(?, quantity),
                        note=COALESCE(?, note),
                        reason=COALESCE(?, reason),
                        source=COALESCE(?, source),
                        meta_json=COALESCE(?, meta_json),
                        undo_error=NULL
                    WHERE id = ?
                ''', (created_at, base_upc, quantity, note, reason, source, merged_meta_json, rid))
                cur.execute('SELECT * FROM prep_log WHERE id = ? LIMIT 1', (rid,))
                return _listagent_row_to_dict(cur.fetchone())

        cur.execute('''
            INSERT INTO prep_log (
                created_at, upc, base_upc, status, quantity, note, reason, source, meta_json, undone
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
        ''', (created_at, upc, base_upc, status, quantity, note, reason, source, meta_json))
        rid = cur.lastrowid
        cur.execute('SELECT * FROM prep_log WHERE id = ? LIMIT 1', (rid,))
        return _listagent_row_to_dict(cur.fetchone())

def _preplog_recent(*, limit=200, include_undone=True):
    limit = int(limit or 200)
    limit = max(1, min(limit, 2000))
    with db_connection('preplog.db') as conn:
        cur = conn.cursor()
        _preplog_init_tables(cur)

        sql = 'SELECT * FROM prep_log WHERE 1=1'
        params = []
        if not include_undone:
            sql += ' AND undone = 0'
        sql += ' ORDER BY created_at DESC, id DESC LIMIT ?'
        params.append(limit)

        cur.execute(sql, params)
        return [_listagent_row_to_dict(r) for r in cur.fetchall()]

def _preplog_mark_undone(log_id: int, *, undone_at=None, undo_error=None):
    log_id = int(log_id)
    undone_at = (undone_at or _listagent_now_iso()).strip()
    undo_error = (undo_error or '').strip() or None

    with db_connection('preplog.db') as conn:
        cur = conn.cursor()
        _preplog_init_tables(cur)
        cur.execute('''
            UPDATE prep_log
            SET undone = 1,
                undone_at = ?,
                undo_error = ?
            WHERE id = ?
        ''', (undone_at, undo_error, log_id))
        cur.execute('SELECT * FROM prep_log WHERE id = ? LIMIT 1', (log_id,))
        return _listagent_row_to_dict(cur.fetchone())

def _preplog_set_undo_error(log_id: int, error: str):
    log_id = int(log_id)
    error = (error or '').strip() or None
    with db_connection('preplog.db') as conn:
        cur = conn.cursor()
        _preplog_init_tables(cur)
        cur.execute('UPDATE prep_log SET undo_error = ? WHERE id = ?', (error, log_id))
        cur.execute('SELECT * FROM prep_log WHERE id = ? LIMIT 1', (log_id,))
        return _listagent_row_to_dict(cur.fetchone())

def _preplog_meta_dict(entry):
    if not isinstance(entry, dict):
        return {}
    raw = entry.get('meta_json')
    if raw is None:
        return {}
    if isinstance(raw, dict):
        return raw
    try:
        parsed = json.loads(str(raw))
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}

def _listinglog_meta_dict(entry):
    if not isinstance(entry, dict):
        return {}
    raw = entry.get('meta_json')
    if raw is None:
        return {}
    if isinstance(raw, dict):
        return raw
    try:
        parsed = json.loads(str(raw))
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}

def _preplog_enrich_row(entry):
    row = dict(entry or {})
    meta = _preplog_meta_dict(row)
    lot_number = _normalize_lot_number(
        meta.get('lot_number') or
        meta.get('assigned_lot') or
        meta.get('lot')
    )
    requested_lot = _normalize_lot_number(meta.get('requested_lot') or meta.get('requested'))

    auto_assigned = meta.get('auto_assigned')
    if isinstance(auto_assigned, str):
        auto_assigned = auto_assigned.strip().lower() in ('1', 'true', 'yes', 'y')
    else:
        auto_assigned = bool(auto_assigned)

    if not auto_assigned and lot_number:
        if not requested_lot:
            auto_assigned = bool(meta.get('auto_assign_reason'))
        elif requested_lot.lower() != lot_number.lower():
            auto_assigned = True

    row['meta'] = meta
    row['lot_number'] = lot_number
    row['requested_lot'] = requested_lot
    row['auto_assigned'] = bool(auto_assigned)
    return row

def _preplog_update_meta(log_id: int, meta: dict):
    log_id = int(log_id)
    payload = {}
    if isinstance(meta, dict):
        payload = meta
    meta_json = json.dumps(payload, ensure_ascii=False)
    with db_connection('preplog.db') as conn:
        cur = conn.cursor()
        _preplog_init_tables(cur)
        cur.execute('UPDATE prep_log SET meta_json = ? WHERE id = ?', (meta_json, log_id))
        cur.execute('SELECT * FROM prep_log WHERE id = ? LIMIT 1', (log_id,))
        row = cur.fetchone()
        return _preplog_enrich_row(_listagent_row_to_dict(row))

def _preplog_auto_assigned_entries(*, include_undone=False, lot_number='', limit=None):
    lot_filter = _normalize_lot_number(lot_number)
    with db_connection('preplog.db') as conn:
        cur = conn.cursor()
        _preplog_init_tables(cur)
        sql = 'SELECT * FROM prep_log WHERE 1=1'
        params = []
        if not include_undone:
            sql += ' AND undone = 0'
        sql += ' ORDER BY created_at DESC, id DESC'
        if limit is not None:
            try:
                lim = int(limit)
            except Exception:
                lim = 500
            lim = max(1, min(lim, 5000))
            sql += ' LIMIT ?'
            params.append(lim)
        cur.execute(sql, params)
        rows = [_preplog_enrich_row(_listagent_row_to_dict(r)) for r in cur.fetchall()]

    filtered = []
    for row in rows:
        if not row.get('auto_assigned'):
            continue
        if lot_filter and _normalize_lot_number(row.get('lot_number')).lower() != lot_filter.lower():
            continue
        filtered.append(row)
    return filtered

def _preplog_attach_titles(items):
    """Attach `item_title` to prep-log rows, preferring bol.db then rawbol.db."""
    rows = [dict(it or {}) for it in (items or [])]
    if not rows:
        return rows

    def _norm_upc(value):
        try:
            return _normalize_upc_preserve_suffix_for_match(_normalize_upc(value))
        except Exception:
            return str(value or '').strip()

    upcs = []
    seen = set()

    def _add_upc(v):
        u = _norm_upc(v)
        if u and u not in seen:
            seen.add(u)
            upcs.append(u)

    for row in rows:
        upc = _norm_upc(row.get('upc'))
        if not upc:
            continue
        _add_upc(upc)
        base_upc = (str(row.get('base_upc') or '').strip() or (upc.split('-', 1)[0] if '-' in upc else upc))
        _add_upc(base_upc)

    if not upcs:
        return rows

    def _chunked(seq, size=350):
        for i in range(0, len(seq), size):
            yield seq[i:i+size]

    bol_title_map = {}
    try:
        with db_connection('bol.db') as conn:
            cur = conn.cursor()
            for chunk in _chunked(upcs):
                placeholders = ','.join('?' for _ in chunk)
                cur.execute(f'''
                    SELECT upc, item_description
                    FROM bol_items
                    WHERE upc IN ({placeholders})
                    ORDER BY import_date DESC, id DESC
                ''', tuple(chunk))
                for rr in cur.fetchall():
                    key = _norm_upc(rr['upc'] if isinstance(rr, sqlite3.Row) else rr[0])
                    title = ((rr['item_description'] if isinstance(rr, sqlite3.Row) else rr[1]) or '').strip()
                    if key and title and key not in bol_title_map:
                        bol_title_map[key] = title
    except Exception:
        bol_title_map = {}

    raw_title_map = {}
    try:
        with db_connection('rawbol.db') as conn:
            cur = conn.cursor()
            for chunk in _chunked(upcs):
                placeholders = ','.join('?' for _ in chunk)
                cur.execute(f'''
                    SELECT upc, item_description
                    FROM raw_bol_items
                    WHERE upc IN ({placeholders})
                ''', tuple(chunk))
                for rr in cur.fetchall():
                    key = _norm_upc(rr['upc'] if isinstance(rr, sqlite3.Row) else rr[0])
                    title = ((rr['item_description'] if isinstance(rr, sqlite3.Row) else rr[1]) or '').strip()
                    if key and title and key not in raw_title_map:
                        raw_title_map[key] = title
    except Exception:
        raw_title_map = {}

    for row in rows:
        upc = _norm_upc(row.get('upc'))
        base_upc = (str(row.get('base_upc') or '').strip() or (upc.split('-', 1)[0] if '-' in upc else upc))
        meta = row.get('meta') if isinstance(row.get('meta'), dict) else {}
        meta_title = str(meta.get('title') or meta.get('item_description') or '').strip()
        item_title = (
            bol_title_map.get(upc) or
            bol_title_map.get(base_upc) or
            raw_title_map.get(upc) or
            raw_title_map.get(base_upc) or
            meta_title or
            upc
        )
        row['item_title'] = item_title

    return rows

def _preplog_apply_quantity_change(entry, *, old_qty, new_qty):
    """Apply prep-log quantity edits to backing bol/items_prep rows."""
    try:
        old_qty_n = int(old_qty if old_qty is not None else 1)
    except Exception:
        old_qty_n = 1
    try:
        new_qty_n = int(new_qty if new_qty is not None else old_qty_n)
    except Exception:
        return False, 'Invalid quantity'
    if old_qty_n < 1:
        old_qty_n = 1
    if new_qty_n < 1:
        return False, 'Quantity must be at least 1'
    if new_qty_n == old_qty_n:
        return True, None

    row = _preplog_enrich_row(entry or {})
    status = str(row.get('status') or '').strip().lower()
    if status not in ('good', 'bad', 'return'):
        return False, 'Unsupported status for quantity edit'

    upc = _normalize_upc_preserve_suffix_for_match(_normalize_upc(row.get('upc')))
    if not upc:
        return False, 'Missing UPC on log entry'
    base_upc = (
        _normalize_upc_preserve_suffix_for_match(_normalize_upc(row.get('base_upc')))
        or (upc.split('-', 1)[0] if '-' in upc else upc)
    )
    lot_hint = _normalize_lot_number(row.get('lot_number'))
    meta = dict(row.get('meta') or {})
    action = str(meta.get('action') or '').strip().lower()
    affects_base_good = bool(_coerce_bool(meta.get('affects_base_good'))) or action in (
        'saved_good_suffixed',
        'special_good_suffixed',
        'good_suffixed',
    )
    note = str(row.get('note') or '').strip()
    reason = str(row.get('reason') or '').strip()
    delta = new_qty_n - old_qty_n

    conn = None
    try:
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        _ensure_items_prep_tables()
        ts = _listagent_now_iso()

        if not lot_hint and _has_multiple_lot_rows(cur, upc):
            return False, (
                f'Cannot edit quantity for {upc} without LOT context. '
                'This UPC exists in multiple LOTs.'
            )

        def _pick_bol_row(target_upc, preferred_lot=''):
            lot_n = _normalize_lot_number(preferred_lot)
            if lot_n:
                cur.execute('''
                    SELECT id, upc, lot_number, original_qty, good_qty, bad_qty, unchecked_qty, quantity
                    FROM bol_items
                    WHERE upc = ? COLLATE NOCASE
                      AND lot_number = ? COLLATE NOCASE
                    ORDER BY import_date DESC, id DESC
                    LIMIT 1
                ''', (target_upc, lot_n))
                row_local = cur.fetchone()
                if row_local:
                    return row_local
                # Legacy fallback only: lot-less row for this UPC.
                cur.execute('''
                    SELECT id, upc, lot_number, original_qty, good_qty, bad_qty, unchecked_qty, quantity
                    FROM bol_items
                    WHERE upc = ? COLLATE NOCASE
                      AND COALESCE(lot_number, '') = ''
                    ORDER BY import_date DESC, id DESC
                    LIMIT 1
                ''', (target_upc,))
                row_local = cur.fetchone()
                if row_local:
                    return row_local
                # Lot-aware edits must not spill into a different lot.
                return None
            cur.execute('''
                SELECT id, upc, lot_number, original_qty, good_qty, bad_qty, unchecked_qty, quantity
                FROM bol_items
                WHERE upc = ? COLLATE NOCASE
                ORDER BY import_date DESC, id DESC
                LIMIT 1
            ''', (target_upc,))
            return cur.fetchone()

        def _effective_unchecked(row_local):
            unchecked_local = row_local[6]
            if unchecked_local is not None:
                return int(unchecked_local or 0)
            original_local = int(row_local[3] or 0)
            good_local = int(row_local[4] or 0)
            bad_local = int(row_local[5] or 0)
            return max(0, original_local - good_local - bad_local)

        def _upsert_status_qty(target_upc, target_lot, target_status, target_reason, target_note, qty_local):
            lot_key = _resolve_prep_status_lot(cur, target_upc, target_lot)
            cur.execute('''
                UPDATE items_prep_status
                SET status = ?, reason = ?, note = ?, quantity = ?, updated_at = ?
                WHERE upc = ? COLLATE NOCASE
                  AND COALESCE(lot_number, '') = ? COLLATE NOCASE
            ''', (target_status, target_reason, target_note, qty_local, ts, target_upc, lot_key))
            if cur.rowcount == 0:
                cur.execute('''
                    INSERT INTO items_prep_status (upc, lot_number, status, reason, note, quantity, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?)
                ''', (target_upc, _normalize_lot_number(target_lot), target_status, target_reason, target_note, qty_local, ts))

        target_row = _pick_bol_row(upc, lot_hint)
        if not target_row:
            return False, f'Item {upc} not found'
        target_id = int(target_row[0])
        target_lot = _normalize_lot_number(target_row[2]) or lot_hint
        is_suffixed = _is_items_to_list_suffixed_upc(upc)

        if status in ('bad', 'return') and not is_suffixed:
            return False, 'BAD and RETURN quantity edits require a suffixed UPC. Base UPC rows cannot be special entries.'

        if status == 'good':
            if is_suffixed:
                # Independent suffixed GOOD rows (including noted GOOD) hold their own qty.
                cur.execute('''
                    UPDATE bol_items
                    SET original_qty = ?, good_qty = ?, bad_qty = 0, unchecked_qty = 0, quantity = ?, temporary = 0
                    WHERE id = ?
                ''', (new_qty_n, new_qty_n, new_qty_n, target_id))

            # Base-tracked GOOD quantity (base rows + noted suffix rows that consume base unchecked).
            if (not is_suffixed) or affects_base_good:
                base_row = target_row if not is_suffixed else _pick_bol_row(base_upc, target_lot)
                if not base_row:
                    return False, f'Base UPC {base_upc} not found'
                base_id = int(base_row[0])
                base_good = int(base_row[4] or 0)
                base_unchecked = _effective_unchecked(base_row)
                if delta > 0 and base_unchecked < delta:
                    return False, f'Cannot increase quantity by {delta}: only {base_unchecked} unchecked available'
                new_base_good = max(0, base_good + delta)
                new_base_unchecked = max(0, base_unchecked - delta)
                cur.execute('''
                    UPDATE bol_items
                    SET good_qty = ?, unchecked_qty = ?
                    WHERE id = ?
                ''', (new_base_good, new_base_unchecked, base_id))

            _upsert_status_qty(upc, target_lot, 'good', reason, note, new_qty_n)

        elif status == 'bad':
            cur.execute('''
                UPDATE bol_items
                SET original_qty = ?, bad_qty = ?, good_qty = 0, unchecked_qty = 0, quantity = ?, temporary = 0
                WHERE id = ?
            ''', (new_qty_n, new_qty_n, new_qty_n, target_id))

            base_row = _pick_bol_row(base_upc, target_lot)
            if not base_row:
                return False, f'Base UPC {base_upc} not found'
            base_id = int(base_row[0])
            base_bad = int(base_row[5] or 0)
            base_unchecked = _effective_unchecked(base_row)
            if delta > 0 and base_unchecked < delta:
                return False, f'Cannot increase BAD quantity by {delta}: only {base_unchecked} unchecked available'
            new_base_bad = max(0, base_bad + delta)
            new_base_unchecked = max(0, base_unchecked - delta)
            cur.execute('''
                UPDATE bol_items
                SET bad_qty = ?, unchecked_qty = ?
                WHERE id = ?
            ''', (new_base_bad, new_base_unchecked, base_id))

            _upsert_status_qty(upc, target_lot, 'bad', reason, note, new_qty_n)

        elif status == 'return':
            cur.execute('''
                UPDATE bol_items
                SET original_qty = ?, good_qty = ?, bad_qty = 0, unchecked_qty = 0, quantity = ?, temporary = 0
                WHERE id = ?
            ''', (new_qty_n, new_qty_n, new_qty_n, target_id))

            base_row = _pick_bol_row(base_upc, target_lot)
            if not base_row:
                return False, f'Base UPC {base_upc} not found'
            base_id = int(base_row[0])
            base_unchecked = _effective_unchecked(base_row)
            if delta > 0 and base_unchecked < delta:
                return False, f'Cannot increase RETURN quantity by {delta}: only {base_unchecked} unchecked available'
            new_base_unchecked = max(0, base_unchecked - delta)
            cur.execute('''
                UPDATE bol_items
                SET unchecked_qty = ?
                WHERE id = ?
            ''', (new_base_unchecked, base_id))

            _upsert_status_qty(upc, target_lot, 'return', (reason or 'return'), note, new_qty_n)

        conn.commit()
        try:
            update_data_version()
        except Exception:
            pass
        return True, None
    except Exception as e:
        try:
            if conn:
                conn.rollback()
        except Exception:
            pass
        return False, _safe_error(e, 'preplog:apply_qty')
    finally:
        try:
            if conn:
                conn.close()
        except Exception:
            pass

def _listagent_format_upc12(value):
    s = (value or '').strip()
    if not s:
        return ''
    if '-' in s:
        base, suffix = s.split('-', 1)
    else:
        base, suffix = s, ''
    base = (base or '').strip()
    suffix = (suffix or '').strip()
    if base.isdigit() and len(base) <= 12:
        base = base.zfill(12)
    return f'{base}-{suffix}' if suffix else base

def _listagent_upc_variants(value):
    """Return tolerant UPC variants: padded/raw/stripped (preserving -suffix)."""
    raw = (value or '').strip()
    if not raw:
        return []
    formatted = _listagent_format_upc12(raw)
    out = []

    def add(v):
        vv = (v or '').strip()
        if vv and vv not in out:
            out.append(vv)

    add(formatted)
    add(raw)

    core = formatted or raw
    if '-' in core:
        base, suffix = core.split('-', 1)
    else:
        base, suffix = core, ''

    if base.isdigit():
        stripped = base.lstrip('0') or '0'
        add(f'{stripped}-{suffix}' if suffix else stripped)

    return out

def _listagent_add_to_queue(upc, *, title=None, source=None, item_status=None, added_mode=None):
    upc = _listagent_format_upc12(upc)
    if not upc:
        raise ValueError('upc is required')
    upc_variants = _listagent_upc_variants(upc)
    placeholders = ','.join('?' for _ in upc_variants)

    now = _listagent_now_iso()
    title = (title or '').strip() or None
    source = (source or '').strip() or None
    item_status = (item_status or '').strip().lower() or None
    added_mode = _listagent_normalize_added_mode(added_mode, default='my')

    with db_connection('listagent.db') as conn:
        cur = conn.cursor()
        _listagent_init_tables(cur)

        # If it already exists in the active list (queued or done), keep it and just fill metadata.
        cur.execute('''
            SELECT *
            FROM listing_queue
            WHERE upc IN (''' + placeholders + ''') AND status IN ('queued', 'done')
            ORDER BY added_at DESC, id DESC
            LIMIT 1
        ''', tuple(upc_variants))
        row = cur.fetchone()
        if row:
            qid = row['id']
            should_update_metadata = (
                title is not None or
                source is not None or
                item_status is not None or
                added_mode in ('my', 'auto')
            )
            if should_update_metadata:
                cur.execute('''
                    UPDATE listing_queue
                    SET
                        title = COALESCE(NULLIF(title, ''), ?),
                        source = COALESCE(NULLIF(source, ''), ?),
                        added_mode = COALESCE(?, COALESCE(NULLIF(TRIM(added_mode), ''), 'my')),
                        item_status = COALESCE(?, item_status)
                    WHERE id = ?
                ''', (title, source, added_mode, item_status, qid))
            cur.execute('SELECT * FROM listing_queue WHERE id = ? LIMIT 1', (qid,))
            return _listagent_row_to_dict(cur.fetchone()), False

        # If it was removed before, revive it (and clear any previous "listed" flags).
        cur.execute('''
            SELECT id
            FROM listing_queue
            WHERE upc IN (''' + placeholders + ''') AND status = 'removed'
            ORDER BY removed_at DESC, id DESC
            LIMIT 1
        ''', tuple(upc_variants))
        removed = cur.fetchone()
        if removed:
            qid = removed['id']
            cur.execute('''
                UPDATE listing_queue
                SET
                    status = 'queued',
                    added_at = ?,
                    removed_at = NULL,
                    title = COALESCE(?, title),
                    source = COALESCE(?, source),
                    added_mode = COALESCE(?, COALESCE(NULLIF(TRIM(added_mode), ''), 'my')),
                    item_status = COALESCE(?, item_status),
                    listed_at = NULL,
                    listed_platform = NULL,
                    listed_listing_id = NULL,
                    listed_offer_id = NULL,
                    listed_sku = NULL,
                    listed_asin = NULL,
                    listed_url = NULL,
                    listed_ebay_at = NULL,
                    listed_amazon_at = NULL
                WHERE id = ?
            ''', (now, title, source, added_mode, item_status, qid))
            cur.execute('SELECT * FROM listing_queue WHERE id = ? LIMIT 1', (qid,))
            return _listagent_row_to_dict(cur.fetchone()), True

        # Fresh insert
        cur.execute('''
            INSERT INTO listing_queue (upc, title, source, added_mode, item_status, status, added_at)
            VALUES (?, ?, ?, ?, ?, 'queued', ?)
        ''', (upc, title, source, added_mode, item_status, now))
        qid = cur.lastrowid
        cur.execute('SELECT * FROM listing_queue WHERE id = ? LIMIT 1', (qid,))
        return _listagent_row_to_dict(cur.fetchone()), True

def _listagent_get_queue(*, limit=50, added_mode=''):
    limit = int(limit or 50)
    limit = max(1, min(limit, 200))
    mode = _listagent_normalize_added_mode(added_mode, default='')
    if mode not in ('my', 'auto'):
        mode = ''
    with db_connection('listagent.db') as conn:
        cur = conn.cursor()
        _listagent_init_tables(cur)
        sql = '''
            SELECT *
            FROM listing_queue
            WHERE status IN ('queued', 'done')
        '''
        params = []
        if mode:
            sql += " AND COALESCE(NULLIF(TRIM(added_mode), ''), 'my') = ?"
            params.append(mode)
        sql += '''
            ORDER BY CASE WHEN status = 'done' THEN 1 ELSE 0 END, added_at DESC, id DESC
            LIMIT ?
        '''
        params.append(limit)
        cur.execute(sql, tuple(params))
        return [_listagent_row_to_dict(r) for r in cur.fetchall()]

def _listagent_get_queue_statuses(upcs, *, added_mode=''):
    mode = _listagent_normalize_added_mode(added_mode, default='')
    if mode not in ('my', 'auto'):
        mode = ''

    requested = []
    requested_seen = set()
    variant_to_requested = {}
    all_variants = []

    for raw in upcs or []:
        key = (raw or '').strip()
        if not key or key in requested_seen:
            continue
        requested_seen.add(key)
        requested.append(key)
        for variant in _listagent_upc_variants(key):
            if variant not in variant_to_requested:
                variant_to_requested[variant] = []
            if key not in variant_to_requested[variant]:
                variant_to_requested[variant].append(key)
            if variant not in all_variants:
                all_variants.append(variant)

    if not requested or not all_variants:
        return {}

    placeholders = ','.join('?' for _ in all_variants)
    with db_connection('listagent.db') as conn:
        cur = conn.cursor()
        _listagent_init_tables(cur)
        sql = '''
            SELECT *
            FROM listing_queue
            WHERE upc IN (''' + placeholders + ''')
              AND status IN ('queued', 'done')
        '''
        params = list(all_variants)
        if mode:
            sql += " AND COALESCE(NULLIF(TRIM(added_mode), ''), 'my') = ?"
            params.append(mode)
        sql += '''
            ORDER BY CASE WHEN status = 'queued' THEN 0 ELSE 1 END, added_at DESC, id DESC
        '''
        cur.execute(sql, tuple(params))
        rows = cur.fetchall()

    out = {}
    for row in rows:
        item = _listagent_row_to_dict(row)
        if not item:
            continue
        matched_requested = []
        for variant in _listagent_upc_variants(item.get('upc') or ''):
            matched_requested.extend(variant_to_requested.get(variant, []))
        for key in matched_requested:
            if key not in out:
                out[key] = item
    return out

def _listagent_mark_listed(upc, *, platform=None, listing_id=None, offer_id=None, sku=None, asin=None, url=None,
                           marketplace_id=None, title=None, price=None, quantity=None,
                           source='listingagent', action='listed', success=True, error=None, meta=None):
    upc = _listagent_format_upc12(upc)
    if not upc:
        raise ValueError('upc is required')
    upc_variants = _listagent_upc_variants(upc)
    placeholders = ','.join('?' for _ in upc_variants)

    now = _listagent_now_iso()
    platform = (platform or '').strip().lower() or None
    updated_item = None

    with db_connection('listagent.db') as conn:
        cur = conn.cursor()
        _listagent_init_tables(cur)

        cur.execute('''
            SELECT *
            FROM listing_queue
            WHERE upc IN (''' + placeholders + ''') AND status IN ('queued', 'done')
            ORDER BY added_at DESC, id DESC
            LIMIT 1
        ''', tuple(upc_variants))
        row = cur.fetchone()

        if row and bool(success):
            qid = row['id']

            # Persist per-platform completion (queue stays visible until both platforms are done).
            cur.execute('''
                UPDATE listing_queue
                SET
                    listed_at = ?,
                    listed_platform = ?,
                    listed_listing_id = ?,
                    listed_offer_id = ?,
                    listed_sku = ?,
                    listed_asin = ?,
                    listed_url = ?,
                    listed_ebay_at = CASE WHEN ? = 'ebay' THEN ? ELSE listed_ebay_at END,
                    listed_amazon_at = CASE WHEN ? = 'amazon' THEN ? ELSE listed_amazon_at END
                WHERE id = ?
            ''', (
                now, platform, listing_id, offer_id, sku, asin, url,
                platform, now,
                platform, now,
                qid
            ))

            # If both platforms are listed, mark the queue item as done.
            cur.execute('SELECT listed_ebay_at, listed_amazon_at FROM listing_queue WHERE id = ? LIMIT 1', (qid,))
            st = cur.fetchone()
            ebay_at = (st['listed_ebay_at'] if st else None)
            amazon_at = (st['listed_amazon_at'] if st else None)
            new_status = 'done' if (ebay_at and amazon_at) else 'queued'
            cur.execute('UPDATE listing_queue SET status = ? WHERE id = ?', (new_status, qid))

            cur.execute('SELECT * FROM listing_queue WHERE id = ? LIMIT 1', (qid,))
            updated_item = _listagent_row_to_dict(cur.fetchone())

    # Best-effort persistent listing log (separate DB; never blocks listing flow)
    try:
        _listinglog_add_entry(
            upc=upc,
            platform=platform,
            action=action or 'listed',
            source=source or 'listingagent',
            created_at=now,
            marketplace_id=marketplace_id,
            listing_id=listing_id,
            offer_id=offer_id,
            sku=sku,
            asin=asin,
            url=url,
            title=title,
            price=price,
            quantity=quantity,
            success=bool(success),
            error=error,
            meta=meta
        )
    except Exception:
        pass

    return updated_item

def _listagent_remove_from_queue(upc):
    upc = _listagent_format_upc12(upc)
    if not upc:
        raise ValueError('upc is required')
    upc_variants = _listagent_upc_variants(upc)
    placeholders = ','.join('?' for _ in upc_variants)
    now = _listagent_now_iso()
    with db_connection('listagent.db') as conn:
        cur = conn.cursor()
        _listagent_init_tables(cur)
        cur.execute('''
            UPDATE listing_queue
            SET status = 'removed', removed_at = ?
            WHERE upc IN (''' + placeholders + ''') AND status IN ('queued', 'done')
        ''', (now, *tuple(upc_variants)))
        changed = bool(cur.rowcount and cur.rowcount > 0)
        cur.execute('''
            SELECT *
            FROM listing_queue
            WHERE upc IN (''' + placeholders + ''')
            ORDER BY removed_at DESC, id DESC
            LIMIT 1
        ''', tuple(upc_variants))
        return _listagent_row_to_dict(cur.fetchone()), changed

