# API endpoint for financial analytics data
@app.route('/api/financial-analytics')
@cache.cached(timeout=300, query_string=True)
def api_financial_analytics():
    """
    Fetch all sold orders with cost data from BOL and calculate profits.
    Returns financial metrics for the dashboard.
    """
    print("DEBUG: Financial analytics API called")
    try:
        # Use connection pool for better performance
        sold_conn = get_db_connection('sold.db')
        sold_cur = sold_conn.cursor()
        
        # Get all sold orders with lot_number
        sold_cur.execute('''
            SELECT 
                id,
                order_id,
                item_id,
                title,
                quantity,
                price,
                seller_fee,
                taxes,
                paid_time,
                shipped_time,
                barcode,
                store,
                location,
                shipping_cost,
                lot_number
            FROM orders
            WHERE paid_time IS NOT NULL
            ORDER BY paid_time DESC
        ''')
        orders = sold_cur.fetchall()
        
        # Use connection pool for other databases
        rawbol_conn = get_db_connection('rawbol.db')
        rawbol_cur = rawbol_conn.cursor()
        
        ebay_conn = get_db_connection('ebayStore.db')
        ebay_cur = ebay_conn.cursor()
        
        amazon_conn = get_db_connection('amazonStore.db')
        amazon_cur = amazon_conn.cursor()
        
        # Get returns data from sold.db
        returns_data = {}
        seller_fee_refunds_by_order = {}
        unmatched_returns = []  # Store returns without original_order_id
        try:
            sold_cur.execute('''
                SELECT 
                    id,
                    original_order_id,
                    order_id,
                    item_id,
                    barcode,
                    title,
                    refund_amount,
                    original_shipping_cost,
                    return_shipping_cost,
                    seller_fee_refund,
                    return_date,
                    store,
                    return_reason
                FROM returns
                ORDER BY id DESC
            ''')
            
            returns_rows = sold_cur.fetchall()
            print(f"DEBUG: Found {len(returns_rows)} returns in database")

            def _to_float(value):
                try:
                    if value is None:
                        return 0.0
                    return float(value)
                except Exception:
                    return 0.0

            # Deduplicate returns that are re-synced with identical financial payload.
            # Keep the latest row (highest id) because rows are ordered by id DESC.
            deduped_returns = []
            seen_signatures = set()
            for row in returns_rows:
                signature = (
                    row['original_order_id'],
                    row['order_id'] or '',
                    row['item_id'] or '',
                    row['barcode'] or '',
                    row['title'] or '',
                    row['return_date'] or '',
                    row['store'] or ''
                )
                if signature in seen_signatures:
                    continue
                seen_signatures.add(signature)
                deduped_returns.append(row)

            matched_returns_count = 0
            for row in deduped_returns:
                original_order_id = row['original_order_id']
                refund_amount = _to_float(row['refund_amount'])
                original_shipping_cost = _to_float(row['original_shipping_cost'])
                return_shipping_cost = _to_float(row['return_shipping_cost'])
                seller_fee_refund = _to_float(row['seller_fee_refund'])

                # For matched returns, original shipping is already captured in orders.shipping_cost.
                # Excluding it here prevents double counting.
                matched_return_cost = refund_amount + return_shipping_cost

                # For unmatched returns, include original shipping because there is no matched order row.
                unmatched_return_cost = refund_amount + original_shipping_cost + return_shipping_cost

                if original_order_id is not None and str(original_order_id).strip() != '':
                    order_key = str(original_order_id).strip()
                    matched_returns_count += 1
                    returns_data[order_key] = returns_data.get(order_key, 0.0) + matched_return_cost
                    seller_fee_refunds_by_order[order_key] = seller_fee_refunds_by_order.get(order_key, 0.0) + seller_fee_refund
                else:
                    # Unmatched return - add as standalone transaction
                    unmatched_returns.append({
                        'order_id': row['order_id'],
                        'title': row['title'] or 'Unknown returned item',
                        'refund_amount': refund_amount,
                        'return_cost': unmatched_return_cost,
                        'seller_fee_refund': seller_fee_refund,
                        'return_date': row['return_date'],
                        'store': row['store'],
                        'return_reason': row['return_reason'],
                        'is_unmatched_return': True
                    })

            total_return_costs = sum(returns_data.values()) + sum(r['return_cost'] for r in unmatched_returns)
            deduped_count = len(returns_rows) - len(deduped_returns)
            print(
                f"DEBUG: Processed {matched_returns_count} matched returns across {len(returns_data)} orders, "
                f"{len(unmatched_returns)} unmatched returns, deduped={deduped_count}, "
                f"total return costs: ${total_return_costs:.2f}"
            )
        except Exception as e:
            print(f"Warning: Could not load returns data: {e}")
            import traceback
            traceback.print_exc()
        
        transactions = []
        
        for order in orders:
            item_data = dict(order)
            
            # Add return cost if this order has a return
            # Use .get() to safely access the id key
            order_pk_id = item_data.get('id', 0)
            order_pk_key = str(order_pk_id).strip() if order_pk_id is not None else ''
            item_data['return_cost'] = returns_data.get(order_pk_key, 0.0)
            item_data['seller_fee_refund'] = seller_fee_refunds_by_order.get(order_pk_key, 0.0)
            
            # Skip cost lookup for marketplace sales (no cost associated)
            if order['store'] == 'marketplace':
                item_data['cost'] = None
                item_data['cost_source'] = 'marketplace'
                item_data['upc'] = order['barcode'] or order['item_id']
                item_data['bol_number'] = None
                transactions.append(item_data)
                continue
            
            # Try to get cost from rawbol.db
            upc = order['barcode'] or order['item_id']
            cost = None
            cost_source = None
            # LOT number comes directly from sold.db (already enriched from rawbol.db)
            bol_number = order['lot_number'] if order['lot_number'] and str(order['lot_number']).lower() not in ['', 'nan', 'none', 'null'] else None
            
            if upc:
                # Check rawbol for avg_cost.
                # Prefer the sold order's assigned LOT when available, then fall back to UPC-only lookup.
                rawbol_row = None
                if bol_number:
                    rawbol_cur.execute('''
                        SELECT avg_cost, lot_number
                        FROM raw_bol_items
                        WHERE upc = ? COLLATE NOCASE
                          AND lot_number = ? COLLATE NOCASE
                        ORDER BY created_at DESC
                        LIMIT 1
                    ''', (upc, bol_number))
                    rawbol_row = rawbol_cur.fetchone()
                if not rawbol_row:
                    rawbol_cur.execute('''
                        SELECT avg_cost, lot_number
                        FROM raw_bol_items
                        WHERE upc = ? COLLATE NOCASE
                        ORDER BY created_at DESC
                        LIMIT 1
                    ''', (upc,))
                    rawbol_row = rawbol_cur.fetchone()
                if rawbol_row and rawbol_row['avg_cost']:
                    cost = float(rawbol_row['avg_cost'])
                    cost_source = 'rawbol'
                    # Update bol_number if we found it in rawbol and it wasn't set
                    if not bol_number and rawbol_row['lot_number']:
                        bol_number = rawbol_row['lot_number']
                
                # For Amazon items, if barcode looks like ASIN, try to get UPC from amazonStore
                # and re-lookup in rawbol (handles old items that had ASIN as barcode)
                if not cost and order['store'] == 'amazon' and upc and (upc.startswith('B0') or len(upc) == 10):
                    amazon_cur.execute('SELECT UPC FROM ITEMS WHERE ASIN = ? COLLATE NOCASE', (upc,))
                    amazon_row = amazon_cur.fetchone()
                    if amazon_row and amazon_row['UPC']:
                        actual_upc = amazon_row['UPC']
                        # Try rawbol again with the actual UPC, preferring assigned LOT.
                        rawbol_row = None
                        if bol_number:
                            rawbol_cur.execute('''
                                SELECT avg_cost, lot_number
                                FROM raw_bol_items
                                WHERE upc = ? COLLATE NOCASE
                                  AND lot_number = ? COLLATE NOCASE
                                ORDER BY created_at DESC
                                LIMIT 1
                            ''', (actual_upc, bol_number))
                            rawbol_row = rawbol_cur.fetchone()
                        if not rawbol_row:
                            rawbol_cur.execute('''
                                SELECT avg_cost, lot_number
                                FROM raw_bol_items
                                WHERE upc = ? COLLATE NOCASE
                                ORDER BY created_at DESC
                                LIMIT 1
                            ''', (actual_upc,))
                            rawbol_row = rawbol_cur.fetchone()
                        if rawbol_row and rawbol_row['avg_cost']:
                            cost = float(rawbol_row['avg_cost'])
                            cost_source = 'rawbol_via_asin'
                            if not bol_number and rawbol_row['lot_number']:
                                bol_number = rawbol_row['lot_number']
                
                # Fallback to eBay store data (could have cost in some cases)
                if not cost:
                    ebay_cur.execute('SELECT UPC FROM INVENTORY WHERE UPC = ? OR ItemID = ? COLLATE NOCASE LIMIT 1', (upc, upc))
                    if ebay_cur.fetchone():
                        cost_source = 'ebay'
                        # Note: ebayStore.db doesn't have cost data, just marking source
                
                # Fallback to Amazon store data
                if not cost:
                    amazon_cur.execute('SELECT UPC FROM ITEMS WHERE UPC = ? OR ASIN = ? COLLATE NOCASE LIMIT 1', (upc, upc))
                    if amazon_cur.fetchone():
                        cost_source = 'amazon'
                        # Note: amazonStore.db doesn't have cost data, just marking source
            
            item_data['cost'] = cost
            item_data['cost_source'] = cost_source
            item_data['upc'] = upc
            item_data['bol_number'] = bol_number
            
            transactions.append(item_data)
        
        # No need to close connections - they're pooled and reused
        
        # Get LOT # data from rawbol.db upload_logs
        lot_options = []
        try:
            # Reuse existing connection
            rawbol_cur.execute('''
                SELECT 
                    lot_number,
                    import_date,
                    total_client_cost
                FROM upload_logs
                WHERE lot_number IS NOT NULL 
                    AND lot_number != ''
                ORDER BY import_date DESC
            ''')
            
            rows = rawbol_cur.fetchall()
            print(f"DEBUG: Found {len(rows)} LOT entries in rawbol.db")
            
            for row in rows:
                lot_num = row['lot_number']
                import_date = row['import_date']
                total_cost = row['total_client_cost']
                
                # Format as "Date + LOT #"
                display_name = f"{import_date} + {lot_num}"
                lot_options.append({
                    'value': lot_num,
                    'label': display_name,
                    'date': import_date,
                    'cost': float(total_cost) if total_cost else 0
                })
                print(f"DEBUG: Added LOT option: {display_name} (${float(total_cost) if total_cost else 0:.2f})")
            
        except Exception as e:
            print(f"Warning: Could not fetch LOT # data from rawbol.db: {e}")
            import traceback
            traceback.print_exc()
        
        # Add unmatched returns as standalone transactions (for financial impact)
        for unmatched in unmatched_returns:
            # Create a transaction entry for unmatched return
            # Use negative values to represent a loss
            transactions.append({
                'id': None,
                'order_id': unmatched['order_id'],
                'title': unmatched['title'],
                'quantity': 0,
                'price': 0,  # No revenue from return
                'seller_fee': 0,
                'seller_fee_refund': unmatched.get('seller_fee_refund', 0.0),
                'taxes': 0,
                'paid_time': unmatched['return_date'],
                'shipped_time': None,
                'barcode': None,
                'store': unmatched['store'] or 'unknown',
                'location': None,
                'shipping_cost': 0,
                'lot_number': None,
                'return_cost': unmatched['return_cost'],
                'cost': 0,
                'cost_source': 'unmatched_return',
                'upc': None,
                'bol_number': None,
                'is_unmatched_return': True  # Flag for UI
            })
        
        print(f"DEBUG: Total transactions (including {len(unmatched_returns)} unmatched returns): {len(transactions)}")
        
        # Get BOL extract totals from rawbol.db (total_client_cost + shipping_cost per LOT)
        bol_extract_totals = {}
        try:
            rawbol_cur.execute('''
                SELECT 
                    lot_number,
                    total_client_cost,
                    shipping_cost
                FROM upload_logs
                WHERE lot_number IS NOT NULL
            ''')
            
            for row in rawbol_cur.fetchall():
                lot_num = row['lot_number']
                total_cost = float(row['total_client_cost']) if row['total_client_cost'] else 0
                shipping_cost = float(row['shipping_cost']) if row['shipping_cost'] else 0
                
                bol_extract_totals[lot_num] = {
                    'total_cost': total_cost,
                    'shipping_cost': shipping_cost
                }
            
            print(f"DEBUG: Loaded BOL extract totals for {len(bol_extract_totals)} LOTs")
        except Exception as e:
            print(f"Warning: Could not fetch BOL extract totals: {e}")
        
        return jsonify({
            'success': True,
            'transactions': transactions,
            'count': len(transactions),
            'lot_options': lot_options,
            'bol_extract_totals': bol_extract_totals
        })
        
    except Exception as e:
        print(f"Error in financial analytics API: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': _safe_error(e)
        }), 500

@app.route('/api/amazon/financial-summary', methods=['GET'])
@cache.cached(timeout=300, query_string=True)  # Cache for 5 minutes
def api_amazon_financial_summary():
    """
    Get aggregate financial totals from Amazon Financial Events API.
    Returns total seller fees, shipping costs, taxes, and returns data across all orders.
    Query params: days (default 30), include_returns (default true)
    """
    if not AMAZON_AVAILABLE:
        return jsonify({'success': False, 'error': 'Amazon integration not available'}), 503
    
    try:
        days = int(request.args.get('days', 30))
        include_returns = request.args.get('include_returns', 'true').lower() == 'true'
        
        amazon = AmazonManager()
        financial_data = amazon.get_financial_events(days_back=days)
        
        # Calculate totals
        total_seller_fees = 0
        total_shipping_costs = 0
        total_taxes = 0
        orders_with_fees = 0
        orders_with_shipping = 0
        
        for order_id, data in financial_data.items():
            if data['seller_fee'] > 0:
                total_seller_fees += data['seller_fee']
                orders_with_fees += 1
            
            if data['shipping_cost'] > 0:
                total_shipping_costs += data['shipping_cost']
                orders_with_shipping += 1
            
            total_taxes += data['taxes']
        
        summary = {
            'total_orders': len(financial_data),
            'orders_with_fees': orders_with_fees,
            'orders_with_shipping': orders_with_shipping,
            'total_seller_fees': round(total_seller_fees, 2),
            'total_shipping_costs': round(total_shipping_costs, 2),
            'total_taxes': round(total_taxes, 2),
            'total_amazon_costs': round(total_seller_fees + total_shipping_costs + total_taxes, 2)
        }
        
        # Add returns data if requested
        if include_returns:
            try:
                conn = sqlite3.connect('sold.db')
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                
                # Get returns within the same time period
                cur.execute('''
                    SELECT 
                        COUNT(*) as total_returns,
                        SUM(refund_amount) as total_refunded,
                        SUM(refund_amount + original_shipping_cost + return_shipping_cost) as total_return_cost
                    FROM returns
                    WHERE store = 'amazon'
                    AND return_date >= datetime('now', '-' || ? || ' days')
                ''', (days,))
                
                returns_row = cur.fetchone()
                
                summary['returns'] = {
                    'total_returns': returns_row['total_returns'] or 0,
                    'total_refunded': round(returns_row['total_refunded'] or 0, 2),
                    'total_return_cost': round(returns_row['total_return_cost'] or 0, 2),
                    'return_rate': round((returns_row['total_returns'] or 0) / len(financial_data) * 100, 2) if len(financial_data) > 0 else 0
                }
                
                # Calculate net profit impact
                summary['net_costs_with_returns'] = round(
                    summary['total_amazon_costs'] + summary['returns']['total_return_cost'], 2
                )
                
            except Exception as e:
                print(f"Warning: Could not include returns data: {e}")
                summary['returns'] = None
            finally:
                conn.close()
        
        return jsonify({
            'success': True,
            'days': days,
            'summary': summary
        })
        
    except Exception as e:
        print(f"Error fetching Amazon financial summary: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': _safe_error(e)
        }), 500

@app.route('/api/refresh-sold-data', methods=['POST'])
def api_refresh_sold_data():
    """
    Re-enrich sold.db orders with latest barcode and LOT number data.
    This updates old Amazon items that may have ASIN as barcode to use proper UPC.
    """
    try:
        print("DEBUG: Refreshing sold data...")
        
        # Use connection pool
        sold_conn = get_db_connection('sold.db')
        sold_cur = sold_conn.cursor()
        
        amazon_conn = get_db_connection('amazonStore.db')
        amazon_cur = amazon_conn.cursor()
        
        rawbol_conn = get_db_connection('rawbol.db')
        rawbol_cur = rawbol_conn.cursor()
        
        # Get Amazon orders that might need updating
        sold_cur.execute('''
            SELECT id, order_id, item_id, barcode, lot_number
            FROM orders
            WHERE store = 'amazon' AND barcode IS NOT NULL
        ''')
        amazon_orders = sold_cur.fetchall()
        
        updated_barcodes = 0
        updated_lot_numbers = 0
        ambiguous_lot_matches = 0
        
        for order in amazon_orders:
            order_id = order['order_id']
            current_barcode = order['barcode']
            current_lot = order['lot_number']
            needs_update = False
            new_barcode = current_barcode
            new_lot = current_lot
            
            # Check if barcode looks like ASIN (old format)
            if current_barcode and (current_barcode.startswith('B0') or len(current_barcode) == 10):
                # Try to get UPC from amazonStore
                amazon_cur.execute('SELECT UPC FROM ITEMS WHERE ASIN = ? COLLATE NOCASE', (current_barcode,))
                amazon_row = amazon_cur.fetchone()
                if amazon_row and amazon_row['UPC'] and amazon_row['UPC'] != current_barcode:
                    new_barcode = amazon_row['UPC']
                    needs_update = True
                    updated_barcodes += 1
            
            # Check if we can enrich lot_number from rawbol using the (possibly new) barcode
            if not current_lot or str(current_lot).lower() in ['', 'nan', 'none', 'null']:
                lot_candidates = []
                rawbol_cur.execute('''
                    SELECT DISTINCT lot_number
                    FROM raw_bol_items
                    WHERE upc = ? COLLATE NOCASE
                      AND lot_number IS NOT NULL
                      AND TRIM(COALESCE(lot_number, '')) != ''
                ''', (new_barcode,))
                lot_candidates = [r['lot_number'] for r in rawbol_cur.fetchall() if r['lot_number']]

                # Try a stripped-numeric fallback for leading-zero mismatches.
                if not lot_candidates and new_barcode:
                    stripped = str(new_barcode).lstrip('0')
                    if stripped and stripped != str(new_barcode):
                        rawbol_cur.execute('''
                            SELECT DISTINCT lot_number
                            FROM raw_bol_items
                            WHERE upc = ? COLLATE NOCASE
                              AND lot_number IS NOT NULL
                              AND TRIM(COALESCE(lot_number, '')) != ''
                        ''', (stripped,))
                        lot_candidates = [r['lot_number'] for r in rawbol_cur.fetchall() if r['lot_number']]

                if len(lot_candidates) == 1:
                    new_lot = lot_candidates[0]
                    needs_update = True
                    updated_lot_numbers += 1
                elif len(lot_candidates) > 1:
                    ambiguous_lot_matches += 1
                    print(f"⚠️ Ambiguous LOT match for order {order_id} barcode {new_barcode}: {lot_candidates}")
            
            # Update if changes were made
            if needs_update:
                sold_cur.execute('UPDATE orders SET barcode = ?, lot_number = ? WHERE id = ?', 
                               (new_barcode, new_lot, order['id']))
                print(f"✅ Updated {order_id}: barcode={new_barcode}, lot={new_lot}")
        
        sold_conn.commit()
        
        # No need to close - connections are pooled
        
        return jsonify({
            'success': True,
            'updated_barcodes': updated_barcodes,
            'updated_lot_numbers': updated_lot_numbers,
            'ambiguous_lot_matches': ambiguous_lot_matches,
            'message': f'Updated {updated_barcodes} barcodes, {updated_lot_numbers} LOT numbers, {ambiguous_lot_matches} ambiguous LOT matches skipped'
        })
        
    except Exception as e:
        print(f"Error refreshing sold data: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': _safe_error(e)
        }), 500

# =========== Item Preparation Helpers and Routes ===========
def _normalize_upc(upc):
    try:
        if upc is None:
            return ''
        s = str(upc).strip()
        if not s:
            return ''
        # handle float-like strings ending with .0
        if s.endswith('.0') and s.replace('.0', '').isdigit():
            return str(int(float(s)))
        # handle numeric floats
        if s.replace('.', '', 1).isdigit():
            try:
                f = float(s)
                if abs(f - int(f)) < 1e-9:
                    return str(int(f))
            except Exception:
                pass
        return s
    except Exception:
        return str(upc or '')

def _format_upc_display(upc):
    """Display helper: numeric UPCs are shown as UPC-A width (12 digits)."""
    s = _normalize_upc(upc)
    if s and s.isdigit() and len(s) <= 12:
        return s.zfill(12)
    return s

def _normalize_scanned_upc(upc):
    """
    Scanner helper:
    - Preserve original code unless it has extra leading zeros beyond UPC-A width.
    - Keep non-digit values unchanged.
    """
    s = _normalize_upc(upc)
    if not s or not s.isdigit():
        return s
    if len(s) > 12 and s.startswith('0'):
        stripped = s.lstrip('0')
        if stripped and len(stripped) <= 12:
            return stripped
    return s

def _strip_leading_zeros_numeric(value):
    """Legacy-match helper: strip leading zeros only for fully numeric codes."""
    s = _normalize_upc(value)
    if s and s.isdigit():
        stripped = s.lstrip('0')
        return stripped if stripped else '0'
    return s

def _normalize_upc_preserve_suffix_for_match(value):
    """
    Strip leading zeros from numeric UPCs while preserving -suffix variants.
    Example: 0719978859014-24 -> 719978859014-24
    """
    s = _normalize_upc(value)
    if not s:
        return s
    if '-' in s:
        base, suffix = s.split('-', 1)
        return f"{_strip_leading_zeros_numeric(base)}-{suffix}"
    return _strip_leading_zeros_numeric(s)

def _normalize_lot_number(value):
    return str(value or '').strip()

def _normalize_listing_source(value, default='system'):
    """Normalize listing source into one of: system, user, listing_center."""
    raw = (str(value or '').strip().lower().replace('-', '_').replace(' ', '_'))
    if not raw:
        return default
    if raw in ('listingagent', 'listing_agent', 'listing_center', 'listingcenter', 'list_manager', 'listing_centre', 'listingcentre'):
        return 'listing_center'
    if raw in ('user', 'manual', 'list_status_api', 'list_status', 'mail_center', 'mailcenter'):
        return 'user'
    if raw in ('system', 'auto', 'automated', 'sync', 'migration', 'unknown'):
        return 'system'
    return default or 'system'

def _normalize_prep_row_status(value):
    raw = str(value or '').strip().lower().replace(' ', '_')
    return raw if raw in ('good', 'bad', 'return', 'unchecked') else ''

def _is_items_to_list_suffixed_upc(upc):
    upc_n = _normalize_upc_preserve_suffix_for_match(upc)
    if not upc_n or '-' not in upc_n:
        return False
    base, suffix = upc_n.rsplit('-', 1)
    return bool(base and suffix)

def _items_to_list_bucket_status(upc, good_qty=0, bad_qty=0):
    try:
        good_qty_n = int(good_qty or 0)
    except Exception:
        good_qty_n = 0
    try:
        bad_qty_n = int(bad_qty or 0)
    except Exception:
        bad_qty_n = 0

    is_suffixed = _is_items_to_list_suffixed_upc(upc)
    if good_qty_n > 0 and (not is_suffixed or bad_qty_n <= 0):
        return 'good'
    if is_suffixed and bad_qty_n > 0:
        return 'bad'
    return ''

def _items_to_list_effective_status(upc, explicit_status='', good_qty=0, bad_qty=0):
    status_n = _normalize_prep_row_status(explicit_status)
    if status_n == 'good':
        return status_n
    if status_n in ('bad', 'return'):
        if _is_items_to_list_suffixed_upc(upc):
            return status_n
        # Base UPCs are reserved for canonical non-special rows. Ignore corrupted
        # BAD/RETURN states and fall back to quantity buckets so the visible row stays canonical.
        status_n = ''
    if status_n == 'unchecked':
        return ''
    if status_n:
        return status_n
    return _items_to_list_bucket_status(upc, good_qty=good_qty, bad_qty=bad_qty)

def _items_to_list_asset_scope(upc, row_status=''):
    """Scope Items-to-List notes/photos by status+barcode; suffixed barcodes are already unique."""
    upc_n = _normalize_upc_preserve_suffix_for_match(upc)
    status_n = _normalize_prep_row_status(row_status)
    if not upc_n:
        return '', ''
    if '-' in upc_n:
        return upc_n, ''
    return upc_n, status_n

def _items_prep_scope_has_actionable_status(cur, upc, row_status='', lot_number=''):
    """
    Notes only make sense on actionable prep rows.
    Unchecked rows should not carry notes, even if legacy data exists.
    """
    scope_upc, _scope_status = _items_to_list_asset_scope(upc, row_status)
    if not scope_upc:
        return False

    explicit_status = _normalize_prep_row_status(row_status)
    if _items_to_list_effective_status(scope_upc, explicit_status) in ('good', 'bad', 'return'):
        return True
    if explicit_status == 'unchecked':
        return False

    lot_n = _normalize_lot_number(lot_number)

    try:
        status_row = _select_prep_status_row(cur, scope_upc, lot_n, columns='status')
        status_value = _items_to_list_effective_status(scope_upc, status_row[0]) if status_row else ''
        if status_value in ('good', 'bad', 'return'):
            return True
    except Exception:
        pass

    try:
        if lot_n:
            cur.execute('''
                SELECT COALESCE(good_qty, 0), COALESCE(bad_qty, 0)
                FROM bol_items
                WHERE upc = ? COLLATE NOCASE
                  AND lot_number = ? COLLATE NOCASE
                ORDER BY import_date DESC, id DESC
                LIMIT 1
            ''', (scope_upc, lot_n))
            bol_row = cur.fetchone()
        else:
            cur.execute('''
                SELECT COALESCE(good_qty, 0), COALESCE(bad_qty, 0)
                FROM bol_items
                WHERE upc = ? COLLATE NOCASE
                ORDER BY import_date DESC, id DESC
                LIMIT 1
            ''', (scope_upc,))
            bol_row = cur.fetchone()
        if bol_row:
            return bool(_items_to_list_bucket_status(scope_upc, good_qty=bol_row[0], bad_qty=bol_row[1]))
    except Exception:
        pass

    return False

def _ready_to_ship_prep_related_like(base_upc):
    safe = str(base_upc or '').replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
    return f'{safe}-%'

def _ready_to_ship_prep_sort_value(value):
    raw = str(value or '').strip()
    if not raw:
        return 0.0
    try:
        cleaned = raw.replace('Z', '+00:00')
        dt = datetime.datetime.fromisoformat(cleaned)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.timestamp()
    except Exception:
        return 0.0

def _ready_to_ship_prep_relevance(requested_upc, scope_upc):
    requested = _normalize_upc_preserve_suffix_for_match(requested_upc)
    scope = _normalize_upc_preserve_suffix_for_match(scope_upc)
    if not requested or not scope:
        return 99
    requested_base = requested.split('-', 1)[0]
    scope_base = scope.split('-', 1)[0]
    requested_has_suffix = '-' in requested
    scope_has_suffix = '-' in scope

    if requested_has_suffix:
        if scope.lower() == requested.lower():
            return 0
        if scope.lower() == requested_base.lower():
            return 1
        if scope_base.lower() == requested_base.lower():
            return 2
        return 3

    if scope_has_suffix and scope_base.lower() == requested_base.lower():
        return 0
    if scope.lower() == requested_base.lower():
        return 1
    if scope_base.lower() == requested_base.lower():
        return 2
    return 3

def _ready_to_ship_prep_relevance_label(requested_upc, scope_upc):
    requested = _normalize_upc_preserve_suffix_for_match(requested_upc)
    scope = _normalize_upc_preserve_suffix_for_match(scope_upc)
    if not requested or not scope:
        return 'Related entry'
    requested_base = requested.split('-', 1)[0]
    scope_base = scope.split('-', 1)[0]
    requested_has_suffix = '-' in requested
    scope_has_suffix = '-' in scope

    if requested_has_suffix:
        if scope.lower() == requested.lower():
            return 'Direct item'
        if scope.lower() == requested_base.lower():
            return 'Base item'
        if scope_base.lower() == requested_base.lower():
            return 'Related suffixed item'
        return 'Related entry'

    if scope_has_suffix and scope_base.lower() == requested_base.lower():
        return 'Possible suffixed item'
    if scope.lower() == requested_base.lower():
        return 'Direct item'
    if scope_base.lower() == requested_base.lower():
        return 'Related item'
    return 'Related entry'

def _build_ready_to_ship_prep_context(cur, barcode, include_details=True, max_notes_per_entry=12, max_images_per_entry=8):
    requested_upc = _normalize_upc_preserve_suffix_for_match(barcode)
    if not requested_upc:
        return {
            'requested_barcode': '',
            'base_barcode': '',
            'has_alerts': False,
            'summary': {
                'has_alerts': False,
                'entry_count': 0,
                'note_count': 0,
                'defect_count': 0,
                'image_count': 0,
                'latest_at': '',
                'has_suffixed': False
            },
            'entries': []
        }

    requested_base = requested_upc.split('-', 1)[0]
    like_related = _ready_to_ship_prep_related_like(requested_base)

    entry_map = {}

    def ensure_entry(scope_upc, scope_status=''):
        key = (str(scope_upc or '').strip().lower(), str(scope_status or '').strip().lower())
        if key not in entry_map:
            entry_map[key] = {
                'scope_upc': scope_upc,
                'row_status': scope_status,
                'status': scope_status or '',
                'reason': '',
                'latest_at': '',
                'notes': [],
                'images': [],
                'note_count': 0,
                'image_count': 0,
                'has_suffixed': '-' in str(scope_upc or ''),
                '_note_keys': set(),
                '_image_ids': set(),
            }
        return entry_map[key]

    def push_timestamp(entry, value):
        raw = str(value or '').strip()
        if not raw:
            return
        if _ready_to_ship_prep_sort_value(raw) >= _ready_to_ship_prep_sort_value(entry.get('latest_at')):
            entry['latest_at'] = raw

    bol_visible_status_by_scope = {}

    def entry_scope_key(entry):
        return _normalize_upc_preserve_suffix_for_match(entry.get('scope_upc'))

    def entry_base_key(entry):
        scope_key = entry_scope_key(entry)
        return scope_key.split('-', 1)[0] if scope_key else ''

    def entry_display_status(entry):
        return str(entry.get('display_status') or entry.get('row_status') or entry.get('status') or '').strip().lower()

    def entry_visible_status(entry):
        scope_key = entry_scope_key(entry)
        status = _items_to_list_effective_status(scope_key, entry_display_status(entry))
        if status in ('good', 'bad', 'return'):
            return status
        return str(bol_visible_status_by_scope.get(scope_key) or '').strip().lower()

    def is_visible_items_to_list_entry(entry):
        return entry_visible_status(entry) in ('good', 'bad', 'return')

    def merge_orphan_entry_into(target, source):
        push_timestamp(target, source.get('latest_at'))
        target['has_suffixed'] = bool(target.get('has_suffixed') or source.get('has_suffixed'))

        source_note_keys = source.get('_note_keys') or set()
        target_note_keys = target.get('_note_keys')
        if not isinstance(target_note_keys, set):
            target_note_keys = set(target_note_keys or [])
            target['_note_keys'] = target_note_keys
        existing_target_note_keys = set(target_note_keys)
        added_note_count = 0
        for note_key in source_note_keys:
            if note_key in target_note_keys:
                continue
            target_note_keys.add(note_key)
            added_note_count += 1
        if added_note_count:
            target['note_count'] = int(target.get('note_count') or 0) + added_note_count
        if include_details:
            existing_note_ids = {
                str(note.get('id') or '')
                for note in (target.get('notes') or [])
            }
            for note in (source.get('notes') or []):
                note_id = str(note.get('id') or '')
                dedupe_key = (
                    note.get('kind'),
                    str(note.get('note') or '').strip().lower(),
                    str(note.get('created_at') or '').strip()
                )
                if note_id in existing_note_ids or dedupe_key in existing_target_note_keys:
                    continue
                target.setdefault('notes', []).append(note)
                existing_note_ids.add(note_id)

        source_image_ids = source.get('_image_ids') or set()
        target_image_ids = target.get('_image_ids')
        if not isinstance(target_image_ids, set):
            target_image_ids = set(target_image_ids or [])
            target['_image_ids'] = target_image_ids
        added_image_count = 0
        for image_id in source_image_ids:
            if image_id in target_image_ids:
                continue
            target_image_ids.add(image_id)
            added_image_count += 1
        if added_image_count:
            target['image_count'] = int(target.get('image_count') or 0) + added_image_count
        if include_details:
            existing_image_ids = {
                int(img.get('id') or 0)
                for img in (target.get('images') or [])
                if str(img.get('id') or '').isdigit()
            }
            for image in (source.get('images') or []):
                image_id = image.get('id')
                if image_id in existing_image_ids:
                    continue
                target.setdefault('images', []).append(image)
                if str(image_id or '').isdigit():
                    existing_image_ids.add(int(image_id))

    try:
        cur.execute('''
            SELECT upc, COALESCE(status, '') AS status, COALESCE(reason, '') AS reason,
                   COALESCE(note, '') AS note, COALESCE(updated_at, '') AS updated_at,
                   COALESCE(quantity, 0) AS quantity
            FROM items_prep_status
            WHERE upc = ? COLLATE NOCASE
               OR upc LIKE ? ESCAPE '\\'
            ORDER BY updated_at DESC, id DESC
        ''', (requested_base, like_related))
        status_rows = [dict(r) for r in cur.fetchall()]
    except Exception:
        status_rows = []

    for row in status_rows:
        raw_upc = _normalize_upc_preserve_suffix_for_match(row.get('upc'))
        status_value = _normalize_prep_row_status(row.get('status'))
        scope_upc, scope_status = _items_to_list_asset_scope(raw_upc, status_value)
        if not scope_upc:
            continue
        entry = ensure_entry(scope_upc, scope_status)
        if status_value and not entry.get('status'):
            entry['status'] = status_value
        reason_text = str(row.get('reason') or '').strip()
        if reason_text and (
            not entry.get('reason')
            or _ready_to_ship_prep_sort_value(row.get('updated_at')) >= _ready_to_ship_prep_sort_value(entry.get('latest_at'))
        ):
            entry['reason'] = reason_text
        push_timestamp(entry, row.get('updated_at'))
        note_text = str(row.get('note') or '').strip()
        note_at = str(row.get('updated_at') or '').strip()
        if note_text:
            note_key = ('status', note_text.lower(), note_at)
            if note_key not in entry['_note_keys']:
                entry['_note_keys'].add(note_key)
                entry['note_count'] += 1
                if include_details and len(entry['notes']) < max_notes_per_entry:
                    entry['notes'].append({
                        'id': f"status-{scope_upc}-{scope_status or 'none'}-{len(entry['notes'])}",
                        'note': note_text,
                        'created_at': note_at,
                        'kind': 'status'
                    })

    try:
        cur.execute('''
            SELECT id, upc, COALESCE(row_status, '') AS row_status,
                   COALESCE(note, '') AS note, COALESCE(created_at, '') AS created_at
            FROM items_prep_notes
            WHERE upc = ? COLLATE NOCASE
               OR upc LIKE ? ESCAPE '\\'
            ORDER BY created_at DESC, id DESC
        ''', (requested_base, like_related))
        note_rows = [dict(r) for r in cur.fetchall()]
    except Exception:
        note_rows = []

    for row in note_rows:
        raw_upc = _normalize_upc_preserve_suffix_for_match(row.get('upc'))
        scope_upc, scope_status = _items_to_list_asset_scope(raw_upc, row.get('row_status'))
        if not scope_upc:
            continue
        entry = ensure_entry(scope_upc, scope_status)
        note_text = str(row.get('note') or '').strip()
        note_at = str(row.get('created_at') or '').strip()
        if not note_text:
            continue
        note_key = ('note', note_text.lower(), note_at)
        if note_key in entry['_note_keys']:
            continue
        entry['_note_keys'].add(note_key)
        entry['note_count'] += 1
        push_timestamp(entry, note_at)
        if include_details and len(entry['notes']) < max_notes_per_entry:
            entry['notes'].append({
                'id': row.get('id'),
                'note': note_text,
                'created_at': note_at,
                'kind': 'note'
            })

    try:
        cur.execute('''
            SELECT id, upc, COALESCE(row_status, '') AS row_status,
                   COALESCE(image_path, '') AS image_path, COALESCE(created_at, '') AS created_at,
                   COALESCE(rotation, 0) AS rotation
            FROM items_prep_images
            WHERE (upc = ? COLLATE NOCASE OR upc LIKE ? ESCAPE '\\')
              AND (deleted_at IS NULL OR TRIM(COALESCE(deleted_at, '')) = '')
            ORDER BY created_at DESC, id DESC
        ''', (requested_base, like_related))
        image_rows = [dict(r) for r in cur.fetchall()]
    except Exception:
        image_rows = []

    for row in image_rows:
        raw_upc = _normalize_upc_preserve_suffix_for_match(row.get('upc'))
        scope_upc, scope_status = _items_to_list_asset_scope(raw_upc, row.get('row_status'))
        if not scope_upc:
            continue
        entry = ensure_entry(scope_upc, scope_status)
        image_id = row.get('id')
        if image_id in entry['_image_ids']:
            continue
        entry['_image_ids'].add(image_id)
        entry['image_count'] += 1
        push_timestamp(entry, row.get('created_at'))
        image_path = str(row.get('image_path') or '').strip()
        if include_details and image_path and len(entry['images']) < max_images_per_entry:
            image_url = image_path if image_path.startswith(('http://', 'https://', '/')) else f"/static/{image_path}"
            entry['images'].append({
                'id': image_id,
                'image_path': image_path,
                'image_url': image_url,
                'created_at': row.get('created_at') or '',
                'rotation': int(row.get('rotation') or 0)
            })

    try:
        cur.execute('''
            SELECT upc,
                   MAX(
                       CASE
                           WHEN INSTR(COALESCE(upc, ''), '-') > 0 AND COALESCE(bad_qty, 0) > 0 THEN 2
                           WHEN COALESCE(good_qty, 0) > 0 THEN 1
                           ELSE 0
                       END
                   ) AS visibility_rank
            FROM bol_items
            WHERE upc = ? COLLATE NOCASE
               OR upc LIKE ? ESCAPE '\\'
            GROUP BY upc
        ''', (requested_base, like_related))
        for row in cur.fetchall():
            scope_upc = _normalize_upc_preserve_suffix_for_match(row['upc'])
            if not scope_upc:
                continue
            rank = int(row['visibility_rank'] or 0)
            if rank >= 2:
                bol_visible_status_by_scope[scope_upc] = 'bad'
            elif rank == 1:
                bol_visible_status_by_scope[scope_upc] = 'good'
    except Exception:
        bol_visible_status_by_scope = {}

    working_entries = []

    for entry in entry_map.values():
        if entry['note_count'] <= 0 and not str(entry.get('reason') or '').strip() and entry['image_count'] <= 0:
            continue
        entry['relevance_rank'] = _ready_to_ship_prep_relevance(requested_upc, entry.get('scope_upc'))
        entry['relevance_label'] = _ready_to_ship_prep_relevance_label(requested_upc, entry.get('scope_upc'))
        entry['display_status'] = entry_visible_status(entry)
        if entry['display_status'] and not str(entry.get('status') or '').strip():
            entry['status'] = entry['display_status']
        entry['display_label'] = entry.get('scope_upc') or ''
        working_entries.append(entry)

    # Notes/photos can exist on a base UPC without a visible /items-to-list row.
    # When that happens, fold those orphan assets into the related visible row so
    # Ready to Ship doesn't report a fake second "entry" for the same prep item.
    merged_entries = []
    for entry in working_entries:
        if is_visible_items_to_list_entry(entry):
            merged_entries.append(entry)
            continue

        entry_base = entry_base_key(entry)
        if not entry_base:
            merged_entries.append(entry)
            continue

        candidate_entries = [
            candidate for candidate in working_entries
            if candidate is not entry
            and is_visible_items_to_list_entry(candidate)
            and entry_base_key(candidate).lower() == entry_base.lower()
        ]
        if not candidate_entries:
            continue

        source_scope = entry_scope_key(entry).lower()
        exact_scope = [
            candidate for candidate in candidate_entries
            if entry_scope_key(candidate).lower() == source_scope
        ]
        if exact_scope:
            candidate_entries = exact_scope

        requested_key = requested_upc.lower()
        if len(candidate_entries) > 1:
            exact_requested = [
                candidate for candidate in candidate_entries
                if entry_scope_key(candidate).lower() == requested_key
            ]
            if exact_requested:
                candidate_entries = exact_requested

        candidate_entries.sort(
            key=lambda candidate: (
                int(candidate.get('relevance_rank', 99)),
                -_ready_to_ship_prep_sort_value(candidate.get('latest_at')),
                0 if '-' in str(candidate.get('scope_upc') or '') else 1,
                str(candidate.get('scope_upc') or '').lower()
            )
        )
        merge_orphan_entry_into(candidate_entries[0], entry)

    entries = []
    note_total = 0
    defect_total = 0
    image_total = 0
    latest_at = ''
    has_suffixed = False

    for entry in merged_entries:
        if entry['note_count'] <= 0 and not str(entry.get('reason') or '').strip() and entry['image_count'] <= 0:
            continue
        note_total += int(entry.get('note_count') or 0)
        image_total += int(entry.get('image_count') or 0)
        if str(entry.get('reason') or '').strip():
            defect_total += 1
        if entry.get('has_suffixed'):
            has_suffixed = True
        if _ready_to_ship_prep_sort_value(entry.get('latest_at')) >= _ready_to_ship_prep_sort_value(latest_at):
            latest_at = entry.get('latest_at') or latest_at
        if include_details:
            entry['notes'] = sorted(
                entry['notes'],
                key=lambda n: (_ready_to_ship_prep_sort_value(n.get('created_at')), int(n.get('id') or 0) if str(n.get('id') or '').isdigit() else 0),
                reverse=True
            )[:max_notes_per_entry]
            entry['images'] = sorted(
                entry['images'],
                key=lambda img: (_ready_to_ship_prep_sort_value(img.get('created_at')), int(img.get('id') or 0) if str(img.get('id') or '').isdigit() else 0),
                reverse=True
            )[:max_images_per_entry]
        else:
            entry.pop('notes', None)
            entry.pop('images', None)
        entry.pop('_note_keys', None)
        entry.pop('_image_ids', None)
        entries.append(entry)

    entries.sort(
        key=lambda e: (
            int(e.get('relevance_rank', 99)),
            -_ready_to_ship_prep_sort_value(e.get('latest_at')),
            str(e.get('scope_upc') or '').lower(),
            str(e.get('row_status') or '').lower()
        )
    )

    summary = {
        'has_alerts': bool(entries),
        'entry_count': len(entries),
        'note_count': note_total,
        'defect_count': defect_total,
        'image_count': image_total,
        'latest_at': latest_at,
        'has_suffixed': has_suffixed
    }
    payload = {
        'requested_barcode': requested_upc,
        'base_barcode': requested_base,
        'has_alerts': summary['has_alerts'],
        'summary': summary,
        'entries': entries if include_details else []
    }
    return payload

def _listing_source_label(value):
    norm = _normalize_listing_source(value, default='system')
    if norm == 'listing_center':
        return 'Listing Center'
    if norm == 'user':
        return 'User'
    return 'System'

def _marketplace_upc_lookup_variants(raw_upc):
    """
    UPC matching helper for cross-db marketplace checks:
    supports suffix variants and zero-padded/stripped numeric forms.
    """
    upc = _normalize_upc(raw_upc)
    if not upc:
        return []
    out = []

    def add(v):
        vv = str(v or '').strip().lower()
        if vv and vv not in out:
            out.append(vv)

    add(upc)
    if '-' in upc:
        base, suffix = upc.split('-', 1)
    else:
        base, suffix = upc, ''

    base = (base or '').strip()
    suffix = (suffix or '').strip()
    stripped_base = _strip_leading_zeros_numeric(base) or base

    add(base)
    add(stripped_base)
    if suffix:
        add(f'{base}-{suffix}')
        add(f'{stripped_base}-{suffix}')

    if base.isdigit() and len(base) <= 12:
        add(base.zfill(12))
    if stripped_base.isdigit() and len(stripped_base) <= 12:
        add(stripped_base.zfill(12))
    return out

def _is_marketplace_live_for_upc(upc, live_key_set):
    if not upc or not live_key_set:
        return False
    for key in _marketplace_upc_lookup_variants(upc):
        if key in live_key_set:
            return True
    return False

def _chunk_list(items, size):
    for i in range(0, len(items), size):
        yield items[i:i + size]

def _fetch_live_marketplace_upc_keys(upcs, *, max_lookup_keys=4000):
    """
    Return active listing key sets for eBay/Amazon from store DBs.
    Keeps /items-to-list checkboxes aligned with currently live listings.
    """
    key_pool = set()
    for upc in upcs or []:
        for key in _marketplace_upc_lookup_variants(upc):
            key_pool.add(key)

    payload = {
        'ebay': set(),
        'amazon': set(),
        'ebay_checked': False,
        'amazon_checked': False,
    }
    if not key_pool:
        return payload

    # Avoid expensive cross-db scans on huge pages (ex: analytics calls with limit=50000).
    if len(key_pool) > max_lookup_keys:
        return payload

    keys = sorted(key_pool)
    chunk_size = 700  # stay below SQLite parameter limits

    try:
        with sqlite3.connect('ebayStore.db') as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            for part in _chunk_list(keys, chunk_size):
                placeholders = ','.join('?' for _ in part)
                cur.execute(f'''
                    SELECT UPC
                    FROM INVENTORY
                    WHERE UPC IS NOT NULL
                      AND TRIM(UPC) != ''
                      AND LOWER(TRIM(COALESCE(List_State, ''))) IN ('active', 'live', 'listed')
                      AND TRIM(COALESCE(ItemID, '')) != ''
                      AND COALESCE(CAST(Quantity AS INTEGER), 0) > 0
                      AND LOWER(TRIM(UPC)) IN ({placeholders})
                ''', tuple(part))
                for row in cur.fetchall():
                    for key in _marketplace_upc_lookup_variants(row['UPC']):
                        payload['ebay'].add(key)
            payload['ebay_checked'] = True
    except Exception as e:
        print(f"[_fetch_live_marketplace_upc_keys] eBay lookup failed: {e}")

    try:
        with sqlite3.connect('amazonStore.db') as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            for part in _chunk_list(keys, chunk_size):
                placeholders = ','.join('?' for _ in part)
                cur.execute(f'''
                    SELECT UPC
                    FROM ITEMS
                    WHERE UPC IS NOT NULL
                      AND TRIM(UPC) != ''
                      AND LOWER(TRIM(COALESCE(STATUS, ''))) IN ('active', 'live', 'listed')
                      AND TRIM(COALESCE(ASIN, '')) != ''
                      AND COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
                      AND LOWER(TRIM(UPC)) IN ({placeholders})
                ''', tuple(part))
                for row in cur.fetchall():
                    for key in _marketplace_upc_lookup_variants(row['UPC']):
                        payload['amazon'].add(key)
            payload['amazon_checked'] = True
    except Exception as e:
        print(f"[_fetch_live_marketplace_upc_keys] Amazon lookup failed: {e}")

    return payload

def _fetch_auto_marketplace_listing_links(upcs, *, max_lookup_keys=4000, max_links_per_platform=40):
    """
    Return live marketplace listing links keyed by normalized UPC-variant key.
    This is display-only enrichment for /items-to-list auto listing preview.
    """
    key_pool = set()
    for upc in upcs or []:
        for key in _marketplace_upc_lookup_variants(upc):
            key_pool.add(key)

    if not key_pool:
        return {}
    if len(key_pool) > max_lookup_keys:
        return {}

    listing_map = {}
    dedupe_map = {}
    keys_sorted = sorted(key_pool)
    chunk_size = 700
    amazon_live_max_age_days = _coerce_int(os.getenv('ITEMS_TO_LIST_AMAZON_LIVE_MAX_AGE_DAYS', 45), 45)
    if amazon_live_max_age_days < 0:
        amazon_live_max_age_days = 0
    now_utc = datetime.datetime.utcnow()

    def _is_recent_amazon_listing(last_updated_raw):
        if amazon_live_max_age_days <= 0:
            return True
        dt = _parse_iso_utc_naive(last_updated_raw)
        if dt is None:
            return False
        age_seconds = (now_utc - dt).total_seconds()
        return age_seconds <= (amazon_live_max_age_days * 86400)

    def _add_listing(raw_upc, platform, listing_id='', title='', url=''):
        upc_variants = _marketplace_upc_lookup_variants(raw_upc)
        if not upc_variants:
            return
        listing_id = str(listing_id or '').strip()
        title = str(title or '').strip()
        url = str(url or '').strip()
        if not url and platform == 'ebay' and listing_id:
            url = f'https://www.ebay.com/itm/{listing_id}'
        if not url and platform == 'amazon' and listing_id and listing_id.upper().startswith('B'):
            url = f'https://www.amazon.com/dp/{listing_id}'
        if not listing_id and not url:
            return

        token = f"{listing_id.lower()}|{url.lower()}"
        for key in upc_variants:
            if key not in key_pool:
                continue
            bucket = listing_map.get(key)
            if bucket is None:
                bucket = {'ebay': [], 'amazon': []}
                listing_map[key] = bucket
            dedupe_bucket = dedupe_map.get(key)
            if dedupe_bucket is None:
                dedupe_bucket = {'ebay': set(), 'amazon': set()}
                dedupe_map[key] = dedupe_bucket
            if token in dedupe_bucket[platform]:
                continue
            if len(bucket[platform]) >= max_links_per_platform:
                continue
            dedupe_bucket[platform].add(token)
            bucket[platform].append({
                'platform': platform,
                'listing_id': listing_id,
                'title': title,
                'url': url
            })

    try:
        with sqlite3.connect('ebayStore.db') as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute("PRAGMA table_info('INVENTORY')")
            cols = [r[1] for r in cur.fetchall()]
            cols_lower = {c.lower(): c for c in cols}
            upc_col = cols_lower.get('upc') or cols_lower.get('barcode')
            state_col = cols_lower.get('list_state') or cols_lower.get('status')
            item_id_col = cols_lower.get('itemid') or cols_lower.get('item_id')
            url_col = cols_lower.get('url') or cols_lower.get('viewitemurl')
            title_col = cols_lower.get('title')
            qty_col = cols_lower.get('quantity')
            order_col = cols_lower.get('list_date') or cols_lower.get('created_at')

            if upc_col:
                upc_where = f"{upc_col} IS NOT NULL AND TRIM({upc_col}) != ''"
                state_where = f"LOWER(TRIM(COALESCE({state_col}, ''))) IN ('active', 'live', 'listed')" if state_col else "1=1"
                item_where = f"TRIM(COALESCE({item_id_col}, '')) != ''" if item_id_col else "1=1"
                qty_where = f"COALESCE(CAST({qty_col} AS INTEGER), 0) > 0" if qty_col else "1=1"
                item_expr = f"{item_id_col} AS ITEM_ID" if item_id_col else "'' AS ITEM_ID"
                url_expr = f"{url_col} AS URL" if url_col else "'' AS URL"
                title_expr = f"{title_col} AS TITLE" if title_col else "'' AS TITLE"
                order_sql = f" ORDER BY {order_col} DESC" if order_col else ""

                for part in _chunk_list(keys_sorted, chunk_size):
                    placeholders = ','.join('?' for _ in part)
                    cur.execute(f'''
                        SELECT {upc_col} AS UPC_RAW, {item_expr}, {url_expr}, {title_expr}
                        FROM INVENTORY
                        WHERE {upc_where}
                          AND {state_where}
                          AND {item_where}
                          AND {qty_where}
                          AND LOWER(TRIM({upc_col})) IN ({placeholders})
                        {order_sql}
                    ''', tuple(part))
                    for row in cur.fetchall():
                        _add_listing(
                            row['UPC_RAW'],
                            'ebay',
                            listing_id=row['ITEM_ID'],
                            title=row['TITLE'],
                            url=row['URL']
                        )
    except Exception as e:
        print(f"[_fetch_auto_marketplace_listing_links] eBay lookup failed: {e}")

    try:
        with sqlite3.connect('amazonStore.db') as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute("PRAGMA table_info('ITEMS')")
            cols = [r[1] for r in cur.fetchall()]
            cols_lower = {c.lower(): c for c in cols}
            upc_col = cols_lower.get('upc') or cols_lower.get('barcode')
            status_col = cols_lower.get('status')
            asin_col = cols_lower.get('asin')
            sku_col = cols_lower.get('sku')
            url_col = cols_lower.get('product_url') or cols_lower.get('url')
            title_col = cols_lower.get('title')
            qty_col = cols_lower.get('quantity')
            order_col = cols_lower.get('last_updated') or cols_lower.get('created_at')

            if upc_col:
                upc_where = f"{upc_col} IS NOT NULL AND TRIM({upc_col}) != ''"
                status_where = f"LOWER(TRIM(COALESCE({status_col}, ''))) IN ('active', 'live', 'listed')" if status_col else "1=1"
                qty_where = f"COALESCE(CAST({qty_col} AS INTEGER), 0) > 0" if qty_col else "1=1"
                if asin_col:
                    live_id_where = f"TRIM(COALESCE({asin_col}, '')) != ''"
                elif sku_col:
                    live_id_where = f"TRIM(COALESCE({sku_col}, '')) != ''"
                else:
                    live_id_where = "1=1"
                asin_expr = f"{asin_col} AS ASIN" if asin_col else "'' AS ASIN"
                sku_expr = f"{sku_col} AS SKU" if sku_col else "'' AS SKU"
                url_expr = f"{url_col} AS URL" if url_col else "'' AS URL"
                title_expr = f"{title_col} AS TITLE" if title_col else "'' AS TITLE"
                updated_expr = f"{order_col} AS LAST_UPDATED_RAW" if order_col else "NULL AS LAST_UPDATED_RAW"
                order_sql = f" ORDER BY {order_col} DESC" if order_col else ""

                for part in _chunk_list(keys_sorted, chunk_size):
                    placeholders = ','.join('?' for _ in part)
                    cur.execute(f'''
                        SELECT {upc_col} AS UPC_RAW, {asin_expr}, {sku_expr}, {url_expr}, {title_expr}, {updated_expr}
                        FROM ITEMS
                        WHERE {upc_where}
                          AND {status_where}
                          AND {qty_where}
                          AND {live_id_where}
                          AND LOWER(TRIM({upc_col})) IN ({placeholders})
                        {order_sql}
                    ''', tuple(part))
                    for row in cur.fetchall():
                        if not _is_recent_amazon_listing(row['LAST_UPDATED_RAW']):
                            continue
                        asin = str(row['ASIN'] or '').strip()
                        sku = str(row['SKU'] or '').strip()
                        listing_id = asin or sku
                        listing_url = str(row['URL'] or '').strip()
                        if not listing_url and asin:
                            listing_url = f"https://www.amazon.com/dp/{asin}"
                        _add_listing(
                            row['UPC_RAW'],
                            'amazon',
                            listing_id=listing_id,
                            title=row['TITLE'],
                            url=listing_url
                        )
    except Exception as e:
        print(f"[_fetch_auto_marketplace_listing_links] Amazon lookup failed: {e}")

    return listing_map

def _apply_marketplace_status_overlay(rows):
    """
    Normalize marketplace status + source payload for UI rows.
    Manual list-status in bol.db is the source of truth for /items-to-list.
    Live marketplace DBs are intentionally not used here.
    """
    if not rows:
        return

    for row in rows:
        row['listed_ebay_live'] = None
        row['listed_amazon_live'] = None

        for mp in ('amazon', 'ebay', 'facebook'):
            listed_key = f'listed_{mp}'
            source_key = f'listed_{mp}_source'
            source_label_key = f'{source_key}_label'
            listed = int(row.get(listed_key) or 0) == 1
            source = (row.get(source_key) or '').strip()
            if listed and not source:
                source = 'system'
            row[source_key] = source
            row[source_label_key] = _listing_source_label(source) if listed else ''

def _listing_center_mark_bol_listed(marketplace, *, upc='', lot_number='', item_id=None):
    """
    Mark exactly one bol_items row as listed for Listing Center flows.
    Resolution order: explicit id, then (upc, lot), then newest by upc.
    """
    mp = (marketplace or '').strip().lower()
    if mp not in ('amazon', 'ebay', 'facebook'):
        return {'success': False, 'error': 'invalid marketplace'}

    upc_n = _strip_leading_zeros_numeric(_normalize_upc(upc))
    lot_n = _normalize_lot_number(lot_number)

    target_id = None
    if item_id is not None and str(item_id).strip() != '':
        try:
            target_id = int(item_id)
        except Exception:
            target_id = None
        if target_id is not None and target_id <= 0:
            target_id = None

    if not upc_n and target_id is None:
        return {'success': False, 'error': 'missing upc or id'}

    _ensure_bol_list_status_column()
    conn = None
    try:
        conn = sqlite3.connect('bol.db', isolation_level='IMMEDIATE')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()

        row = None
        if target_id is not None:
            cur.execute('''
                SELECT id, upc, COALESCE(lot_number, '') AS lot_number
                FROM bol_items
                WHERE id = ?
                LIMIT 1
            ''', (target_id,))
            row = cur.fetchone()
        else:
            if lot_n:
                cur.execute('''
                    SELECT id, upc, COALESCE(lot_number, '') AS lot_number
                    FROM bol_items
                    WHERE TRIM(upc) = ? COLLATE NOCASE
                      AND lot_number = ? COLLATE NOCASE
                    ORDER BY import_date DESC, id DESC
                    LIMIT 1
                ''', (upc_n, lot_n))
                row = cur.fetchone()
            if not row:
                cur.execute('''
                    SELECT id, upc, COALESCE(lot_number, '') AS lot_number
                    FROM bol_items
                    WHERE TRIM(upc) = ? COLLATE NOCASE
                    ORDER BY import_date DESC, id DESC
                    LIMIT 1
                ''', (upc_n,))
                row = cur.fetchone()

        if not row:
            return {'success': False, 'error': 'target row not found'}

        resolved_id = int(row['id'])
        resolved_upc = _strip_leading_zeros_numeric(_normalize_upc(row['upc'])) or upc_n
        resolved_lot = _normalize_lot_number(row['lot_number'])
        now_iso = datetime.datetime.now(datetime.UTC).isoformat()

        if mp == 'amazon':
            cur.execute('''
                UPDATE bol_items
                SET listed_amazon = 1,
                    listed_amazon_date = ?,
                    listed_amazon_source = 'listing_center'
                WHERE id = ?
            ''', (now_iso, resolved_id))
        elif mp == 'ebay':
            cur.execute('''
                UPDATE bol_items
                SET listed_ebay = 1,
                    listed_ebay_date = ?,
                    listed_ebay_source = 'listing_center'
                WHERE id = ?
            ''', (now_iso, resolved_id))
        else:
            cur.execute('''
                UPDATE bol_items
                SET listed_facebook = 1,
                    listed_facebook_date = ?,
                    listed_facebook_source = 'listing_center'
                WHERE id = ?
            ''', (now_iso, resolved_id))

        cur.execute('''
            UPDATE bol_items
            SET list_status = CASE
                WHEN COALESCE(listed_amazon, 0) = 1
                  OR COALESCE(listed_ebay, 0) = 1
                  OR COALESCE(listed_facebook, 0) = 1
                THEN 'listed'
                ELSE NULL
            END
            WHERE id = ?
        ''', (resolved_id,))

        conn.commit()
        return {
            'success': True,
            'id': resolved_id,
            'upc': resolved_upc,
            'lot_number': resolved_lot
        }
    except Exception as e:
        try:
            if conn:
                conn.rollback()
        except Exception:
            pass
        return {'success': False, 'error': _safe_error(e, 'listing_center:mark_listed')}
    finally:
        try:
            if conn:
                conn.close()
        except Exception:
            pass

def _coerce_bool(value):
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    if isinstance(value, (int, float)):
        return value != 0
    s = str(value).strip().lower()
    return s in ('1', 'true', 'yes', 'y', 'on')

def _request_lot_scope_is_all(data=None):
    scope = ''
    if isinstance(data, dict):
        scope = str(data.get('lot_scope') or data.get('scope') or '').strip().lower()
    if not scope:
        try:
            scope = str(request.args.get('lot_scope') or request.form.get('lot_scope') or '').strip().lower()
        except Exception:
            scope = ''
    return scope == 'all'

def _preferred_lot_from_request(data=None):
    if _request_lot_scope_is_all(data):
        return ''
    lot = ''
    if isinstance(data, dict):
        lot = _normalize_lot_number(data.get('lot_number') or data.get('lot'))
    if not lot:
        try:
            lot = _normalize_lot_number(request.args.get('lot_number') or request.args.get('lot'))
        except Exception:
            lot = ''
    if not lot:
        try:
            lot = _normalize_lot_number(session.get('selected_lot'))
        except Exception:
            lot = ''
    return lot

def _select_prep_status_row(cur, upc, lot_number='', columns='*'):
    """Fetch prep status row for (upc, lot) with fallback to legacy lotless rows."""
    upc_n = _normalize_upc_preserve_suffix_for_match(upc)
    if not upc_n:
        return None
    lot_n = _normalize_lot_number(lot_number)
    if lot_n:
        cur.execute(
            f'''SELECT {columns}
                FROM items_prep_status
                WHERE upc = ? COLLATE NOCASE
                  AND COALESCE(lot_number, '') = ? COLLATE NOCASE
                LIMIT 1''',
            (upc_n, lot_n)
        )
        row = cur.fetchone()
        if row:
            return row
    cur.execute(
        f'''SELECT {columns}
            FROM items_prep_status
            WHERE upc = ? COLLATE NOCASE
              AND COALESCE(lot_number, '') = ''
            LIMIT 1''',
        (upc_n,)
    )
    return cur.fetchone()

def _resolve_prep_status_lot(cur, upc, preferred_lot=''):
    """Return the lot key that should be used for UPDATE/DELETE on prep status."""
    upc_n = _normalize_upc_preserve_suffix_for_match(upc)
    lot_n = _normalize_lot_number(preferred_lot)
    if not upc_n:
        return lot_n
    if lot_n:
        cur.execute('''
            SELECT 1
            FROM items_prep_status
            WHERE upc = ? COLLATE NOCASE
              AND COALESCE(lot_number, '') = ? COLLATE NOCASE
            LIMIT 1
        ''', (upc_n, lot_n))
        if cur.fetchone():
            return lot_n
    cur.execute('''
        SELECT 1
        FROM items_prep_status
        WHERE upc = ? COLLATE NOCASE
          AND COALESCE(lot_number, '') = ''
        LIMIT 1
    ''', (upc_n,))
    if cur.fetchone():
        return ''
    return lot_n

def _resolve_bol_lot_for_upc(cur, upc, preferred_lot=''):
    """Resolve the most relevant lot for a UPC, preferring explicit/session lot."""
    upc_n = _normalize_upc_preserve_suffix_for_match(upc)
    if not upc_n:
        return ''
    lot_n = _normalize_lot_number(preferred_lot)
    if lot_n:
        cur.execute('''
            SELECT lot_number
            FROM bol_items
            WHERE upc = ? COLLATE NOCASE
              AND lot_number = ? COLLATE NOCASE
            ORDER BY import_date DESC, id DESC
            LIMIT 1
        ''', (upc_n, lot_n))
        row = cur.fetchone()
        if row and row[0]:
            return _normalize_lot_number(row[0])
    cur.execute('''
        SELECT lot_number
        FROM bol_items
        WHERE upc = ? COLLATE NOCASE
        ORDER BY import_date DESC, id DESC
        LIMIT 1
    ''', (upc_n,))
    row = cur.fetchone()
    return _normalize_lot_number(row[0] if row else lot_n)

def _select_canonical_bol_row(cur, upc, lot_number='', columns='id, upc, lot_number', strict_lot=False):
    """Return newest canonical bol_items row for a UPC (+ optional lot)."""
    upc_n = _normalize_upc_preserve_suffix_for_match(upc)
    if not upc_n:
        return None
    lot_n = _normalize_lot_number(lot_number)
    if lot_n:
        cur.execute(
            f'''SELECT {columns}
                FROM bol_items
                WHERE upc = ? COLLATE NOCASE
                  AND lot_number = ? COLLATE NOCASE
                ORDER BY import_date DESC, id DESC
                LIMIT 1''',
            (upc_n, lot_n)
        )
        row = cur.fetchone()
        if row:
            return row
        if strict_lot:
            return None
    cur.execute(
        f'''SELECT {columns}
            FROM bol_items
            WHERE upc = ? COLLATE NOCASE
            ORDER BY import_date DESC, id DESC
            LIMIT 1''',
        (upc_n,)
    )
    return cur.fetchone()

def _has_multiple_lot_rows(cur, upc):
    """True when a UPC exists in more than one distinct LOT in bol_items."""
    upc_n = _normalize_upc_preserve_suffix_for_match(upc)
    if not upc_n:
        return False
    cur.execute('''
        SELECT COUNT(DISTINCT COALESCE(lot_number, ''))
        FROM bol_items
        WHERE upc = ? COLLATE NOCASE
    ''', (upc_n,))
    row = cur.fetchone()
    lot_count = int((row[0] if row else 0) or 0)
    return lot_count > 1

def _resolve_action_lot_assignment(cur, upc, requested_lot=''):
    """Resolve lot for mutable item-prep actions and report whether fallback was auto-assigned."""
    requested = _normalize_lot_number(requested_lot)
    assigned = _resolve_bol_lot_for_upc(cur, upc, requested)
    auto_assigned = False
    auto_reason = ''

    if assigned:
        if not requested:
            auto_assigned = True
            auto_reason = 'no_lot_requested_used_latest'
        elif assigned.lower() != requested.lower():
            auto_assigned = True
            auto_reason = 'requested_lot_unavailable_used_latest'

    return {
        'requested_lot': requested,
        'assigned_lot': assigned,
        'auto_assigned': auto_assigned,
        'auto_assign_reason': auto_reason
    }

def _check_requested_lot_mismatch(cur, upc, requested_lot=''):
    """Detect whether requested lot is invalid for an existing UPC and return suggested latest lot."""
    upc_n = _normalize_upc_preserve_suffix_for_match(upc)
    requested = _normalize_lot_number(requested_lot)
    if not upc_n or not requested:
        return False, ''

    cur.execute('''
        SELECT 1
        FROM bol_items
        WHERE upc = ? COLLATE NOCASE
        LIMIT 1
    ''', (upc_n,))
    if not cur.fetchone():
        return False, ''

    cur.execute('''
        SELECT 1
        FROM bol_items
        WHERE upc = ? COLLATE NOCASE
          AND lot_number = ? COLLATE NOCASE
        LIMIT 1
    ''', (upc_n, requested))
    if cur.fetchone():
        return False, requested

    suggested = _resolve_bol_lot_for_upc(cur, upc_n, '')
    return True, _normalize_lot_number(suggested)

def _lot_mismatch_payload(*, upc, requested_lot, suggested_lot=''):
    upc_n = _normalize_upc_preserve_suffix_for_match(upc)
    requested = _normalize_lot_number(requested_lot)
    suggested = _normalize_lot_number(suggested_lot)
    msg = f'LOT match failed for UPC {upc_n} in LOT {requested}.'
    if suggested:
        msg += f' Most recent available LOT: {suggested}.'
    msg += ' Continue without LOT or cancel.'
    return {
        'success': False,
        'error': msg,
        'lot_match_error': True,
        'requested_lot': requested,
        'suggested_lot': suggested,
        'can_continue_without_lot': True,
        'can_override_this_lot': True,
        'can_auto_assign': True
    }

def _items_prep_items_to_list_url(upc, lot_number=''):
    try:
        from urllib.parse import quote
        upc_n = _normalize_upc_preserve_suffix_for_match(upc)
        lot_n = _normalize_lot_number(lot_number)
        url = f"/items-to-list?q={quote(upc_n)}&status=good,bad,return&direct_search=1"
        if lot_n:
            url += f"&lot={quote(lot_n)}"
        return url
    except Exception:
        return '/items-to-list'

def _items_prep_overage_payload(*, upc, lot_number='', unchecked_remaining=0, requested_qty=1, action='add'):
    upc_n = _normalize_upc_preserve_suffix_for_match(upc)
    lot_n = _normalize_lot_number(lot_number)
    try:
        unchecked_n = int(unchecked_remaining or 0)
    except Exception:
        unchecked_n = 0
    try:
        req_qty_n = int(requested_qty or 1)
    except Exception:
        req_qty_n = 1
    return {
        'success': False,
        'overage_blocked': True,
        'requires_exception_override': True,
        'error': (
            f'Item {upc_n} appears fully added already '
            f'(unchecked remaining: {unchecked_n}).'
        ),
        'message': (
            'This item already appears fully added for the current BOL quantity. '
            'Use Add Anyway to save as an exception, or skip.'
        ),
        'upc': upc_n,
        'lot_number': lot_n,
        'unchecked_remaining': unchecked_n,
        'requested_qty': req_qty_n,
        'action': (action or 'add'),
        'items_to_list_url': _items_prep_items_to_list_url(upc_n, lot_n)
    }

def _items_prep_record_exception(cur, *, upc, base_upc=None, lot_number='', action='overage_override',
                                 quantity=1, unchecked_remaining=None, source='item-prep',
                                 note=None, meta=None):
    if cur is None:
        return
    upc_n = _normalize_upc_preserve_suffix_for_match(upc)
    base_upc_n = _normalize_upc_preserve_suffix_for_match(base_upc or upc_n)
    lot_n = _normalize_lot_number(lot_number)
    action_n = (action or 'overage_override').strip().lower()
    source_n = (source or 'item-prep').strip() or 'item-prep'
    note_n = (note or '').strip() or None
    try:
        qty_n = int(quantity or 1)
    except Exception:
        qty_n = 1
    try:
        unchecked_n = int(unchecked_remaining) if unchecked_remaining is not None else None
    except Exception:
        unchecked_n = None

    meta_json = None
    try:
        if meta is not None:
            meta_json = json.dumps(meta, ensure_ascii=False)
    except Exception:
        meta_json = None

    cur.execute('''
        CREATE TABLE IF NOT EXISTS items_prep_exceptions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            created_at TEXT NOT NULL,
            upc TEXT NOT NULL,
            base_upc TEXT NOT NULL,
            lot_number TEXT,
            action TEXT NOT NULL,
            quantity INTEGER,
            unchecked_remaining INTEGER,
            source TEXT,
            note TEXT,
            meta_json TEXT
        )
    ''')
    cur.execute('''
        INSERT INTO items_prep_exceptions (
            created_at, upc, base_upc, lot_number, action,
            quantity, unchecked_remaining, source, note, meta_json
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ''', (
        _listagent_now_iso(), upc_n, base_upc_n, lot_n, action_n,
        qty_n, unchecked_n, source_n, note_n, meta_json
    ))

def _ensure_items_prep_tables(force=False):
    while True:
        now_ts = time.time()
        with _items_prep_ensure_lock:
            last_success = float(_items_prep_ensure_state.get('last_success') or 0.0)
            running = bool(_items_prep_ensure_state.get('running'))
            if (
                (not force)
                and last_success > 0
                and (now_ts - last_success) < _ITEMS_PREP_ENSURE_MIN_INTERVAL_SECONDS
            ):
                return
            if not running:
                _items_prep_ensure_state['running'] = True
                break
        time.sleep(0.01)

    conn = None
    success = False
    try:
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='items_prep_status'")
        has_status_table = cur.fetchone() is not None

        if not has_status_table:
            cur.execute('''
                CREATE TABLE IF NOT EXISTS items_prep_status (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    upc TEXT NOT NULL,
                    lot_number TEXT NOT NULL DEFAULT '',
                    status TEXT,
                    reason TEXT,
                    note TEXT,
                    updated_at TEXT,
                    location TEXT,
                    pictureposition TEXT,
                    quantity INTEGER DEFAULT 1,
                    UNIQUE(upc, lot_number)
                )
            ''')
        else:
            cur.execute("PRAGMA table_info(items_prep_status)")
            status_info = cur.fetchall()
            status_cols = [r[1] for r in status_info]
            has_upc_pk = any((r[1] == 'upc' and int(r[5] or 0) == 1) for r in status_info)
            needs_migration = (
                'id' not in status_cols or
                'lot_number' not in status_cols or
                has_upc_pk
            )

            if needs_migration:
                select_location = 'location' if 'location' in status_cols else 'NULL'
                select_pictureposition = 'pictureposition' if 'pictureposition' in status_cols else 'NULL'
                select_quantity = 'quantity' if 'quantity' in status_cols else '1'
                cur.execute('''
                    CREATE TABLE IF NOT EXISTS items_prep_status_new (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        upc TEXT NOT NULL,
                        lot_number TEXT NOT NULL DEFAULT '',
                        status TEXT,
                        reason TEXT,
                        note TEXT,
                        updated_at TEXT,
                        location TEXT,
                        pictureposition TEXT,
                        quantity INTEGER DEFAULT 1,
                        UNIQUE(upc, lot_number)
                    )
                ''')
                cur.execute(f'''
                    INSERT OR REPLACE INTO items_prep_status_new
                    (upc, lot_number, status, reason, note, updated_at, location, pictureposition, quantity)
                    SELECT
                        upc,
                        '',
                        status,
                        reason,
                        note,
                        updated_at,
                        {select_location},
                        {select_pictureposition},
                        COALESCE({select_quantity}, 1)
                    FROM items_prep_status
                    WHERE upc IS NOT NULL
                      AND TRIM(COALESCE(upc, '')) != ''
                ''')
                cur.execute('DROP TABLE items_prep_status')
                cur.execute('ALTER TABLE items_prep_status_new RENAME TO items_prep_status')
            else:
                if 'lot_number' not in status_cols:
                    cur.execute("ALTER TABLE items_prep_status ADD COLUMN lot_number TEXT NOT NULL DEFAULT ''")
                if 'location' not in status_cols:
                    cur.execute('ALTER TABLE items_prep_status ADD COLUMN location TEXT')
                if 'pictureposition' not in status_cols:
                    cur.execute('ALTER TABLE items_prep_status ADD COLUMN pictureposition TEXT')
                if 'quantity' not in status_cols:
                    cur.execute('ALTER TABLE items_prep_status ADD COLUMN quantity INTEGER DEFAULT 1')
                # Keep lot_number normalized for reliable matching.
                cur.execute("UPDATE items_prep_status SET lot_number = COALESCE(TRIM(lot_number), '')")

        cur.execute('CREATE UNIQUE INDEX IF NOT EXISTS idx_items_prep_status_upc_lot ON items_prep_status(upc, lot_number)')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_items_prep_status_upc ON items_prep_status(upc)')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_items_prep_status_lot ON items_prep_status(lot_number)')

        # One-time compatibility backfill:
        # if a UPC maps to exactly one lot in bol_items, assign that lot to legacy lotless prep rows.
        cur.execute('CREATE TABLE IF NOT EXISTS app_metadata (key TEXT PRIMARY KEY, value TEXT)')
        cur.execute('SELECT value FROM app_metadata WHERE key = ? LIMIT 1', ('items_prep_lot_backfill_v1',))
        lot_backfill_marker_row = cur.fetchone()
        lot_backfill_marker = (lot_backfill_marker_row[0] if lot_backfill_marker_row else '')
        if str(lot_backfill_marker) != '1':
            cur.execute('''
                SELECT upc, MIN(COALESCE(lot_number, '')) AS lot_number
                FROM bol_items
                WHERE lot_number IS NOT NULL
                  AND TRIM(COALESCE(lot_number, '')) != ''
                GROUP BY upc
                HAVING COUNT(DISTINCT COALESCE(lot_number, '')) = 1
            ''')
            for upc, only_lot in cur.fetchall():
                cur.execute('''
                    SELECT 1
                    FROM items_prep_status
                    WHERE upc = ? COLLATE NOCASE
                      AND COALESCE(lot_number, '') = ? COLLATE NOCASE
                    LIMIT 1
                ''', (upc, only_lot))
                if cur.fetchone():
                    continue
                cur.execute('''
                    UPDATE items_prep_status
                    SET lot_number = ?
                    WHERE upc = ? COLLATE NOCASE
                      AND COALESCE(lot_number, '') = ''
                ''', (only_lot, upc))
            cur.execute(
                'INSERT OR REPLACE INTO app_metadata (key, value) VALUES (?, ?)',
                ('items_prep_lot_backfill_v1', '1')
            )

        cur.execute('''
            CREATE TABLE IF NOT EXISTS items_prep_images (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                upc TEXT,
                image_path TEXT,
                created_at TEXT,
                deleted_at TEXT,
                expires_at TEXT,
                trash_path TEXT
            )
        ''')
        cur.execute('''
            CREATE TABLE IF NOT EXISTS items_prep_notes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                upc TEXT,
                note TEXT,
                created_at TEXT
            )
        ''')

        cur.execute("PRAGMA table_info(items_prep_images)")
        cols = [r[1] for r in cur.fetchall()]
        if 'deleted_at' not in cols:
            cur.execute("ALTER TABLE items_prep_images ADD COLUMN deleted_at TEXT")
        if 'expires_at' not in cols:
            cur.execute("ALTER TABLE items_prep_images ADD COLUMN expires_at TEXT")
        if 'trash_path' not in cols:
            cur.execute("ALTER TABLE items_prep_images ADD COLUMN trash_path TEXT")
        if 'row_status' not in cols:
            cur.execute("ALTER TABLE items_prep_images ADD COLUMN row_status TEXT DEFAULT ''")
        # Add rotation column to keep track of image orientation (degrees)
        if 'rotation' not in cols:
            try:
                cur.execute("ALTER TABLE items_prep_images ADD COLUMN rotation INTEGER DEFAULT 0")
            except Exception:
                # some older sqlite versions may behave differently; ignore errors
                pass

        cur.execute("PRAGMA table_info(items_prep_notes)")
        note_cols = [r[1] for r in cur.fetchall()]
        if 'row_status' not in note_cols:
            cur.execute("ALTER TABLE items_prep_notes ADD COLUMN row_status TEXT DEFAULT ''")

        # Speed up per-UPC image/note lookups used by list views.
        cur.execute('CREATE INDEX IF NOT EXISTS idx_items_prep_images_upc ON items_prep_images(upc)')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_items_prep_images_upc_deleted ON items_prep_images(upc, deleted_at)')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_items_prep_images_upc_status_deleted ON items_prep_images(upc, row_status, deleted_at)')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_items_prep_notes_upc ON items_prep_notes(upc)')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_items_prep_notes_upc_status ON items_prep_notes(upc, row_status)')

        # Exception audit trail for intentional overage adds.
        cur.execute('''
            CREATE TABLE IF NOT EXISTS items_prep_exceptions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                created_at TEXT NOT NULL,
                upc TEXT NOT NULL,
                base_upc TEXT NOT NULL,
                lot_number TEXT,
                action TEXT NOT NULL,
                quantity INTEGER,
                unchecked_remaining INTEGER,
                source TEXT,
                note TEXT,
                meta_json TEXT
            )
        ''')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_items_prep_exceptions_created_at ON items_prep_exceptions(created_at, id)')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_items_prep_exceptions_upc ON items_prep_exceptions(upc)')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_items_prep_exceptions_base_upc ON items_prep_exceptions(base_upc)')
        
        # Create print queue table for cross-device synchronization
        cur.execute('''CREATE TABLE IF NOT EXISTS print_queue (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            barcode TEXT NOT NULL,
            added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(title, barcode)
        )''')
        
        conn.commit()
        success = True
    except Exception as e:
        print('Failed ensuring items_prep tables:', e)
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass
        with _items_prep_ensure_lock:
            _items_prep_ensure_state['running'] = False
            if success:
                _items_prep_ensure_state['last_success'] = time.time()

def _now_iso():
    import datetime as _dt
    return _dt.datetime.now(_dt.UTC).isoformat()

def _trash_retention_days():
    # Prefer app_settings table value; fallback to env var; then default 7
    try:
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='app_settings'")
        if cur.fetchone():
            cur.execute("SELECT value FROM app_settings WHERE key='TRASH_RETENTION_DAYS'")
            row = cur.fetchone()
            if row and row[0] is not None:
                return int(row[0])
    except Exception:
        pass
    finally:
        conn.close()
    try:
        return int(os.getenv('TRASH_RETENTION_DAYS', '7'))
    except Exception:
        return 7

def _ensure_app_settings():
    try:
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        cur.execute('''CREATE TABLE IF NOT EXISTS app_settings (
            key TEXT PRIMARY KEY,
            value TEXT
        )''')
        conn.commit()
    except Exception as e:
        print('Failed ensuring app_settings:', e)
    finally:
        conn.close()

def _set_trash_retention_days(days: int):
    try:
        days = int(days)
        _ensure_app_settings()
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        cur.execute("INSERT INTO app_settings(key, value) VALUES('TRASH_RETENTION_DAYS', ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (str(days),))
        # Update expires_at for existing trashed items
        cur.execute("SELECT id, deleted_at FROM items_prep_images WHERE deleted_at IS NOT NULL")
        rows = cur.fetchall()
        import datetime as _dt
        for rid, del_at in rows:
            try:
                base = _dt.datetime.fromisoformat(del_at)
            except Exception:
                base = _dt.datetime.now(_dt.UTC)
            new_exp = (base + _dt.timedelta(days=days)).isoformat()
            cur.execute('UPDATE items_prep_images SET expires_at=? WHERE id=?', (new_exp, rid))
        conn.commit()
        return True
    except Exception as e:
        print('Failed setting retention days:', e)
        return False
    finally:
        conn.close()

def _move_to_trash(abs_path, upc):
    try:
        # Build trash path under static/items_prep_trash/YYYY/MM/UPC
        import datetime as _dt
        base = os.path.join(app.root_path, 'static', 'items_prep_trash')
        now = _dt.datetime.now(_dt.UTC)
        year = str(now.year)
        month = f"{now.month:02d}"
        target_dir = os.path.join(base, year, month, str(upc))
        os.makedirs(target_dir, exist_ok=True)
        fname = os.path.basename(abs_path)
        target = os.path.join(target_dir, fname)
        # If name exists, add counter
        if os.path.exists(target):
            name, ext = os.path.splitext(fname)
            k = 1
            while os.path.exists(target):
                target = os.path.join(target_dir, f"{name}_{k}{ext}")
                k += 1
        os.replace(abs_path, target)
        # Return relative path under static
        rel = os.path.relpath(target, os.path.join(app.root_path, 'static')).replace('\\','/')
        return rel
    except Exception as e:
        print('Failed move to trash:', e)
        return None

def _purge_expired_trash():
    try:
        _ensure_items_prep_tables()
        conn = sqlite3.connect('bol.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute("SELECT id, trash_path FROM items_prep_images WHERE deleted_at IS NOT NULL AND expires_at IS NOT NULL AND expires_at <= ?", (_now_iso(),))
        rows = cur.fetchall()
        count = 0
        for r in rows:
            tr = r['trash_path']
            if tr:
                abs_path = os.path.join(app.root_path, 'static', tr)
                try:
                    if os.path.isfile(abs_path):
                        os.remove(abs_path)
                except Exception as fe:
                    print('Purge remove failed:', fe)
            try:
                cur.execute('DELETE FROM items_prep_images WHERE id = ?', (r['id'],))
                count += 1
            except Exception as de:
                print('Purge delete row failed:', de)
        conn.commit()
        return count
    except Exception as e:
        print('Purge error:', e)
        return 0
    finally:
        conn.close()

_trash_purger_started = False
def _start_trash_purger_thread():
    global _trash_purger_started
    if _trash_purger_started:
        return
    _trash_purger_started = True
    def _runner():
        import time as _time
        while True:
            try:
                _purge_expired_trash()
            except Exception as e:
                print('Trash purge tick error:', e)
            _time.sleep(24*60*60)
    t = threading.Thread(target=_runner, daemon=True)
    t.start()

# ZERO-QUANTITY DELETION WORKER
# ============================================================================
_zero_qty_deleter_started = False
_automatic_removal_started = False

def _purge_zero_qty_items():
    """Delete searchRack items that have been at 0 quantity for the configured interval"""
    try:
        conn = sqlite3.connect('searchRack.db')
        cur = conn.cursor()
        
        # Ensure tables exist
        cur.execute('''
            CREATE TABLE IF NOT EXISTS zero_qty_pending_deletion (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                searchrack_id INTEGER,
                marked_at TEXT,
                delete_at TEXT,
                deletion_cancelled INTEGER DEFAULT 0
            )
        ''')
        
        cur.execute('''
            CREATE TABLE IF NOT EXISTS zero_qty_settings (
                key TEXT PRIMARY KEY,
                value TEXT
            )
        ''')
        
        # Get interval from settings
        cur.execute("SELECT value FROM zero_qty_settings WHERE key = 'interval_minutes'")
        settings = cur.fetchone()
        interval_minutes = int(settings[0]) if settings else 60
        
        from datetime import datetime, timedelta
        now = datetime.now()
        
        # STEP 1: Scan for unmarked zero-quantity items and mark them
        print(f"🔍 Scanning for unmarked zero-quantity items...")
        cur.execute('''
            SELECT ID, BARCODE, TITLE 
            FROM SEARCHRACK 
            WHERE QUANTITY = 0
        ''')
        zero_qty_items = cur.fetchall()
        
        if zero_qty_items:
            # Get already marked items
            cur.execute('SELECT searchrack_id FROM zero_qty_pending_deletion')
            already_marked = {row[0] for row in cur.fetchall()}
            
            marked_count = 0
            for item_id, barcode, title in zero_qty_items:
                if item_id not in already_marked:
                    delete_at = now + timedelta(minutes=interval_minutes)
                    cur.execute('''
                        INSERT INTO zero_qty_pending_deletion (searchrack_id, marked_at, delete_at, deletion_cancelled)
                        VALUES (?, ?, ?, 0)
                    ''', (item_id, now.isoformat(), delete_at.isoformat()))
                    marked_count += 1
                    print(f"  ✓ Marked item {item_id} ({barcode}): {title[:50]} for deletion")
            
            if marked_count > 0:
                print(f"✅ Marked {marked_count} new zero-quantity items for deletion")
                conn.commit()
        
        # STEP 2: Find items ready for deletion (past grace period and not cancelled)
        cur.execute('''
            SELECT id, searchrack_id, marked_at, delete_at 
            FROM zero_qty_pending_deletion 
            WHERE delete_at <= ? AND COALESCE(deletion_cancelled, 0) = 0
        ''', (now.isoformat(),))
        
        items_to_delete = cur.fetchall()
        
        if not items_to_delete:
            return
        
        print(f"🗑️  Processing {len(items_to_delete)} zero-quantity items for deletion...")
        
        # Ensure archived table exists
        cur.execute('''
            CREATE TABLE IF NOT EXISTS archived_searchrack (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                original_id INTEGER,
                title TEXT,
                barcode TEXT,
                item_position TEXT,
                images TEXT,
                pictureposition TEXT,
                itemid TEXT,
                quantity INTEGER,
                created_at TEXT,
                image TEXT,
                archived_at TEXT,
                reason TEXT
            )
        ''')
        
        deleted_count = 0
        for pending_id, searchrack_id, marked_at, delete_at in items_to_delete:
            # Verify the item still has 0 quantity
            cur.execute('SELECT QUANTITY FROM SEARCHRACK WHERE ID = ?', (searchrack_id,))
            row = cur.fetchone()
            
            if not row:
                # Item already deleted somehow, just remove from pending
                cur.execute('DELETE FROM zero_qty_pending_deletion WHERE id = ?', (pending_id,))
                continue
            
            qty = row[0] or 0
            if qty > 0:
                # Quantity was increased, remove from pending deletion
                cur.execute('DELETE FROM zero_qty_pending_deletion WHERE id = ?', (pending_id,))
                print(f"  ℹ️  Item {searchrack_id} quantity is now {qty}, skipping deletion")
                continue
            
            # Archive the item before deletion
            cur.execute('''
                INSERT INTO archived_searchrack 
                (original_id, title, barcode, item_position, images, pictureposition, itemid, quantity, created_at, image, archived_at, reason)
                SELECT ID, TITLE, BARCODE, ITEM_POSITION, IMAGES, PICTUREPOSITION, ITEMID, QUANTITY, CREATED_AT, IMAGE, ?, 'zero_quantity_auto_delete'
                FROM SEARCHRACK WHERE ID = ?
            ''', (now.isoformat(), searchrack_id))
            
            # Delete the item from SEARCHRACK
            cur.execute('DELETE FROM SEARCHRACK WHERE ID = ?', (searchrack_id,))
            
            # Remove from pending deletion
            cur.execute('DELETE FROM zero_qty_pending_deletion WHERE id = ?', (pending_id,))
            
            deleted_count += 1
            print(f"  ✓ Deleted item {searchrack_id} (marked at {marked_at})")
        
        conn.commit()
        
        if deleted_count > 0:
            print(f"✅ Deleted {deleted_count} zero-quantity items from searchRack")
    
    except Exception as e:
        print(f"❌ Error purging zero-quantity items: {e}")
        import traceback
        traceback.print_exc()
    finally:
        conn.close()

def _start_zero_qty_deleter_thread():
    """Start background thread to delete zero-quantity items after 24 hours"""
    global _zero_qty_deleter_started
    if _zero_qty_deleter_started:
        return
    _zero_qty_deleter_started = True
    
    def _runner():
        import time as _time
        # Run immediately on startup
        try:
            _purge_zero_qty_items()
        except Exception as e:
            print('Zero-qty deletion initial run error:', e)
        
        while True:
            # Check every hour
            _time.sleep(60*60)
            try:
                _purge_zero_qty_items()
            except Exception as e:
                print('Zero-qty deletion tick error:', e)
    
    t = threading.Thread(target=_runner, daemon=True)
    t.start()
    print("🚀 Zero-quantity deletion thread started")

def _process_automatic_inventory_removals():
    """Process sold orders that are past grace period and reduce inventory automatically"""
    from datetime import datetime, timedelta
    sold_conn = None
    searchrack_conn = None

    try:
        print("🔄 Checking for automatic inventory removals...")
        sold_conn = sqlite3.connect('sold.db')
        sold_conn.row_factory = sqlite3.Row
        sold_cur = sold_conn.cursor()
        _ensure_order_removal_allocations_table(sold_cur)
        
        # Get grace period setting
        sold_cur.execute("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)")
        sold_conn.commit()
        sold_cur.execute("SELECT value FROM settings WHERE key = 'removal_grace_hours'")
        row = sold_cur.fetchone()
        grace_period_hours = float(row[0]) if row and str(row[0]).strip() else 48
        
        print(f"   Grace period: {grace_period_hours} hours ({grace_period_hours * 60:.1f} minutes)")
        
        # Get orders eligible for automatic removal - MUST include shipped_time
        sold_cur.execute('''
            SELECT id, order_id, barcode, quantity, title, shipped_time
            FROM orders 
            WHERE rackupdated = 0 
            AND shipped_time IS NOT NULL 
            AND shipped_time != ''
            AND barcode IS NOT NULL
            AND barcode != ''
            AND COALESCE(removal_cancelled, 0) = 0
        ''')
        orders = sold_cur.fetchall()
        
        print(f"   Found {len(orders)} orders with shipped_time")
        
        now = datetime.now()
        
        searchrack_conn = sqlite3.connect('searchRack.db')
        searchrack_conn.row_factory = sqlite3.Row
        searchrack_cur = searchrack_conn.cursor()
        searchrack_schema = _searchrack_removal_schema(searchrack_cur)
        barcode_col = searchrack_schema.get('barcode_col')
        qty_col = searchrack_schema.get('qty_col')
        id_lookup_col = searchrack_schema.get('id_col') or 'rowid'

        if not barcode_col or not qty_col:
            print("❌ Automatic removal skipped: SEARCHRACK is missing BARCODE/UPC or QUANTITY/QTY columns")
            return

        def _mark_zero_qty_for_deletion(item_id):
            try:
                searchrack_cur.execute("SELECT value FROM zero_qty_settings WHERE key = 'interval_minutes'")
                settings = searchrack_cur.fetchone()
                interval = int(settings[0]) if settings else 60
                delete_at = datetime.now() + timedelta(minutes=interval)
                searchrack_cur.execute(
                    'SELECT id, deletion_cancelled FROM zero_qty_pending_deletion WHERE searchrack_id = ?',
                    (item_id,)
                )
                existing = searchrack_cur.fetchone()
                if not existing:
                    searchrack_cur.execute('''
                        INSERT INTO zero_qty_pending_deletion (searchrack_id, marked_at, delete_at, deletion_cancelled)
                        VALUES (?, ?, ?, 0)
                    ''', (item_id, datetime.now().isoformat(), delete_at.isoformat()))
                elif existing[1] == 1:
                    searchrack_cur.execute('''
                        UPDATE zero_qty_pending_deletion
                        SET deletion_cancelled = 0, marked_at = ?, delete_at = ?
                        WHERE searchrack_id = ?
                    ''', (datetime.now().isoformat(), delete_at.isoformat(), item_id))
            except Exception as mark_error:
                print(f"  ❌ Error marking item {item_id} for zero-qty deletion: {mark_error}")
                import traceback
                traceback.print_exc()
        
        processed_count = 0
        
        for order in orders:
            try:
                shipped_str = order['shipped_time']
                
                # Parse shipped time
                if 'T' in shipped_str:
                    if shipped_str.endswith('Z'):
                        shipped_dt = datetime.fromisoformat(shipped_str.replace('Z', '+00:00'))
                    else:
                        shipped_dt = datetime.fromisoformat(shipped_str)
                else:
                    shipped_dt = datetime.fromisoformat(shipped_str)
                
                if shipped_dt.tzinfo:
                    shipped_dt = shipped_dt.replace(tzinfo=None)
                
                hours_since_shipped = (now - shipped_dt).total_seconds() / 3600
                
                # Check if eligible for removal (past grace period)
                if hours_since_shipped < grace_period_hours:
                    continue
                
                barcode = order['barcode']
                sold_qty = max(1, _coerce_int(order['quantity'], 1))

                matches = _searchrack_matches_for_barcode(
                    searchrack_cur,
                    barcode,
                    schema=searchrack_schema,
                    include_zero=False
                )
                if not matches:
                    print(f"  ⏭️  Order {order['order_id']}: Item not in inventory yet (barcode: {barcode}) - will retry later")
                    continue

                location_groups = _group_searchrack_matches_by_location(matches)
                saved_allocations = _load_order_removal_allocations(sold_cur, order['id'])

                planned_steps = []
                using_saved_allocations = False

                if len(location_groups) > 1:
                    if not saved_allocations:
                        print(f"  ⏭️  Order {order['order_id']}: multiple locations found; awaiting explicit location selection")
                        continue

                    using_saved_allocations = True
                    group_by_key = {g['location_key']: g for g in location_groups}

                    for alloc in saved_allocations:
                        alloc_qty = max(0, _coerce_int(alloc.get('quantity'), 0))
                        if alloc_qty <= 0:
                            continue
                        alloc_key = _sold_location_key(alloc.get('location_key') or alloc.get('location_code'))
                        group = group_by_key.get(alloc_key)
                        if not group:
                            planned_steps = []
                            print(
                                f"  ⏭️  Order {order['order_id']}: saved location {alloc.get('location_code')} not found in current inventory; waiting"
                            )
                            break
                        if alloc_qty > max(0, _coerce_int(group.get('available_qty'), 0)):
                            planned_steps = []
                            print(
                                f"  ⏭️  Order {order['order_id']}: saved qty for {group['location_code']} exceeds available inventory; waiting"
                            )
                            break

                        remaining = alloc_qty
                        for row_match in group['rows']:
                            if remaining <= 0:
                                break
                            available = max(0, _coerce_int(row_match.get('quantity'), 0))
                            if available <= 0:
                                continue
                            take = min(available, remaining)
                            if take > 0:
                                planned_steps.append({
                                    'searchrack_id': int(row_match['id']),
                                    'location_code': group['location_code'],
                                    'quantity': int(take)
                                })
                                remaining -= take
                        if remaining > 0:
                            planned_steps = []
                            print(
                                f"  ⏭️  Order {order['order_id']}: insufficient inventory in selected location {group['location_code']}; waiting"
                            )
                            break

                    if not planned_steps:
                        continue

                    # Respect sold quantity exactly even if stale allocations sum higher.
                    keep = sold_qty
                    trimmed = []
                    for step in planned_steps:
                        if keep <= 0:
                            break
                        take = min(int(step['quantity']), keep)
                        if take > 0:
                            trimmed.append({
                                'searchrack_id': step['searchrack_id'],
                                'location_code': step['location_code'],
                                'quantity': take
                            })
                            keep -= take
                    if keep > 0:
                        print(f"  ⏭️  Order {order['order_id']}: selected location quantities do not cover sold qty ({sold_qty})")
                        continue
                    planned_steps = trimmed
                else:
                    if not location_groups:
                        print(f"  ⏭️  Order {order['order_id']}: no matching location rows with quantity > 0; will retry later")
                        continue
                    remaining = sold_qty
                    for row_match in location_groups[0]['rows']:
                        if remaining <= 0:
                            break
                        available = max(0, _coerce_int(row_match.get('quantity'), 0))
                        if available <= 0:
                            continue
                        take = min(available, remaining)
                        if take > 0:
                            planned_steps.append({
                                'searchrack_id': int(row_match['id']),
                                'location_code': location_groups[0]['location_code'],
                                'quantity': int(take)
                            })
                            remaining -= take
                    if remaining > 0:
                        print(f"  ⏭️  Order {order['order_id']}: insufficient inventory to remove {sold_qty}; will retry later")
                        continue

                # Merge by SEARCHRACK row id in case stale data contains duplicates.
                merged_steps = []
                merged_index = {}
                for step in planned_steps:
                    sid = int(step['searchrack_id'])
                    if sid in merged_index:
                        idx = merged_index[sid]
                        merged_steps[idx]['quantity'] += int(step['quantity'])
                    else:
                        merged_index[sid] = len(merged_steps)
                        merged_steps.append({
                            'searchrack_id': sid,
                            'location_code': step['location_code'],
                            'quantity': int(step['quantity'])
                        })

                # Re-read row quantities to ensure nothing changed before applying updates.
                recheck = {}
                recheck_ok = True
                for step in merged_steps:
                    sid = int(step['searchrack_id'])
                    searchrack_cur.execute(
                        f'''
                            SELECT {qty_col} AS qty,
                                   COALESCE({searchrack_schema.get('pos_col') or "''"}, '') AS item_position,
                                   COALESCE({searchrack_schema.get('pic_col') or "''"}, '') AS pictureposition
                            FROM SEARCHRACK
                            WHERE {id_lookup_col} = ?
                        ''',
                        (sid,)
                    )
                    row_now = searchrack_cur.fetchone()
                    if not row_now:
                        recheck_ok = False
                        print(f"  ⏭️  Order {order['order_id']}: selected inventory row {sid} no longer exists; waiting")
                        break
                    current_qty = max(0, _coerce_int(row_now['qty'], 0))
                    remove_qty = max(0, _coerce_int(step['quantity'], 0))
                    if remove_qty <= 0 or current_qty < remove_qty:
                        recheck_ok = False
                        print(
                            f"  ⏭️  Order {order['order_id']}: selected row {sid} has qty {current_qty}, cannot remove {remove_qty}; waiting"
                        )
                        break
                    recheck[sid] = {
                        'current_qty': current_qty,
                        'item_position': str(row_now['item_position'] or row_now['pictureposition'] or step['location_code'] or '').strip()
                    }

                if not recheck_ok:
                    continue

                removed_conn = sqlite3.connect('rackhistory.db')
                try:
                    removed_cur = removed_conn.cursor()
                    _ensure_removed_items_table(removed_cur)

                    for step in merged_steps:
                        sid = int(step['searchrack_id'])
                        remove_qty = max(0, _coerce_int(step['quantity'], 0))
                        if remove_qty <= 0:
                            continue
                        old_qty = recheck[sid]['current_qty']
                        new_qty = max(0, old_qty - remove_qty)

                        searchrack_cur.execute(
                            f'UPDATE SEARCHRACK SET {qty_col} = ? WHERE {id_lookup_col} = ?',
                            (new_qty, sid)
                        )

                        removed_cur.execute('''
                            INSERT INTO removed_items
                            (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        ''', (
                            order['order_id'],
                            barcode,
                            order['title'],
                            remove_qty,
                            now.isoformat(),
                            sid,
                            old_qty,
                            new_qty,
                            'automatic_allocated' if using_saved_allocations else 'automatic',
                            recheck[sid]['item_position']
                        ))

                        if new_qty == 0:
                            _mark_zero_qty_for_deletion(sid)

                    removed_conn.commit()
                finally:
                    removed_conn.close()

                sold_cur.execute('UPDATE orders SET rackupdated = 1 WHERE id = ?', (order['id'],))
                sold_cur.execute('DELETE FROM order_removal_allocations WHERE order_row_id = ?', (order['id'],))
                processed_count += 1
                print(
                    f"  ✓ Order {order['order_id']}: removed {sold_qty} from "
                    f"{'selected locations' if using_saved_allocations else 'single location inventory'}"
                )
                
            except Exception as e:
                print(f"  ❌ Error processing order {order['order_id']}: {e}")
                continue
        
        searchrack_conn.commit()
        
        sold_conn.commit()
        
        if processed_count > 0:
            print(f"✅ Automatically processed {processed_count} inventory removals")
    
    except Exception as e:
        print(f"❌ Error in automatic inventory removal: {e}")
        import traceback
        traceback.print_exc()
    finally:
        try:
            if sold_conn is not None:
                sold_conn.close()
        except Exception:
            pass
        try:
            if searchrack_conn is not None:
                searchrack_conn.close()
        except Exception:
            pass

def _start_automatic_removal_thread():
    """Start background thread to automatically process inventory removals after grace period"""
    global _automatic_removal_started
    if _automatic_removal_started:
        return
    _automatic_removal_started = True
    
    def _runner():
        import time as _time
        # Run immediately on startup
        try:
            _process_automatic_inventory_removals()
        except Exception as e:
            print('Automatic removal initial run error:', e)
        
        # Then run every 5 minutes
        while True:
            _time.sleep(5*60)
            try:
                _process_automatic_inventory_removals()
            except Exception as e:
                print('Automatic removal tick error:', e)
    
    t = threading.Thread(target=_runner, daemon=True)
    t.start()
    print("🚀 Automatic inventory removal thread started")

def _ensure_bol_list_status_column():
    """Ensure bol_items has list_status, temporary, and quantity tracking columns."""
    print("[_ensure_bol_list_status_column] Starting migration check...")
    try:
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='bol_items'")
        if not cur.fetchone():
            print("[_ensure_bol_list_status_column] bol_items table not found")
            return
        cur.execute("PRAGMA table_info(bol_items)")
        # Use lowercase for case-insensitive comparison
        cols = [r[1].lower() for r in cur.fetchall()]
        print(f"[_ensure_bol_list_status_column] Found {len(cols)} columns in bol_items")
        
        # Add list_status and temporary columns
        if 'list_status' not in cols:
            print("[_ensure_bol_list_status_column] Adding list_status column")
            cur.execute("ALTER TABLE bol_items ADD COLUMN list_status TEXT")
        if 'temporary' not in cols:
            print("[_ensure_bol_list_status_column] Adding temporary column")
            cur.execute("ALTER TABLE bol_items ADD COLUMN temporary INTEGER DEFAULT 0")
        
        # NEW: Add quantity tracking columns for robust prep workflow
        if 'original_qty' not in cols:
            print("📊 Adding original_qty column and backfilling from quantity...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN original_qty INTEGER")
            # Backfill from quantity column
            cur.execute("UPDATE bol_items SET original_qty = quantity WHERE original_qty IS NULL")
            
        if 'good_qty' not in cols:
            print("✅ Adding good_qty column...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN good_qty INTEGER DEFAULT 0")
            # Backfill from items_prep_status for items already marked good
            cur.execute('''
                UPDATE bol_items 
                SET good_qty = (
                    SELECT COALESCE(quantity, 0) 
                    FROM items_prep_status 
                    WHERE items_prep_status.upc = bol_items.upc 
                    AND COALESCE(items_prep_status.lot_number, '') = COALESCE(bol_items.lot_number, '')
                    AND items_prep_status.status = 'good'
                )
                WHERE EXISTS (
                    SELECT 1 FROM items_prep_status 
                    WHERE items_prep_status.upc = bol_items.upc 
                    AND COALESCE(items_prep_status.lot_number, '') = COALESCE(bol_items.lot_number, '')
                    AND items_prep_status.status = 'good'
                )
            ''')
            
        if 'bad_qty' not in cols:
            print("❌ Adding bad_qty column...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN bad_qty INTEGER DEFAULT 0")
            # Calculate bad_qty from suffixed entries
            cur.execute('''
                UPDATE bol_items 
                SET bad_qty = (
                    SELECT COALESCE(SUM(quantity), 0)
                    FROM bol_items AS suffixed
                    WHERE suffixed.upc LIKE bol_items.upc || '-%'
                    AND suffixed.temporary = 1
                )
                WHERE upc NOT LIKE '%-%'
            ''')
            
        if 'unchecked_qty' not in cols:
            print("📦 Adding unchecked_qty column and calculating from original - good - bad...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN unchecked_qty INTEGER")
            # Backfill: original - good - bad = unchecked
            cur.execute('''
                UPDATE bol_items 
                SET unchecked_qty = COALESCE(original_qty, 0) - COALESCE(good_qty, 0) - COALESCE(bad_qty, 0)
                WHERE unchecked_qty IS NULL
            ''')
        
        # NEW: Add marketplace-specific listing columns with timestamps
        if 'listed_amazon' not in cols:
            print("🛒 Adding Amazon listing tracking columns...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN listed_amazon INTEGER DEFAULT 0")
        else:
            print("[_ensure_bol_list_status_column] listed_amazon column already exists")
            
        if 'listed_amazon_date' not in cols:
            print("🛒 Adding Amazon listing date column...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN listed_amazon_date TEXT")
        else:
            print("[_ensure_bol_list_status_column] listed_amazon_date column already exists")
            
        if 'listed_ebay' not in cols:
            print("🏷️ Adding eBay listing tracking columns...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN listed_ebay INTEGER DEFAULT 0")
        else:
            print("[_ensure_bol_list_status_column] listed_ebay column already exists")
            
        if 'listed_ebay_date' not in cols:
            print("🏷️ Adding eBay listing date column...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN listed_ebay_date TEXT")
        else:
            print("[_ensure_bol_list_status_column] listed_ebay_date column already exists")
            
        if 'listed_facebook' not in cols:
            print("📘 Adding Facebook listing tracking columns...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN listed_facebook INTEGER DEFAULT 0")
        else:
            print("[_ensure_bol_list_status_column] listed_facebook column already exists")
            
        if 'listed_facebook_date' not in cols:
            print("📘 Adding Facebook listing date column...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN listed_facebook_date TEXT")
        else:
            print("[_ensure_bol_list_status_column] listed_facebook_date column already exists")
        
        if 'listed_facebook_qty' not in cols:
            print("📘 Adding Facebook listing quantity column...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN listed_facebook_qty INTEGER")
            # Backfill quantity for existing FB listings
            try:
                cur.execute('''
                    UPDATE bol_items
                    SET listed_facebook_qty = COALESCE(quantity, 1)
                    WHERE COALESCE(listed_facebook, 0) = 1
                    AND listed_facebook_qty IS NULL
                ''')
            except Exception:
                pass

        if 'listed_amazon_source' not in cols:
            print("🛒 Adding Amazon listing source column...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN listed_amazon_source TEXT")
        if 'listed_ebay_source' not in cols:
            print("🏷️ Adding eBay listing source column...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN listed_ebay_source TEXT")
        if 'listed_facebook_source' not in cols:
            print("📘 Adding Facebook listing source column...")
            cur.execute("ALTER TABLE bol_items ADD COLUMN listed_facebook_source TEXT")

        # One-time source backfill so future requests avoid full-table updates.
        try:
            cur.execute('CREATE TABLE IF NOT EXISTS app_metadata (key TEXT PRIMARY KEY, value TEXT)')
            cur.execute('SELECT value FROM app_metadata WHERE key = ? LIMIT 1', ('listing_source_backfill_v1',))
            marker_row = cur.fetchone()
            marker = (marker_row[0] if marker_row else '')
            if str(marker) != '1':
                cur.execute('''
                    UPDATE bol_items
                    SET listed_amazon_source = 'system'
                    WHERE COALESCE(listed_amazon, 0) = 1
                      AND (listed_amazon_source IS NULL OR TRIM(listed_amazon_source) = '')
                ''')
                cur.execute('''
                    UPDATE bol_items
                    SET listed_ebay_source = 'system'
                    WHERE COALESCE(listed_ebay, 0) = 1
                      AND (listed_ebay_source IS NULL OR TRIM(listed_ebay_source) = '')
                ''')
                cur.execute('''
                    UPDATE bol_items
                    SET listed_facebook_source = 'system'
                    WHERE COALESCE(listed_facebook, 0) = 1
                      AND (listed_facebook_source IS NULL OR TRIM(listed_facebook_source) = '')
                ''')
                cur.execute(
                    'INSERT OR REPLACE INTO app_metadata (key, value) VALUES (?, ?)',
                    ('listing_source_backfill_v1', '1')
                )
        except Exception as src_backfill_err:
            print(f"Warning: Could not backfill listing source columns: {src_backfill_err}")

        # Legacy migration disabled in normal request path.
        # Reason: list_status is still maintained as "listed if any marketplace is listed".
        # Auto-converting list_status='listed' -> listed_amazon=1 can incorrectly re-enable
        # Amazon for eBay/Facebook-only rows.
        try:
            cur.execute('CREATE TABLE IF NOT EXISTS app_metadata (key TEXT PRIMARY KEY, value TEXT)')
            cur.execute(
                'INSERT OR REPLACE INTO app_metadata (key, value) VALUES (?, ?)',
                ('legacy_list_status_auto_migration_disabled_v1', '1')
            )
        except Exception as e:
            print(f"Warning: Could not write legacy migration disable marker: {e}")
        
        conn.commit()
        # print("✅ Quantity tracking columns migrated successfully") # Reduce noise
    except Exception as e:
        print('Failed ensuring quantity columns in bol_items:', e)
        import traceback
        traceback.print_exc()
    finally:
        conn.close()

def _legacy_migrate_list_status_to_amazon(cur):
    """
    Legacy backfill helper:
    map old generic list_status='listed' rows to listed_amazon=1.

    IMPORTANT: This should be invoked explicitly (debug/maintenance only),
    not on the normal request path.
    """
    cur.execute("""
        UPDATE bol_items
        SET listed_amazon = 1,
            listed_amazon_date = datetime('now'),
            listed_amazon_source = COALESCE(NULLIF(TRIM(listed_amazon_source), ''), 'system')
        WHERE LOWER(TRIM(COALESCE(list_status, ''))) = 'listed'
          AND COALESCE(listed_amazon, 0) = 0
    """)
    return cur.rowcount or 0

