@app.route('/api/items-prep/generate-barcode', methods=['POST'])
def generate_custom_barcode():
    """Generate auto-incremented 777 prefix barcode with duplicate protection"""
    try:
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        
        # Create temp_items table if not exists
        cur.execute('''
            CREATE TABLE IF NOT EXISTS temp_items (
                upc TEXT PRIMARY KEY,
                item_description TEXT,
                image_url TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        
        # Get the highest 777 barcode from both tables
        cur.execute('''
            SELECT MAX(CAST(upc AS INTEGER)) as max_barcode
            FROM bol_items 
            WHERE upc LIKE '777%' AND LENGTH(upc) = 12
        ''')
        result = cur.fetchone()
        
        # Also check temp_items table
        cur.execute('''
            SELECT MAX(CAST(upc AS INTEGER)) as max_barcode
            FROM temp_items 
            WHERE upc LIKE '777%' AND LENGTH(upc) = 12
        ''')
        temp_result = cur.fetchone()
        
        # Get the highest barcode from both tables
        max_barcode = result[0] if result[0] else None
        temp_max = temp_result[0] if temp_result[0] else None
        
        if temp_max and (not max_barcode or temp_max > max_barcode):
            max_barcode = temp_max
        
        # Generate new barcode with duplicate check
        attempts = 0
        max_attempts = 100
        
        while attempts < max_attempts:
            if max_barcode:
                # Increment by 1
                new_barcode = str(int(max_barcode) + 1)
                # Ensure it still starts with 777
                if not new_barcode.startswith('777'):
                    # Extract the numeric part after 777 and increment
                    numeric_part = int(str(max_barcode)[3:]) + 1
                    new_barcode = f"777{str(numeric_part).zfill(9)}"
            else:
                # Start at 777000000001 (12 digits with 777 prefix)
                new_barcode = '777000000001'
            
            # Ensure it's exactly 12 digits and starts with 777
            if len(new_barcode) < 12:
                # Pad the numeric part after 777
                if new_barcode.startswith('777'):
                    numeric_part = new_barcode[3:]
                    new_barcode = f"777{numeric_part.zfill(9)}"
                else:
                    new_barcode = new_barcode.zfill(12)
            
            # Check if this barcode already exists in either table
            cur.execute('SELECT upc FROM bol_items WHERE upc = ? COLLATE NOCASE', (new_barcode,))
            exists_bol = cur.fetchone()
            
            cur.execute('SELECT upc FROM temp_items WHERE upc = ? COLLATE NOCASE', (new_barcode,))
            exists_temp = cur.fetchone()
            
            if not exists_bol and not exists_temp:
                # Barcode is unique, we're good!
                return jsonify({'success': True, 'barcode': new_barcode.strip()})
            
            # Barcode exists, increment and try again
            max_barcode = int(new_barcode)
            attempts += 1
        
        # If we exhausted attempts, return error
        return jsonify({'success': False, 'error': 'Could not generate unique barcode after 100 attempts'}), 500
        
    except Exception as e:
        print(f'Error generating barcode: {e}')
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        conn.close()

@app.route('/api/items-prep/temp-item', methods=['POST'])
def save_temp_item():
    """Save custom item directly to bol_items so it appears in Item Manager"""
    try:
        data = request.get_json()
        upc = data.get('upc', '').strip()
        item_description = data.get('item_description', '').strip()
        image_data = data.get('image_data', '')
        
        if not upc or not item_description or not image_data:
            return jsonify({'success': False, 'error': 'Missing required fields'}), 400
        
        # Normalize UPC for consistent storage and caching
        upc_norm = _normalize_upc(upc)
        
        # Save image to file
        import base64
        import uuid
        
        # Remove data URL prefix if present
        if image_data.startswith('data:image'):
            image_data = image_data.split(',')[1]
        
        # Decode base64 image
        image_bytes = base64.b64decode(image_data)
        
        # Create directory for custom items if it doesn't exist
        custom_dir = os.path.join('static', 'custom_items')
        os.makedirs(custom_dir, exist_ok=True)
        
        # Save with UPC as filename
        image_filename = f"{upc_norm}.jpg"
        image_path = os.path.join(custom_dir, image_filename)
        
        with open(image_path, 'wb') as f:
            f.write(image_bytes)
        
        # Insert directly into bol_items table
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        
        # Check if item already exists
        cur.execute('SELECT upc FROM bol_items WHERE upc = ? COLLATE NOCASE', (upc_norm,))
        exists = cur.fetchone()
        
        web_image_path = f"/static/custom_items/{image_filename}"
        
        if exists:
            # Update existing item
            cur.execute('''
                UPDATE bol_items 
                SET item_description = ?, image_url = ?
                WHERE upc = ? COLLATE NOCASE
            ''', (item_description, web_image_path, upc_norm))
        else:
            # Insert new item into bol_items
            cur.execute('''
                INSERT INTO bol_items (
                    upc, item_description, image_url, 
                    lot_number, bol_number, import_date
                ) VALUES (?, ?, ?, NULL, 'CUSTOM', datetime('now'))
            ''', (upc_norm, item_description, web_image_path))
        
        conn.commit()
        
        # Clear cache for this UPC using normalized UPC
        cache_key = f"view//api/bol_lookup?upc={upc_norm}"
        cache.delete(cache_key)
        cache.delete_memoized(api_bol_lookup)
        
        return jsonify({'success': True, 'message': 'Custom item saved to inventory', 'image_url': web_image_path})
    except Exception as e:
        print(f'Error saving custom item: {e}')
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        conn.close()

 

@app.route('/api/clear_cache', methods=['GET'])
def api_clear_cache():
    """Clear the cache for a specific UPC lookup to force refresh"""
    try:
        upc = request.args.get('upc')
        if upc:
            # Clear specific cache key for this UPC
            cache_key = f"view//api/bol_lookup?upc={upc}"
            cache.delete(cache_key)
            # Also clear memoized lookup entries (including lot-scoped query variants)
            cache.delete_memoized(api_bol_lookup)
        else:
            # Clear all bol_lookup cache
            cache.delete_memoized(api_bol_lookup)
        
        return jsonify({'success': True})
    except Exception as e:
        print(f"Cache clear error: {e}")
        return jsonify({'success': True})  # Always return success, cache clear is not critical

@app.route('/api/bol_lookup', methods=['GET'])
@cache.cached(timeout=600, query_string=True)  # Cache for 10 minutes
def api_bol_lookup():
    """Lookup a BOL item by UPC in bol.db and return normalized fields.
    First checks temp_items for custom items, then bol_items.
    Suffix entries are created only by explicit prep actions, not during lookup.
    """
    conn = None
    try:
        upc = _normalize_upc(request.args.get('upc'))
        if not upc:
            return jsonify({'found': False, 'error': 'Missing upc'}), 400
        
        conn = sqlite3.connect('bol.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        
        # First check temp_items table for custom created items
        cur.execute('''
            CREATE TABLE IF NOT EXISTS temp_items (
                upc TEXT PRIMARY KEY,
                item_description TEXT,
                image_url TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        
        cur.execute("SELECT upc, item_description, image_url FROM temp_items WHERE upc = ? COLLATE NOCASE", (upc,))
        temp_item = cur.fetchone()
        
        if temp_item:
            # Return the temp item in the expected format
            item = {
                'upc': temp_item['upc'],
                'item_description': temp_item['item_description'],
                'image_url': temp_item['image_url'],
                'lot_number': None,
                'bol_number': None,
                'import_date': None,
                'temporary': 1,
                'is_duplicate': False,
                'is_custom': True
            }
            return jsonify({'found': True, 'item': item})
        
        # Ensure temporary column exists in bol_items
        cur.execute('PRAGMA table_info(bol_items)')
        cols = [r[1] for r in cur.fetchall()]
        if 'temporary' not in cols:
            cur.execute('ALTER TABLE bol_items ADD COLUMN temporary INTEGER DEFAULT 0')
            conn.commit()
        
        selected_lot = _preferred_lot_from_request()
        rows = []
        rows_in_selected = []
        scope_all = _request_lot_scope_is_all()
        if selected_lot:
            cur.execute("""
                SELECT id, upc, item_description, image_url, lot_number, bol_number, import_date, temporary,
                       unchecked_qty, original_qty, good_qty, bad_qty
                FROM bol_items
                WHERE upc = ? COLLATE NOCASE
                  AND lot_number = ? COLLATE NOCASE
                ORDER BY import_date DESC, id DESC
            """, (upc, selected_lot))
            rows_in_selected = cur.fetchall()
            rows = rows_in_selected

        if not rows:
            # Fallback to newest row across lots
            cur.execute("""
                SELECT id, upc, item_description, image_url, lot_number, bol_number, import_date, temporary,
                       unchecked_qty, original_qty, good_qty, bad_qty
                FROM bol_items 
                WHERE upc = ? COLLATE NOCASE 
                ORDER BY import_date DESC, id DESC
            """, (upc,))
            rows = cur.fetchall()
        
        if not rows:
            return jsonify({
                'found': False,
                'requested_lot': selected_lot,
                'scope': ('all' if scope_all else 'current')
            })
        
        lot_mismatch = bool(selected_lot and not rows_in_selected)
        available_lots = []
        seen_lots = set()
        for rr in rows:
            lot_val = _normalize_lot_number(rr['lot_number'])
            if not lot_val:
                continue
            lot_key = lot_val.lower()
            if lot_key in seen_lots:
                continue
            seen_lots.add(lot_key)
            available_lots.append(lot_val)
        
        # Find the newest permanent entry (temporary = 0 or NULL)
        # Since rows are sorted by import_date DESC, the first permanent row is the newest LOT
        permanent_row = None
        for r in rows:
            if not r['temporary']:
                permanent_row = r
                break
        
        if not permanent_row:
            # All rows are temporary (shouldn't happen, but handle gracefully)
            permanent_row = rows[0]
        
        # Check if this item has already been prepped in the relevant lot.
        has_prep_record = False
        status_lot = _normalize_lot_number((permanent_row['lot_number'] if permanent_row else selected_lot))
        if permanent_row:
            _ensure_items_prep_tables()
            if status_lot:
                cur.execute('''
                    SELECT status
                    FROM items_prep_status
                    WHERE (upc = ? OR upc LIKE ? COLLATE NOCASE)
                      AND (
                        COALESCE(lot_number, '') = ? COLLATE NOCASE
                        OR COALESCE(lot_number, '') = ''
                      )
                    LIMIT 1
                ''', (upc, f'{upc}-%', status_lot))
            else:
                cur.execute('SELECT status FROM items_prep_status WHERE upc = ? OR upc LIKE ? COLLATE NOCASE LIMIT 1', (upc, f'{upc}-%'))
            status_row = cur.fetchone()
            has_prep_record = status_row is not None

        # Lookup no longer auto-creates temporary suffixed duplicates.
        # Suffix creation now only happens on explicit user actions (bad/return/noted-good).
        item = dict(permanent_row)
        item['is_duplicate'] = False
        item['has_prep_record'] = bool(has_prep_record)

        # Expose remaining unchecked quantity so the UI can warn before forced exception adds.
        try:
            unchecked_raw = item.get('unchecked_qty')
            if unchecked_raw is None:
                original_raw = int(item.get('original_qty') or 0)
                good_raw = int(item.get('good_qty') or 0)
                bad_raw = int(item.get('bad_qty') or 0)
                unchecked_remaining = max(0, original_raw - good_raw - bad_raw)
            else:
                unchecked_remaining = int(unchecked_raw or 0)
        except Exception:
            unchecked_remaining = 0
        base_lookup_upc = (upc.split('-')[0] if '-' in str(upc) else upc)
        item['unchecked_remaining'] = unchecked_remaining
        item['is_overage_candidate'] = bool(unchecked_remaining <= 0)
        item['items_to_list_url'] = _items_prep_items_to_list_url(base_lookup_upc, item.get('lot_number') or selected_lot)
        item['requested_lot'] = selected_lot
        item['lot_mismatch'] = bool(lot_mismatch)
        item['resolved_lot'] = _normalize_lot_number(item.get('lot_number'))
        item['available_lots'] = available_lots
        
        
        # Also include current prep status if exists
        conn2 = None
        try:
            conn2 = sqlite3.connect('bol.db')
            conn2.row_factory = sqlite3.Row
            cur2 = conn2.cursor()
            prep_lot = _normalize_lot_number(item.get('lot_number') or selected_lot)
            srow = _select_prep_status_row(cur2, item['upc'], prep_lot, columns='status, reason, note, updated_at, quantity, lot_number')
            if srow:
                item['prep_status'] = dict(srow)
        except Exception:
            item['prep_status'] = None
        finally:
            if conn2 is not None:
                conn2.close()

        return jsonify({
            'found': True,
            'item': item,
            'requested_lot': selected_lot,
            'lot_mismatch': bool(lot_mismatch),
            'resolved_lot': _normalize_lot_number(item.get('lot_number')),
            'available_lots': available_lots
        })
    except Exception as e:
        return jsonify({'found': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/items_prep/auto_assign_lot', methods=['POST'])
def api_items_prep_auto_assign_lot():
    """Resolve a lot for item-prep actions.
    - If UPC exists in bol_items: use newest available lot.
    - Else if UPC exists in raw_bol_items with lot: seed bol_items using that lot.
    - Else create a new uncategorized lot entry (UNCATEGORIZED-<UPC>).
    """
    conn = None
    raw_conn = None
    try:
        data = request.get_json() or {}
        upc_raw = _normalize_upc(data.get('upc'))
        upc = _normalize_upc_preserve_suffix_for_match(upc_raw)
        if not upc:
            return jsonify({'success': False, 'error': 'Missing upc'}), 400
        base_upc = upc.split('-', 1)[0] if '-' in upc else upc

        conn = sqlite3.connect('bol.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        _ensure_items_prep_tables()

        # 1) Existing lot in bol_items.
        cur.execute('''
            SELECT id, lot_number
            FROM bol_items
            WHERE upc = ? COLLATE NOCASE
            ORDER BY import_date DESC, id DESC
            LIMIT 1
        ''', (base_upc,))
        row = cur.fetchone()
        if row:
            lot_number = _normalize_lot_number(row['lot_number'])
            if lot_number:
                return jsonify({
                    'success': True,
                    'upc': base_upc,
                    'assigned_lot': lot_number,
                    'created_entry': False,
                    'source': 'bol_items_existing'
                })

        # 2) Try rawbol metadata.
        raw_desc = ''
        raw_image = ''
        raw_lot = ''
        try:
            raw_conn = sqlite3.connect('rawbol.db')
            raw_conn.row_factory = sqlite3.Row
            raw_cur = raw_conn.cursor()
            raw_cur.execute('''
                SELECT upc, item_description, image_url, lot_number
                FROM raw_bol_items
                WHERE upc = ? COLLATE NOCASE
                ORDER BY import_date DESC, id DESC
                LIMIT 1
            ''', (base_upc,))
            raw_row = raw_cur.fetchone()
            if raw_row:
                raw_desc = (raw_row['item_description'] or '').strip()
                raw_image = (raw_row['image_url'] or '').strip()
                raw_lot = _normalize_lot_number(raw_row['lot_number'])
        except Exception:
            raw_desc = raw_desc or ''
            raw_image = raw_image or ''
            raw_lot = raw_lot or ''
        finally:
            if raw_conn is not None:
                raw_conn.close()
                raw_conn = None

        assigned_lot = raw_lot or f'UNCATEGORIZED-{base_upc}'

        # 3) If already seeded for that lot, reuse it.
        cur.execute('''
            SELECT id
            FROM bol_items
            WHERE upc = ? COLLATE NOCASE
              AND COALESCE(lot_number, '') = ? COLLATE NOCASE
            ORDER BY import_date DESC, id DESC
            LIMIT 1
        ''', (base_upc, assigned_lot))
        seeded = cur.fetchone()
        if seeded:
            return jsonify({
                'success': True,
                'upc': base_upc,
                'assigned_lot': assigned_lot,
                'created_entry': False,
                'source': 'bol_items_seeded'
            })

        # 4) Seed a new bol_items row.
        cur.execute('PRAGMA table_info(bol_items)')
        cols = {r[1] for r in cur.fetchall()}
        now_iso = _listagent_now_iso()
        payload = {
            'upc': base_upc,
            'item_description': raw_desc or f'Uncategorized Item {base_upc}',
            'image_url': raw_image or '',
            'lot_number': assigned_lot,
            'bol_number': assigned_lot,
            'import_date': now_iso,
            'temporary': 0,
            'original_qty': 1,
            'unchecked_qty': 1,
            'good_qty': 0,
            'bad_qty': 0,
            'quantity': 1
        }
        insert_cols = [k for k in payload.keys() if k in cols]
        if 'upc' not in insert_cols:
            return jsonify({'success': False, 'error': 'bol_items schema is missing upc'}), 500
        placeholders = ','.join(['?'] * len(insert_cols))
        cur.execute(
            f"INSERT INTO bol_items ({','.join(insert_cols)}) VALUES ({placeholders})",
            tuple(payload[k] for k in insert_cols)
        )
        conn.commit()
        try:
            update_data_version()
        except Exception:
            pass

        return jsonify({
            'success': True,
            'upc': base_upc,
            'assigned_lot': assigned_lot,
            'created_entry': True,
            'source': ('rawbol_seed' if raw_lot else 'uncategorized_created')
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'items_prep:auto_assign_lot')}), 500
    finally:
        if raw_conn is not None:
            raw_conn.close()
        if conn is not None:
            conn.close()

@app.route('/api/items_prep/status/<upc>', methods=['GET'])
def api_items_prep_status_get(upc):
    """Get preparation status for a UPC."""
