@app.route('/api/items_prep/status', methods=['POST'])
def api_items_prep_status():
    """Upsert preparation status for a UPC.
    
    NEW LOGIC:
    - GOOD flow: Base UPC is default; if a note is provided, create a suffixed GOOD special-case entry
    - BAD flow: UPC should already be suffixed (created by Bad button), just update status
    - Base qty is only decremented when status is finalized (Good immediately, Bad on Complete)
    """
    conn = None
    try:
        data = request.get_json() or {}
        upc = _normalize_upc(data.get('upc'))
        status = (data.get('status') or '').strip().lower()
        reason = (data.get('reason') or '').strip()
        note = (data.get('note') or '').strip()
        exception_note = (data.get('exception_note') or '').strip()
        raw_qty = data.get('qty', 1)
        try:
            qty = int(raw_qty if raw_qty is not None else 1)
        except Exception:
            return jsonify({'success': False, 'error': 'Invalid qty'}), 400
        if qty < 1:
            return jsonify({'success': False, 'error': 'qty must be at least 1'}), 400
        
        if not upc or status not in ('good', 'bad', 'unchecked', 'return'):
            return jsonify({'success': False, 'error': 'Missing upc or invalid status'}), 400

        if status == 'unchecked':
            reason = ''
            note = ''
        
        # Strip leading zeros but preserve suffix
        upc = _normalize_upc_preserve_suffix_for_match(upc)
        
        base_upc = upc.split('-')[0] if '-' in upc else upc
        requested_lot = _preferred_lot_from_request(data)
        allow_no_lot = _coerce_bool(data.get('allow_no_lot'))
        force_requested_lot = _coerce_bool(
            data.get('force_requested_lot') if data.get('force_requested_lot') is not None else data.get('override_lot')
        )
        allow_overage_exception = _coerce_bool(
            data.get('allow_overage_exception') if data.get('allow_overage_exception') is not None else data.get('force_exception')
        )
        exception_overage_applied = False
        if allow_no_lot:
            requested_lot = ''
            force_requested_lot = False
        requested_lot_norm = _normalize_lot_number(requested_lot)
        
        print(f'[STATUS API] Received UPC: {data.get("upc")}, Normalized: {upc}, Base: {base_upc}, Status: {status}')
        print(f'[STATUS API] UPC has suffix: {upc != base_upc}')
        print(f'[STATUS API] Reason: "{reason}", Note: "{note}", Qty: {qty}')
        print(f'[STATUS API] Requested LOT: {requested_lot or "(none)"}')
        
        conn = sqlite3.connect('bol.db', isolation_level='IMMEDIATE')
        cur = conn.cursor()
        _ensure_items_prep_tables()
        lot_mismatch, suggested_lot = _check_requested_lot_mismatch(cur, base_upc, requested_lot_norm)
        if lot_mismatch and not allow_no_lot and not force_requested_lot:
            return jsonify(_lot_mismatch_payload(
                upc=base_upc,
                requested_lot=requested_lot_norm,
                suggested_lot=suggested_lot
            )), 409
        
        import datetime
        ts = datetime.datetime.now(datetime.UTC).isoformat()

        def _next_clean_suffix(base_upc_value):
            """Find next suffix not used by bol_items or prep artifacts."""
            suffix_num = 1
            max_suffix_attempts = 500
            while suffix_num <= max_suffix_attempts:
                candidate = f"{base_upc_value}-{suffix_num}"
                cur.execute('SELECT 1 FROM bol_items WHERE upc = ? COLLATE NOCASE LIMIT 1', (candidate,))
                if cur.fetchone():
                    suffix_num += 1
                    continue
                cur.execute('SELECT 1 FROM items_prep_status WHERE upc = ? COLLATE NOCASE LIMIT 1', (candidate,))
                if cur.fetchone():
                    suffix_num += 1
                    continue
                cur.execute('SELECT 1 FROM items_prep_images WHERE upc = ? COLLATE NOCASE LIMIT 1', (candidate,))
                if cur.fetchone():
                    suffix_num += 1
                    continue
                try:
                    cur.execute('SELECT 1 FROM items_prep_notes WHERE upc = ? COLLATE NOCASE LIMIT 1', (candidate,))
                    if cur.fetchone():
                        suffix_num += 1
                        continue
                except Exception:
                    pass
                return candidate
            raise RuntimeError(f'Unable to allocate suffix for {base_upc_value} after {max_suffix_attempts} attempts')
        
        # GOOD flow - base UPC by default; note-driven special cases are suffixed
        if status == 'good':
            # GOOD items cannot have defect reasons
            if reason:
                return jsonify({'success': False, 'error': 'GOOD items cannot have defect reasons. Please clear the defect field or select BAD status.'}), 400
            
            # Resolve lot context first so status/quantity updates are scoped to one manifest lot.
            if allow_no_lot:
                selected_lot = ''
            elif force_requested_lot and requested_lot_norm:
                selected_lot = requested_lot_norm
            else:
                selected_lot = _resolve_bol_lot_for_upc(cur, base_upc, requested_lot)
            forced_lot_override = bool(force_requested_lot and selected_lot)
            print(f'[STATUS API] Resolved LOT for GOOD flow: {selected_lot or "(none)"}')

            # Special-case GOOD with note: create a dedicated suffixed GOOD entry.
            # This preserves per-unit notes/photos without collapsing into base UPC state.
            temp_note_suffix_row = None
            if note and upc != base_upc:
                # Lookup can return a temporary suffixed duplicate for already-prepped UPCs.
                # If user adds a note on that row, keep it as a distinct suffixed GOOD entry
                # instead of collapsing back into the base UPC.
                existing_suffixed_status = _select_prep_status_row(cur, upc, selected_lot, columns='status')
                existing_suffixed_status_val = (
                    str(existing_suffixed_status[0] or '').strip().lower()
                    if existing_suffixed_status else ''
                )
                if existing_suffixed_status_val != 'bad':
                    cur.execute('''
                        SELECT id, temporary
                        FROM bol_items
                        WHERE upc = ? COLLATE NOCASE
                        ORDER BY import_date DESC, id DESC
                        LIMIT 1
                    ''', (upc,))
                    _tmp_row = cur.fetchone()
                    if _tmp_row and int(_tmp_row[1] or 0) == 1:
                        temp_note_suffix_row = _tmp_row

            if note and (upc == base_upc or temp_note_suffix_row):
                suffixed_upc = upc if temp_note_suffix_row else _next_clean_suffix(base_upc)
                print(f'[GOOD] Creating noted special-case suffix {suffixed_upc} for base {base_upc}')

                # Use lot-specific base row when possible; fallback to latest base row.
                if selected_lot:
                    cur.execute('''
                        SELECT id, item_description, image_url, lot_number, bol_number, good_qty, bad_qty, unchecked_qty, original_qty
                        FROM bol_items
                        WHERE upc = ? COLLATE NOCASE
                          AND lot_number = ? COLLATE NOCASE
                        ORDER BY import_date DESC, id DESC
                        LIMIT 1
                    ''', (base_upc, selected_lot))
                    base_item = cur.fetchone()
                else:
                    base_item = None
                if not base_item:
                    cur.execute('''
                        SELECT id, item_description, image_url, lot_number, bol_number, good_qty, bad_qty, unchecked_qty, original_qty
                        FROM bol_items
                        WHERE upc = ? COLLATE NOCASE
                        ORDER BY import_date DESC, id DESC
                        LIMIT 1
                    ''', (base_upc,))
                    base_item = cur.fetchone()
                if not base_item:
                    return jsonify({'success': False, 'error': f'Base UPC {base_upc} not found in bol_items'}), 404

                base_row_id = int(base_item[0])
                base_desc = base_item[1] or ''
                base_img = base_item[2] or ''
                resolved_base_lot = _normalize_lot_number(base_item[3])
                base_bol = base_item[4] or ''
                current_good = int(base_item[5] or 0)
                current_bad = int(base_item[6] or 0)
                current_unchecked = base_item[7]
                original_qty = int(base_item[8] or 0)
                if current_unchecked is None:
                    current_unchecked = max(0, original_qty - current_good - current_bad)
                else:
                    current_unchecked = int(current_unchecked or 0)

                if allow_no_lot:
                    selected_lot = ''
                elif force_requested_lot and requested_lot_norm:
                    selected_lot = requested_lot_norm
                else:
                    selected_lot = resolved_base_lot

                if qty > current_unchecked:
                    exception_overage_applied = True
                    if allow_overage_exception:
                        print(
                            f'[GOOD][EXCEPTION] Allowing noted suffix overage for {base_upc}: '
                            f'requested={qty}, unchecked={current_unchecked}'
                        )
                    else:
                        print(
                            f'[GOOD][EXCEPTION][AUTO] Unchecked gate bypassed for noted suffix {base_upc}: '
                            f'requested={qty}, unchecked={current_unchecked}'
                        )

                new_base_good = current_good + qty
                new_base_unchecked = max(0, current_unchecked - qty)
                if force_requested_lot and selected_lot:
                    cur.execute('''
                        UPDATE bol_items
                        SET good_qty = ?, unchecked_qty = ?, lot_number = ?
                        WHERE id = ?
                    ''', (new_base_good, new_base_unchecked, selected_lot, base_row_id))
                else:
                    cur.execute('''
                        UPDATE bol_items
                        SET good_qty = ?, unchecked_qty = ?
                        WHERE id = ?
                    ''', (new_base_good, new_base_unchecked, base_row_id))
                print(
                    f'[GOOD] Updated base {base_upc}: good_qty {current_good}->{new_base_good}, '
                    f'unchecked_qty {current_unchecked}->{new_base_unchecked}'
                )

                if temp_note_suffix_row:
                    temp_row_id = int(temp_note_suffix_row[0])
                    cur.execute('''
                        UPDATE bol_items
                        SET upc = ?,
                            item_description = ?,
                            image_url = ?,
                            lot_number = ?,
                            bol_number = ?,
                            import_date = ?,
                            temporary = 0,
                            original_qty = ?,
                            unchecked_qty = 0,
                            good_qty = ?,
                            bad_qty = 0,
                            quantity = ?
                        WHERE id = ?
                    ''', (suffixed_upc, base_desc, base_img, selected_lot, base_bol, ts, qty, qty, qty, temp_row_id))
                else:
                    cur.execute('''
                        INSERT INTO bol_items (
                            upc, item_description, image_url, lot_number, bol_number, import_date,
                            temporary, original_qty, unchecked_qty, good_qty, bad_qty, quantity
                        )
                        VALUES (?, ?, ?, ?, ?, ?, 0, ?, 0, ?, 0, ?)
                    ''', (suffixed_upc, base_desc, base_img, selected_lot, base_bol, ts, qty, qty, qty))

                existing_note_status = _select_prep_status_row(cur, suffixed_upc, selected_lot, columns='upc')
                suffixed_status_lot = _resolve_prep_status_lot(cur, suffixed_upc, selected_lot)
                if existing_note_status:
                    cur.execute('''
                        UPDATE items_prep_status
                        SET status = 'good',
                            reason = '',
                            note = ?,
                            quantity = ?,
                            updated_at = ?
                        WHERE upc = ? COLLATE NOCASE
                          AND COALESCE(lot_number, '') = ? COLLATE NOCASE
                    ''', (note, qty, ts, suffixed_upc, suffixed_status_lot))
                else:
                    cur.execute('''
                        INSERT INTO items_prep_status (upc, lot_number, status, reason, note, quantity, updated_at)
                        VALUES (?, ?, ?, ?, ?, ?, ?)
                    ''', (suffixed_upc, _normalize_lot_number(selected_lot), 'good', '', note, qty, ts))

                if exception_overage_applied:
                    _items_prep_record_exception(
                        cur,
                        upc=suffixed_upc,
                        base_upc=base_upc,
                        lot_number=selected_lot,
                        action='good_overage_override',
                        quantity=qty,
                        unchecked_remaining=current_unchecked,
                        source='item-prep',
                        note=exception_note or 'Noted GOOD suffix added as exception after unchecked quantity was exhausted.',
                        meta={
                            'status': 'good',
                            'requested_qty': qty,
                            'unchecked_before': current_unchecked,
                            'allow_overage_exception': True,
                            'requested_lot': requested_lot_norm,
                            'assigned_lot': selected_lot,
                            'forced_lot_override': bool(forced_lot_override),
                            'special_case_note': True
                        }
                    )

                conn.commit()
                update_data_version()

                try:
                    good_meta = {
                        'action': 'saved_good_suffixed',
                        'requested_lot': requested_lot_norm,
                        'lot_number': selected_lot,
                        'assigned_lot': selected_lot,
                        'photo_upc': suffixed_upc,
                        'special_case_note': True,
                        'affects_base_good': True
                    }
                    if selected_lot and (not requested_lot_norm or selected_lot.lower() != requested_lot_norm.lower()):
                        good_meta['auto_assigned'] = True
                    if forced_lot_override:
                        good_meta['forced_lot_override'] = True
                        good_meta['needs_review'] = True
                    if exception_overage_applied:
                        good_meta['exception_overage'] = True
                        good_meta['unchecked_before'] = current_unchecked
                        good_meta['requested_qty'] = qty
                    _preplog_add_entry(
                        upc=suffixed_upc,
                        base_upc=base_upc,
                        status='good',
                        quantity=qty,
                        note=note or None,
                        reason=None,
                        source='item-prep',
                        meta=good_meta,
                        dedupe=False
                    )
                except Exception:
                    pass

                return jsonify({
                    'success': True,
                    'action': 'saved_good_suffixed',
                    'upc': suffixed_upc,
                    'base_upc': base_upc,
                    'lot_number': selected_lot,
                    'exception_overage': bool(exception_overage_applied),
                    'forced_lot_override': bool(forced_lot_override),
                    'special_case_note': True
                })
            
            # Check if the incoming UPC itself is a suffixed BAD entry
            suffixed_upc_found = None
            suffixed_reason = None
            
            if upc != base_upc:
                # UPC is already suffixed, check if it's a BAD entry
                row = _select_prep_status_row(cur, upc, selected_lot, columns='status, reason, quantity')
                print(f'[GOOD] Checking suffixed UPC {upc} in items_prep_status: {row}')
                if row and row[0] == 'bad':
                    suffixed_upc_found = upc
                    suffixed_reason = (row[1] or '').strip()
                    print(f'[GOOD] Found suffixed BAD entry directly: {suffixed_upc_found}')
                elif row:
                    # Suffix exists and is not BAD: keep this suffixed row as GOOD without touching base UPC aggregates.
                    existing_qty = int(row[2] or 0)
                    next_qty = max(existing_qty, qty)
                    status_update_lot = _resolve_prep_status_lot(cur, upc, selected_lot)
                    cur.execute('''
                        UPDATE items_prep_status
                        SET status = 'good',
                            reason = '',
                            note = ?,
                            quantity = ?,
                            updated_at = ?
                        WHERE upc = ? COLLATE NOCASE
                          AND COALESCE(lot_number, '') = ? COLLATE NOCASE
                    ''', (note, next_qty, ts, upc, status_update_lot))

                    bol_row = _select_canonical_bol_row(
                        cur,
                        upc,
                        selected_lot,
                        columns='id, good_qty, quantity'
                    )
                    if bol_row:
                        bol_id = int(bol_row[0])
                        bol_good = int((bol_row[1] if bol_row else 0) or 0)
                        bol_qty = int((bol_row[2] if bol_row else 0) or 0)
                        merged_qty = max(bol_good, bol_qty, next_qty)
                        cur.execute('''
                            UPDATE bol_items
                            SET good_qty = ?, bad_qty = 0, unchecked_qty = 0, quantity = ?, temporary = 0
                            WHERE id = ?
                        ''', (merged_qty, merged_qty, bol_id))

                    conn.commit()
                    update_data_version()
                    return jsonify({
                        'success': True,
                        'action': 'updated_suffixed_good',
                        'upc': upc,
                        'base_upc': base_upc,
                        'lot_number': selected_lot,
                        'forced_lot_override': bool(forced_lot_override)
                    })
                else:
                    # No items_prep_status entry yet - check if this is a bad entry in bol_items
                    # (created by Bad button but diagnostic not completed yet)
                    bol_row = _select_canonical_bol_row(
                        cur,
                        upc,
                        selected_lot,
                        columns='bad_qty, original_qty'
                    )
                    print(f'[GOOD] No prep_status entry, checking bol_items for {upc}: {bol_row}')
                    if bol_row and bol_row[0] and bol_row[0] > 0:
                        # This suffixed entry has bad_qty > 0, meaning it was created from Bad flow
                        suffixed_upc_found = upc
                        suffixed_reason = ''
                        print(f'[GOOD] Found suffixed BAD entry in bol_items (no prep_status yet): {suffixed_upc_found}')
            
            # If not found yet, search for suffixed entries starting from base_upc
            if not suffixed_upc_found:
                suffix_num = 1
                while True:
                    test_suffixed = f"{base_upc}-{suffix_num}"
                    row = _select_prep_status_row(cur, test_suffixed, selected_lot, columns='status, reason')
                    if row and row[0] == 'bad':
                        suffixed_upc_found = test_suffixed
                        suffixed_reason = (row[1] or '').strip()
                        print(f'[GOOD] Found suffixed BAD entry by search: {suffixed_upc_found}')
                        break
                    elif not row:
                        # No more suffixes exist
                        break
                    suffix_num += 1
            
            # If we found a BAD suffixed entry, this is a BAD→GOOD conversion
            if suffixed_upc_found:
                print(f'[GOOD] Converting BAD item {suffixed_upc_found} to GOOD')
                
                # Keep the suffixed entry but change status to GOOD (don't merge back to base)
                # This preserves any notes or distinguishing information added during BAD flow
                
                # UPSERT items_prep_status (might not exist yet if diagnostic not completed)
                existing_suffixed = _select_prep_status_row(cur, suffixed_upc_found, selected_lot, columns='upc')
                suffixed_status_lot = _resolve_prep_status_lot(cur, suffixed_upc_found, selected_lot)
                if existing_suffixed:
                    # Update existing entry
                    cur.execute('''
                        UPDATE items_prep_status
                        SET status = ?, reason = ?, note = ?, updated_at = ?, quantity = ?
                        WHERE upc = ? COLLATE NOCASE
                          AND COALESCE(lot_number, '') = ? COLLATE NOCASE
                    ''', ('good', reason or '', note, ts, qty, suffixed_upc_found, suffixed_status_lot))
                    print(f'[GOOD] Updated items_prep_status {suffixed_upc_found}: status=good, reason="{reason or ""}"')
                else:
                    # Insert new entry
                    cur.execute('''
                        INSERT INTO items_prep_status (upc, lot_number, status, reason, note, updated_at, quantity)
                        VALUES (?, ?, ?, ?, ?, ?, ?)
                    ''', (suffixed_upc_found, _normalize_lot_number(selected_lot), 'good', reason or '', note, ts, qty))
                    print(f'[GOOD] Inserted items_prep_status {suffixed_upc_found}: status=good, reason="{reason or ""}"')
                
                # Update bol_items quantities: move from bad_qty to good_qty
                bol_row = _select_canonical_bol_row(
                    cur,
                    suffixed_upc_found,
                    selected_lot,
                    columns='id, bad_qty, good_qty'
                )
                if bol_row:
                    suffixed_bol_id = int(bol_row[0])
                    current_bad = bol_row[1] or 0
                    current_good = bol_row[2] or 0
                    # Move all bad_qty to good_qty
                    new_bad = 0
                    new_good = current_good + current_bad
                    cur.execute('''
                        UPDATE bol_items
                        SET bad_qty = ?, good_qty = ?, temporary = 0
                        WHERE id = ?
                    ''', (new_bad, new_good, suffixed_bol_id))
                    print(f'[GOOD] Updated bol_items {suffixed_upc_found}: bad_qty {current_bad}→{new_bad}, good_qty {current_good}→{new_good}')
                    
                    # Also update base UPC: decrement bad_qty
                    base_row = _select_canonical_bol_row(
                        cur,
                        base_upc,
                        selected_lot,
                        columns='id, bad_qty'
                    )
                    if base_row:
                        base_bol_id = int(base_row[0])
                        base_bad = base_row[1] or 0
                        new_base_bad = max(0, base_bad - current_bad)
                        cur.execute('''
                            UPDATE bol_items
                            SET bad_qty = ?
                            WHERE id = ?
                        ''', (new_base_bad, base_bol_id))
                        print(f'[GOOD] Updated base {base_upc}: bad_qty {base_bad}→{new_base_bad}')
                
                conn.commit()
                
                # Update data version for cache invalidation
                update_data_version()

                return jsonify({
                    'success': True, 
                    'action': 'converted_bad_to_good_kept_suffix',
                    'upc': suffixed_upc_found,
                    'base_upc': base_upc,
                    'lot_number': selected_lot,
                    'forced_lot_override': bool(forced_lot_override)
                })
            
            # Not a BAD→GOOD conversion - proceed with normal GOOD flow for base UPC
            # Update items_prep_status for the base UPC
            # Check if ANY entry exists for this UPC (regardless of status)
            existing_prep_row = _select_prep_status_row(cur, base_upc, selected_lot, columns='status, quantity')
            status_update_lot = _resolve_prep_status_lot(cur, base_upc, selected_lot)
            if existing_prep_row:
                existing_status = existing_prep_row[0]
                existing_qty = existing_prep_row[1] if existing_prep_row[1] is not None else 0
                
                if existing_status == 'good':
                    # Add to existing GOOD quantity
                    total_prep_good = existing_qty + qty
                    cur.execute('''
                        UPDATE items_prep_status
                        SET quantity = ?, reason = ?, note = ?, updated_at = ?
                        WHERE upc = ? COLLATE NOCASE
                          AND COALESCE(lot_number, '') = ? COLLATE NOCASE
                    ''', (total_prep_good, reason, note, ts, base_upc, status_update_lot))
                    print(f'[GOOD] Updated items_prep_status {base_upc}: qty {existing_qty}→{total_prep_good}')
                else:
                    # Replace existing status (was unchecked/bad) with GOOD
                    cur.execute('''
                        UPDATE items_prep_status
                        SET status = ?, quantity = ?, reason = ?, note = ?, updated_at = ?
                        WHERE upc = ? COLLATE NOCASE
                          AND COALESCE(lot_number, '') = ? COLLATE NOCASE
                    ''', ('good', qty, reason, note, ts, base_upc, status_update_lot))
                    print(f'[GOOD] Changed items_prep_status {base_upc} from {existing_status} to good, qty={qty}')
            else:
                # No existing entry, insert new GOOD status
                cur.execute('''
                    INSERT INTO items_prep_status (upc, lot_number, status, reason, note, quantity, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?)
                ''', (base_upc, _normalize_lot_number(selected_lot), 'good', reason, note, qty, ts))
                print(f'[GOOD] Created items_prep_status {base_upc} with status=good, qty={qty}')
            
            # Update bol_items quantities (good and unchecked) on the best-matching LOT row.
            if selected_lot:
                cur.execute('''
                    SELECT id, good_qty, bad_qty, unchecked_qty, original_qty
                    FROM bol_items
                    WHERE upc = ? COLLATE NOCASE
                      AND lot_number = ? COLLATE NOCASE
                    ORDER BY import_date DESC, id DESC
                    LIMIT 1
                ''', (base_upc, selected_lot))
                bol_row = cur.fetchone()
                if not bol_row:
                    print(f'[GOOD] WARNING: No bol_items row for {base_upc} in LOT {selected_lot}, falling back to newest row')
                    cur.execute('''
                        SELECT id, good_qty, bad_qty, unchecked_qty, original_qty
                        FROM bol_items
                        WHERE upc = ? COLLATE NOCASE
                        ORDER BY import_date DESC, id DESC
                        LIMIT 1
                    ''', (base_upc,))
                    bol_row = cur.fetchone()
            else:
                cur.execute('''
                    SELECT id, good_qty, bad_qty, unchecked_qty, original_qty
                    FROM bol_items
                    WHERE upc = ? COLLATE NOCASE
                    ORDER BY import_date DESC, id DESC
                    LIMIT 1
                ''', (base_upc,))
                bol_row = cur.fetchone()

            if bol_row:
                bol_id = bol_row[0]
                current_good = bol_row[1] or 0
                current_bad = bol_row[2] or 0
                current_unchecked = bol_row[3]
                original_qty = bol_row[4] or 0

                if current_unchecked is None:
                    current_unchecked = max(0, original_qty - current_good - current_bad)

                if qty > current_unchecked:
                    exception_overage_applied = True
                    if allow_overage_exception:
                        print(
                            f'[GOOD][EXCEPTION] Allowing overage add for {base_upc}: '
                            f'requested={qty}, unchecked={current_unchecked}'
                        )
                    else:
                        print(
                            f'[GOOD][EXCEPTION][AUTO] Unchecked gate bypassed for {base_upc}: '
                            f'requested={qty}, unchecked={current_unchecked}'
                        )

                new_good = current_good + qty
                new_unchecked = max(0, current_unchecked - qty)

                if selected_lot:
                    cur.execute('''
                        UPDATE bol_items
                        SET good_qty = ?, unchecked_qty = ?, lot_number = ?
                        WHERE id = ?
                    ''', (new_good, new_unchecked, selected_lot, bol_id))
                    print(f'[GOOD] Updated bol_items {base_upc} (id={bol_id}): good_qty {current_good}→{new_good}, unchecked_qty {current_unchecked}→{new_unchecked}, lot_number={selected_lot}')
                else:
                    cur.execute('''
                        UPDATE bol_items
                        SET good_qty = ?, unchecked_qty = ?
                        WHERE id = ?
                    ''', (new_good, new_unchecked, bol_id))
                    print(f'[GOOD] Updated bol_items {base_upc} (id={bol_id}): good_qty {current_good}→{new_good}, unchecked_qty {current_unchecked}→{new_unchecked}')

                if exception_overage_applied:
                    _items_prep_record_exception(
                        cur,
                        upc=base_upc,
                        base_upc=base_upc,
                        lot_number=selected_lot,
                        action='good_overage_override',
                        quantity=qty,
                        unchecked_remaining=current_unchecked,
                        source='item-prep',
                        note=exception_note or 'Added as exception after unchecked quantity was exhausted.',
                        meta={
                            'status': 'good',
                            'requested_qty': qty,
                            'unchecked_before': current_unchecked,
                            'allow_overage_exception': True,
                            'requested_lot': requested_lot_norm,
                            'assigned_lot': selected_lot,
                            'forced_lot_override': bool(forced_lot_override)
                        }
                    )
            else:
                print(f'[GOOD] WARNING: Could not find bol_items entry for {base_upc} to update quantities')

            
            conn.commit()
            print(f'[GOOD] Transaction committed for {base_upc}')
            
            # Update data version for cache invalidation
            update_data_version()

            # Prep log (preplog.db)
            try:
                good_meta = {
                    'action': 'converted_to_good' if suffixed_upc_found else 'saved_good',
                    'requested_lot': requested_lot_norm,
                    'lot_number': selected_lot,
                    'assigned_lot': selected_lot
                }
                if suffixed_upc_found:
                    # Keep original diagnostic UPC so log photo viewer can open exact-image rows.
                    good_meta['photo_upc'] = suffixed_upc_found
                if selected_lot and (not requested_lot_norm or selected_lot.lower() != requested_lot_norm.lower()):
                    good_meta['auto_assigned'] = True
                if forced_lot_override:
                    good_meta['forced_lot_override'] = True
                    good_meta['needs_review'] = True
                if exception_overage_applied:
                    good_meta['exception_overage'] = True
                    good_meta['unchecked_before'] = current_unchecked
                    good_meta['requested_qty'] = qty
                _preplog_add_entry(
                    upc=base_upc,
                    base_upc=base_upc,
                    status='good',
                    quantity=qty,
                    note=note or None,
                    reason=None,
                    source='item-prep',
                    meta=good_meta,
                    dedupe=False
                )
            except Exception:
                pass

            return jsonify({
                'success': True, 
                'action': 'converted_to_good' if suffixed_upc_found else 'saved_good',
                'upc': base_upc,
                'base_upc': base_upc,
                'lot_number': selected_lot,
                'exception_overage': bool(exception_overage_applied),
                'forced_lot_override': bool(forced_lot_override)
            })
        
        # BAD/UNCHECKED flow - upc should already be suffixed if coming from Bad button
        # Just upsert the status (no qty changes here, that happens in diagnostic Complete)
        
        # Special case: If changing GOOD (base UPC) to BAD, need to create a suffixed entry
        # Check if we're working with a base UPC (no suffix) - this is a GOOD->BAD conversion
        if status == 'bad' and '-' not in str(upc):
            # This is a GOOD item (base UPC) being changed to BAD
            print(f'[BAD] Converting GOOD item {base_upc} to BAD')
            
            # Resolve lot for this UPC (explicit/session lot first), unless user opted to continue without lot.
            if allow_no_lot:
                selected_lot = ''
            elif force_requested_lot and requested_lot_norm:
                selected_lot = requested_lot_norm
            else:
                selected_lot = _resolve_bol_lot_for_upc(cur, base_upc, requested_lot)
            if selected_lot:
                # Get the bol_items entry to decrement its quantity
                cur.execute('''
                    SELECT id, quantity
                    FROM bol_items 
                    WHERE upc = ? COLLATE NOCASE 
                      AND lot_number = ? COLLATE NOCASE
                      AND (itemprepped IS NULL OR itemprepped = 0)
                    ORDER BY import_date DESC, id DESC
                    LIMIT 1
                ''', (base_upc, selected_lot))
            else:
                cur.execute('''
                    SELECT id, quantity
                    FROM bol_items
                    WHERE upc = ? COLLATE NOCASE
                      AND (itemprepped IS NULL OR itemprepped = 0)
                    ORDER BY import_date DESC, id DESC
                    LIMIT 1
                ''', (base_upc,))
            
            bol_row = cur.fetchone()
            if bol_row:
                bol_id, current_bol_qty = bol_row
                current_bol_qty = current_bol_qty or 1
                
                # Decrement bol_items quantity by 1
                if current_bol_qty > 1:
                    new_bol_qty = current_bol_qty - 1
                    cur.execute('UPDATE bol_items SET quantity = ? WHERE id = ?', (new_bol_qty, bol_id))
                    print(f'[BAD] Decremented bol_items quantity for {base_upc} from {current_bol_qty} to {new_bol_qty}')
                # If qty=1, leave it at 1 so the GOOD item stays visible with qty=1
            
            # Check if the GOOD item exists in items_prep_status
            # If it doesn't exist, we need to create it with the remaining quantity
            base_status_lot = _resolve_prep_status_lot(cur, base_upc, selected_lot)
            good_row = _select_prep_status_row(cur, base_upc, selected_lot, columns='quantity')
            
            if good_row:
                # Entry exists in items_prep_status
                good_qty = good_row[0] if good_row[0] is not None else 1
                
                # Check if we actually decremented bol_items (meaning original qty > 1)
                if bol_row and current_bol_qty > 1:
                    # Original had multiple units - keep remaining as GOOD
                    # Use bol_items quantity as source of truth for remaining GOOD units
                    remaining_qty = new_bol_qty  # This is current_bol_qty - 1
                    cur.execute('''
                        UPDATE items_prep_status
                        SET quantity = ?
                        WHERE upc = ? COLLATE NOCASE
                          AND COALESCE(lot_number, '') = ? COLLATE NOCASE
                    ''', (remaining_qty, base_upc, base_status_lot))
                    print(f'[BAD] Set GOOD status qty for {base_upc} to {remaining_qty} (bol_items was decremented)')
                else:
                    # Original qty was 1 - all units now BAD, set to unchecked
                    cur.execute('''
                        UPDATE items_prep_status
                        SET status = ?, quantity = ?
                        WHERE upc = ? COLLATE NOCASE
                          AND COALESCE(lot_number, '') = ? COLLATE NOCASE
                    ''', ('unchecked', 1, base_upc, base_status_lot))
                    print(f'[BAD] Set {base_upc} to unchecked (original bol_items qty was 1)')
            else:
                # No entry in items_prep_status - create one with remaining bol_items quantity
                # After decrement, bol_items now has the remaining GOOD quantity
                if bol_row and current_bol_qty > 1:
                    # We decremented from 2+ to at least 1
                    remaining_qty = new_bol_qty  # This is current_bol_qty - 1
                    cur.execute('''
                        INSERT INTO items_prep_status (upc, lot_number, status, reason, note, quantity, updated_at)
                        VALUES (?,?,?,?,?,?,?)
                    ''', (base_upc, _normalize_lot_number(selected_lot), 'good', '', '', remaining_qty, ts))
                    print(f'[BAD] Created GOOD status entry {base_upc} with qty={remaining_qty}')
                else:
                    # We had qty=1, didn't decrement, so set to unchecked (all units now BAD)
                    cur.execute('''
                        INSERT INTO items_prep_status (upc, lot_number, status, reason, note, quantity, updated_at)
                        VALUES (?,?,?,?,?,?,?)
                    ''', (base_upc, _normalize_lot_number(selected_lot), 'unchecked', '', '', 1, ts))
                    print(f'[BAD] Created unchecked status entry {base_upc} (original qty was 1)')
            
            # Find next available suffix (check items_prep_status only)
            # We do this BEFORE commit to ensure atomicity
            suffix_num = 1
            max_suffix_attempts = 50
            suffixed_upc = None
            
            for attempt in range(max_suffix_attempts):
                test_suffixed = f"{base_upc}-{suffix_num}"
                cur.execute('SELECT upc FROM items_prep_status WHERE upc = ? COLLATE NOCASE', (test_suffixed,))
                if not cur.fetchone():
                    suffixed_upc = test_suffixed
                    print(f'[BAD] Found available suffix: {suffixed_upc}')
                    break
                suffix_num += 1
            
            if not suffixed_upc:
                conn.rollback()
                return jsonify({'success': False, 'error': f'Could not find available suffix after {max_suffix_attempts} attempts'}), 500
            
            # Create new suffixed entry (BAD) with quantity=1
            try:
                cur.execute('''
                    INSERT INTO items_prep_status (upc, lot_number, status, reason, note, quantity, updated_at)
                    VALUES (?,?,?,?,?,?,?)
                ''', (suffixed_upc, _normalize_lot_number(selected_lot), status, reason, note, 1, ts))
                print(f'[BAD] Created BAD status entry {suffixed_upc} with qty=1')
            except Exception as e:
                # If insert fails, rollback everything and return error
                print(f'[BAD] Failed to create {suffixed_upc}. Error: {e}')
                conn.rollback()
                return jsonify({'success': False, 'error': _safe_error(e, 'Failed to create BAD entry')}), 500
            
            # Commit all changes atomically
            conn.commit()

            # Update data version for cache invalidation
            update_data_version()

            # Prep log (preplog.db)
            try:
                log_note = note or ''
                try:
                    cur.execute('''
                        SELECT note
                        FROM items_prep_notes
                        WHERE upc = ? COLLATE NOCASE
                        ORDER BY created_at DESC, id DESC
                        LIMIT 1
                    ''', (suffixed_upc,))
                    nrow = cur.fetchone()
                    if nrow and nrow[0] and str(nrow[0]).strip():
                        log_note = str(nrow[0]).strip()
                except Exception:
                    pass
                converted_bad_meta = {
                    'action': 'converted_to_bad',
                    'requested_lot': requested_lot_norm,
                    'lot_number': selected_lot,
                    'assigned_lot': selected_lot
                }
                if selected_lot and (not requested_lot_norm or selected_lot.lower() != requested_lot_norm.lower()):
                    converted_bad_meta['auto_assigned'] = True
                _preplog_add_entry(
                    upc=suffixed_upc,
                    base_upc=base_upc,
                    status='bad',
                    quantity=1,
                    note=log_note or None,
                    reason=reason or None,
                    source='item-prep',
                    meta=converted_bad_meta,
                    dedupe=True
                )
            except Exception:
                pass

            return jsonify({'success': True, 'upc': suffixed_upc, 'action': 'converted_to_bad', 'quantity': 1})

        if status == 'return' and '-' not in str(upc):
            print(f'[RETURN] Converting base item {base_upc} to RETURN')

            cur.execute('''
                SELECT id, item_description, image_url, lot_number, bol_number, unchecked_qty, bad_qty, original_qty, good_qty
                FROM bol_items
                WHERE upc = ? COLLATE NOCASE
                ORDER BY import_date DESC, id DESC
                LIMIT 1
            ''', (base_upc,))
            base_item = cur.fetchone()

            if not base_item:
                return jsonify({'success': False, 'error': f'Base UPC {base_upc} not found in bol_items'}), 404

            resolved_base_lot = _normalize_lot_number(base_item[3])
            base_row_id = int(base_item[0])
            unchecked = base_item[5]
            current_bad = int(base_item[6] or 0)
            original_qty = int(base_item[7] or 0)
            current_good = int(base_item[8] or 0)
            if unchecked is None:
                unchecked = max(0, original_qty - current_good - current_bad)
            else:
                unchecked = int(unchecked or 0)

            if qty > unchecked:
                exception_overage_applied = True
                if allow_overage_exception:
                    print(
                        f'[RETURN][EXCEPTION] Allowing overage return-entry for {base_upc}: '
                        f'requested={qty}, unchecked={unchecked}'
                    )
                else:
                    print(
                        f'[RETURN][EXCEPTION][AUTO] Unchecked gate bypassed for {base_upc}: '
                        f'requested={qty}, unchecked={unchecked}'
                    )

            suffixed_upc = _next_clean_suffix(base_upc)
            return_reason = reason or 'return'

            cur.execute('''
                INSERT INTO bol_items (
                    upc, item_description, image_url, lot_number, bol_number, import_date,
                    temporary, original_qty, unchecked_qty, good_qty, bad_qty, quantity
                )
                VALUES (?, ?, ?, ?, ?, ?, 0, ?, 0, ?, 0, ?)
            ''', (suffixed_upc, base_item[1], base_item[2], '', base_item[4], ts, qty, qty, qty))

            cur.execute('''
                INSERT INTO items_prep_status (upc, lot_number, status, reason, note, quantity, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?)
            ''', (suffixed_upc, '', 'return', return_reason, note, qty, ts))

            new_unchecked = max(0, unchecked - qty)
            cur.execute('''
                UPDATE bol_items
                SET unchecked_qty = ?
                WHERE id = ?
            ''', (new_unchecked, base_row_id))

            if exception_overage_applied:
                _items_prep_record_exception(
                    cur,
                    upc=suffixed_upc,
                    base_upc=base_upc,
                    lot_number='',
                    action='return_overage_override',
                    quantity=qty,
                    unchecked_remaining=unchecked,
                    source='item-prep',
                    note=exception_note or 'Return entry created as exception after unchecked quantity was exhausted.',
                    meta={
                        'status': 'return',
                        'requested_qty': qty,
                        'unchecked_before': unchecked,
                        'allow_overage_exception': True,
                        'requested_lot': requested_lot_norm,
                        'assigned_lot': '',
                        'forced_lot_override': False,
                        'source_lot': resolved_base_lot
                    }
                )

            conn.commit()
            update_data_version()

            try:
                _preplog_add_entry(
                    upc=suffixed_upc,
                    base_upc=base_upc,
                    status='return',
                    quantity=qty,
                    note=note or None,
                    reason=return_reason,
                    source='item-prep',
                    meta={
                        'action': 'converted_to_return',
                        'requested_lot': requested_lot_norm,
                        'lot_number': '',
                        'assigned_lot': '',
                        'continued_without_lot': True,
                        'source_lot': resolved_base_lot,
                        'exception_overage': bool(exception_overage_applied),
                        'unchecked_before': unchecked if exception_overage_applied else None
                    },
                    dedupe=True
                )
            except Exception:
                pass

            return jsonify({
                'success': True,
                'upc': suffixed_upc,
                'base_upc': base_upc,
                'action': 'converted_to_return',
                'quantity': qty,
                'lot_number': '',
                'continued_without_lot': True,
                'exception_overage': bool(exception_overage_applied)
            })

        # Normal BAD/UNCHECKED flow - UPC already has suffix or is being updated
        # Just update the existing entry directly
        if allow_no_lot:
            status_lot = ''
        elif force_requested_lot and requested_lot_norm:
            status_lot = requested_lot_norm
        else:
            status_lot = _resolve_bol_lot_for_upc(cur, upc, requested_lot)
        status_update_lot = _resolve_prep_status_lot(cur, upc, status_lot)
        existing_row = _select_prep_status_row(cur, upc, status_lot, columns='upc')
        if existing_row:
            cur.execute('''
                UPDATE items_prep_status
                SET status=?, reason=?, note=?, quantity=?, updated_at=?
                WHERE upc=? COLLATE NOCASE
                  AND COALESCE(lot_number, '') = ? COLLATE NOCASE
            ''', (status, reason, note, qty, ts, upc, status_update_lot))
            print(f'[{status.upper()}] Updated existing entry {upc}')
        else:
            cur.execute('''
                INSERT INTO items_prep_status (upc, lot_number, status, reason, note, quantity, updated_at)
                VALUES (?,?,?,?,?,?,?)
            ''', (upc, _normalize_lot_number(status_lot), status, reason, note, qty, ts))
            print(f'[{status.upper()}] Created new entry {upc}')
        conn.commit()
        

        # Update data version for cache invalidation
        update_data_version()

        # Prep log (preplog.db) — only for BAD (we don't log unchecked).
        if status == 'bad':
            try:
                log_note = note or ''
                try:
                    cur.execute('''
                        SELECT note
                        FROM items_prep_notes
                        WHERE upc = ? COLLATE NOCASE
                        ORDER BY created_at DESC, id DESC
                        LIMIT 1
                    ''', (upc,))
                    nrow = cur.fetchone()
                    if nrow and nrow[0] and str(nrow[0]).strip():
                        log_note = str(nrow[0]).strip()
                except Exception:
                    pass
                updated_bad_meta = {
                    'action': 'updated',
                    'requested_lot': requested_lot_norm,
                    'lot_number': status_lot,
                    'assigned_lot': status_lot
                }
                if status_lot and (not requested_lot_norm or status_lot.lower() != requested_lot_norm.lower()):
                    updated_bad_meta['auto_assigned'] = True
                _preplog_add_entry(
                    upc=upc,
                    base_upc=base_upc,
                    status='bad',
                    quantity=qty,
                    note=log_note or None,
                    reason=reason or None,
                    source='item-prep',
                    meta=updated_bad_meta,
                    dedupe=True
                )
            except Exception:
                pass

        return jsonify({'success': True, 'upc': upc, 'action': 'updated', 'quantity': qty})
        
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/items_prep/allocate_lots', methods=['POST'])
def api_items_prep_allocate_lots():
    """Handle multi-LOT good marking with qty distribution across LOTs.
    JSON: { upc, allocations: [{lot_id, qty}], reason, note }
    """
    conn = None
    try:
        data = request.get_json() or {}
        upc = _normalize_upc(data.get('upc'))
        allocations = data.get('allocations', [])  # [{lot_id, qty}, ...]
        reason = (data.get('reason') or '').strip()
        note = (data.get('note') or '').strip()
        
        if not upc or not allocations:
            return jsonify({'success': False, 'error': 'Missing upc or allocations'}), 400
        
        # Strip leading zeros
        base_upc = _strip_leading_zeros_numeric(upc)
        
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        _ensure_items_prep_tables()
        
        import datetime
        ts = datetime.datetime.now(datetime.UTC).isoformat()
        
        total_qty_allocated = 0
        results = []
        
        # Process each LOT allocation
        for alloc in allocations:
            lot_id = alloc.get('id')
            qty = int(alloc.get('qty', 0))
            
            if qty <= 0:
                continue
            
            # Get LOT details and validate
            cur.execute('''
                SELECT lot_number, good_qty, unchecked_qty, original_qty 
                FROM bol_items 
                WHERE id = ? AND upc = ? COLLATE NOCASE
            ''', (lot_id, base_upc))
            
            lot_row = cur.fetchone()
            if not lot_row:
                return jsonify({'success': False, 'error': f'LOT with id {lot_id} not found'}), 404
            
            lot_number, current_good, current_unchecked, original_qty = lot_row
            current_good = current_good or 0
            current_unchecked = current_unchecked or 0
            original_qty = original_qty or 0
            
            # Validate sufficient unchecked qty
            if qty > current_unchecked:
                return jsonify({
                    'success': False,
                    'error': f'LOT {lot_number}: Cannot mark {qty} as good - only {current_unchecked} unchecked'
                }), 400
            
            # Update quantities for this LOT
            new_good = current_good + qty
            new_unchecked = current_unchecked - qty
            
            cur.execute('''
                UPDATE bol_items 
                SET good_qty = ?, unchecked_qty = ?, quantity = ?
                WHERE id = ?
            ''', (new_good, new_unchecked, new_good, lot_id))
            
            total_qty_allocated += qty
            results.append({
                'lot_number': lot_number,
                'qty': qty,
                'good_qty': new_good,
                'unchecked_qty': new_unchecked
            })
            
            print(f'[GOOD-LOT] {base_upc} LOT {lot_number}: moved {qty} from unchecked to good (good: {current_good}→{new_good}, unchecked: {current_unchecked}→{new_unchecked})')
        
        # Update prep status per lot so one UPC can be tracked independently across multiple lots.
        for lot_update in results:
            lot_number = _normalize_lot_number(lot_update.get('lot_number'))
            lot_qty = int(lot_update.get('qty') or 0)
            if lot_qty <= 0:
                continue

            existing_row = _select_prep_status_row(cur, base_upc, lot_number, columns='status, quantity')
            status_update_lot = _resolve_prep_status_lot(cur, base_upc, lot_number)
            if existing_row:
                existing_status = (existing_row[0] or '').strip().lower()
                existing_qty = int(existing_row[1] or 0)
                if existing_status == 'good':
                    next_qty = existing_qty + lot_qty
                else:
                    next_qty = lot_qty
                cur.execute('''
                    UPDATE items_prep_status
                    SET status = 'good',
                        reason = ?,
                        note = ?,
                        quantity = ?,
                        updated_at = ?
                    WHERE upc = ? COLLATE NOCASE
                      AND COALESCE(lot_number, '') = ? COLLATE NOCASE
                ''', (reason, note, next_qty, ts, base_upc, status_update_lot))
            else:
                cur.execute('''
                    INSERT INTO items_prep_status (upc, lot_number, status, reason, note, quantity, updated_at)
                    VALUES (?,?,?,?,?,?,?)
                ''', (base_upc, lot_number, 'good', reason, note, lot_qty, ts))

        cur.execute('''
            SELECT SUM(COALESCE(quantity, 0))
            FROM items_prep_status
            WHERE upc = ? COLLATE NOCASE
              AND status = 'good'
        ''', (base_upc,))
        new_prep_qty = cur.fetchone()[0] or 0
        
        conn.commit()

        # Update data version for cache invalidation
        try:
            update_data_version()
        except Exception:
            pass

        # Prep log (preplog.db)
        try:
            _preplog_add_entry(
                upc=base_upc,
                base_upc=base_upc,
                status='good',
                quantity=total_qty_allocated,
                note=note or None,
                reason=reason or None,
                source='item-prep',
                meta={'action': 'allocate_lots', 'lots_updated': results},
                dedupe=False
            )
        except Exception:
            pass
        
        return jsonify({
            'success': True,
            'upc': base_upc,
            'total_qty': total_qty_allocated,
            'total_good': new_prep_qty,
            'lots_updated': results
        })
        
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/items_prep/create_bad_entry', methods=['POST'])
def api_items_prep_create_bad_entry():
    """Create a temporary suffixed entry for Bad flow.
    This creates the suffix and temporary bol_items entry and immediately moves qty from
    the base lot's unchecked bucket into bad bucket.
    JSON: { upc, qty }
    Returns: { success, suffixed_upc }
    """
    conn = None
    try:
        data = request.get_json() or {}
        upc = _strip_leading_zeros_numeric(_normalize_upc(data.get('upc')))
        exception_note = (data.get('exception_note') or '').strip()
        try:
            qty = int(data.get('qty', 1))
        except Exception:
            return jsonify({'success': False, 'error': 'Invalid qty'}), 400
        if qty < 1:
            return jsonify({'success': False, 'error': 'qty must be at least 1'}), 400
        
        if not upc:
            return jsonify({'success': False, 'error': 'Missing upc'}), 400
        
        # Strip leading zeros
        upc = _normalize_upc_preserve_suffix_for_match(upc)
        
        base_upc = upc.split('-')[0] if '-' in upc else upc
        requested_lot_input = _normalize_lot_number(_preferred_lot_from_request(data))
        requested_lot = ''
        allow_no_lot = True
        force_requested_lot = False
        allow_overage_exception = _coerce_bool(
            data.get('allow_overage_exception') if data.get('allow_overage_exception') is not None else data.get('force_exception')
        )
        exception_overage_applied = False
        
        conn = sqlite3.connect('bol.db', isolation_level='IMMEDIATE')
        cur = conn.cursor()
        _ensure_items_prep_tables()
        requested_lot_norm = ''
        lot_info = {
            'requested_lot': '',
            'assigned_lot': '',
            'auto_assigned': False,
            'auto_assign_reason': ''
        }
        selected_lot = ''
        
        # Find next available suffix for bad items
        # Check BOTH bol_items AND prep tables to avoid reusing deleted suffixes with orphaned data
        suffix_num = 1
        while True:
            suffixed_upc = f"{base_upc}-{suffix_num}"
            
            # Check if exists in bol_items
            cur.execute('SELECT upc FROM bol_items WHERE upc = ? COLLATE NOCASE', (suffixed_upc,))
            if cur.fetchone():
                suffix_num += 1
                continue
            
            # Also check if prep data exists (images, status, notes) to avoid reusing old suffixes
            cur.execute('SELECT upc FROM items_prep_images WHERE upc = ? COLLATE NOCASE LIMIT 1', (suffixed_upc,))
            if cur.fetchone():
                suffix_num += 1
                continue
            
            cur.execute('SELECT upc FROM items_prep_status WHERE upc = ? COLLATE NOCASE LIMIT 1', (suffixed_upc,))
            if cur.fetchone():
                suffix_num += 1
                continue
            
            try:
                cur.execute('SELECT upc FROM items_prep_notes WHERE upc = ? COLLATE NOCASE LIMIT 1', (suffixed_upc,))
                if cur.fetchone():
                    suffix_num += 1
                    continue
            except Exception:
                pass
            
            # Suffix is clean - no bol_items entry and no orphaned prep data
            break
        
        # Get base item details to copy and check unchecked quantity.
        if selected_lot:
            cur.execute('''
                SELECT id, item_description, image_url, lot_number, bol_number, unchecked_qty, bad_qty, original_qty, good_qty
                FROM bol_items
                WHERE upc = ? COLLATE NOCASE
                  AND lot_number = ? COLLATE NOCASE
                ORDER BY import_date DESC, id DESC
                LIMIT 1
            ''', (base_upc, selected_lot))
            base_item = cur.fetchone()
        else:
            base_item = None
        if not base_item:
            cur.execute('''
                SELECT id, item_description, image_url, lot_number, bol_number, unchecked_qty, bad_qty, original_qty, good_qty
                FROM bol_items
                WHERE upc = ? COLLATE NOCASE
                ORDER BY import_date DESC, id DESC
                LIMIT 1
            ''', (base_upc,))
            base_item = cur.fetchone()
        
        if not base_item:
            return jsonify({'success': False, 'error': f'Base UPC {base_upc} not found in bol_items'}), 404

        resolved_base_lot = _normalize_lot_number(base_item[3])
        if allow_no_lot:
            selected_lot = ''
        elif force_requested_lot and requested_lot_norm:
            selected_lot = requested_lot_norm
        else:
            selected_lot = resolved_base_lot
        requested_lot_norm = _normalize_lot_number(lot_info.get('requested_lot'))
        auto_assigned = bool(selected_lot and (not requested_lot_norm or selected_lot.lower() != requested_lot_norm.lower()))
        forced_lot_override = bool(force_requested_lot and selected_lot)
        auto_assign_reason = lot_info.get('auto_assign_reason') or (
            'requested_lot_unavailable_used_latest' if requested_lot_norm and auto_assigned else (
                'no_lot_requested_used_latest' if auto_assigned else ''
            )
        )
        
        base_row_id = base_item[0]
        unchecked = base_item[5]
        current_bad = base_item[6] or 0
        original_qty = base_item[7] or 0
        current_good = base_item[8] or 0

        if unchecked is None:
            unchecked = max(0, original_qty - current_good - current_bad)
        if qty > unchecked:
            exception_overage_applied = True
            if allow_overage_exception:
                print(
                    f'[BAD][EXCEPTION] Allowing overage bad-entry for {base_upc}: '
                    f'requested={qty}, unchecked={unchecked}'
                )
            else:
                print(
                    f'[BAD][EXCEPTION][AUTO] Unchecked gate bypassed for {base_upc}: '
                    f'requested={qty}, unchecked={unchecked}'
                )
        
        # Create temporary suffixed entry with new quantity columns
        import datetime
        import_date = datetime.datetime.now(datetime.UTC).isoformat()
        
        cur.execute('''
            INSERT INTO bol_items (
                upc, item_description, image_url, lot_number, bol_number, import_date, 
                temporary, original_qty, unchecked_qty, bad_qty, good_qty, quantity
            )
            VALUES (?, ?, ?, ?, ?, ?, 1, ?, 0, ?, 0, ?)
        ''', (suffixed_upc, base_item[1], base_item[2], selected_lot, base_item[4], import_date, 
              qty, qty, qty))  # original_qty=qty, bad_qty=qty, quantity=qty for this suffixed entry
        
        # Seed prep status immediately so Items-to-List visibility stays in sync
        # even before diagnostic completion posts the final reason/note payload.
        cur.execute('''
            INSERT INTO items_prep_status (upc, lot_number, status, reason, note, quantity, updated_at)
            VALUES (?, ?, 'bad', '', '', ?, ?)
        ''', (suffixed_upc, _normalize_lot_number(selected_lot), qty, import_date))
        
        # Update base item: move qty from unchecked to bad
        new_unchecked = max(0, unchecked - qty)
        new_bad = current_bad + qty
        
        if force_requested_lot and selected_lot:
            cur.execute('''
                UPDATE bol_items 
                SET unchecked_qty = ?, bad_qty = ?, lot_number = ?
                WHERE id = ?
            ''', (new_unchecked, new_bad, selected_lot, base_row_id))
        else:
            cur.execute('''
                UPDATE bol_items 
                SET unchecked_qty = ?, bad_qty = ?
                WHERE id = ?
            ''', (new_unchecked, new_bad, base_row_id))

        if exception_overage_applied:
            _items_prep_record_exception(
                cur,
                upc=suffixed_upc,
                base_upc=base_upc,
                lot_number=selected_lot,
                action='bad_overage_override',
                quantity=qty,
                unchecked_remaining=unchecked,
                source='item-prep',
                note=exception_note or 'BAD entry created as exception after unchecked quantity was exhausted.',
                meta={
                    'status': 'bad',
                    'requested_qty': qty,
                    'unchecked_before': unchecked,
                    'allow_overage_exception': True,
                    'requested_lot': requested_lot_norm,
                    'assigned_lot': selected_lot,
                    'forced_lot_override': bool(forced_lot_override)
                }
            )
        
        conn.commit()
        
        print(f'[BAD] Created temporary suffixed entry: {suffixed_upc} (temporary=1, qty={qty})')
        print(f'[BAD] {base_upc}: moved {qty} from unchecked to bad (bad: {current_bad}→{new_bad}, unchecked: {unchecked}→{new_unchecked})')
        

        # Update data version for cache invalidation
        update_data_version()

        # Prep log (preplog.db): keep lot-assignment details so auto-assigned items can be reviewed.
        try:
            _preplog_add_entry(
                upc=suffixed_upc,
                base_upc=base_upc,
                status='bad',
                quantity=qty,
                note=None,
                reason=None,
                source='item-prep',
                meta={
                    'action': 'create_bad_entry',
                    'requested_lot': requested_lot_norm,
                    'lot_number': selected_lot,
                    'assigned_lot': selected_lot,
                    'auto_assigned': bool(auto_assigned),
                    'auto_assign_reason': auto_assign_reason,
                    'continued_without_lot': bool(allow_no_lot),
                    'source_lot': resolved_base_lot,
                    'forced_lot_override': bool(forced_lot_override),
                    'needs_review': bool(auto_assigned or forced_lot_override),
                    'exception_overage': bool(exception_overage_applied),
                    'unchecked_before': unchecked if exception_overage_applied else None
                },
                dedupe=True
            )
        except Exception:
            pass

        return jsonify({
            'success': True, 
            'suffixed_upc': suffixed_upc, 
            'base_upc': base_upc,
            'lot_number': selected_lot,
            'requested_lot': requested_lot_norm,
            'auto_assigned': bool(auto_assigned),
            'auto_assign_reason': auto_assign_reason,
            'forced_lot_override': bool(forced_lot_override),
            'continued_without_lot': bool(allow_no_lot),
            'unchecked_qty': new_unchecked,
            'bad_qty': new_bad,
            'exception_overage': bool(exception_overage_applied),
            'items_to_list_url': _items_prep_items_to_list_url(base_upc, selected_lot)
        })
        
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            if conn:
                conn.close()
        except Exception:
            pass

@app.route('/api/items_prep/create_return_entry', methods=['POST'])
def api_items_prep_create_return_entry():
    """Create a suffixed entry for return flow.
    Similar to bad flow but tracks status as 'return'.
    JSON: { upc, qty }
    Returns: { success, suffixed_upc }
    """
    conn = None
    try:
        data = request.get_json() or {}
        upc = _strip_leading_zeros_numeric(_normalize_upc(data.get('upc')))
        exception_note = (data.get('exception_note') or '').strip()
        try:
            qty = int(data.get('qty', 1))
        except Exception:
            return jsonify({'success': False, 'error': 'Invalid qty'}), 400
        if qty < 1:
            return jsonify({'success': False, 'error': 'qty must be at least 1'}), 400
        
        if not upc:
            return jsonify({'success': False, 'error': 'Missing upc'}), 400
        
        # Strip leading zeros
        upc = _normalize_upc_preserve_suffix_for_match(upc)
        
        base_upc = upc.split('-')[0] if '-' in upc else upc
        requested_lot_input = _normalize_lot_number(_preferred_lot_from_request(data))
        requested_lot = ''
        allow_no_lot = True
        force_requested_lot = False
        allow_overage_exception = _coerce_bool(
            data.get('allow_overage_exception') if data.get('allow_overage_exception') is not None else data.get('force_exception')
        )
        exception_overage_applied = False
        
        conn = sqlite3.connect('bol.db', isolation_level='IMMEDIATE')
        cur = conn.cursor()
        _ensure_items_prep_tables()
        requested_lot_norm = ''
        selected_lot = ''
        
        # Find next available suffix for return items
        suffix_num = 1
        while True:
            suffixed_upc = f"{base_upc}-{suffix_num}"
            
            # Check if exists in bol_items
            cur.execute('SELECT upc FROM bol_items WHERE upc = ? COLLATE NOCASE', (suffixed_upc,))
            if cur.fetchone():
                suffix_num += 1
                continue
            
            # Also check prep tables
            cur.execute('SELECT upc FROM items_prep_status WHERE upc = ? COLLATE NOCASE LIMIT 1', (suffixed_upc,))
            if cur.fetchone():
                suffix_num += 1
                continue
            
            cur.execute('SELECT upc FROM items_prep_images WHERE upc = ? COLLATE NOCASE LIMIT 1', (suffixed_upc,))
            if cur.fetchone():
                suffix_num += 1
                continue
            try:
                cur.execute('SELECT upc FROM items_prep_notes WHERE upc = ? COLLATE NOCASE LIMIT 1', (suffixed_upc,))
                if cur.fetchone():
                    suffix_num += 1
                    continue
            except Exception:
                pass
            
            # Suffix is available
            break
        
        # Return rows stay lotless; use the latest base UPC row without lot matching.
        cur.execute('''
            SELECT id, item_description, image_url, lot_number, bol_number, unchecked_qty, bad_qty, original_qty, good_qty
            FROM bol_items
            WHERE upc = ? COLLATE NOCASE
            ORDER BY import_date DESC, id DESC
            LIMIT 1
        ''', (base_upc,))
        base_item = cur.fetchone()
        
        if not base_item:
            return jsonify({'success': False, 'error': f'Base UPC {base_upc} not found in bol_items'}), 404

        resolved_base_lot = _normalize_lot_number(base_item[3])
        selected_lot = ''
        requested_lot_norm = ''
        auto_assigned = False
        forced_lot_override = False
        auto_assign_reason = ''

        base_row_id = int(base_item[0])
        unchecked = base_item[5]
        current_bad = int(base_item[6] or 0)
        original_qty = int(base_item[7] or 0)
        current_good = int(base_item[8] or 0)
        if unchecked is None:
            unchecked = max(0, original_qty - current_good - current_bad)
        else:
            unchecked = int(unchecked or 0)
        if qty > unchecked:
            exception_overage_applied = True
            if allow_overage_exception:
                print(
                    f'[RETURN][EXCEPTION] Allowing overage return-entry for {base_upc}: '
                    f'requested={qty}, unchecked={unchecked}'
                )
            else:
                print(
                    f'[RETURN][EXCEPTION][AUTO] Unchecked gate bypassed for {base_upc}: '
                    f'requested={qty}, unchecked={unchecked}'
                )
        
        # Create suffixed entry in bol_items as a permanent RETURN row.
        import datetime
        import_date = datetime.datetime.now(datetime.UTC).isoformat()
        
        cur.execute('''
            INSERT INTO bol_items (
                upc, item_description, image_url, lot_number, bol_number, import_date, 
                temporary, original_qty, unchecked_qty, good_qty, bad_qty, quantity
            )
            VALUES (?, ?, ?, ?, ?, ?, 0, ?, 0, ?, 0, ?)
        ''', (suffixed_upc, base_item[1], base_item[2], selected_lot, base_item[4], import_date, 
              qty, qty, qty))  # original_qty=qty, good_qty=qty, quantity=qty for this suffixed entry
        
        # Seed prep status so return rows are visible and can be finalized in diagnostic.
        ts = datetime.datetime.now(datetime.UTC).isoformat()
        cur.execute('''
            INSERT INTO items_prep_status (upc, lot_number, status, reason, note, updated_at, quantity)
            VALUES (?, ?, ?, ?, ?, ?, ?)
        ''', (suffixed_upc, _normalize_lot_number(selected_lot), 'return', 'return', '', ts, qty))

        # Return flow consumes unchecked units from the base row.
        new_unchecked = max(0, unchecked - qty)
        cur.execute('''
            UPDATE bol_items
            SET unchecked_qty = ?
            WHERE id = ?
        ''', (new_unchecked, base_row_id))

        if exception_overage_applied:
            _items_prep_record_exception(
                cur,
                upc=suffixed_upc,
                base_upc=base_upc,
                lot_number=selected_lot,
                action='return_overage_override',
                quantity=qty,
                unchecked_remaining=unchecked,
                source='item-prep',
                note=exception_note or 'Return entry created as exception after unchecked quantity was exhausted.',
                meta={
                    'status': 'return',
                    'requested_qty': qty,
                    'unchecked_before': unchecked,
                    'allow_overage_exception': True,
                    'requested_lot': '',
                    'assigned_lot': selected_lot,
                    'forced_lot_override': False,
                    'source_lot': resolved_base_lot,
                    'ignored_requested_lot': requested_lot_input
                }
            )
        
        conn.commit()
        
        print(
            f'[RETURN] Created return entry {suffixed_upc}: '
            f'consumed {qty} unchecked from {base_upc} '
            f'(unchecked {unchecked}->{new_unchecked})'
        )
        

        # Update data version for cache invalidation
        update_data_version()

        # Prep log (preplog.db)
        try:
            _preplog_add_entry(
                upc=suffixed_upc,
                base_upc=base_upc,
                status='return',
                quantity=qty,
                note=None,
                reason='return',
                source='item-prep',
                meta={
                    'action': 'create_return_entry',
                    'requested_lot': '',
                    'lot_number': selected_lot,
                    'assigned_lot': selected_lot,
                    'auto_assigned': False,
                    'auto_assign_reason': auto_assign_reason,
                    'continued_without_lot': True,
                    'source_lot': resolved_base_lot,
                    'forced_lot_override': False,
                    'needs_review': False,
                    'exception_overage': bool(exception_overage_applied),
                    'unchecked_before': unchecked if exception_overage_applied else None,
                    'ignored_requested_lot': requested_lot_input
                },
                dedupe=True
            )
        except Exception:
            pass

        return jsonify({
            'success': True, 
            'suffixed_upc': suffixed_upc, 
            'base_upc': base_upc,
            'lot_number': selected_lot,
            'requested_lot': requested_lot_norm,
            'auto_assigned': False,
            'auto_assign_reason': auto_assign_reason,
            'forced_lot_override': False,
            'continued_without_lot': True,
            'unchecked_qty': new_unchecked,
            'exception_overage': bool(exception_overage_applied),
            'items_to_list_url': _items_prep_items_to_list_url(base_upc, '')
        })
        
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            if conn:
                conn.close()
        except Exception:
            pass

@app.route('/api/items_prep/cleanup_temp', methods=['POST'])
def api_items_prep_cleanup_temp():
    """Delete temporary entries when user skips. JSON: { upc }"""
    conn = None
    try:
        data = request.get_json() or {}
        upc = _normalize_upc(data.get('upc'))
        if not upc:
            return jsonify({'success': False, 'error': 'Missing upc'}), 400
        
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        # Delete temporary entries with this UPC
        cur.execute('DELETE FROM bol_items WHERE upc = ? COLLATE NOCASE AND temporary = 1', (upc,))
        deleted = cur.rowcount
        if deleted:
            # Keep prep status in sync when a temporary BAD entry is abandoned.
            cur.execute('DELETE FROM items_prep_status WHERE upc = ? COLLATE NOCASE', (upc,))
        conn.commit()
        return jsonify({'success': True, 'deleted': deleted})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/bol_items/quantity', methods=['POST'])
def api_bol_items_update_quantity():
    """Update quantity for a BOL item. JSON: { id?, upc?, lot_number?, quantity }"""
    conn = None
    try:
        data = request.get_json() or {}
        upc = _normalize_upc(data.get('upc'))
        quantity = data.get('quantity')
        lot_number = _normalize_lot_number(_preferred_lot_from_request(data))
        item_id = data.get('id')
        source = _normalize_listing_source(data.get('source'), default='user')
        if quantity is None:
            return jsonify({'success': False, 'error': 'Missing quantity'}), 400
        if item_id is not None and str(item_id).strip() != '':
            try:
                item_id = int(item_id)
            except Exception:
                return jsonify({'success': False, 'error': 'Invalid id'}), 400
            if item_id <= 0:
                return jsonify({'success': False, 'error': 'Invalid id'}), 400
        else:
            item_id = None
        
        try:
            quantity = int(quantity)
        except (ValueError, TypeError):
            return jsonify({'success': False, 'error': 'Invalid quantity'}), 400
        if quantity < 0:
            return jsonify({'success': False, 'error': 'Quantity must be 0 or greater'}), 400
        
        conn = sqlite3.connect('bol.db', isolation_level='IMMEDIATE')
        cur = conn.cursor()
        target_upc = upc
        target_lot = lot_number

        target_id = None
        if item_id is not None:
            cur.execute('''
                SELECT id, upc, lot_number
                FROM bol_items
                WHERE id = ?
                LIMIT 1
            ''', (item_id,))
            item_row = cur.fetchone()
            if not item_row:
                return jsonify({'success': False, 'error': f'Item id {item_id} not found'}), 404
            target_id = int(item_row[0])
            row_upc = _normalize_upc(item_row[1])
            row_lot = _normalize_lot_number(item_row[2])
            if upc and row_upc and row_upc.lower() != upc.lower():
                return jsonify({'success': False, 'error': 'Provided upc does not match item id'}), 400
            if target_lot and row_lot and target_lot.lower() != row_lot.lower():
                return jsonify({'success': False, 'error': 'Provided lot_number does not match item id'}), 400
            target_upc = row_upc
            target_lot = row_lot

        if not target_upc:
            return jsonify({'success': False, 'error': 'Missing upc or id'}), 400

        is_suffixed = ('-' in str(target_upc) and str(target_upc).rsplit('-', 1)[-1].isdigit())

        if item_id is None:
            if target_lot:
                cur.execute('''
                    SELECT COUNT(*)
                    FROM bol_items
                    WHERE upc = ? COLLATE NOCASE
                      AND lot_number = ? COLLATE NOCASE
                ''', (target_upc, target_lot))
                same_lot_rows = int((cur.fetchone() or [0])[0] or 0)
                if same_lot_rows > 1:
                    return jsonify({
                        'success': False,
                        'error': 'Multiple rows found for this UPC+LOT. Please update quantity from the latest Items-to-List page so row id is included.'
                    }), 400
            cur.execute('''
                SELECT COUNT(*), COUNT(DISTINCT COALESCE(lot_number, ''))
                FROM bol_items
                WHERE upc = ? COLLATE NOCASE
            ''', (target_upc,))
            row_total, lot_variants = cur.fetchone() or (0, 0)
            row_total = int(row_total or 0)
            lot_variants = int(lot_variants or 0)

            if not target_lot and row_total > 1:
                if not is_suffixed and lot_variants > 1:
                    return jsonify({
                        'success': False,
                        'error': 'Multiple LOT rows found for this UPC. Please specify a lot_number for quantity edits.'
                    }), 400
                return jsonify({
                    'success': False,
                    'error': 'Multiple rows found for this UPC. Please update quantity from the latest Items-to-List page so row id is included.'
                }), 400

            if target_lot:
                target_row = _select_canonical_bol_row(
                    cur,
                    target_upc,
                    target_lot,
                    columns='id, upc, lot_number',
                    strict_lot=True
                )
                if not target_row:
                    return jsonify({'success': False, 'error': f'Item {target_upc} not found in lot {target_lot}'}), 404
            else:
                target_row = _select_canonical_bol_row(
                    cur,
                    target_upc,
                    '',
                    columns='id, upc, lot_number'
                )
                if not target_row:
                    return jsonify({'success': False, 'error': f'Item {target_upc} not found'}), 404

            target_id = int(target_row[0])
            target_upc = _normalize_upc(target_row[1]) or target_upc
            target_lot = _normalize_lot_number(target_row[2]) or target_lot

        if target_id is None:
            return jsonify({'success': False, 'error': 'Missing target row id'}), 400

        # Check if new quantity columns exist
        cur.execute('PRAGMA table_info(bol_items)')
        cols = [col[1].lower() for col in cur.fetchall()]
        has_new_cols = 'original_qty' in cols and 'unchecked_qty' in cols
        has_good_bad_cols = 'good_qty' in cols and 'bad_qty' in cols

        if has_new_cols and has_good_bad_cols:
            cur.execute('''
                SELECT
                    COALESCE(quantity, 0),
                    COALESCE(original_qty, 0),
                    COALESCE(good_qty, 0),
                    COALESCE(bad_qty, 0),
                    COALESCE(unchecked_qty, 0)
                FROM bol_items
                WHERE id = ?
                LIMIT 1
            ''', (target_id,))
        elif has_good_bad_cols:
            cur.execute('''
                SELECT
                    COALESCE(quantity, 0),
                    COALESCE(quantity, 0),
                    COALESCE(good_qty, 0),
                    COALESCE(bad_qty, 0),
                    0
                FROM bol_items
                WHERE id = ?
                LIMIT 1
            ''', (target_id,))
        else:
            cur.execute('''
                SELECT
                    COALESCE(quantity, 0),
                    COALESCE(quantity, 0),
                    0,
                    0,
                    0
                FROM bol_items
                WHERE id = ?
                LIMIT 1
            ''', (target_id,))
        qty_before_row = cur.fetchone() or (0, 0, 0, 0, 0)
        old_qty = int(qty_before_row[0] or 0)
        old_original_qty = int(qty_before_row[1] or 0)
        old_good_qty = int(qty_before_row[2] or 0)
        old_bad_qty = int(qty_before_row[3] or 0)
        old_unchecked_qty = int(qty_before_row[4] or 0)
        
        if has_new_cols:
            # Update both quantity and unchecked_qty (manual edits adjust unchecked bucket).
            cur.execute('''
                UPDATE bol_items
                SET quantity = ?,
                    original_qty = ?,
                    unchecked_qty = MAX(0, ? - COALESCE(good_qty, 0) - COALESCE(bad_qty, 0))
                WHERE id = ?
            ''', (quantity, quantity, quantity, target_id))
        else:
            # Old behavior
            cur.execute('UPDATE bol_items SET quantity = ? WHERE id = ?', (quantity, target_id))

        if cur.rowcount == 0:
            if target_lot:
                return jsonify({'success': False, 'error': f'Item {target_upc} not found in lot {target_lot}'}), 404
            return jsonify({'success': False, 'error': f'Item {target_upc} not found'}), 404
        
        # Also update items_prep_status.quantity if the item has been prepped (status exists)
        _ensure_items_prep_tables()
        prep_row = _select_prep_status_row(cur, target_upc, target_lot, columns='status')
        if prep_row:
            status_update_lot = _resolve_prep_status_lot(cur, target_upc, target_lot)
            # Item has prep status, update its prep quantity too
            cur.execute('''
                UPDATE items_prep_status
                SET quantity = ?
                WHERE upc = ? COLLATE NOCASE
                  AND COALESCE(lot_number, '') = ? COLLATE NOCASE
            ''', (quantity, target_upc, status_update_lot))

        new_original_qty = quantity if has_new_cols else old_original_qty
        new_unchecked_qty = max(0, quantity - old_good_qty - old_bad_qty) if has_new_cols else old_unchecked_qty
        quantity_changes = {}
        if old_qty != quantity:
            quantity_changes['quantity'] = {'from': old_qty, 'to': quantity}
        if has_new_cols and old_original_qty != new_original_qty:
            quantity_changes['original_qty'] = {'from': old_original_qty, 'to': new_original_qty}
        if has_new_cols and old_unchecked_qty != new_unchecked_qty:
            quantity_changes['unchecked_qty'] = {'from': old_unchecked_qty, 'to': new_unchecked_qty}
        
        conn.commit()
        try:
            update_data_version()
        except Exception:
            pass

        if quantity_changes:
            try:
                _listinglog_add_entry(
                    upc=target_upc,
                    platform='item_manager',
                    action='quantity_update',
                    source=source,
                    quantity=quantity,
                    success=True,
                    meta={
                        'item_id': target_id,
                        'lot_number': target_lot,
                        'changes': quantity_changes,
                        'via': 'api_bol_items_update_quantity'
                    }
                )
            except Exception:
                pass
        return jsonify({'success': True, 'upc': target_upc, 'lot_number': target_lot, 'id': target_id})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/items_prep/status/<upc>', methods=['DELETE'])
def api_items_prep_status_delete(upc):
    """Delete preparation status for a UPC (for undo functionality).
    If UPC has a suffix (e.g., 110101-1), also delete the suffixed entry from bol_items.
    """
    conn = None
    try:
        upc_norm = _normalize_upc(upc)
        # Strip leading zeros to match item manager behavior (but preserve suffixes like -1)
        upc = _normalize_upc_preserve_suffix_for_match(upc_norm)
        if not upc:
            return jsonify({'success': False, 'error': 'Missing upc'}), 400
        lot_number = _preferred_lot_from_request()
        
        _ensure_items_prep_tables()
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        
        # Delete from items_prep_status for the relevant lot
        if lot_number:
            cur.execute('''
                DELETE FROM items_prep_status
                WHERE upc = ? COLLATE NOCASE
                  AND COALESCE(lot_number, '') = ? COLLATE NOCASE
            ''', (upc, _normalize_lot_number(lot_number)))
            if cur.rowcount == 0:
                cur.execute('''
                    DELETE FROM items_prep_status
                    WHERE upc = ? COLLATE NOCASE
                      AND COALESCE(lot_number, '') = ''
                ''', (upc,))
        else:
            cur.execute('DELETE FROM items_prep_status WHERE upc = ? COLLATE NOCASE', (upc,))
        
        # If this is a suffixed UPC (e.g., 110101-1), delete it from bol_items too
        if '-' in upc and upc.split('-')[-1].isdigit():
            print(f'Deleting suffixed entry {upc} from bol_items')
            if lot_number:
                cur.execute('DELETE FROM bol_items WHERE upc = ? COLLATE NOCASE AND lot_number = ? COLLATE NOCASE', (upc, lot_number))
                if cur.rowcount == 0:
                    cur.execute('DELETE FROM bol_items WHERE upc = ? COLLATE NOCASE', (upc,))
            else:
                cur.execute('DELETE FROM bol_items WHERE upc = ? COLLATE NOCASE', (upc,))
        
        conn.commit()
        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

def _items_prep_undo_core(*, upc, status, qty=1, base_upc=None, lot_number=None, action=None):
    """Shared undo logic for Item Prep actions.

    Returns: (ok: bool, error: str|None, http_status: int)
    """
    try:
        upc = (upc or '').strip()
        status = (status or '').strip().lower()
        action = (action or '').strip().lower()
        base_upc = (base_upc or '').strip() or None
        lot_number = _normalize_lot_number(lot_number)

        if not upc or status not in ('good', 'bad', 'return'):
            return False, 'Missing upc or invalid status', 400

        try:
            qty = int(qty or 1)
        except Exception:
            qty = 1
        if qty < 1:
            qty = 1

        upc = _normalize_upc_preserve_suffix_for_match(_normalize_upc(upc))
        if base_upc:
            base_upc = _strip_leading_zeros_numeric(_normalize_upc(base_upc))
        elif '-' in upc and upc.rsplit('-', 1)[-1].isdigit():
            base_upc = upc.split('-', 1)[0]

        _ensure_items_prep_tables()
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        try:
            if not lot_number and _has_multiple_lot_rows(cur, upc):
                return False, (
                    f'Cannot undo {upc} without LOT context. '
                    'This UPC exists in multiple LOTs.'
                ), 400

            def _pick_bol_row(target_upc, cols):
                if lot_number:
                    cur.execute(f'''
                        SELECT {cols}
                        FROM bol_items
                        WHERE upc = ? COLLATE NOCASE
                          AND lot_number = ? COLLATE NOCASE
                        ORDER BY import_date DESC, id DESC
                        LIMIT 1
                    ''', (target_upc, lot_number))
                    row = cur.fetchone()
                    if row:
                        return row
                    cur.execute(f'''
                        SELECT {cols}
                        FROM bol_items
                        WHERE upc = ? COLLATE NOCASE
                          AND COALESCE(lot_number, '') = ''
                        ORDER BY import_date DESC, id DESC
                        LIMIT 1
                    ''', (target_upc,))
                    row = cur.fetchone()
                    if row:
                        return row
                    # When lot context is provided, do not mutate a different lot row.
                    return None
                cur.execute(f'''
                    SELECT {cols}
                    FROM bol_items
                    WHERE upc = ? COLLATE NOCASE
                    ORDER BY import_date DESC, id DESC
                    LIMIT 1
                ''', (target_upc,))
                return cur.fetchone()

            if status == 'good':
                is_suffixed = ('-' in upc and upc.rsplit('-', 1)[-1].isdigit())
                if is_suffixed and action in ('saved_good_suffixed', 'special_good_suffixed', 'good_suffixed'):
                    row = _pick_bol_row(upc, 'id, lot_number, good_qty, unchecked_qty, quantity')
                    if not row:
                        return False, f'UPC {upc} not found', 404

                    bol_id = row[0]
                    row_lot = _normalize_lot_number(row[1])
                    current_good = int(row[2] or 0)
                    current_unchecked = int(row[3] or 0)
                    row_qty = int(row[4] or 0)
                    if current_good <= 0:
                        current_good = row_qty

                    if qty > current_good:
                        return False, f'Cannot undo {qty} - only {current_good} marked as good', 400

                    undo_qty = qty
                    cur.execute('DELETE FROM bol_items WHERE id = ?', (bol_id,))
                    cur.execute('''
                        DELETE FROM items_prep_status
                        WHERE upc = ? COLLATE NOCASE
                          AND (
                            COALESCE(lot_number, '') = ? COLLATE NOCASE
                            OR (? <> '' AND COALESCE(lot_number, '') = '')
                          )
                    ''', (upc, row_lot, row_lot))
                    cur.execute('DELETE FROM items_prep_images WHERE upc = ? COLLATE NOCASE', (upc,))
                    try:
                        cur.execute('DELETE FROM items_prep_notes WHERE upc = ? COLLATE NOCASE', (upc,))
                    except Exception:
                        pass

                    base_key = (base_upc or '').strip() or upc.split('-', 1)[0]
                    if row_lot:
                        cur.execute('''
                            SELECT id, good_qty, unchecked_qty
                            FROM bol_items
                            WHERE upc = ? COLLATE NOCASE
                              AND lot_number = ? COLLATE NOCASE
                            ORDER BY import_date DESC, id DESC
                            LIMIT 1
                        ''', (base_key, row_lot))
                        base_row = cur.fetchone()
                    else:
                        cur.execute('''
                            SELECT id, good_qty, unchecked_qty
                            FROM bol_items
                            WHERE upc = ? COLLATE NOCASE
                            ORDER BY import_date DESC, id DESC
                            LIMIT 1
                        ''', (base_key,))
                        base_row = cur.fetchone()

                    if base_row:
                        base_id = int(base_row[0])
                        base_good = int(base_row[1] or 0)
                        base_unchecked = int(base_row[2] or 0)
                        new_base_good = max(0, base_good - undo_qty)
                        new_base_unchecked = base_unchecked + undo_qty
                        cur.execute('''
                            UPDATE bol_items
                            SET good_qty = ?, unchecked_qty = ?
                            WHERE id = ?
                        ''', (new_base_good, new_base_unchecked, base_id))
                        print(
                            f'[UNDO GOOD SUFFIX] Deleted {upc} (lot={row_lot}); '
                            f'base {base_key}: good {base_good}->{new_base_good}, '
                            f'unchecked {base_unchecked}->{new_base_unchecked}'
                        )
                    else:
                        print(f'[UNDO GOOD SUFFIX] Warning: base UPC {base_key} not found to restore quantity')
                else:
                    row = _pick_bol_row(upc, 'id, lot_number, good_qty, unchecked_qty')
                    if not row:
                        return False, f'UPC {upc} not found', 404

                    bol_id = row[0]
                    row_lot = _normalize_lot_number(row[1])
                    current_good = row[2] or 0
                    current_unchecked = row[3] or 0

                    if qty > current_good:
                        return False, f'Cannot undo {qty} - only {current_good} marked as good', 400

                    new_good = current_good - qty
                    new_unchecked = current_unchecked + qty

                    cur.execute('''
                        UPDATE bol_items
                        SET good_qty = ?, unchecked_qty = ?
                        WHERE id = ?
                    ''', (new_good, new_unchecked, bol_id))

                    if new_good > 0:
                        cur.execute('''
                            UPDATE items_prep_status
                            SET quantity = ?
                            WHERE upc = ? COLLATE NOCASE
                              AND COALESCE(lot_number, '') = ? COLLATE NOCASE
                        ''', (new_good, upc, row_lot))
                        if cur.rowcount == 0 and row_lot:
                            cur.execute('''
                                UPDATE items_prep_status
                                SET quantity = ?
                                WHERE upc = ? COLLATE NOCASE
                                  AND COALESCE(lot_number, '') = ''
                            ''', (new_good, upc))
                    else:
                        cur.execute('''
                            DELETE FROM items_prep_status
                            WHERE upc = ? COLLATE NOCASE
                              AND (
                                COALESCE(lot_number, '') = ? COLLATE NOCASE
                                OR (? <> '' AND COALESCE(lot_number, '') = '')
                              )
                        ''', (upc, row_lot, row_lot))

                    print(f'[UNDO GOOD] {upc} (lot={row_lot}): moved {qty} from good to unchecked (good: {current_good}→{new_good}, unchecked: {current_unchecked}→{new_unchecked})')

            elif status == 'bad':
                row = _pick_bol_row(upc, 'id, lot_number, quantity, temporary')
                if not row:
                    return False, f'UPC {upc} not found', 404

                bol_id = row[0]
                row_lot = _normalize_lot_number(row[1])
                bad_qty_for_this_entry = row[2] if row[2] else 1
                temporary = row[3]

                cur.execute('DELETE FROM bol_items WHERE id = ?', (bol_id,))
                cur.execute('''
                    DELETE FROM items_prep_status
                    WHERE upc = ? COLLATE NOCASE
                      AND (
                        COALESCE(lot_number, '') = ? COLLATE NOCASE
                        OR (? <> '' AND COALESCE(lot_number, '') = '')
                      )
                ''', (upc, row_lot, row_lot))

                if temporary == 0:
                    cur.execute('DELETE FROM items_prep_images WHERE upc = ? COLLATE NOCASE', (upc,))
                    try:
                        cur.execute('DELETE FROM items_prep_notes WHERE upc = ? COLLATE NOCASE', (upc,))
                    except Exception:
                        pass

                if base_upc:
                    base_lot = _normalize_lot_number(row_lot or lot_number)
                    if base_lot:
                        cur.execute('''
                            SELECT id, bad_qty, unchecked_qty
                            FROM bol_items
                            WHERE upc = ? COLLATE NOCASE
                              AND lot_number = ? COLLATE NOCASE
                            ORDER BY import_date DESC, id DESC
                            LIMIT 1
                        ''', (base_upc, base_lot))
                        base_row = cur.fetchone()
                    else:
                        cur.execute('''
                            SELECT id, bad_qty, unchecked_qty
                            FROM bol_items
                            WHERE upc = ? COLLATE NOCASE
                            ORDER BY import_date DESC, id DESC
                            LIMIT 1
                        ''', (base_upc,))
                        base_row = cur.fetchone()

                    if base_row:
                        base_id = base_row[0]
                        current_bad = base_row[1] or 0
                        current_unchecked = base_row[2] or 0
                        new_bad = max(0, current_bad - bad_qty_for_this_entry)
                        new_unchecked = current_unchecked + bad_qty_for_this_entry
                        cur.execute('''
                            UPDATE bol_items
                            SET bad_qty = ?, unchecked_qty = ?
                            WHERE id = ?
                        ''', (new_bad, new_unchecked, base_id))
                        print(f'[UNDO BAD] Deleted {upc}, {base_upc} (lot={base_lot}): moved {bad_qty_for_this_entry} from bad to unchecked (bad: {current_bad}→{new_bad}, unchecked: {current_unchecked}→{new_unchecked})')
                else:
                    print(f'[UNDO BAD] Warning: No base_upc provided for {upc}, could not restore qty')

            elif status == 'return':
                row = _pick_bol_row(upc, 'id, lot_number, temporary, quantity, good_qty, original_qty')
                if not row:
                    return False, f'UPC {upc} not found', 404

                bol_id = row[0]
                row_lot = _normalize_lot_number(row[1])
                temporary = row[2]
                entry_qty = int(row[3] or 0)
                if entry_qty <= 0:
                    entry_qty = int(row[4] or 0)
                if entry_qty <= 0:
                    entry_qty = int(row[5] or 0)
                if entry_qty <= 0:
                    entry_qty = int(qty or 1)
                if entry_qty < 1:
                    entry_qty = 1
                cur.execute('DELETE FROM bol_items WHERE id = ?', (bol_id,))
                cur.execute('''
                    DELETE FROM items_prep_status
                    WHERE upc = ? COLLATE NOCASE
                      AND (
                        COALESCE(lot_number, '') = ? COLLATE NOCASE
                        OR (? <> '' AND COALESCE(lot_number, '') = '')
                      )
                ''', (upc, row_lot, row_lot))
                if temporary == 0:
                    cur.execute('DELETE FROM items_prep_images WHERE upc = ? COLLATE NOCASE', (upc,))
                    try:
                        cur.execute('DELETE FROM items_prep_notes WHERE upc = ? COLLATE NOCASE', (upc,))
                    except Exception:
                        pass

                if base_upc:
                    base_lot = _normalize_lot_number(row_lot or lot_number)
                    if base_lot:
                        cur.execute('''
                            SELECT id, unchecked_qty, original_qty, good_qty, bad_qty
                            FROM bol_items
                            WHERE upc = ? COLLATE NOCASE
                              AND lot_number = ? COLLATE NOCASE
                            ORDER BY import_date DESC, id DESC
                            LIMIT 1
                        ''', (base_upc, base_lot))
                        base_row = cur.fetchone()
                    else:
                        cur.execute('''
                            SELECT id, unchecked_qty, original_qty, good_qty, bad_qty
                            FROM bol_items
                            WHERE upc = ? COLLATE NOCASE
                            ORDER BY import_date DESC, id DESC
                            LIMIT 1
                        ''', (base_upc,))
                        base_row = cur.fetchone()

                    if base_row:
                        base_id = int(base_row[0])
                        base_unchecked_raw = base_row[1]
                        if base_unchecked_raw is None:
                            base_original = int(base_row[2] or 0)
                            base_good = int(base_row[3] or 0)
                            base_bad = int(base_row[4] or 0)
                            base_unchecked = max(0, base_original - base_good - base_bad)
                        else:
                            base_unchecked = int(base_unchecked_raw or 0)
                        new_base_unchecked = base_unchecked + entry_qty
                        cur.execute('''
                            UPDATE bol_items
                            SET unchecked_qty = ?
                            WHERE id = ?
                        ''', (new_base_unchecked, base_id))
                        print(
                            f'[UNDO RETURN] Deleted {upc}, restored {entry_qty} unchecked to {base_upc} '
                            f'(lot={base_lot}, unchecked {base_unchecked}->{new_base_unchecked})'
                        )
                    else:
                        print(f'[UNDO RETURN] Warning: base UPC {base_upc} not found to restore unchecked quantity')
                else:
                    print(f'[UNDO RETURN] Warning: No base_upc provided for {upc}, could not restore unchecked qty')

            conn.commit()
            try:
                update_data_version()
            except Exception:
                pass
            return True, None, 200
        except Exception as e:
            try:
                conn.rollback()
            except Exception:
                pass
            return False, _safe_error(e, 'items_prep:undo_core'), 500
        finally:
            conn.close()
    except Exception as e:
        return False, _safe_error(e, 'items_prep:undo_core_outer'), 500

@app.route('/api/items_prep/undo', methods=['POST'])
def api_items_prep_undo():
    """Undo the last item prep action.
    For Good items: Decrement status qty (or delete if qty becomes 0), increment base UPC qty
    For Bad items: Delete suffixed entry from bol_items if temporary=1 (not completed yet)
                   or if temporary=0 (completed), restore base qty and delete suffixed entry
    """
    try:
        data = request.get_json() or {}
        upc = data.get('upc')
        status = data.get('status')
        action = data.get('action')
        base_upc = data.get('base_upc')
        qty = data.get('qty', 1)
        lot_number = _preferred_lot_from_request(data)

        ok, err, code = _items_prep_undo_core(
            upc=upc,
            status=status,
            qty=qty,
            base_upc=base_upc,
            lot_number=lot_number,
            action=action
        )
        if not ok:
            return jsonify({'success': False, 'error': err or 'Undo failed'}), (code or 400)
        return jsonify({'success': True})
        
    except Exception as e:
        print(f'Undo error: {e}')
        return jsonify({'success': False, 'error': _safe_error(e)}), 500


@app.route('/api/items_prep/diagnostic', methods=['POST'])
def api_items_prep_diagnostic():
    """Save diagnostic info and photos for a UPC. form-data: upc, reason, note, files: photos[]"""
    conn_temp = None
    try:
        _ensure_items_prep_tables()
        upc_raw = _normalize_upc(request.form.get('upc'))
        # Strip leading zeros ONLY if it's all digits (preserve suffix like -24)
        upc = _normalize_upc_preserve_suffix_for_match(upc_raw)
        reason = (request.form.get('reason') or '').strip()
        note = (request.form.get('note') or '').strip()
        if not upc:
            return jsonify({'success': False, 'error': 'Missing upc'}), 400

        # DEBUG: Log incoming request details
        print(f'[DEBUG] Diagnostic upload for UPC: {upc_raw} -> {upc}')
        print(f'[DEBUG] Form keys: {list(request.form.keys())}')
        print(f'[DEBUG] Files keys: {list(request.files.keys())}')
        
        # Mark the target diagnostic row as permanent (no qty changes needed here).
        conn_temp = sqlite3.connect('bol.db', isolation_level='IMMEDIATE')
        cur_temp = conn_temp.cursor()
        selected_lot = _preferred_lot_from_request()
        if selected_lot:
            cur_temp.execute('''
                SELECT id, temporary, COALESCE(lot_number, '')
                FROM bol_items
                WHERE upc = ? COLLATE NOCASE
                  AND lot_number = ? COLLATE NOCASE
                ORDER BY import_date DESC, id DESC
                LIMIT 1
            ''', (upc, selected_lot))
            temp_row = cur_temp.fetchone()
        else:
            cur_temp.execute('''
                SELECT id, temporary, COALESCE(lot_number, '')
                FROM bol_items
                WHERE upc = ? COLLATE NOCASE
                ORDER BY import_date DESC, id DESC
                LIMIT 1
            ''', (upc,))
            temp_row = cur_temp.fetchone()

        if temp_row:
            target_id = int(temp_row[0])
            is_temporary = int(temp_row[1] or 0) == 1
            target_lot = _normalize_lot_number(temp_row[2])
            cur_temp.execute('UPDATE bol_items SET temporary = 0 WHERE id = ?', (target_id,))
            conn_temp.commit()
            if is_temporary:
                print(f'[DIAGNOSTIC COMPLETE] Set {upc} (id={target_id}, lot={target_lot or "(none)"}) to permanent')
                print(f'[DIAGNOSTIC COMPLETE] Base qty already decremented on bad entry creation - no further changes needed')

        # save files under static/items_prep
        from werkzeug.utils import secure_filename
        save_dir = os.path.join(app.root_path, 'static', 'items_prep')
        os.makedirs(save_dir, exist_ok=True)
        saved = []
        files = request.files.getlist('photos[]') or request.files.getlist('photos') or ([] if 'photo' not in request.files else [request.files['photo']])
        # optional per-file rotations can be provided as rotations[] in the same form-data (one per file, same order)
        rotations = request.form.getlist('rotations[]') or request.form.getlist('rotations') or []
        print(f'[DEBUG] Files received: {len(files)}')
        print(f'[DEBUG] Rotations received: {len(rotations)}')
        import datetime
        ts = datetime.datetime.now(datetime.UTC).isoformat()
        if files:
            conn_i = sqlite3.connect('bol.db')
            try:
                cur_i = conn_i.cursor()
                for idx, f in enumerate(files):
                    if not f or not getattr(f, 'filename', ''):
                        print(f'[DEBUG] Skipping invalid file at index {idx}')
                        continue
                    fn = secure_filename(f.filename)
                    name, ext = os.path.splitext(fn)
                    unique = f"{_normalize_upc(upc)}_{int(time.time()*1000)}{ext or '.jpg'}"
                    path = os.path.join(save_dir, unique)
                    try:
                        f.save(path)
                        rel = f"items_prep/{unique}"
                        # parse rotation for this file (if provided), default to 0
                        rot = 0
                        try:
                            if idx < len(rotations):
                                rot = int(rotations[idx] or 0)
                        except Exception:
                            rot = 0
                        cur_i.execute('INSERT INTO items_prep_images (upc, image_path, created_at, rotation) VALUES (?,?,?,?)', (upc, rel, ts, rot))
                        saved.append(rel)
                        print(f'[DEBUG] Successfully saved photo {idx+1}: {rel}')
                    except Exception as se:
                        print(f'[DEBUG] Failed to save diagnostic image {idx}:', se)
                conn_i.commit()
            finally:
                conn_i.close()
            print(f'[DEBUG] Total photos saved to database: {len(saved)}')
        # Note: Status is now handled by /api/items_prep/status endpoint which properly handles suffixed UPCs
        # Do not update status here as it would overwrite base barcode status incorrectly

        # Update data version for cache invalidation
        update_data_version()

        return jsonify({'success': True, 'saved': saved})
    except Exception as e:
        try:
            import traceback
            print('Diagnostic upload error:', e)
            traceback.print_exc()
        except Exception:
            pass
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn_temp is not None:
            conn_temp.close()

@app.errorhandler(RequestEntityTooLarge)
def handle_file_too_large(e):
    return jsonify({'success': False, 'error': 'Upload too large. Try fewer photos or enable Low res.'}), 413

@app.route('/api/items_prep/diagnostic/<upc>', methods=['GET'])
def api_items_prep_diagnostic_get(upc):
    conn = None
    try:
        upc_raw = _normalize_upc(upc)
        # Strip leading zeros from numeric base while preserving suffix (e.g. 071..-4 -> 71..-4)
        upc_n = _normalize_upc_preserve_suffix_for_match(upc_raw)
        lot_number = _preferred_lot_from_request()
        row_status = _normalize_prep_row_status(request.args.get('row_status') or request.args.get('status'))
        include_related_arg = request.args.get('include_related')
        include_related = True if include_related_arg is None else _coerce_bool(include_related_arg)
        exact_scope = _coerce_bool(request.args.get('exact_scope'))
        if exact_scope:
            include_related = False
        include_bol_image = _coerce_bool(request.args.get('include_bol_image'))
        try:
            max_images = int(request.args.get('max_images') or 0)
        except Exception:
            max_images = 0
        max_images = max(0, min(max_images, 50))
        print(f'[DEBUG] Getting diagnostic for UPC: {upc} -> {upc_raw} -> {upc_n}')
        _ensure_items_prep_tables()
        conn = sqlite3.connect('bol.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        srow = _select_prep_status_row(cur, upc_n, lot_number, columns='status, reason, note, updated_at, lot_number, quantity')
        image_lookup = 'exact'
        prefer_bol_image = _coerce_bool(request.args.get('prefer_bol_image'))

        # Try exact UPC first, then compatible normalizations used by older codepaths.
        candidate_upcs = []
        for cand in (upc_n, upc_raw, _strip_leading_zeros_numeric(upc_raw), str(upc or '').strip()):
            cand_n = _normalize_upc(cand)
            if cand_n and cand_n not in candidate_upcs:
                candidate_upcs.append(cand_n)

        related_bases = []
        for source in (upc_n, upc_raw, str(upc or '').strip()):
            source = _normalize_upc(source)
            if not source:
                continue
            base = source.split('-', 1)[0] if '-' in source else source
            base = _strip_leading_zeros_numeric(base)
            if base and base not in related_bases:
                related_bases.append(base)

        def _collect_manifest_rows(table_name):
            rows = []
            seen_ids = set()
            try:
                cur.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name = ? LIMIT 1", (table_name,))
                if not cur.fetchone():
                    return rows
            except Exception:
                return rows

            def _append(sql, params):
                try:
                    cur.execute(sql, params)
                    for rr in cur.fetchall():
                        rid = rr['id']
                        if rid in seen_ids:
                            continue
                        seen_ids.add(rid)
                        rows.append(dict(rr))
                except Exception:
                    return

            for cand in candidate_upcs:
                if lot_number:
                    _append(f'''
                        SELECT id, upc, image_url, import_date
                        FROM {table_name}
                        WHERE upc = ? COLLATE NOCASE
                          AND lot_number = ? COLLATE NOCASE
                          AND TRIM(COALESCE(image_url, '')) <> ''
                        ORDER BY import_date DESC, id DESC
                        LIMIT 5
                    ''', (cand, lot_number))
                _append(f'''
                    SELECT id, upc, image_url, import_date
                    FROM {table_name}
                    WHERE upc = ? COLLATE NOCASE
                      AND TRIM(COALESCE(image_url, '')) <> ''
                    ORDER BY import_date DESC, id DESC
                    LIMIT 5
                ''', (cand,))

            if include_related:
                for base in related_bases:
                    safe_base = base.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
                    like_base = f"{safe_base}-%"
                    if lot_number:
                        _append(f'''
                            SELECT id, upc, image_url, import_date
                            FROM {table_name}
                            WHERE (upc = ? COLLATE NOCASE OR upc LIKE ? ESCAPE '\\')
                              AND lot_number = ? COLLATE NOCASE
                              AND TRIM(COALESCE(image_url, '')) <> ''
                            ORDER BY import_date DESC, id DESC
                            LIMIT 10
                        ''', (base, like_base, lot_number))
                    _append(f'''
                        SELECT id, upc, image_url, import_date
                        FROM {table_name}
                        WHERE (upc = ? COLLATE NOCASE OR upc LIKE ? ESCAPE '\\')
                          AND TRIM(COALESCE(image_url, '')) <> ''
                        ORDER BY import_date DESC, id DESC
                        LIMIT 10
                    ''', (base, like_base))

            return rows

        def _rows_to_images(rows, source_label):
            seen_urls = set()
            out = []
            for rr in rows:
                raw_url = str(rr.get('image_url') or '').strip()
                if not raw_url:
                    continue
                key = raw_url.lower()
                if key in seen_urls:
                    continue
                seen_urls.add(key)
                out.append({
                    'id': f"{source_label}-{rr.get('id')}",
                    'image_path': raw_url,
                    'created_at': rr.get('import_date') or '',
                    'rotation': 0,
                    'source': source_label
                })
            return out

        def _collect_manifest_images():
            raw_rows = _collect_manifest_rows('raw_bol_items')
            raw_images = _rows_to_images(raw_rows, 'raw_bol_items')
            if raw_images:
                return raw_images, 'rawbol_image'

            bol_rows = _collect_manifest_rows('bol_items')
            bol_images = _rows_to_images(bol_rows, 'bol_items')
            if bol_images:
                return bol_images, 'bol_image'
            return [], ''

        images = []
        if include_bol_image and prefer_bol_image:
            manifest_images, manifest_lookup = _collect_manifest_images()
            if manifest_images:
                images = manifest_images
                image_lookup = manifest_lookup

        if not images:
            asset_scope_upc, asset_scope_status = _items_to_list_asset_scope(upc_n, row_status)
            for cand in candidate_upcs:
                if exact_scope or row_status or ('-' in asset_scope_upc and cand.lower() == asset_scope_upc.lower()):
                    scope_upc, scope_status = _items_to_list_asset_scope(cand, row_status)
                    cur.execute(
                        "SELECT id, image_path, created_at, rotation, COALESCE(row_status, '') AS row_status FROM items_prep_images "
                        "WHERE upc = ? COLLATE NOCASE "
                        "AND COALESCE(row_status, '') = ? COLLATE NOCASE "
                        "AND (deleted_at IS NULL OR TRIM(COALESCE(deleted_at,'')) = '') "
                        "ORDER BY created_at DESC, id DESC",
                        (scope_upc, scope_status)
                    )
                else:
                    cur.execute(
                        "SELECT id, image_path, created_at, rotation, COALESCE(row_status, '') AS row_status FROM items_prep_images "
                        "WHERE upc = ? COLLATE NOCASE "
                        "AND (deleted_at IS NULL OR TRIM(COALESCE(deleted_at,'')) = '') "
                        "ORDER BY created_at DESC, id DESC",
                        (cand,)
                    )
                rows = [dict(r) for r in cur.fetchall()]
                if rows:
                    images = rows
                    if cand != upc_n:
                        image_lookup = 'variant'
                    break

        # Optional log-mode fallback: if exact/variant not found, include base and suffixed UPC rows.
        if include_related and not images:
            related_rows = []
            for base in related_bases:
                safe_base = base.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
                like_base = f"{safe_base}-%"
                cur.execute(
                    "SELECT id, image_path, created_at, rotation FROM items_prep_images "
                    "WHERE (upc = ? COLLATE NOCASE OR upc LIKE ? ESCAPE '\\') "
                    "AND (deleted_at IS NULL OR TRIM(COALESCE(deleted_at,'')) = '') "
                    "ORDER BY created_at DESC, id DESC",
                    (base, like_base)
                )
                related_rows.extend([dict(r) for r in cur.fetchall()])

            if related_rows:
                # Preserve newest-first ordering and avoid duplicates across multiple base candidates.
                seen = set()
                deduped = []
                for row in related_rows:
                    rid = row.get('id')
                    if rid in seen:
                        continue
                    seen.add(rid)
                    deduped.append(row)
                images = deduped
                image_lookup = 'related'

        # Optional fallback for log/modal usage: if no diagnostic photos exist,
        # surface manifest image_url (raw_bol_items first, then bol_items).
        if include_bol_image and not images:
            manifest_images, manifest_lookup = _collect_manifest_images()
            if manifest_images:
                images = manifest_images
                image_lookup = manifest_lookup

        if max_images > 0 and len(images) > max_images:
            images = images[:max_images]

        print(f'[DEBUG] Found {len(images)} images for UPC {upc_n} (lookup={image_lookup}, include_related={include_related})')
        return jsonify({
            'upc': upc_n,
            'status': dict(srow) if srow else None,
            'images': images,
            'image_lookup': image_lookup
        })
    except Exception as e:
        return jsonify({'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/items_prep/diagnostic/<upc>/live_listings', methods=['GET'])
def api_items_prep_diagnostic_live_listings(upc):
    """Return live marketplace listings (active/listed) for one diagnostic UPC."""
    try:
        upc_raw = _normalize_upc(upc)
        upc_n = _normalize_upc_preserve_suffix_for_match(upc_raw)
        if not upc_n:
            return jsonify({'success': False, 'error': 'Missing UPC'}), 400

        listing_map = _fetch_auto_marketplace_listing_links(
            [upc_n],
            max_lookup_keys=4000,
            max_links_per_platform=80
        ) or {}

        seen = set()
        listings = []
        ebay_count = 0
        amazon_count = 0

        for key in _marketplace_upc_lookup_variants(upc_n):
            bucket = listing_map.get(key) or {}
            for platform in ('ebay', 'amazon'):
                for entry in (bucket.get(platform) or []):
                    listing_id = str(entry.get('listing_id') or '').strip()
                    listing_url = str(entry.get('url') or '').strip()
                    token = f"{platform}|{listing_id.lower()}|{listing_url.lower()}"
                    if token in seen:
                        continue
                    seen.add(token)
                    row = {
                        'platform': platform,
                        'listing_id': listing_id,
                        'title': str(entry.get('title') or '').strip(),
                        'url': listing_url
                    }
                    listings.append(row)
                    if platform == 'ebay':
                        ebay_count += 1
                    elif platform == 'amazon':
                        amazon_count += 1

        listings.sort(
            key=lambda x: (
                0 if (x.get('platform') or '') == 'ebay' else 1,
                (x.get('listing_id') or '').lower(),
                (x.get('url') or '').lower()
            )
        )

        return jsonify({
            'success': True,
            'upc': upc_n,
            'total_count': ebay_count + amazon_count,
            'ebay_count': ebay_count,
            'amazon_count': amazon_count,
            'listings': listings
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'items_prep:live_listings')}), 500

@app.route('/api/items_prep/diagnostic/<upc>/history', methods=['GET'])
def api_items_prep_diagnostic_history(upc):
    """Unified per-item timeline for diagnostic view (item-prep + item-manager changes)."""
    try:
        upc_n = _normalize_upc_preserve_suffix_for_match(_normalize_upc(upc))
        if not upc_n:
            return jsonify({'success': False, 'error': 'Missing upc'}), 400

        base_upc = upc_n.split('-', 1)[0] if '-' in upc_n else upc_n
        requested_lot = _normalize_lot_number(_preferred_lot_from_request())
        requested_row_status = _normalize_prep_row_status(request.args.get('row_status') or request.args.get('status'))
        exact_row_status = '' if '-' in upc_n else requested_row_status
        limit = _listingagent_parse_int(request.args.get('limit'), 200) or 200
        limit = max(1, min(limit, 1000))
        fetch_limit = max(100, min(limit * 4, 4000))

        safe_base = base_upc.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
        like_base = f"{safe_base}-%"
        events = []

        def _parse_dt(raw_ts):
            txt = str(raw_ts or '').strip()
            if not txt:
                return datetime.datetime.min
            try:
                txt = txt.replace(' ', 'T')
                if txt.endswith('Z'):
                    txt = txt[:-1] + '+00:00'
                parsed = datetime.datetime.fromisoformat(txt)
                if parsed.tzinfo is not None:
                    parsed = parsed.astimezone(datetime.timezone.utc).replace(tzinfo=None)
                return parsed
            except Exception:
                return datetime.datetime.min

        def _to_int(raw_value):
            try:
                return int(raw_value) if raw_value is not None else None
            except Exception:
                return None

        target_upc_key = upc_n.lower()

        def _matches_upc(candidate):
            key = _normalize_upc_preserve_suffix_for_match(_normalize_upc(candidate))
            if not key:
                return False
            return key.lower() == target_upc_key

        def _matches_lot(event_lot):
            if not requested_lot:
                return True
            lot_key = _normalize_lot_number(event_lot)
            if not lot_key:
                # Keep older/unscoped records visible even when lot context is active.
                return True
            return lot_key.lower() == requested_lot.lower()

        def _matches_row_status(event_status='', event_row_status=''):
            if not exact_row_status:
                return True
            candidate = _normalize_prep_row_status(event_row_status or event_status)
            return bool(candidate and candidate == exact_row_status)

        def _append_event(payload):
            if not isinstance(payload, dict):
                return
            if not str(payload.get('timestamp') or '').strip():
                return
            events.append(payload)

        prep_rows = []
        try:
            with db_connection('preplog.db') as prep_conn:
                prep_cur = prep_conn.cursor()
                _preplog_init_tables(prep_cur)
                prep_cur.execute('''
                    SELECT *
                    FROM prep_log
                    WHERE (
                        upc = ? COLLATE NOCASE
                        OR upc = ? COLLATE NOCASE
                        OR base_upc = ? COLLATE NOCASE
                        OR upc LIKE ? ESCAPE '\\'
                    )
                    ORDER BY created_at DESC, id DESC
                    LIMIT ?
                ''', (upc_n, base_upc, base_upc, like_base, fetch_limit))
                prep_rows = [_preplog_enrich_row(_listagent_row_to_dict(r)) for r in prep_cur.fetchall()]
        except Exception:
            prep_rows = []

        for row in prep_rows:
            row_upc = row.get('upc')
            if not _matches_upc(row_upc):
                continue
            if not _matches_row_status(row.get('status'), row.get('status')):
                continue

            meta = row.get('meta') if isinstance(row.get('meta'), dict) else _preplog_meta_dict(row)
            event_lot = _normalize_lot_number(
                row.get('lot_number')
                or meta.get('lot_number')
                or meta.get('assigned_lot')
                or meta.get('requested_lot')
            )
            if not _matches_lot(event_lot):
                continue

            status = str(row.get('status') or '').strip().lower()
            action = str(meta.get('action') or '').strip().lower()
            qty = _to_int(row.get('quantity'))
            note = str(row.get('note') or '').strip()
            reason = str(row.get('reason') or '').strip()

            if status == 'good' and action in (
                'saved_good',
                'saved_good_suffixed',
                'converted_to_good',
                'updated_suffixed_good',
                'converted_bad_to_good_kept_suffix',
                'allocate_lots'
            ):
                title = 'Added from item-prep'
            elif status == 'good':
                title = 'Item-prep marked good'
            elif status == 'bad':
                title = 'Item-prep marked bad'
            elif status == 'return':
                title = 'Item-prep marked return'
            elif status == 'unchecked':
                title = 'Item-prep marked unchecked'
            else:
                title = 'Item-prep update'

            desc_bits = []
            if qty is not None:
                desc_bits.append(f'qty {qty}')
            if reason:
                desc_bits.append(f'reason: {reason}')
            if action:
                desc_bits.append(action.replace('_', ' '))

            changes = []
            if status:
                changes.append({'field': 'status', 'to': status})
            if qty is not None:
                changes.append({'field': 'quantity', 'to': qty})
            if reason:
                changes.append({'field': 'reason', 'to': reason})
            if note:
                changes.append({'field': 'note', 'to': note})

            _append_event({
                'id': f"prep-{row.get('id')}",
                '_sort_id': _to_int(row.get('id')) or 0,
                'timestamp': row.get('created_at') or '',
                'category': 'item_prep',
                'title': title,
                'description': '; '.join(desc_bits),
                'upc': row_upc,
                'base_upc': row.get('base_upc') or base_upc,
                'lot_number': event_lot,
                'source': row.get('source') or 'item-prep',
                'changes': changes
            })

        listing_rows = []
        try:
            with db_connection('listinglog.db') as listing_conn:
                listing_cur = listing_conn.cursor()
                _listinglog_init_tables(listing_cur)
                listing_cur.execute('''
                    SELECT *
                    FROM listing_log
                    WHERE (
                        upc = ? COLLATE NOCASE
                        OR upc = ? COLLATE NOCASE
                        OR upc LIKE ? ESCAPE '\\'
                    )
                    ORDER BY created_at DESC, id DESC
                    LIMIT ?
                ''', (upc_n, base_upc, like_base, fetch_limit))
                listing_rows = [_listagent_row_to_dict(r) for r in listing_cur.fetchall()]
        except Exception:
            listing_rows = []

        for row in listing_rows:
            row_upc = row.get('upc')
            if not _matches_upc(row_upc):
                continue

            meta = _listinglog_meta_dict(row)
            meta_row_status = _normalize_prep_row_status(meta.get('row_status') or meta.get('status'))
            if not _matches_row_status('', meta_row_status):
                continue
            event_lot = _normalize_lot_number(
                meta.get('lot_number')
                or meta.get('target_lot')
                or meta.get('lot')
                or meta.get('assigned_lot')
            )
            if not _matches_lot(event_lot):
                continue

            platform = str(row.get('platform') or '').strip().lower()
            action = str(row.get('action') or '').strip().lower()
            source = str(row.get('source') or '').strip()
            source_label = _listing_source_label(source) if source else ''
            qty = _to_int(row.get('quantity'))

            changes = []
            meta_changes = meta.get('changes')
            if isinstance(meta_changes, dict):
                for field, change in meta_changes.items():
                    if isinstance(change, dict):
                        changes.append({
                            'field': str(field),
                            'from': change.get('from'),
                            'to': change.get('to')
                        })
                    else:
                        changes.append({'field': str(field), 'to': change})

            category = 'item_manager'
            if platform in ('amazon', 'ebay', 'facebook'):
                category = 'marketplace'
                platform_label = 'eBay' if platform == 'ebay' else platform.capitalize()
                if action == 'listed':
                    title = f'{platform_label} marked listed'
                elif action == 'unlisted':
                    title = f'{platform_label} marked unlisted'
                else:
                    title = f'{platform_label} listing update'
                if qty is not None and not any(ch.get('field') == 'quantity' for ch in changes):
                    changes.append({'field': 'quantity', 'to': qty})
            elif platform == 'item_manager':
                title_map = {
                    'quantity_update': 'Quantity changed in item-manager',
                    'location_update': 'Location updated in item-manager',
                    'note_add': 'Note added in item-manager',
                    'note_delete': 'Note removed in item-manager',
                    'prep_reset': 'Prep quantities reset in item-manager',
                    'diagnostic_reset': 'Diagnostic reset in item-manager'
                }
                title = title_map.get(action) or 'Item-manager update'
                if action == 'note_add':
                    note_text = str(meta.get('note') or '').strip()
                    if note_text and not any(ch.get('field') == 'note' for ch in changes):
                        changes.append({'field': 'note', 'to': note_text})
                elif action == 'note_delete':
                    note_text = str(meta.get('note') or '').strip()
                    if note_text and not any(ch.get('field') == 'note' for ch in changes):
                        changes.append({'field': 'note', 'from': note_text})
            else:
                category = platform or 'other'
                title = 'Inventory update'

            desc_bits = []
            if action:
                desc_bits.append(action.replace('_', ' '))
            if source_label:
                desc_bits.append(f'by {source_label}')
            if event_lot:
                desc_bits.append(f'LOT {event_lot}')

            _append_event({
                'id': f"log-{row.get('id')}",
                '_sort_id': _to_int(row.get('id')) or 0,
                'timestamp': row.get('created_at') or '',
                'category': category,
                'title': title,
                'description': '; '.join(desc_bits),
                'upc': row_upc,
                'base_upc': base_upc,
                'lot_number': event_lot,
                'source': source or None,
                'changes': changes
            })

        events.sort(
            key=lambda ev: (_parse_dt(ev.get('timestamp')), int(ev.get('_sort_id') or 0)),
            reverse=True
        )

        items = []
        for ev in events[:limit]:
            out = dict(ev)
            out.pop('_sort_id', None)
            items.append(out)

        return jsonify({
            'success': True,
            'upc': upc_n,
            'base_upc': base_upc,
            'lot_number': requested_lot,
            'row_status': exact_row_status,
            'items': items,
            'count': len(items)
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'items_prep:diagnostic_history')}), 500

@app.route('/api/items_prep/diagnostic/<upc>/photos', methods=['DELETE'])
def api_items_prep_diagnostic_delete_photos(upc):
    """Soft-delete all diagnostic photos for a UPC by moving them to trash and setting retention expiry.
    Query param hard=1 to permanently delete files and rows.
    """
    conn = None
    try:
        upc_norm = _normalize_upc(upc)
        upc_n = _normalize_upc_preserve_suffix_for_match(upc_norm)
        row_status = _normalize_prep_row_status(request.args.get('row_status') or request.args.get('status'))
        scope_upc, scope_status = _items_to_list_asset_scope(upc_n, row_status)
        hard = (request.args.get('hard') or '0') in ('1','true','yes')
        _ensure_items_prep_tables()
        conn = sqlite3.connect('bol.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        if hard:
            if row_status or ('-' in scope_upc):
                cur.execute('''
                    SELECT id, image_path, trash_path, deleted_at
                    FROM items_prep_images
                    WHERE upc = ? COLLATE NOCASE
                      AND COALESCE(row_status, '') = ? COLLATE NOCASE
                ''', (scope_upc, scope_status))
            else:
                cur.execute('SELECT id, image_path, trash_path, deleted_at FROM items_prep_images WHERE upc = ? COLLATE NOCASE', (scope_upc,))
            rows = cur.fetchall()
            for r in rows:
                # remove from whichever exists
                for rel in [r['trash_path'], r['image_path']]:
                    if rel:
                        abs_path = os.path.join(app.root_path, 'static', rel) if not os.path.isabs(rel) else rel
                        try:
                            if os.path.isfile(abs_path):
                                os.remove(abs_path)
                        except Exception as fe:
                            print('Failed hard remove photo', abs_path, fe)
            if row_status or ('-' in scope_upc):
                cur.execute('''
                    DELETE FROM items_prep_images
                    WHERE upc = ? COLLATE NOCASE
                      AND COALESCE(row_status, '') = ? COLLATE NOCASE
                ''', (scope_upc, scope_status))
            else:
                cur.execute('DELETE FROM items_prep_images WHERE upc = ? COLLATE NOCASE', (scope_upc,))
            deleted = cur.rowcount
            conn.commit()
            return jsonify({'success': True, 'deleted': deleted, 'hard': True})
        else:
            # Soft delete only active (not already deleted) rows
            if row_status or ('-' in scope_upc):
                cur.execute('''
                    SELECT id, image_path
                    FROM items_prep_images
                    WHERE upc = ? COLLATE NOCASE
                      AND COALESCE(row_status, '') = ? COLLATE NOCASE
                      AND (deleted_at IS NULL OR TRIM(COALESCE(deleted_at,'')) = '')
                ''', (scope_upc, scope_status))
            else:
                cur.execute(
                    "SELECT id, image_path FROM items_prep_images WHERE upc = ? COLLATE NOCASE AND (deleted_at IS NULL OR TRIM(COALESCE(deleted_at,'')) = '')",
                    (scope_upc,)
                )
            rows = cur.fetchall()
            deleted = 0
            for r in rows:
                rel = r['image_path']
                if not rel:
                    continue
                abs_path = os.path.join(app.root_path, 'static', rel) if not os.path.isabs(rel) else rel
                new_rel = None
                if os.path.isfile(abs_path):
                    new_rel = _move_to_trash(abs_path, scope_upc)
                # mark as deleted with expiry
                del_at = _now_iso()
                import datetime as _dt
                exp = ( _dt.datetime.now(_dt.UTC) + _dt.timedelta(days=_trash_retention_days()) ).isoformat()
                cur.execute('UPDATE items_prep_images SET deleted_at=?, expires_at=?, trash_path=? WHERE id=?', (del_at, exp, new_rel or rel, r['id']))
                deleted += 1
            conn.commit()
            return jsonify({'success': True, 'deleted': deleted, 'hard': False, 'retention_days': _trash_retention_days()})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()


@app.route('/api/items_prep/diagnostic/<upc>/photos', methods=['POST'])
def api_items_prep_diagnostic_add_photos(upc):
    """Upload additional diagnostic photos for a UPC without changing status.
    Expects multipart/form-data with files in photos[] (or photos/photo) and optional rotations[]
    Returns: { success, images: [{id, image_path, created_at, rotation}] }
    """
    conn = None
    try:
        upc_norm = _normalize_upc(upc)
        upc_n = _normalize_upc_preserve_suffix_for_match(upc_norm)
        row_status = _normalize_prep_row_status(request.form.get('row_status') or request.form.get('status') or request.args.get('row_status') or request.args.get('status'))
        scope_upc, scope_status = _items_to_list_asset_scope(upc_n, row_status)
        if not scope_upc:
            return jsonify({'success': False, 'error': 'Missing upc'}), 400
        _ensure_items_prep_tables()
        from werkzeug.utils import secure_filename
        save_dir = os.path.join(app.root_path, 'static', 'items_prep')
        os.makedirs(save_dir, exist_ok=True)
        files = request.files.getlist('photos[]') or request.files.getlist('photos') or ([] if 'photo' not in request.files else [request.files['photo']])
        rotations = request.form.getlist('rotations[]') or request.form.getlist('rotations') or []
        if not files:
            return jsonify({'success': False, 'error': 'No files uploaded'}), 400
        import datetime
        ts = datetime.datetime.now(datetime.UTC).isoformat()
        conn = sqlite3.connect('bol.db')
        cur = conn.cursor()
        out = []
        for idx, f in enumerate(files):
            if not f or not getattr(f, 'filename', ''):
                continue
            fn = secure_filename(f.filename)
            name, ext = os.path.splitext(fn)
            unique = f"{upc_n}_{int(time.time()*1000)}{ext or '.jpg'}"
            abs_path = os.path.join(save_dir, unique)
            try:
                f.save(abs_path)
                rel = f"items_prep/{unique}"
                rot = 0
                try:
                    if idx < len(rotations):
                        rot = int(rotations[idx] or 0)
                except Exception:
                    rot = 0
                cur.execute(
                    'INSERT INTO items_prep_images (upc, row_status, image_path, created_at, rotation) VALUES (?,?,?,?,?)',
                    (scope_upc, scope_status, rel, ts, rot)
                )
                img_id = cur.lastrowid
                out.append({'id': img_id, 'image_path': rel, 'created_at': ts, 'rotation': rot, 'row_status': scope_status})
            except Exception as se:
                print('Failed to save diagnostic image (add):', se)
        conn.commit()
        
        # Clear cache for this UPC to ensure fresh data on next lookup
        cache_key = f"view//api/bol_lookup?upc={scope_upc}"
        cache.delete(cache_key)
        
        return jsonify({'success': True, 'images': out})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()


@app.route('/api/items_prep/photo/<int:photo_id>', methods=['DELETE'])
def api_items_prep_delete_photo(photo_id):
    """Soft-delete or hard-delete a single diagnostic photo by its id.
    Query param hard=1 to permanently remove file and DB row.
    """
    conn = None
    try:
        hard = (request.args.get('hard') or '0') in ('1','true','yes')
        _ensure_items_prep_tables()
        conn = sqlite3.connect('bol.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute('SELECT id, upc, image_path, trash_path, deleted_at FROM items_prep_images WHERE id = ?', (photo_id,))
        r = cur.fetchone()
        if not r:
            return jsonify({'success': False, 'error': 'Photo not found'}), 404
        if hard:
            # remove file(s) if present then delete row
            for rel in (r['trash_path'], r['image_path']):
                if rel:
                    abs_path = os.path.join(app.root_path, 'static', rel) if not os.path.isabs(rel) else rel
                    try:
                        if os.path.isfile(abs_path):
                            os.remove(abs_path)
                    except Exception as fe:
                        print('Failed hard remove photo', abs_path, fe)
            cur.execute('DELETE FROM items_prep_images WHERE id = ?', (photo_id,))
            deleted = cur.rowcount
            conn.commit()
            return jsonify({'success': True, 'deleted': deleted, 'hard': True})
        else:
            # soft delete (mark deleted_at, set expires_at, move file to trash)
            if r['deleted_at'] and str(r['deleted_at']).strip():
                return jsonify({'success': False, 'error': 'Photo already deleted'}), 400
            rel = r['image_path']
            abs_path = os.path.join(app.root_path, 'static', rel) if not os.path.isabs(rel) else rel
            new_rel = None
            if os.path.isfile(abs_path):
                new_rel = _move_to_trash(abs_path, r['upc'])
            del_at = _now_iso()
            import datetime as _dt
            exp = (_dt.datetime.now(_dt.UTC) + _dt.timedelta(days=_trash_retention_days())).isoformat()
            cur.execute('UPDATE items_prep_images SET deleted_at=?, expires_at=?, trash_path=? WHERE id=?', (del_at, exp, new_rel or rel, photo_id))
            conn.commit()
            return jsonify({'success': True, 'deleted': 1, 'hard': False, 'retention_days': _trash_retention_days()})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/items_prep/set_display_image', methods=['POST'])
def api_items_prep_set_display_image():
    """Set a diagnostic photo as the display image for a UPC in bol_items.
    JSON: { id?, upc, lot_number?, photo_id } OR { id?, upc, lot_number?, image_path }
    Returns: { success, image_url, id, lot_number }
    """
    conn = None
    try:
        data = request.get_json() or {}
        upc = _normalize_upc(data.get('upc', ''))
        upc_n = _normalize_upc_preserve_suffix_for_match(upc)
        item_id = data.get('id')
        if item_id is not None and str(item_id).strip() != '':
            try:
                item_id = int(item_id)
            except Exception:
                return jsonify({'success': False, 'error': 'Invalid id'}), 400
            if item_id <= 0:
                return jsonify({'success': False, 'error': 'Invalid id'}), 400
        else:
            item_id = None
        lot_number = _normalize_lot_number(_preferred_lot_from_request(data))
        photo_id = data.get('photo_id')
        image_path = data.get('image_path')

        if not upc_n:
            return jsonify({'success': False, 'error': 'Missing upc'}), 400

        # Get the image path from photo_id if provided
        if photo_id and not image_path:
            _ensure_items_prep_tables()
            with sqlite3.connect('bol.db') as lookup_conn:
                cur = lookup_conn.cursor()
                cur.execute('SELECT image_path FROM items_prep_images WHERE id = ?', (photo_id,))
                row = cur.fetchone()
                if row:
                    image_path = row[0]

        if not image_path:
            return jsonify({'success': False, 'error': 'Missing photo_id or image_path'}), 400

        # Convert relative path to full URL (items_prep/xxx.jpg -> /static/items_prep/xxx.jpg)
        image_url = f"/static/{image_path}" if not image_path.startswith('/') else image_path

        conn = sqlite3.connect('bol.db', isolation_level='IMMEDIATE')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        target_id = None
        target_lot = lot_number
        if item_id is not None:
            cur.execute('''
                SELECT id, upc, COALESCE(lot_number, '') AS lot_number
                FROM bol_items
                WHERE id = ?
                LIMIT 1
            ''', (item_id,))
            row = cur.fetchone()
            if not row:
                return jsonify({'success': False, 'error': f'Item id {item_id} not found'}), 404
            row_upc = _normalize_upc_preserve_suffix_for_match(row['upc'])
            row_lot = _normalize_lot_number(row['lot_number'])
            if row_upc.lower() != upc_n.lower():
                return jsonify({'success': False, 'error': 'Provided upc does not match item id'}), 400
            if lot_number and row_lot and lot_number.lower() != row_lot.lower():
                return jsonify({'success': False, 'error': 'Provided lot_number does not match item id'}), 400
            target_id = int(row['id'])
            target_lot = row_lot
        else:
            if not lot_number and _has_multiple_lot_rows(cur, upc_n):
                return jsonify({
                    'success': False,
                    'error': 'Multiple LOT rows found for this UPC. Please provide lot_number or row id.'
                }), 400
            row = _select_canonical_bol_row(
                cur,
                upc_n,
                lot_number,
                columns='id, upc, lot_number',
                strict_lot=bool(lot_number)
            )
            if not row:
                if lot_number:
                    return jsonify({'success': False, 'error': f'Item {upc_n} not found in lot {lot_number}'}), 404
                return jsonify({'success': False, 'error': f'Item {upc_n} not found'}), 404
            target_id = int(row[0])
            target_lot = _normalize_lot_number(row[2])

        cur.execute('UPDATE bol_items SET image_url = ? WHERE id = ?', (image_url, target_id))
        updated = cur.rowcount
        conn.commit()

        print(
            f'[SET DISPLAY IMAGE] Updated bol_items id={target_id} '
            f'for UPC {upc_n} lot={target_lot or "(none)"} with image_url: {image_url}'
        )
        return jsonify({
            'success': True,
            'image_url': image_url,
            'updated': updated,
            'id': target_id,
            'lot_number': target_lot
        })
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

