@app.route('/sold-orders', methods=['GET'])
@cache.cached(timeout=300, query_string=True)  # Cache for 5 minutes based on query params (days parameter)
def sold_orders():
    days = int(request.args.get('days', 1))
    if days < 1:
        days = 1
    elif days > 120:
        days = 120
    
    # Get orders from sold.db
    sold_conn = sqlite3.connect('sold.db')
    try:
        sold_conn.row_factory = sqlite3.Row
        sold_cur = sold_conn.cursor()
        # Only show orders from the last N days.
        # Keep ordering deterministic for duplicate suppression and UI stability.
        sold_cur.execute('''
            SELECT *
            FROM orders
            WHERE paid_time >= date('now', '-' || ? || ' days')
            ORDER BY paid_time DESC, id DESC
        ''', (days,))
        raw_orders = sold_cur.fetchall()

        # Defensive dedupe: intermittent sync races can leave clone rows.
        # Keep the newest row per strong content signature.
        dedupe_seen = set()
        orders = []
        duplicate_count = 0
        for order in raw_orders:
            try:
                qty_val = int(order['quantity']) if order['quantity'] is not None else 0
            except Exception:
                qty_val = 0
            try:
                price_val = float(order['price']) if order['price'] is not None else 0.0
            except Exception:
                price_val = 0.0
            signature = (
                str(order['store'] or '').strip().lower(),
                str(order['order_id'] or '').strip(),
                str(order['item_id'] or '').strip(),
                _normalize_upc(order['barcode'] or ''),
                str(order['title'] or '').strip().lower(),
                qty_val,
                round(price_val, 4),
                str(order['paid_time'] or '').strip(),
                str(order['shipped_time'] or '').strip(),
                str(order['shipping_name'] or '').strip().lower()
            )
            if signature in dedupe_seen:
                duplicate_count += 1
                continue
            dedupe_seen.add(signature)
            orders.append(order)

        if duplicate_count > 0:
            print(f"[sold_orders] Deduped {duplicate_count} transient duplicate row(s) from sold.db query")
    finally:
        sold_conn.close()
    
    # Enrich with location from searchRack.db
    result = []
    try:
        rack_conn = sqlite3.connect('searchRack.db')
        rack_conn.row_factory = sqlite3.Row
        rack_cur = rack_conn.cursor()
        
        for order in orders:
            order_dict = dict(order)
            
            # If location is empty and barcode exists, look it up in searchRack
            if (not order_dict.get('location') or order_dict.get('location', '').strip() == '') and order_dict.get('barcode'):
                try:
                    # Try original barcode first (searchRack stores without leading zeros)
                    rack_cur.execute('SELECT ITEM_POSITION, PICTUREPOSITION, QUANTITY FROM SEARCHRACK WHERE BARCODE = ? COLLATE NOCASE', (order_dict['barcode'],))
                    rack_rows = rack_cur.fetchall()
                    
                    # If not found, try padded version
                    if not rack_rows and order_dict['barcode'] and order_dict['barcode'].isdigit():
                        barcode_padded = order_dict['barcode'].zfill(12)
                        rack_cur.execute('SELECT ITEM_POSITION, PICTUREPOSITION, QUANTITY FROM SEARCHRACK WHERE BARCODE = ? COLLATE NOCASE', (barcode_padded,))
                        rack_rows = rack_cur.fetchall()
                    
                    if rack_rows:
                        # Collect all locations for this barcode
                        locations = []
                        for rack_row in rack_rows:
                            loc = rack_row['ITEM_POSITION'] or rack_row['PICTUREPOSITION']
                            if loc:
                                locations.append({
                                    'code': loc,
                                    'image': rack_row['PICTUREPOSITION'] if rack_row['PICTUREPOSITION'] and rack_row['PICTUREPOSITION'].strip() else loc,
                                    'quantity': rack_row['QUANTITY'] if rack_row['QUANTITY'] else 1
                                })
                        
                        # Store as JSON array if multiple locations, or single string for backward compatibility
                        if len(locations) > 1:
                            order_dict['locations'] = locations  # Array of location objects
                            order_dict['location'] = locations[0]['code']  # First location for backward compatibility
                        elif len(locations) == 1:
                            order_dict['location'] = locations[0]['code']
                            order_dict['location_image'] = locations[0]['image']
                except sqlite3.Error as e:
                    # If searchRack query fails, just skip location lookup for this order
                    print(f"Warning: Failed to lookup location for barcode {order_dict['barcode']}: {e}")

            # If still no location, flag for manual search via Finder page
            if not order_dict.get('location') or order_dict.get('location', '').strip() == '':
                if order_dict.get('title'):
                    order_dict['location_search'] = order_dict['title']

            result.append(order_dict)
        
    except Exception as e:
        # If searchRack.db is unavailable, return orders without location enrichment
        print(f"Warning: searchRack.db unavailable, skipping location lookup: {e}")
        result = [dict(order) for order in orders]
    finally:
        rack_conn.close()

    return jsonify(result)

@app.route('/api/ready-to-ship/count', methods=['GET'])
@cache.cached(timeout=60, query_string=True)
def ready_to_ship_count():
    """Return count of unhandled (ready to ship) orders within the last N days."""
    days = int(request.args.get('days', 2))
    if days < 1:
        days = 1
    elif days > 120:
        days = 120
    conn = sqlite3.connect('sold.db')
    try:
        cur = conn.cursor()
        cur.execute('''
            SELECT COUNT(*)
            FROM orders
            WHERE paid_time >= date('now', '-' || ? || ' days')
              AND COALESCE(TRIM(isHandled), '') != '1'
        ''', (days,))
        row = cur.fetchone()
        count = int(row[0] or 0) if row else 0
        return jsonify({'success': True, 'count': count, 'days': days})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'ready_to_ship:count')}), 500
    finally:
        conn.close()


@app.route('/get-order', methods=['GET'])
def get_order():
    order_id = request.args.get('id')
    if not order_id:
        return jsonify({'error': 'Missing order id'}), 400
    try:
        conn = sqlite3.connect('sold.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute("SELECT * FROM orders WHERE id = ?", (order_id,))
        order = cur.fetchone()
        
        if not order:
            return jsonify({'error': 'Order not found'}), 404
            
        # Convert sqlite3.Row to dict
        order_dict = dict(order)
        return jsonify(order_dict)
    except Exception as e:
        return jsonify({'error': _safe_error(e)}), 500
    finally:
        conn.close()

@app.route('/api/ready-to-ship/location-options/<int:order_id>', methods=['GET'])
def ready_to_ship_location_options(order_id):
    sold_conn = None
    rack_conn = None
    try:
        sold_conn = sqlite3.connect('sold.db')
        sold_conn.row_factory = sqlite3.Row
        sold_cur = sold_conn.cursor()
        _ensure_order_removal_allocations_table(sold_cur)

        sold_cur.execute('SELECT id, order_id, barcode, quantity, title FROM orders WHERE id = ?', (order_id,))
        order = sold_cur.fetchone()
        if not order:
            return jsonify({'success': False, 'error': 'Order not found'}), 404

        barcode = str(order['barcode'] or '').strip()
        sold_qty = max(1, _coerce_int(order['quantity'], 1))
        existing_allocations = _load_order_removal_allocations(sold_cur, order_id)

        if not barcode:
            return jsonify({
                'success': True,
                'order_id': order_id,
                'barcode': '',
                'quantity': sold_qty,
                'needs_choice': False,
                'locations': [],
                'existing_allocations': existing_allocations,
                'total_available': 0,
                'can_fulfill': False
            })

        rack_conn = sqlite3.connect('searchRack.db')
        rack_conn.row_factory = sqlite3.Row
        rack_cur = rack_conn.cursor()

        matches = _searchrack_matches_for_barcode(rack_cur, barcode, include_zero=False)
        location_groups = _group_searchrack_matches_by_location(matches)
        locations = [
            {
                'location_key': g['location_key'],
                'location_code': g['location_code'],
                'available_qty': max(0, _coerce_int(g['available_qty'], 0)),
                'preview_key': g['preview_key']
            }
            for g in location_groups
        ]
        total_available = sum(max(0, _coerce_int(x['available_qty'], 0)) for x in locations)

        return jsonify({
            'success': True,
            'order_id': order_id,
            'order_ref': order['order_id'],
            'title': order['title'],
            'barcode': barcode,
            'quantity': sold_qty,
            'needs_choice': len(locations) > 1,
            'locations': locations,
            'existing_allocations': existing_allocations,
            'total_available': total_available,
            'can_fulfill': total_available >= sold_qty
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            if sold_conn is not None:
                sold_conn.close()
        except Exception:
            pass
        try:
            if rack_conn is not None:
                rack_conn.close()
        except Exception:
            pass

@app.route('/mark-order-handled', methods=['POST'])
def mark_order_handled():
    data = request.get_json() or {}
    order_id = data.get('id')
    incoming_allocations = data.get('allocations')
    
    if not order_id:
        return jsonify({'success': False, 'error': 'Missing order id'}), 400

    conn = None
    rack_conn = None
    try:
        conn = sqlite3.connect('sold.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        _ensure_order_removal_allocations_table(cur)

        cur.execute('SELECT id, barcode, quantity FROM orders WHERE id = ?', (order_id,))
        order = cur.fetchone()
        if not order:
            return jsonify({'success': False, 'error': 'Order not found'}), 404

        barcode = str(order['barcode'] or '').strip()
        sold_qty = max(1, _coerce_int(order['quantity'], 1))

        normalized_allocations = []
        if incoming_allocations is not None:
            if not isinstance(incoming_allocations, list):
                return jsonify({'success': False, 'error': 'allocations must be an array'}), 400
            grouped = {}
            for alloc in incoming_allocations:
                if not isinstance(alloc, dict):
                    continue
                qty = max(0, _coerce_int(alloc.get('quantity', alloc.get('qty')), 0))
                if qty <= 0:
                    continue
                location_code = _sold_location_label(alloc.get('location_code') or alloc.get('code'))
                location_key = _sold_location_key(alloc.get('location_key') or location_code)
                bucket = grouped.get(location_key)
                if bucket is None:
                    bucket = {
                        'location_key': location_key,
                        'location_code': location_code,
                        'quantity': 0
                    }
                    grouped[location_key] = bucket
                bucket['quantity'] += qty
            normalized_allocations = list(grouped.values())

        if barcode:
            rack_conn = sqlite3.connect('searchRack.db')
            rack_conn.row_factory = sqlite3.Row
            rack_cur = rack_conn.cursor()
            matches = _searchrack_matches_for_barcode(rack_cur, barcode, include_zero=False)
            location_groups = _group_searchrack_matches_by_location(matches)
            group_map = {g['location_key']: g for g in location_groups}
            needs_choice = len(location_groups) > 1

            if needs_choice and not normalized_allocations:
                return jsonify({
                    'success': False,
                    'error': 'Location selection required for this order',
                    'location_selection_required': True,
                    'order_id': order_id,
                    'quantity': sold_qty,
                    'locations': [
                        {
                            'location_key': g['location_key'],
                            'location_code': g['location_code'],
                            'available_qty': max(0, _coerce_int(g['available_qty'], 0))
                        }
                        for g in location_groups
                    ]
                }), 400

            if normalized_allocations:
                alloc_total = 0
                for alloc in normalized_allocations:
                    loc_key = alloc['location_key']
                    qty = max(0, _coerce_int(alloc['quantity'], 0))
                    group = group_map.get(loc_key)
                    if not group:
                        return jsonify({
                            'success': False,
                            'error': f"Unknown location selected: {alloc['location_code']}"
                        }), 400
                    group_available = max(0, _coerce_int(group.get('available_qty'), 0))
                    if qty > group_available:
                        return jsonify({
                            'success': False,
                            'error': f"Selected quantity exceeds available for {alloc['location_code']}"
                        }), 400
                    alloc_total += qty
                if alloc_total != sold_qty:
                    return jsonify({
                        'success': False,
                        'error': f'Selected location quantities must total {sold_qty}'
                    }), 400

                _save_order_removal_allocations(cur, order_id, normalized_allocations)
            else:
                _save_order_removal_allocations(cur, order_id, [])
        else:
            _save_order_removal_allocations(cur, order_id, [])

        # Set shipped_time if not already set (for test orders to trigger automatic removal)
        cur.execute("""
            UPDATE orders 
            SET isHandled = '1', 
                isHandledDate = datetime('now'),
                shipped_time = COALESCE(shipped_time, datetime('now'))
            WHERE id = ?
        """, (order_id,))
        conn.commit()
        
        # Clear the sold-orders cache since data changed
        cache.delete_memoized(sold_orders)
        cache.delete_memoized(ready_to_ship_count)
        
        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass
        try:
            if rack_conn is not None:
                rack_conn.close()
        except Exception:
            pass

@app.route('/mark-order-unhandled', methods=['POST'])
def mark_order_unhandled():
    data = request.get_json() or {}
    order_id = data.get('id')
    
    if not order_id:
        return jsonify({'success': False, 'error': 'Missing order id'}), 400

    conn = None
    try:
        conn = sqlite3.connect('sold.db')
        cur = conn.cursor()
        _ensure_order_removal_allocations_table(cur)
        cur.execute("UPDATE orders SET isHandled = '', isHandledDate = NULL WHERE id = ?", (order_id,))
        cur.execute('DELETE FROM order_removal_allocations WHERE order_row_id = ?', (order_id,))
        conn.commit()
        
        # Clear the sold-orders cache since data changed
        cache.delete_memoized(sold_orders)
        cache.delete_memoized(ready_to_ship_count)
        
        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/sold/pending-removals', methods=['GET'])
def get_pending_removals():
    """Get list of sold orders pending automatic inventory removal (shipped but within 48h grace period)"""
    try:
        conn = sqlite3.connect('sold.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        # Read grace period from settings (default 48)
        try:
            cur.execute("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)")
            conn.commit()
            cur.execute("SELECT value FROM settings WHERE key = 'removal_grace_hours'")
            row = cur.fetchone()
            grace_period_hours = float(row[0]) if row and str(row[0]).strip() else 48
        except Exception:
            grace_period_hours = 48
        
        # Get orders that are shipped but not yet processed
        cur.execute('''
            SELECT id, order_id, item_id, barcode, title, quantity, 
                   shipped_time, paid_time, image, removal_cancelled
            FROM orders 
            WHERE rackupdated = 0 
            AND shipped_time IS NOT NULL 
            AND shipped_time != ''
            AND barcode IS NOT NULL
            AND barcode != ''
        ''')
        orders = cur.fetchall()
        
        # Calculate time remaining for each order
        import datetime
        now = datetime.datetime.now()
        
        result = []
        for order in orders:
            try:
                shipped_str = order['shipped_time']
                if 'T' in shipped_str:
                    if shipped_str.endswith('Z'):
                        shipped_dt = datetime.datetime.fromisoformat(shipped_str.replace('Z', '+00:00'))
                    elif '+' in shipped_str or shipped_str.count('-') > 2:
                        shipped_dt = datetime.datetime.fromisoformat(shipped_str)
                    else:
                        shipped_dt = datetime.datetime.fromisoformat(shipped_str)
                else:
                    shipped_dt = datetime.datetime.fromisoformat(shipped_str)
                
                # Always convert to naive datetime for comparison
                if shipped_dt.tzinfo:
                    shipped_dt = shipped_dt.replace(tzinfo=None)
                
                hours_since_shipped = (now - shipped_dt).total_seconds() / 3600
                hours_remaining = max(0, grace_period_hours - hours_since_shipped)
                is_eligible = hours_since_shipped >= grace_period_hours
                
                order_dict = dict(order)
                order_dict['hours_remaining'] = round(hours_remaining, 1)
                order_dict['is_eligible_for_removal'] = is_eligible
                result.append(order_dict)
            except Exception as e:
                print(f"Error processing order {order['order_id']}: {e}")
                continue
        
        return jsonify({'success': True, 'orders': result, 'grace_hours': grace_period_hours})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        conn.close()

@app.route('/api/sold/cancel-removal/<int:order_id>', methods=['POST'])
def cancel_automatic_removal(order_id):
    """Cancel automatic inventory removal for a specific sold order"""
    try:
        conn = sqlite3.connect('sold.db')
        cur = conn.cursor()
        
        # Ensure removal_cancelled column exists
        try:
            cur.execute('PRAGMA table_info(orders)')
            cols = [r[1] for r in cur.fetchall()]
            if 'removal_cancelled' not in cols:
                cur.execute('ALTER TABLE orders ADD COLUMN removal_cancelled INTEGER DEFAULT 0')
                conn.commit()
        except Exception:
            pass
        
        # Set removal_cancelled to 1
        cur.execute('UPDATE orders SET removal_cancelled = 1 WHERE id = ?', (order_id,))
        conn.commit()
        
        if cur.rowcount == 0:
            return jsonify({'success': False, 'error': 'Order not found'}), 404
        
        return jsonify({'success': True, 'message': 'Automatic removal cancelled'})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        conn.close()

@app.route('/api/sold/allow-removal/<int:order_id>', methods=['POST'])
def allow_automatic_removal(order_id):
    """Re-enable automatic inventory removal for a specific sold order"""
    try:
        conn = sqlite3.connect('sold.db')
        cur = conn.cursor()
        
        # Set removal_cancelled back to 0
        cur.execute('UPDATE orders SET removal_cancelled = 0 WHERE id = ?', (order_id,))
        conn.commit()
        
        if cur.rowcount == 0:
            return jsonify({'success': False, 'error': 'Order not found'}), 404
        
        return jsonify({'success': True, 'message': 'Automatic removal re-enabled'})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        conn.close()

