@app.route('/api/location_hierarchy', methods=['GET'])
def api_location_hierarchy():
    """Get location hierarchy with item counts for searchRack inventory"""
    try:
        ensure_shelf_groups_table()
        conn = sqlite3.connect('searchRack.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        
        # Get all groups with their shelves and item counts (exclude Default Group)
        cur.execute('''
            SELECT 
                g.id as group_id,
                g.name as group_name,
                s.id as shelf_id,
                s.shelf_name as shelf_code,
                COUNT(DISTINCT sr.ID) as item_count,
                COALESCE(SUM(CAST(sr.QUANTITY as INTEGER)), 0) as total_quantity
            FROM shelf_groups g
            LEFT JOIN shelves s ON s.group_id = g.id
            LEFT JOIN SEARCHRACK sr ON LOWER(TRIM(sr.ITEM_POSITION)) = LOWER(TRIM(s.shelf_name))
            WHERE g.name != 'Default Group' OR g.name IS NULL
            GROUP BY g.id, s.id
            ORDER BY s.shelf_name
        ''')
        
        rows = cur.fetchall()
        
        # Organize into hierarchy
        hierarchy = {}
        for row in rows:
            group_id = row['group_id']
            group_name = row['group_name']
            
            if group_id not in hierarchy:
                hierarchy[group_id] = {
                    'id': group_id,
                    'name': group_name,
                    'total_items': 0,
                    'total_quantity': 0,
                    'shelves': []
                }
            
            if row['shelf_id']:
                shelf_info = {
                    'id': row['shelf_id'],
                    'code': row['shelf_code'],
                    'item_count': row['item_count'] or 0,
                    'quantity': row['total_quantity'] or 0
                }
                hierarchy[group_id]['shelves'].append(shelf_info)
                hierarchy[group_id]['total_items'] += shelf_info['item_count']
                hierarchy[group_id]['total_quantity'] += shelf_info['quantity']
        
        # Convert to list and sort by total_quantity descending
        locations = sorted(hierarchy.values(), key=lambda x: x['total_quantity'], reverse=True)
        
        return jsonify({
            'success': True,
            'locations': locations
        })
    except Exception as e:
        print(f'[api_location_hierarchy] Error: {e}')
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        conn.close()


def _movelocation_barcode_key(value):
    return _normalize_upc_preserve_suffix_for_match(_normalize_upc(value))


def _movelocation_barcode_variants(value):
    raw = _normalize_upc(value)
    key = _movelocation_barcode_key(raw)
    variants = set()
    for candidate in (raw, key):
        s = str(candidate or '').strip()
        if s:
            variants.add(s)

    if key and '-' in key:
        base, suffix = key.split('-', 1)
        if base.isdigit():
            for width in (8, 11, 12, 13, 14):
                if len(base) < width:
                    variants.add(f"{base.zfill(width)}-{suffix}")
    elif key and key.isdigit():
        for width in (8, 11, 12, 13, 14):
            if len(key) < width:
                variants.add(key.zfill(width))

    if raw and raw.isdigit():
        stripped = raw.lstrip('0') or '0'
        variants.add(stripped)
        for width in (8, 11, 12, 13, 14):
            if len(stripped) < width:
                variants.add(stripped.zfill(width))

    return {str(v).strip() for v in variants if str(v).strip()}


def _movelocation_parse_qty(value, default=1):
    try:
        if value is None:
            return default
        s = str(value).strip()
        if not s:
            return default
        return int(float(s))
    except Exception:
        return default


def _movelocation_pick_image(row_dict, image_col=None, images_col=None):
    try:
        image_val = ''
        if image_col:
            image_val = str(row_dict.get(image_col) or '').strip()
        if image_val:
            return image_val

        images_raw = row_dict.get(images_col) if images_col else ''
        if not images_raw:
            return ''

        if isinstance(images_raw, list):
            for item in images_raw:
                s = str(item or '').strip()
                if s:
                    return s
            return ''

        images_text = str(images_raw).strip()
        if not images_text:
            return ''
        if images_text.startswith('['):
            try:
                parsed = json.loads(images_text)
                if isinstance(parsed, list):
                    for item in parsed:
                        s = str(item or '').strip()
                        if s:
                            return s
            except Exception:
                pass
        for sep in ('|', ',', ';'):
            if sep in images_text:
                for part in images_text.split(sep):
                    s = part.strip()
                    if s:
                        return s
        return images_text
    except Exception:
        return ''


def _movelocation_row_location(row_dict, pos_col=None, pic_col=None):
    pos_val = str(row_dict.get(pos_col) or '').strip() if pos_col else ''
    pic_val = str(row_dict.get(pic_col) or '').strip() if pic_col else ''
    code = pos_val or pic_val
    preview = pic_val or pos_val
    return code, pos_val, pic_val, preview


@app.route('/api/movelocation_lookup', methods=['GET'])
def api_movelocation_lookup():
    """Lookup a scanned barcode and return all available source locations."""
    conn = None
    try:
        barcode_raw = (request.args.get('barcode') or '').strip()
        if not barcode_raw:
            return jsonify({'success': False, 'error': 'Missing barcode'}), 400

        barcode_key = _movelocation_barcode_key(barcode_raw)
        if not barcode_key:
            return jsonify({'success': False, 'error': 'Invalid barcode'}), 400

        conn = sqlite3.connect('searchRack.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()

        cur.execute("PRAGMA table_info('SEARCHRACK')")
        cols = [r[1] for r in cur.fetchall()]
        cols_lower = {c.lower(): c for c in cols}
        id_col = cols_lower.get('id')
        barcode_col = cols_lower.get('barcode') or cols_lower.get('upc')
        title_col = cols_lower.get('title')
        image_col = cols_lower.get('image')
        images_col = cols_lower.get('images')
        qty_col = cols_lower.get('quantity') or cols_lower.get('qty')
        pos_col = cols_lower.get('item_position') or cols_lower.get('itemposition') or cols_lower.get('position')
        pic_col = cols_lower.get('pictureposition')

        if not barcode_col:
            return jsonify({'success': False, 'error': 'SEARCHRACK barcode column not found'}), 500

        base_sql = f'''
            SELECT rowid AS _rowid_, *
            FROM SEARCHRACK
            WHERE {barcode_col} IS NOT NULL
              AND TRIM({barcode_col}) != ''
        '''

        variants = sorted(v.lower() for v in _movelocation_barcode_variants(barcode_raw))
        candidate_rows = []
        if variants:
            placeholders = ','.join('?' for _ in variants)
            cur.execute(base_sql + f" AND LOWER(TRIM({barcode_col})) IN ({placeholders})", tuple(variants))
            candidate_rows = [dict(r) for r in cur.fetchall()]

        if not candidate_rows:
            cur.execute(base_sql)
            candidate_rows = [dict(r) for r in cur.fetchall()]

        matched_rows = []
        for row in candidate_rows:
            row_barcode = row.get(barcode_col)
            if _movelocation_barcode_key(row_barcode) == barcode_key:
                matched_rows.append(row)

        if not matched_rows:
            return jsonify({
                'success': True,
                'found': False,
                'error': f'No inventory found for barcode {barcode_raw}'
            })

        title_val = ''
        image_val = ''
        canonical_barcode = ''
        locations_map = {}
        total_available = 0

        for row in matched_rows:
            if not canonical_barcode:
                canonical_barcode = str(row.get(barcode_col) or '').strip()
            if not title_val and title_col:
                title_val = str(row.get(title_col) or '').strip()
            if not image_val:
                image_val = _movelocation_pick_image(row, image_col=image_col, images_col=images_col)

            code, pos_val, pic_val, preview_val = _movelocation_row_location(row, pos_col=pos_col, pic_col=pic_col)
            if not code:
                continue

            qty_val = max(0, _movelocation_parse_qty(row.get(qty_col) if qty_col else None, default=1))
            total_available += qty_val

            loc_key = code.lower()
            bucket = locations_map.get(loc_key)
            if bucket is None:
                bucket = {
                    'location_key': loc_key,
                    'code': code,
                    'item_position': pos_val,
                    'pictureposition': pic_val,
                    'preview_key': preview_val or code,
                    'quantity': 0,
                    'row_ids': []
                }
                locations_map[loc_key] = bucket

            bucket['quantity'] += qty_val
            row_id = row.get(id_col) if id_col else row.get('_rowid_')
            if row_id is None:
                row_id = row.get('_rowid_')
            if row_id is not None and row_id not in bucket['row_ids']:
                bucket['row_ids'].append(row_id)

        locations = sorted(
            locations_map.values(),
            key=lambda x: (-int(x.get('quantity') or 0), str(x.get('code') or '').lower())
        )

        if not locations:
            return jsonify({
                'success': True,
                'found': False,
                'error': f'No location code found for barcode {barcode_raw}'
            })

        canonical_barcode = canonical_barcode or _normalize_upc(barcode_raw)
        if not title_val:
            title_val = canonical_barcode or barcode_raw

        return jsonify({
            'success': True,
            'found': True,
            'item': {
                'barcode': canonical_barcode,
                'barcode_display': _format_upc_display(canonical_barcode),
                'barcode_key': barcode_key,
                'title': title_val,
                'image': image_val,
                'total_available': max(0, int(total_available or 0)),
                'locations_count': len(locations),
                'locations': locations
            }
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass


@app.route('/api/movelocation_lookup_shelf', methods=['GET'])
def api_movelocation_lookup_shelf():
    """Lookup all inventory rows for one shelf code and aggregate by barcode."""
    conn = None
    try:
        shelf_raw = (request.args.get('shelf') or '').strip()
        if not shelf_raw:
            return jsonify({'success': False, 'error': 'Missing shelf code'}), 400

        shelf_norm = shelf_raw.lower()

        conn = sqlite3.connect('searchRack.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()

        cur.execute("PRAGMA table_info('SEARCHRACK')")
        cols = [r[1] for r in cur.fetchall()]
        cols_lower = {c.lower(): c for c in cols}
        id_col = cols_lower.get('id')
        barcode_col = cols_lower.get('barcode') or cols_lower.get('upc')
        title_col = cols_lower.get('title')
        image_col = cols_lower.get('image')
        images_col = cols_lower.get('images')
        qty_col = cols_lower.get('quantity') or cols_lower.get('qty')
        pos_col = cols_lower.get('item_position') or cols_lower.get('itemposition') or cols_lower.get('position')
        pic_col = cols_lower.get('pictureposition')

        if not barcode_col:
            return jsonify({'success': False, 'error': 'SEARCHRACK barcode column not found'}), 500
        if not pos_col and not pic_col:
            return jsonify({'success': False, 'error': 'SEARCHRACK location columns not found'}), 500

        if pos_col and pic_col:
            cur.execute(f'''
                SELECT rowid AS _rowid_, *
                FROM SEARCHRACK
                WHERE LOWER(TRIM(COALESCE(NULLIF({pos_col}, ''), NULLIF({pic_col}, '')))) = ?
            ''', (shelf_norm,))
        elif pos_col:
            cur.execute(f'''
                SELECT rowid AS _rowid_, *
                FROM SEARCHRACK
                WHERE LOWER(TRIM({pos_col})) = ?
            ''', (shelf_norm,))
        else:
            cur.execute(f'''
                SELECT rowid AS _rowid_, *
                FROM SEARCHRACK
                WHERE LOWER(TRIM({pic_col})) = ?
            ''', (shelf_norm,))

        matched_rows = [dict(r) for r in cur.fetchall()]
        if not matched_rows:
            return jsonify({
                'success': True,
                'found': False,
                'shelf': shelf_raw,
                'error': f'No inventory found for shelf {shelf_raw}',
                'items': [],
                'items_count': 0,
                'total_units': 0
            })

        buckets = {}
        total_units = 0

        for row in matched_rows:
            code, pos_val, pic_val, preview_val = _movelocation_row_location(row, pos_col=pos_col, pic_col=pic_col)
            if not code:
                continue

            code_norm = str(code).strip().lower()
            if code_norm != shelf_norm:
                pos_norm = str(pos_val or '').strip().lower()
                pic_norm = str(pic_val or '').strip().lower()
                if pos_norm != shelf_norm and pic_norm != shelf_norm:
                    continue

            barcode_val = str(row.get(barcode_col) or '').strip()
            barcode_key = _movelocation_barcode_key(barcode_val)
            if not barcode_key:
                continue

            qty_val = max(0, _movelocation_parse_qty(row.get(qty_col) if qty_col else None, default=1))
            if qty_val <= 0:
                continue

            bucket = buckets.get(barcode_key)
            if bucket is None:
                canonical_barcode = barcode_val or barcode_key
                title_val = str(row.get(title_col) or '').strip() if title_col else ''
                image_val = _movelocation_pick_image(row, image_col=image_col, images_col=images_col)
                bucket = {
                    'barcode': canonical_barcode,
                    'barcode_display': _format_upc_display(canonical_barcode),
                    'barcode_key': barcode_key,
                    'title': title_val or canonical_barcode,
                    'image': image_val,
                    'total_available': 0,
                    'locations': [{
                        'location_key': code_norm,
                        'code': str(code).strip(),
                        'item_position': pos_val,
                        'pictureposition': pic_val,
                        'preview_key': preview_val or code,
                        'quantity': 0,
                        'row_ids': []
                    }]
                }
                buckets[barcode_key] = bucket
            else:
                if not bucket.get('title') and title_col:
                    bucket['title'] = str(row.get(title_col) or '').strip()
                if not bucket.get('image'):
                    bucket['image'] = _movelocation_pick_image(row, image_col=image_col, images_col=images_col)

            loc_entry = bucket['locations'][0]
            loc_entry['quantity'] += qty_val

            row_id = row.get(id_col) if id_col else row.get('_rowid_')
            if row_id is None:
                row_id = row.get('_rowid_')
            if row_id is not None and row_id not in loc_entry['row_ids']:
                loc_entry['row_ids'].append(row_id)

            bucket['total_available'] += qty_val
            total_units += qty_val

        items = sorted(
            [v for v in buckets.values() if int(v.get('total_available') or 0) > 0 and v.get('locations')],
            key=lambda x: (
                str(x.get('title') or '').lower(),
                str(x.get('barcode') or '').lower()
            )
        )

        if not items:
            return jsonify({
                'success': True,
                'found': False,
                'shelf': shelf_raw,
                'error': f'No movable inventory found for shelf {shelf_raw}',
                'items': [],
                'items_count': 0,
                'total_units': 0
            })

        return jsonify({
            'success': True,
            'found': True,
            'shelf': shelf_raw,
            'items': items,
            'items_count': len(items),
            'total_units': int(total_units or 0)
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass


@app.route('/api/movelocation_execute', methods=['POST'])
def api_movelocation_execute():
    """Move scanned quantities to a destination shelf, or clear location codes when requested."""
    conn = None
    rem_conn = None
    try:
        data = request.get_json() or {}
        to_location = (data.get('to_location') or '').strip()
        clear_location = bool(data.get('clear_location'))
        items = data.get('items') or []

        if not clear_location and not to_location:
            return jsonify({'success': False, 'error': 'Missing destination shelf code'}), 400
        if not isinstance(items, list) or not items:
            return jsonify({'success': False, 'error': 'Missing items list'}), 400

        conn = sqlite3.connect('searchRack.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()

        cur.execute("PRAGMA table_info('SEARCHRACK')")
        cols = [r[1] for r in cur.fetchall()]
        cols_lower = {c.lower(): c for c in cols}
        id_col = cols_lower.get('id')
        barcode_col = cols_lower.get('barcode') or cols_lower.get('upc')
        title_col = cols_lower.get('title')
        qty_col = cols_lower.get('quantity') or cols_lower.get('qty')
        pos_col = cols_lower.get('item_position') or cols_lower.get('itemposition') or cols_lower.get('position')
        pic_col = cols_lower.get('pictureposition')

        if not barcode_col:
            return jsonify({'success': False, 'error': 'SEARCHRACK barcode column not found'}), 500
        if not pos_col and not pic_col:
            return jsonify({'success': False, 'error': 'SEARCHRACK location columns not found'}), 500

        id_lookup_col = id_col or 'rowid'
        skip_pk_cols = {'id', 'rowid'}
        if id_col:
            skip_pk_cols.add(id_col.lower())
        insert_cols = [c for c in cols if c.lower() not in skip_pk_cols]

        rem_conn = sqlite3.connect('rackhistory.db')
        rem_cur = rem_conn.cursor()
        _ensure_removed_items_table(rem_cur)
        try:
            rem_cur.execute("PRAGMA table_info(removed_items)")
            rem_cols = [c[1] for c in rem_cur.fetchall()]
            if 'item_position' not in rem_cols:
                rem_cur.execute('ALTER TABLE removed_items ADD COLUMN item_position TEXT')
                rem_conn.commit()
        except Exception:
            pass

        from datetime import datetime
        moved_items = 0
        moved_units = 0
        skipped_items = 0
        item_results = []
        to_location_norm = to_location.lower() if to_location else ''
        removal_type = 'locationcleared' if clear_location else 'locationmoved'
        target_location_for_logs = '' if clear_location else to_location

        def _location_match_rows(source_location_norm):
            if pos_col and pic_col:
                cur.execute(f'''
                    SELECT rowid AS _rowid_, *
                    FROM SEARCHRACK
                    WHERE LOWER(TRIM(COALESCE(NULLIF({pos_col}, ''), NULLIF({pic_col}, '')))) = ?
                ''', (source_location_norm,))
            elif pos_col:
                cur.execute(f'''
                    SELECT rowid AS _rowid_, *
                    FROM SEARCHRACK
                    WHERE LOWER(TRIM({pos_col})) = ?
                ''', (source_location_norm,))
            else:
                cur.execute(f'''
                    SELECT rowid AS _rowid_, *
                    FROM SEARCHRACK
                    WHERE LOWER(TRIM({pic_col})) = ?
                ''', (source_location_norm,))
            return [dict(r) for r in cur.fetchall()]

        for idx, raw_item in enumerate(items):
            row_result = {
                'index': idx,
                'barcode': str((raw_item or {}).get('barcode') or '').strip(),
                'from_location': str((raw_item or {}).get('from_location') or '').strip(),
                'from_locations': [],
                'requested_qty': 0,
                'moved_qty': 0,
                'success': False
            }
            try:
                barcode_raw = row_result['barcode']
                from_location = row_result['from_location']
                raw_from_locations = (raw_item or {}).get('from_locations')
                try:
                    requested_qty = int((raw_item or {}).get('quantity') or 1)
                except Exception:
                    requested_qty = 1
                requested_qty = max(1, requested_qty)
                row_result['requested_qty'] = requested_qty

                barcode_key = _movelocation_barcode_key(barcode_raw)
                source_locations = []
                source_seen = set()

                def _add_source_location(raw_loc):
                    loc = str(raw_loc or '').strip()
                    if not loc:
                        return
                    norm = loc.lower()
                    if norm in source_seen:
                        return
                    source_seen.add(norm)
                    source_locations.append(loc)

                if isinstance(raw_from_locations, list):
                    for raw_loc in raw_from_locations:
                        _add_source_location(raw_loc)
                elif isinstance(raw_from_locations, str):
                    text = raw_from_locations.strip()
                    if text:
                        if ',' in text:
                            for part in text.split(','):
                                _add_source_location(part)
                        else:
                            _add_source_location(text)
                _add_source_location(from_location)
                if requested_qty > 0 and len(source_locations) > requested_qty:
                    source_locations = source_locations[:requested_qty]
                    row_result['selection_limited'] = True
                row_result['from_locations'] = source_locations
                if source_locations:
                    row_result['from_location'] = ', '.join(source_locations)

                if not barcode_key:
                    row_result['error'] = 'Invalid barcode'
                    skipped_items += 1
                    item_results.append(row_result)
                    continue
                if not source_locations:
                    row_result['error'] = 'Missing source location'
                    skipped_items += 1
                    item_results.append(row_result)
                    continue
                remaining = requested_qty
                moved_this_item = 0
                source_warnings = []
                used_locations = []

                for source_location in source_locations:
                    if remaining <= 0:
                        break

                    source_location_norm = source_location.lower().strip()
                    if not source_location_norm:
                        continue
                    if (not clear_location) and source_location_norm == to_location_norm:
                        source_warnings.append(f'Source {source_location} matches destination')
                        continue

                    source_rows = _location_match_rows(source_location_norm)
                    if not source_rows:
                        source_warnings.append(f'No rows found at source location {source_location}')
                        continue

                    matched_rows = []
                    for source_row in source_rows:
                        if _movelocation_barcode_key(source_row.get(barcode_col)) == barcode_key:
                            qty_here = max(0, _movelocation_parse_qty(source_row.get(qty_col) if qty_col else None, default=1))
                            source_row['_qty_for_move'] = qty_here
                            matched_rows.append(source_row)

                    if not matched_rows:
                        source_warnings.append(f'Barcode not found at {source_location}')
                        continue

                    matched_rows.sort(key=lambda r: int(r.get('_qty_for_move') or 0), reverse=True)
                    available_qty = sum(int(r.get('_qty_for_move') or 0) for r in matched_rows)
                    if available_qty <= 0:
                        source_warnings.append(f'No available quantity at {source_location}')
                        continue

                    move_target_qty = min(remaining, available_qty)
                    moved_from_source = 0

                    for source_row in matched_rows:
                        if move_target_qty <= 0:
                            break

                        row_qty = int(source_row.get('_qty_for_move') or 0)
                        if row_qty <= 0:
                            continue
                        take_qty = min(row_qty, move_target_qty)
                        if take_qty <= 0:
                            continue

                        row_id = source_row.get(id_col) if id_col else source_row.get('_rowid_')
                        if row_id is None:
                            row_id = source_row.get('_rowid_')
                        if row_id is None:
                            continue

                        barcode_val = str(source_row.get(barcode_col) or barcode_raw or '').strip()
                        title_val = str(source_row.get(title_col) or '').strip() if title_col else ''
                        now = datetime.now().isoformat()

                        if take_qty < row_qty and qty_col:
                            new_qty = row_qty - take_qty
                            cur.execute(
                                f"UPDATE SEARCHRACK SET {qty_col} = ? WHERE {id_lookup_col} = ?",
                                (new_qty, row_id)
                            )

                            placeholders = ','.join('?' for _ in insert_cols)
                            insert_values = []
                            for c in insert_cols:
                                val = source_row.get(c)
                                if qty_col and c.lower() == qty_col.lower():
                                    val = take_qty
                                if pos_col and c.lower() == pos_col.lower():
                                    val = '' if clear_location else to_location
                                if pic_col and c.lower() == pic_col.lower():
                                    val = ''
                                insert_values.append(val)

                            cur.execute(
                                f"INSERT INTO SEARCHRACK ({', '.join(insert_cols)}) VALUES ({placeholders})",
                                tuple(insert_values)
                            )
                            new_id = cur.lastrowid

                            rem_cur.execute('''
                                INSERT INTO removed_items
                                (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                            ''', (None, barcode_val, title_val, take_qty, now, row_id, row_qty, new_qty, removal_type, source_location))
                            rem_cur.execute('''
                                INSERT INTO removed_items
                                (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                            ''', (None, barcode_val, title_val, take_qty, now, new_id, 0, take_qty, removal_type, target_location_for_logs))
                        else:
                            if pos_col and pic_col:
                                cur.execute(
                                    f"UPDATE SEARCHRACK SET {pos_col} = ?, {pic_col} = ? WHERE {id_lookup_col} = ?",
                                    ('' if clear_location else to_location, '', row_id)
                                )
                            elif pos_col:
                                cur.execute(
                                    f"UPDATE SEARCHRACK SET {pos_col} = ? WHERE {id_lookup_col} = ?",
                                    ('' if clear_location else to_location, row_id)
                                )
                            else:
                                cur.execute(
                                    f"UPDATE SEARCHRACK SET {pic_col} = ? WHERE {id_lookup_col} = ?",
                                    ('' if clear_location else to_location, row_id)
                                )

                            rem_cur.execute('''
                                INSERT INTO removed_items
                                (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                            ''', (None, barcode_val, title_val, take_qty, now, row_id, take_qty, 0, removal_type, source_location))
                            rem_cur.execute('''
                                INSERT INTO removed_items
                                (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                            ''', (None, barcode_val, title_val, take_qty, now, row_id, 0, take_qty, removal_type, target_location_for_logs))

                        move_target_qty -= take_qty
                        remaining -= take_qty
                        moved_this_item += take_qty
                        moved_from_source += take_qty

                    if moved_from_source > 0:
                        used_locations.append(source_location)

                row_result['moved_qty'] = moved_this_item
                if used_locations:
                    row_result['used_locations'] = used_locations
                if moved_this_item > 0:
                    row_result['success'] = True
                    moved_items += 1
                    moved_units += moved_this_item
                    if moved_this_item < requested_qty:
                        detail = '; '.join(source_warnings[:3]) if source_warnings else ''
                        row_result['error'] = f'Only moved {moved_this_item} of {requested_qty}' + (f' ({detail})' if detail else '')
                else:
                    row_result['error'] = '; '.join(source_warnings) if source_warnings else ('Clear failed' if clear_location else 'Move failed')
                    skipped_items += 1
            except Exception as row_err:
                row_result['error'] = _safe_error(row_err)
                skipped_items += 1

            item_results.append(row_result)

        conn.commit()
        rem_conn.commit()
        if moved_units > 0:
            update_data_version()
            _invalidate_searchrack_cache()

        if moved_units <= 0:
            return jsonify({
                'success': False,
                'error': 'No items were updated' if clear_location else 'No items were moved',
                'moved_items': moved_items,
                'moved_units': moved_units,
                'skipped_items': skipped_items,
                'item_results': item_results,
                'clear_location': clear_location
            }), 400

        return jsonify({
            'success': True,
            'moved_items': moved_items,
            'moved_units': moved_units,
            'skipped_items': skipped_items,
            'item_results': item_results,
            'clear_location': clear_location
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass
        try:
            if rem_conn is not None:
                rem_conn.close()
        except Exception:
            pass

@app.route('/api/movelocation_bulk_cleanup', methods=['POST'])
def api_movelocation_bulk_cleanup():
    """Reduce SEARCHRACK quantities from selected source locations for sold bulk-manifest barcodes."""
    conn = None
    rem_conn = None
    try:
        data = request.get_json() or {}
        items = data.get('items') or []
        if not isinstance(items, list) or not items:
            return jsonify({'success': False, 'error': 'Missing items list'}), 400

        manifest_ids = []
        raw_manifest_ids = data.get('manifest_ids')
        if isinstance(raw_manifest_ids, list):
            seen_manifest_ids = set()
            for raw_id in raw_manifest_ids:
                manifest_id = _coerce_int(raw_id, 0)
                if manifest_id <= 0 or manifest_id in seen_manifest_ids:
                    continue
                seen_manifest_ids.add(manifest_id)
                manifest_ids.append(manifest_id)
        elif raw_manifest_ids is not None:
            manifest_ids = _bulk_manifest_parse_ids(raw_manifest_ids)

        conn = sqlite3.connect('searchRack.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        schema = _searchrack_removal_schema(cur)

        id_lookup_col = schema.get('id_col') or 'rowid'
        qty_col = schema.get('qty_col')
        if not qty_col:
            return jsonify({'success': False, 'error': 'SEARCHRACK quantity column not found'}), 500

        rem_conn = sqlite3.connect('rackhistory.db')
        rem_cur = rem_conn.cursor()
        _ensure_removed_items_table(rem_cur)
        try:
            rem_cur.execute("PRAGMA table_info(removed_items)")
            rem_cols = [c[1] for c in rem_cur.fetchall()]
            if 'item_position' not in rem_cols:
                rem_cur.execute('ALTER TABLE removed_items ADD COLUMN item_position TEXT')
                rem_conn.commit()
        except Exception:
            pass

        now_iso = datetime.datetime.now().isoformat()
        order_ref = f"bulk-manifest:{','.join(str(x) for x in manifest_ids)}" if manifest_ids else None

        removed_items = 0
        removed_units = 0
        skipped_items = 0
        requested_units = 0
        item_results = []

        for idx, raw_item in enumerate(items):
            row_result = {
                'index': idx,
                'barcode': str((raw_item or {}).get('barcode') or '').strip(),
                'from_location': str((raw_item or {}).get('from_location') or '').strip(),
                'from_locations': [],
                'requested_qty': 0,
                'moved_qty': 0,
                'removed_qty': 0,
                'success': False
            }
            try:
                barcode_raw = row_result['barcode']
                requested_qty = max(
                    1,
                    _coerce_int((raw_item or {}).get('quantity') if (raw_item or {}).get('quantity') is not None else (raw_item or {}).get('qty'), 1)
                )
                requested_units += requested_qty
                row_result['requested_qty'] = requested_qty

                raw_from_locations = (raw_item or {}).get('from_locations')
                source_locations = []
                source_seen = set()

                def _add_source_location(raw_loc):
                    loc = str(raw_loc or '').strip()
                    if not loc:
                        return
                    loc_key = _sold_location_key(loc)
                    if loc_key in source_seen:
                        return
                    source_seen.add(loc_key)
                    source_locations.append(loc)

                if isinstance(raw_from_locations, list):
                    for raw_loc in raw_from_locations:
                        _add_source_location(raw_loc)
                elif isinstance(raw_from_locations, str):
                    text = raw_from_locations.strip()
                    if text:
                        if ',' in text:
                            for part in text.split(','):
                                _add_source_location(part)
                        else:
                            _add_source_location(text)
                _add_source_location((raw_item or {}).get('from_location'))

                if requested_qty > 0 and len(source_locations) > requested_qty:
                    source_locations = source_locations[:requested_qty]
                    row_result['selection_limited'] = True
                row_result['from_locations'] = source_locations
                if source_locations:
                    row_result['from_location'] = ', '.join(source_locations)

                barcode_key = _sold_removal_barcode_key(barcode_raw)
                if not barcode_key:
                    row_result['error'] = 'Invalid barcode'
                    skipped_items += 1
                    item_results.append(row_result)
                    continue
                if not source_locations:
                    row_result['error'] = 'Missing source location'
                    skipped_items += 1
                    item_results.append(row_result)
                    continue

                matches = _searchrack_matches_for_barcode(
                    cur,
                    barcode_raw,
                    schema=schema,
                    include_zero=False
                )
                if not matches:
                    row_result['error'] = f'Barcode not found in SEARCHRACK: {barcode_raw}'
                    skipped_items += 1
                    item_results.append(row_result)
                    continue

                matches_by_loc = {}
                for match_row in matches:
                    loc_key = _sold_location_key(match_row.get('location_code'))
                    bucket = matches_by_loc.get(loc_key)
                    if bucket is None:
                        bucket = []
                        matches_by_loc[loc_key] = bucket
                    bucket.append(match_row)

                for loc_rows in matches_by_loc.values():
                    loc_rows.sort(key=lambda r: int(r.get('quantity') or 0), reverse=True)

                remaining = requested_qty
                removed_this_item = 0
                selected_keys = [_sold_location_key(loc) for loc in source_locations]
                source_warnings = []
                used_locations = []

                for source_location, source_key in zip(source_locations, selected_keys):
                    if remaining <= 0:
                        break

                    loc_rows = matches_by_loc.get(source_key) or []
                    if not loc_rows:
                        source_warnings.append(f'Barcode not found at {source_location}')
                        continue

                    removed_from_source = 0
                    for match_row in loc_rows:
                        if remaining <= 0:
                            break
                        current_qty = max(0, _coerce_int(match_row.get('quantity'), 0))
                        if current_qty <= 0:
                            continue
                        take_qty = min(current_qty, remaining)
                        if take_qty <= 0:
                            continue

                        row_id = max(0, _coerce_int(match_row.get('id'), 0))
                        if row_id <= 0:
                            continue

                        new_qty = max(0, current_qty - take_qty)
                        cur.execute(
                            f'UPDATE SEARCHRACK SET {qty_col} = ? WHERE {id_lookup_col} = ?',
                            (new_qty, row_id)
                        )

                        rem_cur.execute('''
                            INSERT INTO removed_items
                            (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        ''', (
                            order_ref,
                            str(match_row.get('barcode') or barcode_raw),
                            str(match_row.get('title') or match_row.get('barcode') or barcode_raw),
                            take_qty,
                            now_iso,
                            row_id,
                            current_qty,
                            new_qty,
                            'bulk_manifest_cleanup',
                            str(match_row.get('location_code') or source_location or '')
                        ))

                        match_row['quantity'] = new_qty
                        remaining -= take_qty
                        removed_this_item += take_qty
                        removed_from_source += take_qty

                    if removed_from_source > 0:
                        used_locations.append(source_location)

                row_result['moved_qty'] = removed_this_item
                row_result['removed_qty'] = removed_this_item
                if used_locations:
                    row_result['used_locations'] = used_locations
                if removed_this_item > 0:
                    row_result['success'] = True
                    removed_items += 1
                    removed_units += removed_this_item
                    if removed_this_item < requested_qty:
                        detail = '; '.join(source_warnings[:3]) if source_warnings else ''
                        row_result['error'] = f'Only removed {removed_this_item} of {requested_qty}' + (f' ({detail})' if detail else '')
                else:
                    row_result['error'] = '; '.join(source_warnings) if source_warnings else 'No quantity removed'
                    skipped_items += 1
            except Exception as row_err:
                row_result['error'] = _safe_error(row_err, 'movelocation_bulk_cleanup_row')
                skipped_items += 1

            item_results.append(row_result)

        conn.commit()
        rem_conn.commit()
        if removed_units > 0:
            update_data_version()
            _invalidate_searchrack_cache()

        cleanup_status = ''
        if manifest_ids:
            cleanup_status = 'cleanup_complete' if removed_units >= requested_units and skipped_items == 0 else ('cleanup_partial' if removed_units > 0 else '')
            if cleanup_status:
                cleanup_note = f'Removed {removed_units}/{requested_units} unit(s) via move-location bulk cleanup'
                with db_connection('marketplace.db') as m_conn:
                    m_cur = m_conn.cursor()
                    _ensure_bulk_manifest_tables(m_cur)
                    placeholders = ','.join('?' for _ in manifest_ids)
                    params = [cleanup_status, now_iso, cleanup_note, now_iso]
                    params.extend(manifest_ids)
                    m_cur.execute(f'''
                        UPDATE bulk_manifests
                        SET status = ?,
                            cleanup_at = ?,
                            cleanup_note = ?,
                            updated_at = ?
                        WHERE id IN ({placeholders})
                    ''', tuple(params))

        if removed_units <= 0:
            return jsonify({
                'success': False,
                'error': 'No quantities were removed from inventory',
                'moved_items': removed_items,
                'moved_units': removed_units,
                'removed_items': removed_items,
                'removed_units': removed_units,
                'requested_units': requested_units,
                'skipped_items': skipped_items,
                'item_results': item_results,
                'manifest_ids': manifest_ids,
                'manifest_cleanup_status': cleanup_status
            }), 400

        return jsonify({
            'success': True,
            'moved_items': removed_items,
            'moved_units': removed_units,
            'removed_items': removed_items,
            'removed_units': removed_units,
            'requested_units': requested_units,
            'skipped_items': skipped_items,
            'item_results': item_results,
            'manifest_ids': manifest_ids,
            'manifest_cleanup_status': cleanup_status
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'movelocation_bulk_cleanup')}), 500
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass
        try:
            if rem_conn is not None:
                rem_conn.close()
        except Exception:
            pass


@app.route('/api/location_items', methods=['GET'])
def api_location_items():
    """Get items for a specific shelf/location from searchRack.db"""
    try:
        location = (request.args.get('location') or '').strip()
        if not location:
            return jsonify({'success': False, 'error': 'Missing location'}), 400

        conn = sqlite3.connect('searchRack.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute('''
            SELECT ID, TITLE, BARCODE, QUANTITY, IMAGE, IMAGES
            FROM SEARCHRACK
            WHERE LOWER(TRIM(ITEM_POSITION)) = LOWER(TRIM(?))
            ORDER BY TITLE
        ''', (location,))
        items = []
        for row in cur.fetchall():
            qty_val = row['QUANTITY'] if 'QUANTITY' in row.keys() else None
            try:
                qty = int(qty_val) if qty_val is not None and str(qty_val).strip() != '' else 1
            except Exception:
                qty = 1
            image_val = row['IMAGE'] or ''
            if not image_val:
                images_raw = row['IMAGES'] if 'IMAGES' in row.keys() else ''
                try:
                    if images_raw and str(images_raw).strip().startswith('['):
                        parsed = json.loads(images_raw)
                        if isinstance(parsed, list) and parsed:
                            image_val = parsed[0]
                except Exception:
                    pass
            items.append({
                'id': row['ID'],
                'title': row['TITLE'] or '',
                'barcode': row['BARCODE'] or '',
                'quantity': qty,
                'image': image_val or row['IMAGES'] or ''
            })
        return jsonify({'success': True, 'items': items})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.route('/api/move_location', methods=['POST'])
def api_move_location():
    """Move searchRack items from one location to another and log history"""
    data = request.get_json() or {}
    from_location = (data.get('from_location') or '').strip()
    to_location = (data.get('to_location') or '').strip()
    item_ids = data.get('item_ids') or []

    if not from_location or not to_location or not item_ids:
        return jsonify({'success': False, 'error': 'Missing from_location, to_location, or item_ids'}), 400
    if not isinstance(item_ids, list):
        return jsonify({'success': False, 'error': 'item_ids must be a list'}), 400
    if from_location.lower() == to_location.lower():
        return jsonify({'success': False, 'error': 'Start and destination locations are the same'}), 400

    moved = 0
    skipped = 0

    try:
        conn = sqlite3.connect('searchRack.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()

        # Determine PK and picture column names
        cur.execute("PRAGMA table_info('SEARCHRACK')")
        cols = [r[1] for r in cur.fetchall()]
        id_col = 'ID' if 'ID' in cols else ('id' if 'id' in cols else 'rowid')
        pic_col = 'PICTUREPOSITION' if 'PICTUREPOSITION' in cols else None
        if not pic_col:
            for c in cols:
                if c.lower() == 'pictureposition':
                    pic_col = c
                    break

        # History logging
        rem_conn = sqlite3.connect('rackhistory.db')
        rem_cur = rem_conn.cursor()
        _ensure_removed_items_table(rem_cur)
        # Ensure item_position column exists for older schemas
        try:
            rem_cur.execute("PRAGMA table_info(removed_items)")
            rem_cols = [c[1] for c in rem_cur.fetchall()]
            if 'item_position' not in rem_cols:
                rem_cur.execute('ALTER TABLE removed_items ADD COLUMN item_position TEXT')
                rem_conn.commit()
        except Exception:
            pass

        def _parse_qty(row_dict):
            for qc in ['QUANTITY', 'Quantity', 'quantity', 'Qty', 'QTY']:
                if qc in row_dict and row_dict.get(qc) is not None:
                    try:
                        return int(row_dict.get(qc))
                    except Exception:
                        return 1
            return 1

        def _find_qty_col():
            for qc in ['QUANTITY', 'Quantity', 'quantity', 'Qty', 'QTY']:
                if qc in cols:
                    return qc
            return None

        from_norm = from_location.strip().lower()

        from datetime import datetime
        qty_col_name = _find_qty_col()
        for raw_entry in item_ids:
            try:
                move_qty = None
                raw_id = raw_entry
                if isinstance(raw_entry, dict):
                    raw_id = raw_entry.get('id') or raw_entry.get('item_id') or raw_entry.get('ID')
                    move_qty = raw_entry.get('qty') if raw_entry.get('qty') is not None else raw_entry.get('quantity')
                if raw_id is None or raw_id == '':
                    skipped += 1
                    continue

                cur.execute(f"SELECT * FROM SEARCHRACK WHERE {id_col} = ?", (raw_id,))
                row = cur.fetchone()
                if not row:
                    skipped += 1
                    continue

                row_dict = dict(row)
                row_loc = (row_dict.get('ITEM_POSITION') or row_dict.get('item_position') or '').strip()
                if row_loc.lower() != from_norm:
                    skipped += 1
                    continue

                barcode = row_dict.get('BARCODE') or row_dict.get('barcode') or ''
                title = row_dict.get('TITLE') or row_dict.get('title') or ''
                qty = _parse_qty(row_dict)
                try:
                    move_qty_int = int(move_qty) if move_qty is not None else qty
                except Exception:
                    move_qty_int = qty
                if move_qty_int < 1 or move_qty_int > qty:
                    skipped += 1
                    continue
                now = datetime.now().isoformat()

                if move_qty_int < qty and qty_col_name:
                    # Partial move: decrement original qty and insert new row at destination
                    new_qty = qty - move_qty_int
                    cur.execute(f"UPDATE SEARCHRACK SET {qty_col_name} = ? WHERE {id_col} = ?", (new_qty, raw_id))

                    # Build new row from existing with updated quantity and location
                    col_names = [c for c in cols if c not in (id_col, 'id', 'ID', 'Id', 'rowid')]
                    placeholders = ','.join('?' for _ in col_names)
                    vals = []
                    for c in col_names:
                        val = row_dict.get(c)
                        if c == qty_col_name:
                            val = move_qty_int
                        if c.lower() == 'pictureposition':
                            val = ''
                        if c.lower() == 'item_position' or c == 'ITEM_POSITION' or c.lower() == 'itemposition':
                            val = to_location
                        vals.append(val)
                    cur.execute(f"INSERT INTO SEARCHRACK ({', '.join(col_names)}) VALUES ({placeholders})", tuple(vals))
                    new_id = cur.lastrowid

                    # Log as a location move (removed from old + added to new)
                    rem_cur.execute('''
                        INSERT INTO removed_items
                        (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ''', (None, barcode, title, move_qty_int, now, raw_id, qty, new_qty, 'locationmoved', from_location))

                    rem_cur.execute('''
                        INSERT INTO removed_items
                        (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ''', (None, barcode, title, move_qty_int, now, new_id, 0, move_qty_int, 'locationmoved', to_location))
                else:
                    # Full move: update row location (clear pictureposition if present)
                    if pic_col:
                        cur.execute(f"UPDATE SEARCHRACK SET ITEM_POSITION = ?, {pic_col} = ? WHERE {id_col} = ?", (to_location, '', raw_id))
                    else:
                        cur.execute(f"UPDATE SEARCHRACK SET ITEM_POSITION = ? WHERE {id_col} = ?", (to_location, raw_id))

                    # Log as a location move (removed from old + added to new)
                    rem_cur.execute('''
                        INSERT INTO removed_items
                        (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ''', (None, barcode, title, qty, now, raw_id, qty, 0, 'locationmoved', from_location))

                    rem_cur.execute('''
                        INSERT INTO removed_items
                        (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ''', (None, barcode, title, qty, now, raw_id, 0, qty, 'locationmoved', to_location))

                moved += 1
            except Exception:
                skipped += 1

        conn.commit()
        rem_conn.commit()

        # Update data version for cache invalidation
        update_data_version()

        return jsonify({'success': True, 'moved': moved, 'skipped': skipped})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass
        try:
            rem_conn.close()
        except Exception:
            pass


@app.route('/api/delete/<db_key>/<int:item_id>', methods=['POST'])
def api_delete_row(db_key, item_id):
    mapping = {
        'ebayStore': 'ebayStore.db',
        'sold': 'sold.db',
        'searchRack': 'searchRack.db',
        'found': 'found.db',
        'bol': 'bol.db'
    }
    if db_key not in mapping:
        return jsonify({'error': 'Unknown db_key'}), 400
    src_db = mapping[db_key]
    try:
        table, pk = _get_table_and_pk(src_db)
        if not table:
            return jsonify({'error': 'No table in source DB'}), 400
        conn = sqlite3.connect(src_db)
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute(f"SELECT * FROM {table} WHERE {pk} = ?", (item_id,))
        row = cur.fetchone()
        if not row:
            return jsonify({'error': 'Row not found'}), 404
        rowdict = dict(row)
        dconn = sqlite3.connect('deleted.db')
        dcur = dconn.cursor()
        dcur.execute('''CREATE TABLE IF NOT EXISTS deleted_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            source_db TEXT,
            source_table TEXT,
            source_pk TEXT,
            source_id TEXT,
            deleted_at TEXT,
            data_json TEXT
        )''')
        import datetime, json
        # Store deletion time in ISO8601 UTC
        deleted_at = datetime.datetime.now(datetime.UTC).isoformat()
        dcur.execute('INSERT INTO deleted_items (source_db, source_table, source_pk, source_id, deleted_at, data_json) VALUES (?,?,?,?,?,?)',
                     (db_key, table, pk, str(item_id), deleted_at, json.dumps(rowdict)))
        dconn.commit()
        archive_id = dcur.lastrowid
        # Log to rackhistory if deleting from searchRack
        if db_key == 'searchRack':
            try:
                removed_conn = sqlite3.connect('rackhistory.db')
                removed_cur = removed_conn.cursor()
                _ensure_removed_items_table(removed_cur)
                
                # Extract details from the archived row data
                item_title = rowdict.get('TITLE') or rowdict.get('title', '')
                item_barcode = rowdict.get('BARCODE') or rowdict.get('barcode', '')
                old_qty = rowdict.get('QUANTITY') or rowdict.get('quantity', 0)
                item_location = rowdict.get('ITEM_POSITION') or rowdict.get('item_position', '')
                
                removed_cur.execute('''
                    INSERT INTO removed_items 
                    (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ''', (None, item_barcode, item_title, old_qty, deleted_at, item_id, old_qty, 0, 'manual_multidb_delete', item_location))
                removed_conn.commit()
            except Exception as log_err:
                print(f"Warning: Could not log multi-db deletion to removed_items: {log_err}")
            finally:
                removed_conn.close()
        
        conn2 = sqlite3.connect(src_db)
        try:
            cur2 = conn2.cursor()
            cur2.execute(f"DELETE FROM {table} WHERE {pk} = ?", (item_id,))
            conn2.commit()
        finally:
            conn2.close()
        return jsonify({'success': True, 'archived_id': archive_id})
    except Exception as e:
        return jsonify({'error': _safe_error(e)}), 500
    finally:
        conn.close()
        dconn.close()


@app.route('/api/undelete/<int:archive_id>', methods=['POST'])
def api_undelete(archive_id):
    try:
        dconn = sqlite3.connect('deleted.db')
        dconn.row_factory = sqlite3.Row
        dcur = dconn.cursor()
        dcur.execute('SELECT * FROM deleted_items WHERE id = ?', (archive_id,))
        row = dcur.fetchone()
        if not row:
            return jsonify({'error': 'Archive not found'}), 404
        rec = dict(row)
        import json
        data = json.loads(rec['data_json'])
        src_db_key = rec['source_db']
        mapping = {
            'ebayStore': 'ebayStore.db',
            'sold': 'sold.db',
            'searchRack': 'searchRack.db',
            'found': 'found.db',
            'bol': 'bol.db'
        }
        if src_db_key not in mapping:
            return jsonify({'error': 'Unknown source db'}), 400
        src_db = mapping[src_db_key]
        table = rec['source_table']
        conn = sqlite3.connect(src_db)
        cur = conn.cursor()
        cur.execute(f"PRAGMA table_info('{table}')")
        cols = [r[1] for r in cur.fetchall()]
        insert_cols = [c for c in cols if c in data and c != rec['source_pk']]
        vals = [data[c] for c in insert_cols]
        placeholders = ','.join(['?'] * len(vals))
        if insert_cols:
            sql = f"INSERT INTO {table} ({','.join(insert_cols)}) VALUES ({placeholders})"
            cur.execute(sql, vals)
            conn.commit()
            dcur.execute('DELETE FROM deleted_items WHERE id = ?', (archive_id,))
            dconn.commit()
            return jsonify({'success': True})
        else:
            return jsonify({'error': 'No insertable columns found'}), 400
    except Exception as e:
        return jsonify({'error': _safe_error(e)}), 500
    finally:
        dconn.close()
        conn.close()


@app.route('/api/location_duplicates', methods=['GET'])
def api_location_duplicates():
    """Return items that have the same barcode in multiple locations - ONE ROW per barcode with locations array"""
    try:
        conn = sqlite3.connect('searchRack.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        
        # Get quantity column name
        cur.execute('PRAGMA table_info(SEARCHRACK)')
        cols = [r[1] for r in cur.fetchall()]
        qty_col = 'QUANTITY' if 'QUANTITY' in cols else ('QTY' if 'QTY' in cols else 'quantity')
        
        # Find barcodes that appear in multiple locations (non-suffixed barcodes only)
        cur.execute(f'''
            SELECT 
                BARCODE,
                MAX(TITLE) as TITLE,
                MAX(IMAGE) as IMAGE,
                MAX(PICTUREPOSITION) as PICTUREPOSITION,
                MAX(CREATED_AT) as CREATED_AT,
                GROUP_CONCAT(ID || ':' || ITEM_POSITION || ':' || {qty_col} || ':' || COALESCE(PICTUREPOSITION, ''), '|') as location_data,
                SUM(CAST({qty_col} AS INTEGER)) as total_quantity
            FROM SEARCHRACK
            WHERE BARCODE IS NOT NULL 
            AND TRIM(BARCODE) != ''
            AND BARCODE NOT LIKE '%-%'
            AND ITEM_POSITION IS NOT NULL
            AND TRIM(ITEM_POSITION) != ''
            GROUP BY BARCODE
            HAVING COUNT(DISTINCT ITEM_POSITION) > 1
            ORDER BY BARCODE
        ''')
        
        grouped_rows = cur.fetchall()
        results = []
        total_qty = 0
        
        for group_row in grouped_rows:
            barcode = group_row['BARCODE']
            title = group_row['TITLE'] or 'Unknown'
            image = group_row['IMAGE'] or ''
            created_at = group_row['CREATED_AT']
            location_data = group_row['location_data']
            group_total_qty = group_row['total_quantity'] or 0
            
            # Parse location data: "id:location:qty:picturepos|..."
            locations_list = []
            
            for loc_entry in location_data.split('|'):
                parts = loc_entry.split(':')
                if len(parts) >= 3:
                    item_id = parts[0]
                    location = parts[1]
                    qty_str = parts[2]
                    picturepos = parts[3] if len(parts) > 3 else ''
                    
                    try:
                        qty = int(float(qty_str)) if qty_str else 0
                    except Exception:
                        qty = 0
                    
                    locations_list.append({
                        'id': item_id,
                        'code': location,
                        'quantity': qty,
                        'image': picturepos if picturepos else location
                    })
            
            total_qty += group_total_qty
            
            # Create ONE result entry per barcode with locations array
            result = {
                'id': locations_list[0]['id'] if locations_list else None,  # Use first ID as primary
                'barcode': barcode,
                'title': title,
                'quantity': group_total_qty,
                'locations': locations_list,  # Array of all locations
                'created_at': created_at,
                'image': image,
                'source_db': 'searchRack',
                'is_duplicate_group': True
            }
            results.append(result)
        
        
        return jsonify({
            'results': results,
            'total_quantity': total_qty,
            'total_groups': len(grouped_rows)
        })
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'error': _safe_error(e), 'results': []}), 500
    finally:
        conn.close()

@app.route('/api/archived', methods=['GET', 'POST'])
def api_archived_list():
    """Return list of archived (deleted) items from deleted.db as normalized results."""
    try:
        conn = sqlite3.connect('deleted.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute('SELECT * FROM deleted_items ORDER BY deleted_at DESC')
        rows = [dict(r) for r in cur.fetchall()]
        results = []
        import json
        for r in rows:
            data = {}
            try:
                data = json.loads(r.get('data_json') or '{}')
            except Exception:
                data = {}
            # Normalize common fields across mixed sources; include UPPERCASE keys from SEARCHRACK
            title_val = (
                data.get('Title') or data.get('title') or data.get('TITLE') or
                data.get('item_description') or data.get('DESCRIPTION') or data.get('description') or ''
            )
            image_val = (
                data.get('Image') or data.get('image') or data.get('image_url') or data.get('IMAGE') or ''
            )
            barcode_val = (
                data.get('BARCODE') or data.get('barcode') or data.get('upc') or
                data.get('UPC') or data.get('ItemID') or ''
            )
            itemid_val = (
                data.get('ItemID') or data.get('item_id') or data.get('ItemId') or
                data.get('ITEMID') or data.get('id') or data.get('ID') or data.get('upc') or ''
            )
            picturepos_val = (
                data.get('PICTUREPOSITION') or data.get('pictureposition') or data.get('picture_position') or ''
            )
            itempos_val = (
                data.get('ITEM_POSITION') or data.get('item_position') or data.get('position') or ''
            )
            quantity_val = (
                data.get('Quantity') or data.get('quantity') or data.get('qty') or data.get('QUANTITY') or ''
            )

            # Parse IMAGES field to extract a first URL if needed
            imgs_field = data.get('IMAGES') or data.get('images')
            if (not image_val) and imgs_field is not None:
                try:
                    if isinstance(imgs_field, list):
                        for u in imgs_field:
                            s = str(u or '')
                            if s.lower().startswith('http'):
                                image_val = s
                                break
                    elif isinstance(imgs_field, str):
                        s = imgs_field.strip()
                        if s.startswith('[') and s.endswith(']'):
                            arr = json.loads(s)
                            if isinstance(arr, list):
                                for u in arr:
                                    us = str(u or '')
                                    if us.lower().startswith('http'):
                                        image_val = us
                                        break
                        if not image_val:
                            for sep in [',',';','|','\n','\t',' ']:
                                if sep in s:
                                    for part in s.split(sep):
                                        ps = part.strip()
                                        if ps.lower().startswith('http'):
                                            image_val = ps
                                            break
                                    if image_val:
                                        break
                            if not image_val and s.lower().startswith('http'):
                                image_val = s
                except Exception:
                    pass

            # Enrich archived rows using UPC against ebayStore/bol for title/image/quantity if missing
            def _to_int_like(q):
                try:
                    if q is None:
                        return None
                    s = str(q).strip()
                    if not s:
                        return None
                    if s.isdigit():
                        return int(s)
                    if s.endswith('.0') and s.replace('.0','').isdigit():
                        return int(float(s))
                    f = float(s)
                    if abs(f - int(f)) < 1e-9:
                        return int(f)
                    return None
                except Exception:
                    return None

            if barcode_val:
                try:
                    es_conn = sqlite3.connect('ebayStore.db')
                    es_conn.row_factory = sqlite3.Row
                    es_cur = es_conn.cursor()
                    es_cur.execute("SELECT Title, Image, ItemID, Quantity FROM INVENTORY WHERE UPC = ? COLLATE NOCASE LIMIT 1", (barcode_val,))
                    row_es = es_cur.fetchone()
                    if row_es:
                        if not title_val:
                            title_val = row_es['Title']
                        if not image_val:
                            image_val = row_es['Image']
                        if not itemid_val:
                            itemid_val = row_es['ItemID']
                        if not quantity_val:
                            quantity_val = row_es['Quantity']
                except Exception:
                    pass
                finally:
                    es_conn.close()
                if (not title_val or not image_val):
                    try:
                        bol_conn = sqlite3.connect('bol.db')
                        bol_conn.row_factory = sqlite3.Row
                        bol_cur = bol_conn.cursor()
                        bol_cur.execute('SELECT item_description, image_url, upc FROM bol_items WHERE upc = ? COLLATE NOCASE LIMIT 1', (barcode_val,))
                        row_bol = bol_cur.fetchone()
                        if row_bol:
                            if not title_val:
                                title_val = row_bol['item_description']
                            if not image_val:
                                image_val = row_bol['image_url']
                            if not itemid_val:
                                itemid_val = row_bol['upc']
                    except Exception:
                        pass
                    finally:
                        bol_conn.close()

            qn = _to_int_like(quantity_val)
            if qn is not None:
                quantity_val = qn
            item_out = {
                'archived': True,
                'archived_id': r.get('id'),
                'deleted_at': r.get('deleted_at'),
                'source_db': 'archived',
                'orig_source_db': r.get('source_db'),
                'orig_table': r.get('source_table'),
                'orig_pk': r.get('source_pk'),
                'orig_id': r.get('source_id'),
                'id': r.get('id'),
                'title': title_val,
                'image': image_val,
                'barcode': barcode_val,
                'item_id': itemid_val,
                'pictureposition': picturepos_val,
                'item_position': itempos_val,
                'quantity': quantity_val,
                'raw': data
            }
            results.append(item_out)
        # Merge archived rows similar to searchRack: group by barcode+item_position and sum quantities
        # IMPORTANT: Store ALL archive IDs in merged_archive_ids so we can delete all entries at once
        if results:
            merged = {}
            for r in results:
                bc = (r.get('barcode') or '').strip().lower()
                pos = (r.get('item_position') or '').strip().lower()
                if not bc:
                    key = f"__{id(r)}_{len(merged)}"
                else:
                    key = f"{bc}||{pos}"
                # normalize qty: if not int-like, treat as 1
                try:
                    q = r.get('quantity')
                    if isinstance(q, str):
                        q = q.strip()
                    if q is None or (isinstance(q, str) and not q):
                        n = 1
                    elif isinstance(q, int):
                        n = q
                    elif isinstance(q, float) and abs(q - int(q)) < 1e-9:
                        n = int(q)
                    elif isinstance(q, str) and q.isdigit():
                        n = int(q)
                    elif isinstance(q, str) and q.endswith('.0') and q.replace('.0','').isdigit():
                        n = int(float(q))
                    else:
                        n = 1
                except Exception:
                    n = 1
                if key not in merged:
                    r_copy = r.copy()
                    r_copy['quantity'] = n
                    # Store array of all archive IDs that were merged into this row
                    r_copy['merged_archive_ids'] = [r.get('id')]
                    merged[key] = r_copy
                else:
                    merged[key]['quantity'] = merged[key].get('quantity', 0) + n
                    # Append this archive ID to the list
                    if 'merged_archive_ids' not in merged[key]:
                        merged[key]['merged_archive_ids'] = []
                    merged[key]['merged_archive_ids'].append(r.get('id'))
            results = list(merged.values())
        return jsonify({'results': results})
    except Exception as e:
        return jsonify({'error': _safe_error(e)}), 500
    finally:
        conn.close()


